INSERT INTO `blog_posts` (`id`, `slug`, `title`, `excerpt`, `body`, `cover_image`, `category`, `author_name`, `seo_title`, `seo_description`, `tags`, `reading_minutes`, `is_published`, `published_at`, `views`, `created_at`, `updated_at`) VALUES (1,'her-gun-10-dakikada-ingilizce','Her gün 10 dakikada İngilizce: işe yarayan bir rutin','Uzun ama seyrek çalışmak yerine kısa ve düzenli çalışmak neden daha etkili? Sınıflarımızda denediğimiz 10 dakikalık rutini paylaşıyoruz.','## Neden kısa ve düzenli?\n\nBeynimiz yeni kelimeleri tekrar edildiğinde kalıcı hafızaya taşır. Haftada bir gün üç saat çalışmak yerine her gün 10 dakika çalışan öğrencilerimiz, üç ayın sonunda **iki kat daha fazla kelimeyi** hatırlıyor.\n\n## 10 dakikalık rutin\n\n- **2 dakika, tekrar:** Dünkü kelimeleri kelime kartlarıyla hızlıca tekrar et.\n- **4 dakika, oku ve dinle:** Seviyene uygun kısa bir hikayeyi önce dinle, sonra oku.\n- **3 dakika, konuş:** Hikayedeki iki cümleyi sesli tekrar et ya da Defne\'ye hikayeyi anlat.\n- **1 dakika, yaz:** Bugün öğrendiğin bir kelimeyle kendi cümleni kur.\n\n## Seriyi bozmamak için\n\nGünlük hedefini gerçekçi seç. Yoğun bir gününde 5 dakikalık bir tekrar bile serini korur. Tatile çıkacaksan mağazadan bir **seri dondurucu** almayı unutma.\n\n> Küçük adımlar, her gün. Akıcılık böyle gelir.','/img/blog/routine.webp','Öğrenme ipuçları','Bayrak Dil Okulları',NULL,NULL,NULL,5,1,'2026-10-01 20:30:41',0,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(2,'turklerin-en-sik-yaptigi-7-ingilizce-hatasi','Türklerin en sık yaptığı 7 İngilizce hatası','\"I am agree\", \"informations\", \"I will go to home\"… Öğretmenlerimizin sınıfta en çok düzelttiği hataları ve doğrularını derledik.','## 1. I am agree ❌ → I agree ✅\n\n*Agree* zaten bir fiil. Yanına *am/is/are* gelmez.\n\n## 2. informations ❌ → information ✅\n\n*Information*, *advice*, *furniture* gibi kelimeler sayılamaz; çoğul eki almaz.\n\n## 3. I will go to home ❌ → I will go home ✅\n\n*Home* yön bildirirken *to* almaz.\n\n## 4. I have 25 years old ❌ → I am 25 years old ✅\n\nYaş İngilizcede *to be* ile söylenir.\n\n## 5. He don\'t like ❌ → He doesn\'t like ✅\n\n*He / she / it* ile olumsuzda **doesn\'t** kullanılır.\n\n## 6. I am living in Izmir since 2019 ❌ → I have lived in Izmir since 2019 ✅\n\n*Since* ve *for* ile süregelen durumlar için present perfect kullanılır.\n\n## 7. Explain me ❌ → Explain to me ✅\n\n*Explain* fiili kişiyi doğrudan nesne olarak almaz.\n\nAda, sohbet ederken bu hataları yakalar ve Türkçe açıklar. Birkaç mesajla dene!','/img/blog/books.webp','Dilbilgisi','Bayrak Dil Okulları',NULL,NULL,NULL,6,1,'2026-09-26 20:30:41',0,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(3,'ielts-speaking-hazirlik-rehberi','IELTS Speaking için 4 haftalık hazırlık planı','Speaking bölümünde band puanını yükseltmek için akıcılık, kelime çeşitliliği ve telaffuza haftalık odaklanan bir plan.','## 1. hafta: Akıcılık\n\nHer gün Part 1 sorularına 2 dakika kesintisiz cevap ver. Mükemmel cümleler kurmaya çalışma, konuşmayı sürdür.\n\n## 2. hafta: Part 2 kartları\n\nDilGO\'daki **IELTS Speaking Part 2** senaryosunda her gün bir kart çalış. 1 dakika not al, 2 dakika konuş.\n\n## 3. hafta: Kelime ve bağlaçlar\n\n*However, although, on the other hand, as a result* gibi bağlaçları bilinçli kullan. Defne\'nin önerdiği yeni kelimeleri kelime defterine ekle.\n\n## 4. hafta: Deneme sınavları\n\nBayrak Dil Okulları\'nda bir öğretmenimizle gerçek sınav formatında deneme yap. Canlı ders kuponunu burada kullanabilirsin.\n\n### Son ipucu\n\nSınav günü bilmediğin bir kelimeyle karşılaşırsan susma; *\"It\'s a kind of…\"* diyerek açıkla. Akıcılık, mükemmellikten daha çok puan getirir.','/img/scenarios/ielts-speaking.webp','Sınavlar','Bayrak Dil Okulları',NULL,NULL,NULL,7,1,'2026-09-21 20:30:41',0,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(4,'is-hayatinda-ingilizce-toplanti-ifadeleri','İş hayatında İngilizce: toplantıda işe yarayan 12 ifade','Söz almak, fikir belirtmek, kibarca itiraz etmek… Toplantılarda kendini rahat ifade etmen için hazır kalıplar.','## Söz almak\n\n- *Could I add something here?*\n- *If I may, I\'d like to comment on that.*\n\n## Fikir belirtmek\n\n- *From my point of view, …*\n- *I\'m fairly confident that …*\n\n## Kibarca itiraz etmek\n\n- *I see your point, but …*\n- *I\'m not sure I completely agree.*\n\n## Netleştirmek\n\n- *Just to clarify, do you mean …?*\n- *Could you go over that again?*\n\n## Toplantıyı bitirmek\n\n- *Let\'s wrap up here.*\n- *I\'ll send a summary by email.*\n\nBu ifadeleri DilGO\'daki **İş mülakatı** senaryosunda Defne ile pratik edebilirsin.','/img/blog/coworkers.webp','Kariyer','Bayrak Dil Okulları',NULL,NULL,NULL,4,1,'2026-09-16 20:30:41',0,'2026-10-04 20:30:41','2026-10-04 20:30:41');
