INSERT INTO `courses` (`id`, `slug`, `title`, `description`, `cefr_level`, `color`, `position`, `is_published`, `created_at`, `updated_at`) VALUES (1,'a1-baslangic','A1 · İlk Adımlar','Kendini tanıt, aileni ve gününü anlat, şehirde yolunu bul. İngilizcede ilk gerçek cümlelerin.','A1','#FF5A36',0,1,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(2,'a2-yol-arkadasi','A2 · Yol Arkadaşı','Geçmişi anlat, planlarını paylaş, karşılaştır ve tavsiye ver. Günlük hayatta rahatça idare et.','A2','#2EC4A0',1,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(3,'b1-ozgur-konusma','B1 · Özgürce Konuş','Deneyimlerini ve fikirlerini anlat, haberleri takip et, iş hayatında kendini ifade et.','B1','#3A6FF7',2,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(4,'b2-ileri','B2 · Akıcılık','Fikirlerini savun, tahminde bulun, akademik metinleri oku. YDS, YDT ve YÖKDİL için sağlam bir temel.','B2','#8F7CF8',3,1,'2026-10-04 20:30:41','2026-10-04 20:30:41');
