INSERT INTO `exam_questions` (`id`, `exams`, `section`, `cefr`, `passage`, `prompt`, `options`, `answer`, `explanation`, `position`, `is_active`, `created_at`, `updated_at`) VALUES (1,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','vocabulary','B2',NULL,'The new vaccine proved highly ---- in clinical trials, reducing infection rates by nearly 90 percent.','[\"ambiguous\",\"obsolete\",\"redundant\",\"reluctant\",\"efficacious\"]',4,'Efficacious = etkili. Enfeksiyonu %90 azaltan bir aşı için olumlu ve etki bildiren tek sıfat bu. Ambiguous (belirsiz), redundant (gereksiz), obsolete (modası geçmiş) anlamı bozar.',0,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(2,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','vocabulary','B2',NULL,'Despite years of research, scientists have not yet been able to ---- the exact cause of the disease.','[\"postpone\",\"undermine\",\"pinpoint\",\"exaggerate\",\"abandon\"]',2,'Pinpoint = tam olarak tespit etmek. \'Kesin nedeni\' ifadesiyle birlikte kullanılır. Undermine (zayıflatmak) ve postpone (ertelemek) bağlama uymaz.',1,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(3,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','vocabulary','B2',NULL,'The committee decided to ---- the meeting until all members could attend.','[\"look into\",\"give in\",\"make up\",\"turn down\",\"put off\"]',4,'Put off = ertelemek. \'Herkes katılana kadar\' ifadesi zamanı ileri atmayı gösterir. Turn down reddetmek, look into incelemek demektir.',2,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(4,'[\"yds\",\"yokdil\",\"ielts\",\"toefl\",\"proficiency\"]','vocabulary','C1',NULL,'The economist argued that the government\'s policies would only ---- the gap between the rich and the poor.','[\"alleviate\",\"commemorate\",\"accommodate\",\"exacerbate\",\"illuminate\"]',3,'Exacerbate = kötüleştirmek, derinleştirmek. \'Only\' vurgusu eleştirel bir ton verir; alleviate (hafifletmek) tam tersi anlamdadır ve tuzak şıktır.',3,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(5,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','vocabulary','B2',NULL,'Many species are now ---- to extinction because their natural habitats are disappearing.','[\"accustomed\",\"indifferent\",\"vulnerable\",\"immune\",\"superior\"]',2,'Vulnerable to = -e karşı savunmasız. Immune to (bağışık) zıt anlamlı tuzaktır; accustomed to (alışkın) bağlama uymaz.',4,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(6,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','vocabulary','B1',NULL,'Our flight was delayed, so we had to ---- a hotel near the airport for the night.','[\"set off\",\"run out of\",\"bring up\",\"check into\",\"get over\"]',3,'Check into a hotel = otele giriş yapmak. Run out of (tükenmek), get over (atlatmak), set off (yola çıkmak) cümleye uymaz.',5,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(7,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','grammar','B2',NULL,'By the time the rescue team arrived, the fire ---- most of the building.','[\"destroys\",\"was destroying\",\"would destroy\",\"has destroyed\",\"had destroyed\"]',4,'\'By the time + geçmiş zaman\' yapısında daha önce tamamlanmış eylem past perfect (had + V3) ile anlatılır.',6,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(8,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','grammar','B2',NULL,'---- the heavy rain, the match went ahead as planned.','[\"Because of\",\"Unless\",\"Although\",\"Despite\",\"Whereas\"]',3,'Boşluktan sonra isim (the heavy rain) geliyor; zıtlık bildiren edat \'despite\' gerekir. \'Although\' cümle ister, \'because of\' zıtlık değil neden bildirir.',7,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(9,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','grammar','B2',NULL,'If the researchers ---- more funding, they could have completed the project on time.','[\"have received\",\"would receive\",\"receive\",\"received\",\"had received\"]',4,'Ana cümlede \'could have completed\' var: geçmişe dönük gerçek dışı koşul (Type 3). Yan cümlede past perfect kullanılır.',8,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(10,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','grammar','B2',NULL,'The report, ---- was published last week, has caused a lot of controversy.','[\"which\",\"whose\",\"where\",\"what\",\"that\"]',0,'Virgülle ayrılmış (non-defining) sıfat cümlesinde \'that\' kullanılamaz; nesneyi niteleyen \'which\' doğrudur.',9,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(11,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','grammar','C1',NULL,'Not only ---- the deadline, but he also forgot to inform his manager.','[\"he did miss\",\"missed he\",\"did he miss\",\"he missed\",\"has he missing\"]',2,'\'Not only\' cümle başında olduğunda devrik yapı gelir: yardımcı fiil + özne + fiil (did he miss).',10,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(12,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','grammar','B2',NULL,'The more you practise speaking, ---- you will become.','[\"more confident\",\"the confident\",\"the more confident\",\"the most confident\",\"most confident\"]',2,'\'The more ..., the more ...\' kalıbı: bir şey arttıkça diğeri de artar. İkinci yarı da \'the + comparative\' ile kurulur.',11,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(13,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','cloze','B2','Sleep is not simply a period of rest. While we sleep, the brain actively processes the information it (1) ---- during the day. Researchers have found that people who sleep well after learning a new skill perform better the next day (2) ---- those who stay awake.','(1) numaralı boşluğa hangisi gelir?','[\"will gather\",\"gathers\",\"had been gathered\",\"has gathered\",\"is gathering\"]',3,'\'During the day\' şimdiye kadar biriken bilgiyi anlatır; genel doğruyu anlatan metinde present perfect (has gathered) en uygun zamandır.',12,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(14,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','cloze','B2','Sleep is not simply a period of rest. While we sleep, the brain actively processes the information it (1) ---- during the day. Researchers have found that people who sleep well after learning a new skill perform better the next day (2) ---- those who stay awake.','(2) numaralı boşluğa hangisi gelir?','[\"to\",\"like\",\"from\",\"as\",\"than\"]',4,'\'Better\' karşılaştırma sıfatıdır ve \'than\' ile tamamlanır.',13,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(15,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','cloze','C1','Urban gardens are becoming increasingly popular in large cities. (1) ---- providing fresh produce, they also help reduce air pollution and create green spaces where neighbours can meet. However, their success largely depends (2) ---- the support of local authorities.','(1) numaralı boşluğa hangisi gelir?','[\"In spite of\",\"On behalf of\",\"In addition to\",\"Instead of\",\"Regardless of\"]',2,'Cümle ek fayda sayıyor (also help...). \'In addition to + V-ing\' = -e ek olarak. Instead of (yerine) ve in spite of (rağmen) anlamı bozar.',14,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(16,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','cloze','C1','Urban gardens are becoming increasingly popular in large cities. (1) ---- providing fresh produce, they also help reduce air pollution and create green spaces where neighbours can meet. However, their success largely depends (2) ---- the support of local authorities.','(2) numaralı boşluğa hangisi gelir?','[\"with\",\"at\",\"for\",\"on\",\"in\"]',3,'\'Depend on\' sabit bir fiil-edat kalıbıdır: -e bağlı olmak.',15,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(17,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','sentence_completion','B2',NULL,'Although electric cars are becoming cheaper, ----.','[\"their batteries have improved considerably in recent years\",\"governments are offering tax reductions to buyers\",\"many people are still worried about the limited number of charging stations\",\"they produce no exhaust emissions at all\",\"more models are available than ever before\"]',2,'\'Although\' zıtlık ister: arabalar ucuzluyor AMA insanlar hâlâ endişeli. Diğer şıklar elektrikli araçların lehine olup zıtlık kurmaz.',16,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(18,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','sentence_completion','B2',NULL,'Unless the city invests in public transport, ----.','[\"the new metro line was opened last year\",\"traffic congestion will continue to get worse\",\"buses were cheaper in the past\",\"more people have started cycling to work\",\"residents voted for a new mayor\"]',1,'\'Unless\' (-mezse) koşul bildirir; ana cümle gelecek zamanlı bir sonuç ister: \'will continue\'. Diğer şıklar zaman ve anlamca uymaz.',17,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(19,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','sentence_completion','C1',NULL,'So complex was the problem that ----.','[\"the engineers found it quite simple\",\"it was solved in a few minutes by a student\",\"even the most experienced engineers needed weeks to solve it\",\"nobody had ever heard of it before\",\"the company decided to hire more staff last year\"]',2,'\'So ... that\' sonuç bildirir: sorun o kadar karmaşıktı ki en deneyimli mühendisler bile haftalarca uğraştı. Diğer şıklar karmaşıklığın doğal sonucu değildir.',18,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(20,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','sentence_completion','B2',NULL,'----, the museum attracts thousands of visitors every summer.','[\"Although it is difficult to reach\",\"Unless it is renovated\",\"Since it was closed for repairs\",\"Even though tickets are free\",\"Located in the heart of the old town\"]',4,'Kısaltılmış sıfat cümlesi (Located in...) müzeyi niteleyip ziyaretçi çekmesinin nedenini verir. \'Although/even though\' zıtlık kurar ama cümlede zıtlık yok.',19,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(21,'[\"yds\",\"yokdil\",\"ydt\"]','translation','B2',NULL,'Scientists believe that regular exercise can significantly reduce the risk of heart disease.','[\"Bilim insanlar\\u0131 kalp hastal\\u0131\\u011f\\u0131n\\u0131n d\\u00fczenli egzersizle tamamen \\u00f6nlenebildi\\u011fini kan\\u0131tlad\\u0131.\",\"D\\u00fczenli egzersiz yapan bilim insanlar\\u0131n\\u0131n kalp hastal\\u0131\\u011f\\u0131 riski olduk\\u00e7a d\\u00fc\\u015f\\u00fckt\\u00fcr.\",\"Bilim insanlar\\u0131na g\\u00f6re kalp hastalar\\u0131 d\\u00fczenli olarak egzersiz yapmal\\u0131d\\u0131r.\",\"Bilim insanlar\\u0131 d\\u00fczenli egzersizin kalp hastal\\u0131\\u011f\\u0131 riskini \\u00f6nemli \\u00f6l\\u00e7\\u00fcde azaltabilece\\u011fine inan\\u0131yor.\",\"Kalp hastal\\u0131\\u011f\\u0131 riskini azaltmak i\\u00e7in bilim insanlar\\u0131 d\\u00fczenli egzersiz \\u00f6neriyor.\"]',3,'\'Believe that\' = inanıyor, \'can significantly reduce\' = önemli ölçüde azaltabilir. B şıkkı \'kanıtladı\' ve \'tamamen\' diyerek anlamı abartıyor; E şıkkı \'öneriyor\' diyerek fiili değiştiriyor.',20,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(22,'[\"yds\",\"yokdil\",\"ydt\"]','translation','B2',NULL,'Türkiye\'nin en kalabalık şehri olan İstanbul, iki kıta üzerinde kurulmuştur.','[\"Turkey\'s biggest city Istanbul was once built on two different continents.\",\"Istanbul, which is the most populous city in Turkey, is built on two continents.\",\"Being built on two continents, Istanbul became Turkey\'s largest city.\",\"Istanbul is one of the most crowded cities built between two continents.\",\"The population of Istanbul, a city on two continents, is the highest in the world.\"]',1,'Ara söz \'Türkiye\'nin en kalabalık şehri olan\' bir sıfat cümlesiyle (which is the most populous city in Turkey) çevrilir. D şıkkı neden sonuç ilişkisi ekliyor, E şıkkı \'dünyada\' diyerek anlamı değiştiriyor.',21,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(23,'[\"yds\",\"yokdil\"]','translation','C1',NULL,'Had the data been analysed more carefully, the researchers would have noticed the error much earlier.','[\"Veriler daha dikkatli analiz edilseydi, ara\\u015ft\\u0131rmac\\u0131lar hatay\\u0131 \\u00e7ok daha \\u00f6nce fark ederdi.\",\"Ara\\u015ft\\u0131rmac\\u0131lar\\u0131n hatay\\u0131 fark etmesi i\\u00e7in verilerin dikkatle analiz edilmesi gerekiyor.\",\"Veriler analiz edildi\\u011finde ara\\u015ft\\u0131rmac\\u0131lar hatan\\u0131n \\u00e7ok eski oldu\\u011funu fark etti.\",\"Veriler daha dikkatli analiz edilirse, ara\\u015ft\\u0131rmac\\u0131lar hatay\\u0131 daha \\u00f6nce fark edecek.\",\"Ara\\u015ft\\u0131rmac\\u0131lar verileri dikkatlice analiz ettikleri i\\u00e7in hatay\\u0131 erkenden fark etti.\"]',0,'\'Had the data been analysed\' devrik Type 3 koşuldur: geçmişte gerçekleşmemiş durum (edilseydi ... ederdi). B şıkkı olmuş bir olayı anlatıyor, E şıkkı gelecek zaman kullanıyor.',22,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(24,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','reading','B2','Bees play a vital role in agriculture. Around one third of the food we eat depends on pollination, and bees are responsible for most of it. In recent decades, however, bee populations have declined sharply in many parts of the world. Scientists point to several causes, including pesticide use, habitat loss and climate change. Some farmers have responded by planting wildflowers along the edges of their fields, which provide food and shelter for bees throughout the year.','According to the passage, why do some farmers plant wildflowers?','[\"To support bee populations by giving them food and shelter\",\"To replace crops that depend on pollination\",\"To increase the price of their crops\",\"To attract tourists to their farms\",\"To reduce their use of pesticides\"]',0,'Son cümle cevabı açıkça veriyor: kır çiçekleri arılara yıl boyunca \'food and shelter\' sağlar. Pestisit metinde neden olarak geçiyor, çözüm olarak değil.',23,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(25,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','reading','B2','Bees play a vital role in agriculture. Around one third of the food we eat depends on pollination, and bees are responsible for most of it. In recent decades, however, bee populations have declined sharply in many parts of the world. Scientists point to several causes, including pesticide use, habitat loss and climate change. Some farmers have responded by planting wildflowers along the edges of their fields, which provide food and shelter for bees throughout the year.','The word \'declined\' in the passage is closest in meaning to ----.','[\"multiplied\",\"stabilised\",\"recovered\",\"decreased\",\"migrated\"]',3,'Decline = azalmak (decrease). \'Sharply\' ile birlikte keskin bir düşüşü anlatır. Recovered ve multiplied zıt anlamlı tuzaklardır.',24,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(26,'[\"yds\",\"yokdil\",\"ielts\",\"toefl\",\"proficiency\"]','reading','C1','The concept of a four-day working week has gained traction in several countries. Proponents argue that shorter weeks lead to higher productivity, better mental health and lower carbon emissions from commuting. A large trial in the United Kingdom found that most participating companies maintained their output while employees reported less stress. Critics, however, caution that the model may not suit every sector; hospitals and schools, for instance, cannot simply close for an extra day.','What is the main purpose of the passage?','[\"To prove that every company should adopt a four-day week\",\"To argue that productivity always falls when hours are reduced\",\"To explain why hospitals are closed on Fridays\",\"To describe the history of working hours in the UK\",\"To present the benefits of a four-day week alongside its limitations\"]',4,'Metin önce savunucuların görüşlerini ve deney sonucunu, ardından eleştirileri veriyor: dengeli bir sunum. \'Prove\' ve \'always\' gibi kesin ifadeler metinde desteklenmiyor.',25,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(27,'[\"yds\",\"yokdil\",\"ielts\",\"toefl\",\"proficiency\"]','reading','C1','The concept of a four-day working week has gained traction in several countries. Proponents argue that shorter weeks lead to higher productivity, better mental health and lower carbon emissions from commuting. A large trial in the United Kingdom found that most participating companies maintained their output while employees reported less stress. Critics, however, caution that the model may not suit every sector; hospitals and schools, for instance, cannot simply close for an extra day.','It can be inferred from the passage that the UK trial ----.','[\"only included hospitals and schools\",\"did not lead to a significant loss of output for most companies\",\"showed that critics were completely right\",\"increased carbon emissions from commuting\",\"was cancelled because employees felt stressed\"]',1,'\'Most participating companies maintained their output\' = çoğu şirket üretimini korudu, yani önemli bir kayıp yaşanmadı. Diğer şıklar metinle çelişiyor.',26,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(28,'[\"yds\",\"ydt\"]','dialogue','B1',NULL,'Emma: I\'ve been offered a job in Berlin, but I don\'t speak any German.\nLeo: ----\nEmma: That\'s true. Most of my colleagues would speak English anyway.','[\"Berlin is the capital of Germany, isn\'t it?\",\"I have never been to Berlin myself.\",\"German is a very difficult language to learn.\",\"You should never accept a job abroad.\",\"Well, a lot of international companies there work in English.\"]',4,'Emma\'nın cevabı (\'That\'s true... English anyway\') Leo\'nun İngilizcenin iş dili olduğunu söylediğini gösterir. E şıkkı endişeyi artırır ve \'That\'s true\' ile desteklenemez.',27,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(29,'[\"yds\",\"ydt\"]','dialogue','B2',NULL,'Doctor: Your test results look fine, but you seem quite tired.\nPatient: ----\nDoctor: Then try to switch off your phone an hour before bed.','[\"I\'ve been having trouble sleeping; I usually check messages until midnight.\",\"Can I get a copy of my test results?\",\"I feel great, I sleep nine hours every night.\",\"I don\'t like taking medicine.\",\"My sister is also a doctor.\"]',0,'Doktorun tavsiyesi (telefonu yatmadan önce kapat) hastanın uyku ve telefon kullanımıyla ilgili bir sorun anlattığını gösterir.',28,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(30,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','paragraph','B2',NULL,'Plastic waste is one of the most serious environmental problems of our time. Every year, millions of tonnes of plastic end up in the oceans, harming marine life. ----. As a result, several countries have banned single-use plastic bags and straws.','[\"Oceans cover more than seventy percent of the Earth\'s surface\",\"Some people prefer paper bags because they look nicer\",\"Plastic was invented at the beginning of the twentieth century\",\"Many sea animals mistake small plastic pieces for food and die\",\"Recycling centres are usually closed at weekends\"]',3,'Boşluk, deniz canlılarına verilen zararı açıklamalı ve \'As a result... banned\' sonucuna zemin hazırlamalı. Diğer şıklar konu dışı bilgiler veriyor.',29,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(31,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','paragraph','C1',NULL,'Learning a second language changes the brain in measurable ways. ----. For example, bilingual people often perform better on tasks that require switching attention between different activities. Some studies even suggest that speaking two languages may delay the onset of dementia.','[\"Research shows that it strengthens areas linked to attention and memory\",\"Some languages have more than twenty vowel sounds\",\"It is easier to learn a language as a child than as an adult\",\"Many schools in Europe teach English from primary level\",\"Translators usually work with at least three languages\"]',0,'Boşluktan sonra gelen \'For example\' dikkat değiştirme becerisinden bahsediyor; boşluk bu örneği kapsayan genel bir iddia olmalı: dikkat ve hafıza bölgelerinin güçlenmesi.',30,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(32,'[\"yds\",\"yokdil\",\"ydt\"]','irrelevant','B2',NULL,'(I) Coffee is one of the most traded commodities in the world. (II) It is grown in more than seventy countries, mainly in tropical regions. (III) Brazil alone produces about a third of the global supply. (IV) Tea, on the other hand, originated in China thousands of years ago. (V) Changes in weather in coffee-growing areas can therefore affect prices worldwide.','[\"I\",\"II\",\"III\",\"IV\",\"V\"]',3,'Paragraf kahve üretimi ve ticaretini anlatıyor. IV. cümle çayın kökenine geçerek akışı bozuyor; V. cümle \'therefore\' ile III\'e bağlanıyor.',31,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(33,'[\"yds\",\"yokdil\",\"ydt\"]','irrelevant','C1',NULL,'(I) Remote work has transformed the daily lives of millions of employees. (II) Without long commutes, many workers report having more time for family and exercise. (III) The first computer mouse was made of wood. (IV) At the same time, some people feel isolated and miss informal chats with colleagues. (V) Companies are therefore experimenting with hybrid models that combine home and office work.','[\"I\",\"II\",\"III\",\"IV\",\"V\"]',2,'Paragraf uzaktan çalışmanın etkilerini tartışıyor. III. cümle bilgisayar faresinin tarihine dair ilgisiz bir bilgi.',32,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(34,'[\"ielts\",\"toefl\",\"proficiency\"]','vocabulary','C1',NULL,'The lecturer gave a ---- overview of the topic, covering its history, current debates and future directions in just twenty minutes.','[\"superficial\",\"tedious\",\"fragile\",\"reluctant\",\"comprehensive\"]',4,'Tarihi, güncel tartışmaları ve geleceği kapsayan bir özet \'comprehensive\' (kapsamlı) olur. Superficial (yüzeysel) \'covering its history, current debates...\' ile çelişir.',33,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(35,'[\"ielts\",\"toefl\",\"proficiency\"]','grammar','B2',NULL,'Hardly ---- the lecture started when the fire alarm went off.','[\"have\",\"was\",\"had\",\"has\",\"did\"]',2,'\'Hardly ... when\' kalıbı devrik past perfect ile kurulur: Hardly had the lecture started when... (ders yeni başlamıştı ki...).',34,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(36,'[\"ielts\",\"toefl\",\"yds\",\"proficiency\"]','reading','B2','Coral reefs cover less than one percent of the ocean floor, yet they support about a quarter of all marine species. Rising sea temperatures cause corals to expel the tiny algae living inside them, a process known as bleaching. Bleached corals are not dead, but they are under severe stress and may die if temperatures stay high for too long.','According to the passage, bleached corals ----.','[\"are always dead\",\"can still survive if conditions improve in time\",\"cover a quarter of the ocean floor\",\"produce more algae than healthy corals\",\"are found only in cold water\"]',1,'\'Bleached corals are not dead... may die if temperatures stay high for too long\': sıcaklık zamanında düşerse hayatta kalabilirler. \'Always dead\' metinle çelişiyor.',35,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(37,'[\"yds\",\"yokdil\",\"proficiency\"]','vocabulary','C1',NULL,'The findings of the study are ---- with earlier research, which also linked poor sleep to weaker memory.','[\"incompatible\",\"exhausted\",\"reluctant\",\"consistent\",\"indifferent\"]',3,'\'Which also linked\' (o da ilişkilendirmişti) önceki araştırmalarla uyumu gösterir: consistent with = ile tutarlı. Incompatible tam tersidir.',36,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(38,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','grammar','B2',NULL,'The students were asked ---- their mobile phones during the exam.','[\"not using\",\"don\'t use\",\"not use\",\"not to use\",\"to not using\"]',3,'\'Ask someone (not) to do something\' kalıbı: olumsuz emir \'not to + V1\' ile verilir. Edilgen yapıda da aynı kalır: were asked not to use.',37,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(39,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','sentence_completion','C1',NULL,'The medicine was withdrawn from the market ----.','[\"so that more patients could buy it\",\"as soon as it became the best-selling drug\",\"after it was found to cause serious side effects in some patients\",\"because it had been extremely effective\",\"even though doctors had never prescribed it\"]',2,'Bir ilacın piyasadan çekilmesinin mantıklı nedeni ciddi yan etkilerdir. B ve C şıkları neden sonuç ilişkisini tersine çeviriyor.',38,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(40,'[\"ydt\"]','dialogue','B1',NULL,'Can: Are you coming to the concert on Saturday?\nMert: ----\nCan: Oh, that\'s a pity. Maybe next time then.','[\"Of course, I\'ve already bought my ticket!\",\"What time does it start?\",\"I\'d love to, but I have to study for my exam.\",\"Who is playing?\",\"Saturday is my favourite day.\"]',2,'Can\'ın \'That\'s a pity. Maybe next time\' demesi Mert\'in gelemeyeceğini gösterir. B şıkkı olumlu bir cevap olduğu için \'pity\' ile uyuşmaz.',39,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(41,'[\"yds\",\"yokdil\"]','translation','C1',NULL,'Bu çalışmanın amacı, sosyal medya kullanımının gençlerin uyku düzeni üzerindeki etkisini incelemektir.','[\"The aim of this study is to examine the effect of social media use on young people\'s sleep patterns.\",\"This study aims to reduce young people\'s use of social media before sleeping.\",\"This study shows that young people who use social media sleep less.\",\"The aim of social media is to change the sleep patterns of young people.\",\"Young people\'s sleep patterns were examined by social media users in this study.\"]',0,'\'Amacı ... incelemektir\' = The aim ... is to examine. B şıkkı bir sonuç iddia ediyor, E şıkkı amacı \'azaltmak\' olarak değiştiriyor.',40,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(42,'[\"lgs\"]','dialogue','A2',NULL,'Ayşe: Would you like to come to my birthday party on Saturday?\nCan: ----. I have to visit my grandparents.','[\"I\'d love to, but I can\'t\",\"I\'m going to bring a cake\",\"That sounds great, see you there\",\"Yes, of course I will\"]',0,'Can davete gelemeyeceğini söylüyor ve sebep veriyor. Kibarca reddetmenin kalıbı: \"I\'d love to, but I can\'t\". Diğer seçenekler kabul ediyor.',41,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(43,'[\"lgs\"]','dialogue','A2',NULL,'Mert: How often do you surf the Net?\nEce: ----','[\"Because it is fun\",\"For two hours\",\"Twice a day, usually after school\",\"On my computer\"]',2,'\"How often\" sıklık sorar. Cevap sıklık bildirmeli: twice a day. \"For two hours\" süre, \"because\" sebep bildirir.',42,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(44,'[\"lgs\"]','vocabulary','A2',NULL,'My brother always helps my mother in the kitchen. He ---- the table before dinner every evening.','[\"takes\",\"does\",\"makes\",\"sets\"]',3,'\"Set the table\" sofrayı kurmak demek. Ev işleri ünitesinin kalıp ifadesi.',43,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(45,'[\"lgs\"]','grammar','A2',NULL,'If it rains tomorrow, we ---- the picnic.','[\"cancel\",\"will cancel\",\"cancelled\",\"are cancelling\"]',1,'Gelecekle ilgili koşul: If + şimdiki zaman, will + fiil.',44,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(46,'[\"lgs\"]','reading','A2','Hi Ali,\nOur science project about volcanoes is due next week, and we haven\'t finished it yet. Let\'s meet at the library on Saturday at 2 pm. Can you bring the poster paper?\nZeynep','Which of the following is TRUE according to the message?','[\"They will meet on Sunday morning.\",\"Zeynep has finished the project.\",\"Zeynep wants to meet at the library.\",\"The project is about animals.\"]',2,'Mesajda \"Let\'s meet at the library on Saturday at 2 pm\" yazıyor. Proje volkanlarla ilgili, bitmemiş, gün Cumartesi.',45,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(47,'[\"lgs\"]','reading','A2','DURING AN EARTHQUAKE\nDROP to the ground.\nCOVER your head under a strong table.\nHOLD ON until the shaking stops.\nStay away from windows!','What is the poster about?','[\"A safety rule for earthquakes\",\"A school trip to a museum\",\"A new library opening\",\"A cooking competition\"]',0,'\"Drop, cover and hold on\" depremde yapılacakları anlatır; afiş bir güvenlik kuralıdır.',46,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(48,'[\"lgs\"]','vocabulary','A2',NULL,'Teenagers usually like ---- time with their friends at weekends.','[\"to spend money\",\"spend on\",\"spent\",\"spending\"]',3,'\"Like\" fiilinden sonra -ing kullanılır: like spending time.',47,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(49,'[\"lgs\"]','dialogue','A2',NULL,'Waiter: Are you ready to order?\nCustomer: ----','[\"I\'m fine, thanks.\",\"It costs ten liras.\",\"No, the restaurant is closed.\",\"Yes, I\'ll have the vegetable soup, please.\"]',3,'Sipariş sorusuna verilecek doğal cevap sipariş vermektir.',48,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(50,'[\"lgs\"]','grammar','A2',NULL,'Kerem is ---- student in our class. He always gets full marks.','[\"the most hardworking\",\"more hardworking\",\"hardworking than\",\"as hardworking\"]',0,'Bir grubun içinde en: the most + sıfat (üstünlük derecesi).',49,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(51,'[\"lgs\"]','reading','A2','FREE-TIME ACTIVITIES OF 8th GRADERS\nPlaying video games: 40%\nDoing sports: 25%\nWatching TV: 20%\nReading books: 15%','According to the chart, which activity do most students prefer?','[\"Playing video games\",\"Doing sports\",\"Reading books\",\"Watching TV\"]',0,'Tabloda en yüksek yüzde (%40) video oyunlarına ait.',50,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(52,'[\"lgs\"]','dialogue','A2',NULL,'Selin: Hello, can I speak to Mr. Aydın, please?\nSecretary: ----','[\"He is fifty years old.\",\"Yes, I\'m speaking English.\",\"Just a moment, I\'ll put you through.\",\"Goodbye, have a nice day.\"]',2,'Telefonda birini istemek. Uygun cevap \"Hold on / I\'ll put you through\".',51,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(53,'[\"lgs\"]','vocabulary','A2',NULL,'Strong winds and heavy rain hit the city last night. It was a terrible ----.','[\"storm\",\"sunrise\",\"drought\",\"heatwave\"]',0,'Kuvvetli rüzgar ve yağmur bir fırtınayı (storm) anlatır. Doğal afetler ünitesi.',52,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(54,'[\"lgs\"]','dialogue','A2',NULL,'Emre: How about going to the cinema this evening?\nMert: ----. I have a science project to finish.','[\"Sure, let\'s meet at seven\",\"I\'ve already seen it twice\",\"What a great idea\",\"Sorry, I can\'t make it\"]',3,'Mert\'in bir projesi var, yani daveti reddediyor. Kibar ret kalıbı: Sorry, I can\'t make it.',53,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(55,'[\"lgs\"]','dialogue','A2',NULL,'Zeynep: Could you help me with my English homework?\nAli: ----. Let\'s start with the first question.','[\"Of course, I\'d be happy to\",\"It was very difficult\",\"No, I don\'t like English\",\"I\'m sorry, I\'m not free\"]',0,'Ali ardından \'Let\'s start\' diyor; demek ki kabul ediyor. Kabul kalıbı: Of course, I\'d be happy to.',54,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(56,'[\"lgs\"]','dialogue','A2',NULL,'Selin: I\'m sorry, but I broke your pencil.\nDeniz: ----. I have another one.','[\"Never mind\",\"Congratulations\",\"Good luck\",\"Help yourself\"]',0,'Özrü kabul edip önemsizleştirmek için \'Never mind\' (önemli değil) denir.',55,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(57,'[\"lgs\"]','vocabulary','A2',NULL,'My best friend is very ----. She always tells the truth and never breaks her promises.','[\"lazy\",\"reliable\",\"rude\",\"selfish\"]',1,'Hep doğruyu söyleyen ve sözünü tutan biri güvenilirdir: reliable.',56,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(58,'[\"lgs\"]','vocabulary','A2',NULL,'Before you ---- the vegetables, wash them carefully under cold water.','[\"borrow\",\"download\",\"chop\",\"invite\"]',2,'Sebzelerle yapılan mutfak eylemi \'chop\' (doğramak).',57,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(59,'[\"lgs\"]','vocabulary','A2',NULL,'Don\'t share your password with anyone. It is important for online ----.','[\"tourism\",\"safety\",\"furniture\",\"weather\"]',1,'Şifre paylaşmamak internet güvenliğiyle ilgili: online safety.',58,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(60,'[\"lgs\"]','vocabulary','A2',NULL,'Bungee jumping is too ---- for me. I prefer safe activities like hiking.','[\"boring\",\"cheap\",\"dangerous\",\"peaceful\"]',2,'Güvenli aktiviteleri tercih ettiğini söylüyor; bungee jumping onun için tehlikeli: dangerous.',59,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(61,'[\"lgs\"]','grammar','A2',NULL,'I ---- my room every Saturday, and my brother does the dishes.','[\"tidied\",\"tidy\",\"am tidy\",\"tidies\"]',1,'Her cumartesi yapılan rutin, özne \'I\': geniş zaman, yalın fiil: tidy.',60,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(62,'[\"lgs\"]','grammar','A2',NULL,'Earthquakes are ---- than storms because we can\'t predict them.','[\"the most dangerous\",\"most dangerous\",\"more dangerous\",\"dangerouser\"]',2,'İki şey karşılaştırılıyor ve \'than\' var. Uzun sıfat: more dangerous.',61,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(63,'[\"lgs\"]','grammar','A2',NULL,'Last summer we ---- to Cappadocia and took a hot air balloon ride.','[\"go\",\"have go\",\"going\",\"went\"]',3,'\'Last summer\' geçmiş zaman ister: go → went.',62,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(64,'[\"lgs\"]','reading','A2','Hi, I\'m Kerem. I\'m a big fan of science. Every Wednesday after school, I go to the science club. We do experiments and learn about natural forces like earthquakes and floods. Last week we built a small model of a safe house. Next month, our club is going to visit the planetarium in Ankara.','Which of the following is TRUE according to the text?','[\"Kerem goes to the science club every day\",\"They built a real house last week\",\"Kerem doesn\'t like science\",\"Kerem\'s club is going to visit a planetarium\"]',3,'Metnin sonunda \'Next month, our club is going to visit the planetarium\' deniyor.',63,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(65,'[\"lgs\"]','reading','A2','Hi, I\'m Kerem. I\'m a big fan of science. Every Wednesday after school, I go to the science club. We do experiments and learn about natural forces like earthquakes and floods. Last week we built a small model of a safe house. Next month, our club is going to visit the planetarium in Ankara.','When does Kerem go to the science club?','[\"Every morning\",\"On Wednesdays after school\",\"At the weekend\",\"Only in summer\"]',1,'\'Every Wednesday after school\' ifadesi cevabı veriyor.',64,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(66,'[\"lgs\"]','reading','A2','Online Safety Rules\n1. Never share your home address.\n2. Use strong passwords with numbers and symbols.\n3. Don\'t accept friend requests from strangers.\n4. Tell an adult if something online makes you uncomfortable.','Which rule is NOT mentioned in the poster?','[\"Turn off your computer at night\",\"Tell an adult about problems\",\"Don\'t accept requests from strangers\",\"Use strong passwords\"]',0,'Afişte bilgisayarı kapatmakla ilgili bir kural yok; diğer üçü listede var.',65,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(67,'[\"lgs\"]','reading','A2','Tourism in Turkey\nMany tourists visit Turkey every year. Antalya is famous for its beaches, Cappadocia for its fairy chimneys and Istanbul for its history. Most visitors come in summer, but winter is the best time for Erzurum because of skiing.','Why do people visit Erzurum in winter?','[\"To swim in the sea\",\"To see fairy chimneys\",\"To visit old palaces\",\"To go skiing\"]',3,'Metne göre Erzurum kış için en iyisi \'because of skiing\'.',66,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(68,'[\"lgs\"]','dialogue','A2',NULL,'Mom: Can you set the table, please?\nAyşe: ----. Where are the forks?','[\"Sure, no problem\",\"I\'ve already eaten\",\"It\'s not my turn\",\"I\'m doing my homework\"]',0,'Ayşe çatalları soruyor; yani masayı kurmayı kabul ediyor: Sure, no problem.',67,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(69,'[\"ielts\",\"toefl\"]','vocabulary','B2',NULL,'Urban planners argue that green spaces can significantly ---- the stress levels of city residents.','[\"aggravate\",\"allocate\",\"alleviate\",\"accumulate\"]',2,'Yeşil alanlar stresi azaltır: alleviate (hafifletmek). Aggravate kötüleştirir, diğerleri anlamsız.',68,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(70,'[\"ielts\",\"toefl\"]','vocabulary','B2',NULL,'The lecturer gave a ---- overview of the topic before discussing the details.','[\"verbose\",\"concise\",\"fragile\",\"reluctant\"]',1,'Detaylardan önce verilen kısa özet: concise (öz).',69,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(71,'[\"ielts\",\"toefl\"]','vocabulary','B2',NULL,'Remote work has become increasingly ---- since the pandemic, with many companies adopting hybrid models.','[\"obsolete\",\"scarce\",\"trivial\",\"prevalent\"]',3,'Uzaktan çalışma yaygınlaştı: prevalent (yaygın).',70,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(72,'[\"ielts\",\"toefl\"]','grammar','B2',NULL,'Had the researchers collected more data, their conclusions ---- more reliable.','[\"had been\",\"would be being\",\"will be\",\"would have been\"]',3,'Devrik third conditional (Had + V3) → sonuç kısmı \'would have been\'.',71,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(73,'[\"ielts\",\"toefl\"]','grammar','B2',NULL,'Not only ---- the price of housing, but it has also affected public transport.','[\"has tourism increased\",\"tourism has increased\",\"tourism increased\",\"did tourism increasing\"]',0,'\'Not only\' cümle başındaysa devrik yapı gelir: has tourism increased.',72,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(74,'[\"ielts\",\"toefl\"]','grammar','B1',NULL,'The number of students studying abroad ---- steadily over the last decade.','[\"has risen\",\"have risen\",\"is rising since\",\"rose up\"]',0,'\'The number of\' tekil özne; \'over the last decade\' present perfect: has risen.',73,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(75,'[\"ielts\",\"toefl\"]','sentence_completion','B2',NULL,'Although the city invested heavily in cycle lanes, ----.','[\"it was a successful project\",\"the cycle lanes were very popular\",\"many residents still prefer to drive to work\",\"more people started cycling to work\"]',2,'\'Although\' zıtlık kurar: yatırıma rağmen insanlar hâlâ araba kullanıyor.',74,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(76,'[\"ielts\",\"toefl\"]','sentence_completion','B2',NULL,'Unless governments take immediate action, ----.','[\"the summit had been successful\",\"renewable energy was very cheap\",\"we reduced emissions last year\",\"global temperatures will continue to rise\"]',3,'\'Unless\' + present → sonuç gelecekte (will). Anlamca da uygun olan bu.',75,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(77,'[\"ielts\",\"toefl\"]','reading','B2','Sleep researchers have found that teenagers\' internal clocks shift later during adolescence, making it biologically difficult for them to fall asleep before 11 pm. Schools that delayed their start times by just one hour reported improved attendance, fewer car accidents among teenage drivers and better grades in morning classes.','What is the main idea of the passage?','[\"Teenagers are lazier than adults\",\"Later school start times can benefit teenagers\",\"Morning classes should be cancelled\",\"Car accidents are caused by schools\"]',1,'Paragraf, gençlerin biyolojik saatinin geç kaydığını ve okulu geç başlatmanın faydalarını anlatıyor.',76,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(78,'[\"ielts\",\"toefl\"]','reading','B2','Sleep researchers have found that teenagers\' internal clocks shift later during adolescence, making it biologically difficult for them to fall asleep before 11 pm. Schools that delayed their start times by just one hour reported improved attendance, fewer car accidents among teenage drivers and better grades in morning classes.','According to the passage, which was NOT reported by schools that started later?','[\"Higher fees for parents\",\"Fewer car accidents\",\"Better morning grades\",\"Better attendance\"]',0,'Ücretlerden hiç söz edilmiyor; diğer üçü metinde sayılıyor.',77,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(79,'[\"ielts\",\"toefl\"]','reading','B1','The town library has introduced a \'Library of Things\'. Instead of books, members can borrow tools, sewing machines, camping equipment and even musical instruments for up to two weeks. The aim is to reduce waste and help people save money on items they rarely use.','Why did the library start the \'Library of Things\'?','[\"To reduce waste and save people money\",\"To replace all its books\",\"To sell old equipment\",\"To teach people music\"]',0,'Son cümle amacı açıkça veriyor: reduce waste and help people save money.',78,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(80,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','vocabulary','B2',NULL,'The government has decided to ---- the new regulations until the economic situation becomes more stable.','[\"undermine\",\"dominate\",\"illuminate\",\"accelerate\",\"postpone\"]',4,'Ekonomi düzelene kadar düzenlemeleri ertelemek: postpone.',79,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(81,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','vocabulary','C1',NULL,'Despite the ---- evidence presented in court, the jury was not convinced of the defendant\'s guilt.','[\"conclusive\",\"spontaneous\",\"unanimous\",\"circumstantial\",\"redundant\"]',3,'\'Despite\' zıtlık kurar; jüri ikna olmadıysa delil dolaylıydı: circumstantial. Conclusive (kesin) zıtlığı bozar.',80,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(82,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','grammar','B2',NULL,'By the time the rescue team arrived, the fire ---- most of the forest.','[\"was destroying\",\"had destroyed\",\"has destroyed\",\"would destroy\",\"destroys\"]',1,'\'By the time\' + past simple → daha önce tamamlanan eylem past perfect: had destroyed.',81,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(83,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','grammar','B2',NULL,'---- the new drug proved effective in early trials, scientists remain cautious about its long-term effects.','[\"So that\",\"Even though\",\"As long as\",\"Unless\",\"Because\"]',1,'Etkili olmasına rağmen temkinliler: zıtlık bağlacı \'Even though\'.',82,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(84,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','sentence_completion','B2',NULL,'If more funding had been allocated to early-warning systems, ----.','[\"people evacuate their homes quickly\",\"the systems are working well now\",\"the government had built new dams\",\"the damage caused by the flood could have been reduced\",\"the flood will cause less damage\"]',3,'Third conditional (had been allocated) → could have been reduced.',83,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(85,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','translation','B2',NULL,'Araştırmacılar, düzenli egzersizin yaşlı yetişkinlerde hafıza kaybını önemli ölçüde yavaşlatabileceğini öne sürüyor.','[\"Researchers have proved that older adults never lose memory if they exercise.\",\"Researchers suggest that regular exercise can significantly slow memory loss in older adults.\",\"Older adults who suggest exercise to researchers slow their memory loss.\",\"Memory loss in older adults is caused by a lack of regular exercise, say researchers.\",\"Regular exercise is suggested by older adults to researchers for memory.\"]',1,'Özne (araştırmacılar), fiil (öne sürüyor = suggest), modal (-ebileceğini = can) ve \'önemli ölçüde\' (significantly) birebir karşılanan seçenek A.',84,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(86,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','dialogue','B1',NULL,'Mert: I\'ve been offered a job in Berlin, but I\'m not sure whether to accept it.\nAylin: ----\nMert: The salary is great, but I\'d have to leave my family behind.','[\"What\'s making you hesitate?\",\"Is the job in Istanbul?\",\"Why did you reject the offer?\",\"I\'ve never been to Berlin.\",\"Congratulations, when do you start?\"]',0,'Mert\'in cevabı tereddüdünün sebeplerini açıklıyor; soru da \'Seni tereddüde düşüren ne?\' olmalı.',85,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(87,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','cloze','B2','Coffee was first discovered in Ethiopia, (1) ---- legend says a goat herder noticed his animals becoming energetic after eating certain berries. (2) ---- the fifteenth century, it was being grown in Yemen.','(1) boşluğu için en uygun seçenek hangisidir?','[\"when\",\"which\",\"whose\",\"where\",\"what\"]',3,'Bir yer (Ethiopia) tanımlanıyor: where.',86,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(88,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','paragraph','B2',NULL,'Bees play a crucial role in agriculture. ---- In fact, about one third of the food we eat depends on pollination. Without bees, the prices of fruit and vegetables would rise dramatically.','[\"Beekeeping is a popular hobby in Turkey.\",\"Some people are afraid of being stung.\",\"Honey has been used as medicine for centuries.\",\"Many crops rely on them for pollination.\",\"Wasps are often confused with bees.\"]',3,'Boşluktan sonra \'In fact … depends on pollination\' geliyor; boşluk tozlaşma fikrini girmeli.',87,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(89,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','irrelevant','B2',NULL,'(I) Social media allows people to stay connected across long distances. (II) However, excessive use has been linked to anxiety among teenagers. (III) The first smartphone was released in 1994. (IV) Some experts therefore recommend limiting screen time. (V) Schools are also starting to teach digital wellbeing.','[\"I\",\"II\",\"III\",\"IV\",\"V\"]',2,'Paragraf sosyal medyanın etkileri ve önlemler hakkında; ilk akıllı telefonun tarihi (III) akışı bozuyor.',88,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(90,'[\"lgs\"]','reading','A2','Hi Ece,\nThanks for inviting me to your birthday party on Saturday! I\'d love to come, but I have a piano exam at 11 a.m. It usually takes two hours. Can I come after that? I\'ll bring the board games we played last time. By the way, is it OK if my cousin Mert comes with me? He is staying with us this week.\nSee you soon,\nDuru','Why can\'t Duru arrive at the party early?','[\"She has to buy some board games.\",\"She doesn\'t like birthday parties.\",\"She has a piano exam in the morning.\",\"She has to look after her cousin.\"]',2,'Metinde \'I have a piano exam at 11 a.m.\' diyor. Sınav iki saat sürdüğü için partiye sonra gelecek. Kuzen ve oyunlar dikkat dağıtan ayrıntılar.',89,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(91,'[\"lgs\"]','reading','A2','Hi Ece,\nThanks for inviting me to your birthday party on Saturday! I\'d love to come, but I have a piano exam at 11 a.m. It usually takes two hours. Can I come after that? I\'ll bring the board games we played last time. By the way, is it OK if my cousin Mert comes with me? He is staying with us this week.\nSee you soon,\nDuru','Which of the following is TRUE according to the message?','[\"The party is on Sunday.\",\"Mert is Ece\'s cousin.\",\"Duru wants to bring someone with her.\",\"Duru refuses the invitation.\"]',2,'Duru \'is it OK if my cousin Mert comes with me?\' diye soruyor. Mert, Ece\'nin değil Duru\'nun kuzeni; parti cumartesi.',90,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(92,'[\"lgs\"]','reading','A2','Teen Survey: How do you spend your free time?\nWe asked 200 students at Atatürk Middle School.\n- Playing online games: 35%\n- Doing sports: 25%\n- Hanging out with friends: 20%\n- Reading books: 12%\n- Watching TV series: 8%\nMost students said they spend more than two hours a day online. Only a few students said they read books every day.','According to the survey, which activity is the second most popular?','[\"Doing sports\",\"Hanging out with friends\",\"Reading books\",\"Playing online games\"]',0,'Yüzdeleri sıralayınca: oyun %35, spor %25. İkinci sıradaki etkinlik spor.',91,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(93,'[\"lgs\"]','reading','A2','Teen Survey: How do you spend your free time?\nWe asked 200 students at Atatürk Middle School.\n- Playing online games: 35%\n- Doing sports: 25%\n- Hanging out with friends: 20%\n- Reading books: 12%\n- Watching TV series: 8%\nMost students said they spend more than two hours a day online. Only a few students said they read books every day.','Which statement can be made from the survey?','[\"Fewer students read books than do sports.\",\"Most students prefer watching TV series to reading.\",\"Nobody spends time online.\",\"Hanging out with friends is the least popular activity.\"]',0,'Kitap okuma %12, spor %25; kitap okuyanlar daha az. TV dizisi %8 ile kitaptan düşük, bu yüzden A yanlış.',92,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(94,'[\"lgs\"]','reading','A2','Science Museum Rules\n- Please don\'t touch the exhibits unless there is a green hand sign.\n- Taking photos is allowed, but you mustn\'t use a flash.\n- Food and drinks are only allowed in the café.\n- Children under 12 must stay with an adult.\n- The 3D cinema show starts every hour. Tickets are sold at the entrance.','Elif is 10 years old and wants to visit the museum alone. What should she know?','[\"She can eat her sandwich next to the exhibits.\",\"She can visit the museum without an adult.\",\"She must come with an adult.\",\"She can\'t take any photos.\"]',2,'\'Children under 12 must stay with an adult.\' Elif 10 yaşında olduğu için yanında bir yetişkin olmalı.',93,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(95,'[\"lgs\"]','reading','A2','Science Museum Rules\n- Please don\'t touch the exhibits unless there is a green hand sign.\n- Taking photos is allowed, but you mustn\'t use a flash.\n- Food and drinks are only allowed in the café.\n- Children under 12 must stay with an adult.\n- The 3D cinema show starts every hour. Tickets are sold at the entrance.','Which of the following is NOT allowed in the museum?','[\"Buying a ticket for the 3D cinema\",\"Touching exhibits with a green hand sign\",\"Taking photos without a flash\",\"Using a flash while taking photos\"]',3,'\'You mustn\'t use a flash.\' Fotoğraf serbest ama flaş yasak. Yeşil el işaretli nesnelere dokunmak serbest.',94,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(96,'[\"lgs\"]','reading','A2','Kerem: I\'m thinking of making a short film about recycling for the school festival. Do you want to join me?\nSelin: Sounds great! But we don\'t have a good camera.\nKerem: No problem. My brother can lend us his. Can you write the script?\nSelin: Sure. I\'m better at writing than acting anyway. Who will be in the film?\nKerem: Let\'s ask Arda and Zeynep. They love acting.','What will Selin do for the film?','[\"She will write the script.\",\"She will lend a camera.\",\"She will act in it.\",\"She will choose the festival.\"]',0,'Kerem \'Can you write the script?\' diye soruyor, Selin \'Sure\' diyor. Oyunculuk Arda ve Zeynep\'e kalıyor.',95,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(97,'[\"lgs\"]','reading','A2','Kerem: I\'m thinking of making a short film about recycling for the school festival. Do you want to join me?\nSelin: Sounds great! But we don\'t have a good camera.\nKerem: No problem. My brother can lend us his. Can you write the script?\nSelin: Sure. I\'m better at writing than acting anyway. Who will be in the film?\nKerem: Let\'s ask Arda and Zeynep. They love acting.','What is the film going to be about?','[\"A school festival\",\"Kerem\'s brother\",\"Acting lessons\",\"Recycling\"]',3,'İlk cümle: \'a short film about recycling\'. Festival, filmin gösterileceği yer.',96,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(98,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','reading','B2','Sleep was long regarded as a passive state in which the brain simply switched off. Research over the past two decades has overturned this view. During deep sleep, the brain actively replays and strengthens the memories formed during the day, a process known as consolidation. At the same time, a network of channels around blood vessels, sometimes called the glymphatic system, clears away waste proteins that accumulate while we are awake. Some of these proteins have been linked to neurodegenerative diseases such as Alzheimer\'s. Consequently, chronic sleep deprivation may do more than leave us tired; it could, over many years, compromise the brain\'s ability to maintain itself. Nevertheless, researchers caution that most of the evidence so far comes from animal studies, and that the precise relationship between poor sleep and disease in humans remains to be established.','According to the passage, the traditional view of sleep was that ----.','[\"it removed waste proteins from the brain\",\"it strengthened memories formed during the day\",\"it was mainly studied in animals\",\"it caused neurodegenerative diseases\",\"the brain was largely inactive during it\"]',4,'İlk cümle: \'regarded as a passive state in which the brain simply switched off\'. Diğer seçenekler yeni araştırmaların bulguları.',97,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(99,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','reading','B2','Sleep was long regarded as a passive state in which the brain simply switched off. Research over the past two decades has overturned this view. During deep sleep, the brain actively replays and strengthens the memories formed during the day, a process known as consolidation. At the same time, a network of channels around blood vessels, sometimes called the glymphatic system, clears away waste proteins that accumulate while we are awake. Some of these proteins have been linked to neurodegenerative diseases such as Alzheimer\'s. Consequently, chronic sleep deprivation may do more than leave us tired; it could, over many years, compromise the brain\'s ability to maintain itself. Nevertheless, researchers caution that most of the evidence so far comes from animal studies, and that the precise relationship between poor sleep and disease in humans remains to be established.','The word \'compromise\' in the passage is closest in meaning to ----.','[\"measure\",\"replace\",\"weaken\",\"improve\",\"delay\"]',2,'Compromise burada \'zayıflatmak, zarar vermek\' anlamında. Bağlam uykusuzluğun beynin kendini koruma yeteneğine zarar vermesinden söz ediyor.',98,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(100,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','reading','C1','Sleep was long regarded as a passive state in which the brain simply switched off. Research over the past two decades has overturned this view. During deep sleep, the brain actively replays and strengthens the memories formed during the day, a process known as consolidation. At the same time, a network of channels around blood vessels, sometimes called the glymphatic system, clears away waste proteins that accumulate while we are awake. Some of these proteins have been linked to neurodegenerative diseases such as Alzheimer\'s. Consequently, chronic sleep deprivation may do more than leave us tired; it could, over many years, compromise the brain\'s ability to maintain itself. Nevertheless, researchers caution that most of the evidence so far comes from animal studies, and that the precise relationship between poor sleep and disease in humans remains to be established.','What can be inferred from the last sentence of the passage?','[\"Further research on humans is needed before firm conclusions can be drawn.\",\"The glymphatic system exists only in animals.\",\"Researchers no longer believe that sleep affects memory.\",\"The link between poor sleep and disease in humans has been fully proven.\",\"Animal studies are of no value in sleep research.\"]',0,'\'Remains to be established\' henüz kanıtlanmadığını gösterir; yani insanlarda daha fazla araştırma gerekir. A seçeneği tam tersini söylüyor.',99,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(101,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','reading','B2','Urban heat islands are areas within cities that are significantly warmer than the surrounding countryside. The phenomenon occurs because materials such as asphalt and concrete absorb solar radiation during the day and release it slowly at night, while the lack of vegetation reduces natural cooling through evaporation. In some large cities, night-time temperatures can be as much as ten degrees higher than in nearby rural areas. This is not merely a matter of comfort: during heatwaves, elevated temperatures increase the risk of heat-related illness, particularly among the elderly. To address the problem, a number of cities have introduced \'cool roofs\' painted in reflective colours, expanded parks and planted trees along streets. Although such measures cannot eliminate the effect entirely, studies suggest they can lower local temperatures by several degrees.','According to the passage, one reason cities are warmer than rural areas is that ----.','[\"there are fewer elderly people in the countryside\",\"urban materials store heat and release it slowly\",\"cool roofs absorb more heat than asphalt\",\"evaporation increases in cities\",\"rural areas receive less solar radiation\"]',1,'\'Asphalt and concrete absorb solar radiation during the day and release it slowly at night.\' E seçeneği tersini söylüyor: bitki azlığı buharlaşmayı azaltır.',100,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(102,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','reading','B2','Urban heat islands are areas within cities that are significantly warmer than the surrounding countryside. The phenomenon occurs because materials such as asphalt and concrete absorb solar radiation during the day and release it slowly at night, while the lack of vegetation reduces natural cooling through evaporation. In some large cities, night-time temperatures can be as much as ten degrees higher than in nearby rural areas. This is not merely a matter of comfort: during heatwaves, elevated temperatures increase the risk of heat-related illness, particularly among the elderly. To address the problem, a number of cities have introduced \'cool roofs\' painted in reflective colours, expanded parks and planted trees along streets. Although such measures cannot eliminate the effect entirely, studies suggest they can lower local temperatures by several degrees.','The author mentions the elderly in order to ----.','[\"suggest that parks are mainly used by older people\",\"explain why cities build cool roofs\",\"show that urban heat islands are only a comfort problem\",\"argue that rural areas are healthier\",\"illustrate a group especially vulnerable to high temperatures\"]',4,'\'This is not merely a matter of comfort\' cümlesinden sonra yaşlılar risk grubu örneği olarak veriliyor.',101,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(103,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','reading','C1','Urban heat islands are areas within cities that are significantly warmer than the surrounding countryside. The phenomenon occurs because materials such as asphalt and concrete absorb solar radiation during the day and release it slowly at night, while the lack of vegetation reduces natural cooling through evaporation. In some large cities, night-time temperatures can be as much as ten degrees higher than in nearby rural areas. This is not merely a matter of comfort: during heatwaves, elevated temperatures increase the risk of heat-related illness, particularly among the elderly. To address the problem, a number of cities have introduced \'cool roofs\' painted in reflective colours, expanded parks and planted trees along streets. Although such measures cannot eliminate the effect entirely, studies suggest they can lower local temperatures by several degrees.','Which of the following best describes the author\'s attitude towards the measures cities have taken?','[\"Indifferent\",\"Overly enthusiastic\",\"Completely dismissive\",\"Cautiously positive\",\"Highly critical\"]',3,'\'Cannot eliminate the effect entirely\' (sınırlı) ama \'can lower local temperatures by several degrees\' (faydalı): temkinli olumlu.',102,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(104,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','reading','B2','The term \'bilingual advantage\' refers to the claim that people who regularly use two languages perform better on tasks requiring attention control, such as ignoring irrelevant information or switching between rules. Early studies in the 2000s reported striking differences between bilingual and monolingual children. More recent large-scale studies, however, have frequently failed to replicate these results, and some researchers now argue that the original findings were influenced by small sample sizes and differences in the participants\' social backgrounds. This does not mean that learning a second language has no benefits. Its cultural, social and economic advantages are well documented. The debate concerns only whether bilingualism produces a general improvement in cognitive control beyond language itself.','According to the passage, recent large-scale studies ----.','[\"only studied monolingual children\",\"have often not found the same results as early studies\",\"show that a second language has no benefits\",\"have confirmed the bilingual advantage\",\"were based on very small samples\"]',1,'\'Have frequently failed to replicate these results\': yeni çalışmalar eski bulguları çoğu zaman tekrarlayamamış. Küçük örneklem eski çalışmaların sorunu.',103,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(105,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','reading','B2','The term \'bilingual advantage\' refers to the claim that people who regularly use two languages perform better on tasks requiring attention control, such as ignoring irrelevant information or switching between rules. Early studies in the 2000s reported striking differences between bilingual and monolingual children. More recent large-scale studies, however, have frequently failed to replicate these results, and some researchers now argue that the original findings were influenced by small sample sizes and differences in the participants\' social backgrounds. This does not mean that learning a second language has no benefits. Its cultural, social and economic advantages are well documented. The debate concerns only whether bilingualism produces a general improvement in cognitive control beyond language itself.','The word \'replicate\' is closest in meaning to ----.','[\"repeat\",\"publish\",\"exaggerate\",\"reject\",\"explain\"]',0,'Replicate = bir deneyi tekrarlayıp aynı sonucu elde etmek (repeat).',104,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(106,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','reading','C1','The term \'bilingual advantage\' refers to the claim that people who regularly use two languages perform better on tasks requiring attention control, such as ignoring irrelevant information or switching between rules. Early studies in the 2000s reported striking differences between bilingual and monolingual children. More recent large-scale studies, however, have frequently failed to replicate these results, and some researchers now argue that the original findings were influenced by small sample sizes and differences in the participants\' social backgrounds. This does not mean that learning a second language has no benefits. Its cultural, social and economic advantages are well documented. The debate concerns only whether bilingualism produces a general improvement in cognitive control beyond language itself.','It is clear from the passage that the debate is NOT about ----.','[\"the reliability of early studies\",\"the social and economic value of learning languages\",\"whether bilingualism improves general cognition\",\"whether bilinguals have better attention control\",\"the effect of sample size on results\"]',1,'Metin kültürel, sosyal ve ekonomik faydaların \'well documented\' olduğunu ve tartışmanın \'only\' bilişsel kontrolle ilgili olduğunu söylüyor.',105,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(107,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','paragraph','B2','Coral reefs cover less than one per cent of the ocean floor. ---- . They provide food and shelter for fish, protect coastlines from storms and support the livelihoods of millions of people. Yet rising sea temperatures are causing widespread bleaching, a process in which corals expel the algae that give them their colour and much of their energy.','Choose the sentence that best completes the paragraph.','[\"Therefore, they are of little importance to marine life\",\"Most tourists visit reefs during the summer months\",\"Algae can also be found in fresh water\",\"Storms have become less frequent in recent years\",\"Nevertheless, they are home to roughly a quarter of all marine species\"]',4,'Boşluktan önce \'çok küçük alan\', sonra \'pek çok fayda\' var. \'Nevertheless\' ile gelen zıtlık ve \'quarter of all marine species\' paragrafın akışına uyuyor.',106,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(108,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','irrelevant','B2','(I) The printing press, developed by Gutenberg around 1440, transformed the spread of knowledge in Europe. (II) Books, which had previously been copied by hand, could now be produced quickly and cheaply. (III) Paper was first invented in China many centuries earlier. (IV) As a result, literacy rates rose and new ideas circulated more widely. (V) Some historians even link the press to the Reformation and the Scientific Revolution.','Which sentence is irrelevant to the flow of the passage?','[\"I\",\"II\",\"III\",\"IV\",\"V\"]',2,'Paragraf matbaanın bilginin yayılmasına etkisini anlatıyor. III. cümle kâğıdın icadına geçiyor ve akışı bozuyor.',107,1,'2026-10-04 20:30:41','2026-10-04 20:30:41');
