INSERT INTO `lessons` (`id`, `unit_id`, `title`, `skill`, `kind`, `position`, `xp_reward`, `is_premium`, `story_id`, `scenario_key`, `exercises`, `meta`, `created_at`, `updated_at`) VALUES (1,1,'Kelimeler','vocabulary','lesson',0,15,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"hello\",\"merhaba\"],[\"goodbye\",\"ho\\u015f\\u00e7a kal\"],[\"name\",\"isim\"],[\"friend\",\"arkada\\u015f\"],[\"student\",\"\\u00f6\\u011frenci\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"teacher\\\" ne demek?\",\"options\":[\"yorgun\",\"\\u015fehir\",\"\\u00f6\\u011fretmen\",\"isim\"],\"answer\":2,\"audio\":\"teacher\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"Nice to meet you\",\"options\":[\"Nice to meet you\",\"Nice to see you\",\"Night to meet you\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Benim ad\\u0131m Deniz ve ben bir \\u00f6\\u011frenciyim.\",\"answer\":\"My name is Deniz and I am a student\",\"alternatives\":[],\"tiles\":[\"I\",\"is\",\"Deniz\",\"My\",\"friend\",\"am\",\"name\",\"student\",\"a\",\"and\",\"country\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"teacher\",\"\\u00f6\\u011fretmen\"],[\"country\",\"\\u00fclke\"],[\"city\",\"\\u015fehir\"],[\"happy\",\"mutlu\"],[\"tired\",\"yorgun\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"mutlu\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"happy\",\"friend\",\"goodbye\",\"city\"],\"answer\":0},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Nice to meet you, Mr Brown.\",\"translation\":\"Tan\\u0131\\u015ft\\u0131\\u011f\\u0131m\\u0131za memnun oldum, Bay Brown.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"She is my best friend\",\"answer\":\"She is my best friend\"}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(2,1,'Dilbilgisi','grammar','lesson',1,15,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"I ___ from Antalya.\",\"options\":[\"am\",\"is\",\"are\"],\"answer\":0,\"hint\":\"I \\u2192 am\"},{\"type\":\"fill\",\"prompt\":\"My teacher ___ very kind.\",\"options\":[\"am\",\"is\",\"are\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"We ___ in the same class.\",\"options\":[\"am\",\"is\",\"are\"],\"answer\":2},{\"type\":\"fill\",\"prompt\":\"___ you a student?\",\"options\":[\"Am\",\"Is\",\"Are\"],\"answer\":2},{\"type\":\"translate\",\"prompt\":\"O benim arkada\\u015f\\u0131m.\",\"answer\":\"She is my friend\",\"alternatives\":[\"She\'s my friend\",\"He is my friend\",\"He\'s my friend\"],\"tiles\":[\"She\",\"is\",\"am\",\"friend\",\"are\",\"my\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"My\",\"sister\",\"are\",\"a\",\"doctor\"],\"error_index\":2,\"options\":[\"is\",\"am\",\"be\"],\"answer\":0,\"explanation_tr\":\"\\\"My sister\\\" tekil (o) oldu\\u011fu i\\u00e7in \\\"is\\\" kullan\\u0131l\\u0131r. \\\"Are\\\" you, we, they i\\u00e7indir. Do\\u011frusu: My sister is a doctor.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I\'m happy to meet you.\",\"translation\":\"Seninle tan\\u0131\\u015ft\\u0131\\u011f\\u0131ma mutluyum.\"}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(3,1,'Okuma: Elif and Tom','reading','lesson',2,15,0,NULL,NULL,'[{\"type\":\"read\",\"title\":\"Elif and Tom\",\"passage\":\"Hello! My name is Elif. I am twelve and I am a student in Izmir. My best friend is Tom. He is from England, but he lives in Turkey now. Tom is very happy here. Today he is tired, because school is long on Mondays. We say goodbye at the bus stop and we meet again tomorrow.\",\"prompt\":\"Where is Tom from?\",\"options\":[\"Turkey\",\"England\",\"Izmir\",\"Germany\"],\"answer\":1},{\"type\":\"read\",\"title\":\"Elif and Tom\",\"passage\":\"Hello! My name is Elif. I am twelve and I am a student in Izmir. My best friend is Tom. He is from England, but he lives in Turkey now. Tom is very happy here. Today he is tired, because school is long on Mondays. We say goodbye at the bus stop and we meet again tomorrow.\",\"prompt\":\"Why is Tom tired today?\",\"options\":[\"He is ill.\",\"School is long on Mondays.\",\"He plays football.\",\"He gets up early.\"],\"answer\":1}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(4,1,'Kelime oyunu','vocabulary','words',3,15,0,NULL,NULL,'[]','{\"game\":\"match\",\"words\":[{\"word\":\"hello\",\"translation\":\"merhaba\"},{\"word\":\"goodbye\",\"translation\":\"ho\\u015f\\u00e7a kal\"},{\"word\":\"name\",\"translation\":\"isim\",\"example\":\"My name is Deniz and I am a student.\"},{\"word\":\"friend\",\"translation\":\"arkada\\u015f\",\"example\":\"She is my best friend\"},{\"word\":\"student\",\"translation\":\"\\u00f6\\u011frenci\",\"example\":\"My name is Deniz and I am a student.\"},{\"word\":\"teacher\",\"translation\":\"\\u00f6\\u011fretmen\",\"example\":\"My teacher is very kind.\"},{\"word\":\"country\",\"translation\":\"\\u00fclke\"},{\"word\":\"city\",\"translation\":\"\\u015fehir\"},{\"word\":\"happy\",\"translation\":\"mutlu\",\"example\":\"I\'m happy to meet you.\"},{\"word\":\"tired\",\"translation\":\"yorgun\"}]}','2026-10-04 20:30:40','2026-10-04 20:30:40'),
(5,1,'Dilbilgisi pekiştir','grammar','lesson',4,15,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"___ you a student?\",\"options\":[\"Am\",\"Are\",\"Is\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"We ___ in the same class.\",\"options\":[\"is\",\"am\",\"are\"],\"answer\":2},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"My\",\"sister\",\"are\",\"a\",\"doctor\"],\"error_index\":2,\"options\":[\"is\",\"am\",\"be\"],\"answer\":0,\"explanation_tr\":\"\\\"My sister\\\" tekil (o) oldu\\u011fu i\\u00e7in \\\"is\\\" kullan\\u0131l\\u0131r. \\\"Are\\\" you, we, they i\\u00e7indir. Do\\u011frusu: My sister is a doctor.\"},{\"type\":\"translate\",\"prompt\":\"Biz \\u0130zmirliyiz.\",\"answer\":\"We are from Izmir\",\"alternatives\":[\"We\'re from Izmir\"],\"tiles\":[\"from\",\"We\",\"are\",\"is\",\"Izmir\",\"in\"]},{\"type\":\"fill\",\"prompt\":\"My teacher ___ very kind.\",\"options\":[\"is\",\"am\",\"are\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"I ___ from Antalya.\",\"options\":[\"are\",\"am\",\"is\"],\"answer\":1,\"hint\":\"I \\u2192 am\"},{\"type\":\"translate\",\"prompt\":\"O benim arkada\\u015f\\u0131m.\",\"answer\":\"She is my friend\",\"alternatives\":[\"She\'s my friend\",\"He is my friend\",\"He\'s my friend\"],\"tiles\":[\"She\",\"is\",\"am\",\"friend\",\"are\",\"my\"]},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Where are you from?\",\"translation\":\"Nerelisin?\"}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(6,1,'Dinle ve konuş','listening','lesson',5,15,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Okulun ilk g\\u00fcn\\u00fc. Yeni bir s\\u0131n\\u0131f arkada\\u015f\\u0131 yan\\u0131na geliyor.\",\"lines\":[{\"who\":\"Emma\",\"text\":\"Hi! I\'m Emma. What\'s your name?\"}],\"options\":[\"My name is Ali. Nice to meet you!\",\"I am name Ali.\",\"Name me Ali.\"],\"answer\":0,\"note_tr\":\"\\u0130smini s\\u00f6ylerken \\\"My name is \\u2026\\\" ya da k\\u0131saca \\\"I\'m \\u2026\\\" dersin. \\\"Nice to meet you\\\" ile bitirmek \\u00e7ok do\\u011fal durur.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"We\'re friends\",\"options\":[\"We\'re friends\",\"Where friends\",\"Were friends\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"How are you\",\"answer\":\"How are you\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Hi, I\'m Can. I\'m from Bursa.\",\"translation\":\"Merhaba, ben Can. Bursal\\u0131y\\u0131m.\"},{\"type\":\"translate\",\"prompt\":\"Biz \\u0130zmirliyiz.\",\"answer\":\"We are from Izmir\",\"alternatives\":[\"We\'re from Izmir\"],\"tiles\":[\"from\",\"We\",\"are\",\"is\",\"Izmir\",\"in\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"I am from Turkey\",\"answer\":\"I am from Turkey\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Where are you from?\",\"translation\":\"Nerelisin?\"}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(7,1,'Kelime tekrarı','vocabulary','lesson',6,15,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"happy\",\"mutlu\"],[\"friend\",\"arkada\\u015f\"],[\"city\",\"\\u015fehir\"],[\"tired\",\"yorgun\"],[\"name\",\"isim\"]]},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"goodbye\",\"options\":[\"country\",\"goodbye\",\"student\",\"happy\"],\"answer\":1},{\"type\":\"choice\",\"prompt\":\"\\\"name\\\" ne demek?\",\"options\":[\"isim\",\"\\u00fclke\",\"\\u00f6\\u011frenci\",\"yorgun\"],\"answer\":0,\"audio\":\"name\"},{\"type\":\"choice\",\"prompt\":\"\\\"\\u00f6\\u011frenci\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"city\",\"student\",\"tired\",\"friend\"],\"answer\":1},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"country\",\"options\":[\"goodbye\",\"tired\",\"country\",\"friend\"],\"answer\":2},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"tired\",\"answer\":\"tired\"},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"friend\",\"arkada\\u015f\"],[\"city\",\"\\u015fehir\"],[\"goodbye\",\"ho\\u015f\\u00e7a kal\"],[\"teacher\",\"\\u00f6\\u011fretmen\"],[\"happy\",\"mutlu\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"hello\\\" ne demek?\",\"options\":[\"\\u015fehir\",\"\\u00f6\\u011frenci\",\"merhaba\",\"isim\"],\"answer\":2,\"audio\":\"hello\"}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(8,1,'Telaffuz','speaking','lesson',7,15,0,NULL,NULL,'[{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"hello\",\"translation\":\"merhaba\"},{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"goodbye\",\"translation\":\"ho\\u015f\\u00e7a kal\"},{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"name\",\"translation\":\"isim\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"My name is Deniz and I am a student.\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"I\'m happy to meet you.\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"Hi, I\'m Can. I\'m from Bursa.\"}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
