(10,1,'Pratik','vocabulary','lesson',9,15,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"happy\",\"mutlu\"],[\"country\",\"\\u00fclke\"],[\"city\",\"\\u015fehir\"],[\"friend\",\"arkada\\u015f\"],[\"tired\",\"yorgun\"]]},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"goodbye\",\"options\":[\"happy\",\"goodbye\",\"country\",\"student\"],\"answer\":1},{\"type\":\"choice\",\"prompt\":\"\\\"name\\\" ne demek?\",\"options\":[\"\\u00fclke\",\"yorgun\",\"\\u00f6\\u011frenci\",\"isim\"],\"answer\":3,\"audio\":\"name\"},{\"type\":\"choice\",\"prompt\":\"\\\"\\u00f6\\u011frenci\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"student\",\"tired\",\"friend\",\"city\"],\"answer\":0},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"country\",\"options\":[\"friend\",\"tired\",\"country\",\"goodbye\"],\"answer\":2},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"tired\",\"answer\":\"tired\"},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"tired\",\"yorgun\"],[\"hello\",\"merhaba\"],[\"happy\",\"mutlu\"],[\"friend\",\"arkada\\u015f\"],[\"name\",\"isim\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"hello\\\" ne demek?\",\"options\":[\"\\u015fehir\",\"\\u00f6\\u011frenci\",\"merhaba\",\"isim\"],\"answer\":2,\"audio\":\"hello\"}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
