(21,2,'Pratik','vocabulary','lesson',9,15,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"mother\",\"anne\"],[\"cousin\",\"kuzen\"],[\"brother\",\"erkek karde\\u015f\"],[\"aunt\",\"teyze \\/ hala\"],[\"uncle\",\"amca \\/ day\\u0131\"]]},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"father\",\"options\":[\"uncle\",\"grandmother\",\"cousin\",\"father\"],\"answer\":3},{\"type\":\"choice\",\"prompt\":\"\\\"brother\\\" ne demek?\",\"options\":[\"amca \\/ day\\u0131\",\"b\\u00fcy\\u00fckanne\",\"ebeveynler\",\"erkek karde\\u015f\"],\"answer\":3,\"audio\":\"brother\"},{\"type\":\"choice\",\"prompt\":\"\\\"b\\u00fcy\\u00fckanne\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"grandmother\",\"parents\",\"sister\",\"aunt\"],\"answer\":0},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"uncle\",\"options\":[\"uncle\",\"father\",\"parents\",\"sister\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"parents\",\"answer\":\"parents\"},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"cousin\",\"kuzen\"],[\"uncle\",\"amca \\/ day\\u0131\"],[\"parents\",\"ebeveynler\"],[\"mother\",\"anne\"],[\"grandfather\",\"b\\u00fcy\\u00fckbaba\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"mother\\\" ne demek?\",\"options\":[\"anne\",\"erkek karde\\u015f\",\"teyze \\/ hala\",\"b\\u00fcy\\u00fckanne\"],\"answer\":0,\"audio\":\"mother\"}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
