(23,3,'Kelimeler','vocabulary','lesson',0,15,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"book\",\"kitap\"],[\"pen\",\"t\\u00fckenmez kalem\"],[\"pencil\",\"kur\\u015fun kalem\"],[\"notebook\",\"defter\"],[\"desk\",\"s\\u0131ra\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"board\\\" ne demek?\",\"options\":[\"\\u00f6dev\",\"tahta\",\"silgi\",\"kur\\u015fun kalem\"],\"answer\":1,\"audio\":\"board\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"Open your books\",\"options\":[\"Open your books\",\"Open your box\",\"Opens your books\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Bu kitaplar s\\u0131ram\\u0131n \\u00fcst\\u00fcnde.\",\"answer\":\"These books are on my desk\",\"alternatives\":[],\"tiles\":[\"desk\",\"classroom\",\"books\",\"my\",\"on\",\"are\",\"These\",\"board\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"board\",\"tahta\"],[\"bag\",\"\\u00e7anta\"],[\"eraser\",\"silgi\"],[\"classroom\",\"s\\u0131n\\u0131f\"],[\"homework\",\"\\u00f6dev\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"s\\u0131n\\u0131f\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"pen\",\"classroom\",\"eraser\",\"notebook\"],\"answer\":1},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Open your notebook, please.\",\"translation\":\"Defterini a\\u00e7 l\\u00fctfen.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"That is my bag\",\"answer\":\"That is my bag\"}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(24,3,'Dilbilgisi','grammar','lesson',1,15,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"___ pen is mine. (elimde)\",\"options\":[\"This\",\"These\",\"Those\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"Look at ___ birds in the sky!\",\"options\":[\"this\",\"that\",\"those\"],\"answer\":2},{\"type\":\"fill\",\"prompt\":\"I need ___ eraser.\",\"options\":[\"a\",\"an\",\"the\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"___ talk in the library!\",\"options\":[\"No\",\"Don\'t\",\"Not\"],\"answer\":1},{\"type\":\"translate\",\"prompt\":\"Kitaplar\\u0131n\\u0131z\\u0131 a\\u00e7\\u0131n.\",\"answer\":\"Open your books\",\"alternatives\":[\"Open your books please\"],\"tiles\":[\"books\",\"Open\",\"your\",\"the\",\"open\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"These\",\"books\",\"is\",\"very\",\"interesting\"],\"error_index\":2,\"options\":[\"are\",\"am\",\"be\"],\"answer\":0,\"explanation_tr\":\"\\\"These books\\\" \\u00e7o\\u011ful oldu\\u011fu i\\u00e7in fiil de \\u00e7o\\u011ful olmal\\u0131: These books are very interesting.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Can I borrow your pencil?\",\"translation\":\"Kur\\u015fun kalemini \\u00f6d\\u00fcn\\u00e7 alabilir miyim?\"}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(25,3,'Okuma: In the Classroom','reading','lesson',2,15,0,NULL,NULL,'[{\"type\":\"read\",\"title\":\"In the Classroom\",\"passage\":\"Our classroom is on the second floor. There are twenty desks and a big white board. My bag is under my desk. In my bag there is a notebook, a pencil, a pen and an eraser. Our teacher says, \\\"Open your books, please!\\\" and \\\"Don\'t forget your homework!\\\" I like my classroom because it is bright and quiet.\",\"prompt\":\"Where is the writer\'s bag?\",\"options\":[\"On the board\",\"Under the desk\",\"At home\",\"On the window\"],\"answer\":1},{\"type\":\"read\",\"title\":\"In the Classroom\",\"passage\":\"Our classroom is on the second floor. There are twenty desks and a big white board. My bag is under my desk. In my bag there is a notebook, a pencil, a pen and an eraser. Our teacher says, \\\"Open your books, please!\\\" and \\\"Don\'t forget your homework!\\\" I like my classroom because it is bright and quiet.\",\"prompt\":\"Why does the writer like the classroom?\",\"options\":[\"It is big and noisy.\",\"It is bright and quiet.\",\"It has a computer.\",\"It is near the garden.\"],\"answer\":1}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(26,3,'Kelime oyunu','vocabulary','words',3,15,0,NULL,NULL,'[]','{\"game\":\"choice\",\"words\":[{\"word\":\"book\",\"translation\":\"kitap\"},{\"word\":\"pen\",\"translation\":\"t\\u00fckenmez kalem\",\"example\":\"This pen is mine. (elimde)\"},{\"word\":\"pencil\",\"translation\":\"kur\\u015fun kalem\",\"example\":\"Can I borrow your pencil?\"},{\"word\":\"notebook\",\"translation\":\"defter\",\"example\":\"Open your notebook, please.\"},{\"word\":\"desk\",\"translation\":\"s\\u0131ra\",\"example\":\"These books are on my desk.\"},{\"word\":\"board\",\"translation\":\"tahta\"},{\"word\":\"bag\",\"translation\":\"\\u00e7anta\",\"example\":\"That is my bag\"},{\"word\":\"eraser\",\"translation\":\"silgi\",\"example\":\"I need an eraser.\"},{\"word\":\"classroom\",\"translation\":\"s\\u0131n\\u0131f\"},{\"word\":\"homework\",\"translation\":\"\\u00f6dev\"}]}','2026-10-04 20:30:40','2026-10-04 20:30:40'),
(27,3,'Dilbilgisi pekiştir','grammar','lesson',4,15,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"___ talk in the library!\",\"options\":[\"Don\'t\",\"No\",\"Not\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"I need ___ eraser.\",\"options\":[\"an\",\"a\",\"the\"],\"answer\":0},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"These\",\"books\",\"is\",\"very\",\"interesting\"],\"error_index\":2,\"options\":[\"are\",\"am\",\"be\"],\"answer\":0,\"explanation_tr\":\"\\\"These books\\\" \\u00e7o\\u011ful oldu\\u011fu i\\u00e7in fiil de \\u00e7o\\u011ful olmal\\u0131: These books are very interesting.\"},{\"type\":\"translate\",\"prompt\":\"\\u015eu \\u00e7anta senin mi?\",\"answer\":\"Is that your bag\",\"alternatives\":[\"Is that bag yours\"],\"tiles\":[\"Is\",\"this\",\"that\",\"bag\",\"are\",\"your\"]},{\"type\":\"fill\",\"prompt\":\"Look at ___ birds in the sky!\",\"options\":[\"this\",\"that\",\"those\"],\"answer\":2},{\"type\":\"fill\",\"prompt\":\"___ pen is mine. (elimde)\",\"options\":[\"These\",\"Those\",\"This\"],\"answer\":2},{\"type\":\"translate\",\"prompt\":\"Kitaplar\\u0131n\\u0131z\\u0131 a\\u00e7\\u0131n.\",\"answer\":\"Open your books\",\"alternatives\":[\"Open your books please\"],\"tiles\":[\"books\",\"Open\",\"your\",\"the\",\"open\"]},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Can you repeat that, please?\",\"translation\":\"Tekrar eder misiniz l\\u00fctfen?\"}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(28,3,'Dinle ve konuş','listening','lesson',5,15,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Derste \\u00f6\\u011fretmen bir soru sordu ama anlamad\\u0131n.\",\"lines\":[{\"who\":\"Mr Green\",\"text\":\"What is the answer to number five?\"}],\"options\":[\"Sorry, can you repeat the question, please?\",\"What? Again!\",\"I not understand.\"],\"answer\":0,\"note_tr\":\"Anlamad\\u0131\\u011f\\u0131nda kibarca tekrar istemek: \\\"Can you repeat that, please?\\\" ya da \\\"Sorry, I don\'t understand.\\\"\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"Those are my pencils\",\"options\":[\"Those are my pencils\",\"These are my pencils\",\"Those are my pencil\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"Close the door please\",\"answer\":\"Close the door please\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Sorry, I don\'t understand.\",\"translation\":\"\\u00d6z\\u00fcr dilerim, anlam\\u0131yorum.\"},{\"type\":\"translate\",\"prompt\":\"\\u015eu \\u00e7anta senin mi?\",\"answer\":\"Is that your bag\",\"alternatives\":[\"Is that bag yours\"],\"tiles\":[\"Is\",\"this\",\"that\",\"bag\",\"are\",\"your\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"Where is my notebook\",\"answer\":\"Where is my notebook\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Can you repeat that, please?\",\"translation\":\"Tekrar eder misiniz l\\u00fctfen?\"}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(29,3,'Kelime tekrarı','vocabulary','lesson',6,15,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"homework\",\"\\u00f6dev\"],[\"bag\",\"\\u00e7anta\"],[\"eraser\",\"silgi\"],[\"board\",\"tahta\"],[\"pen\",\"t\\u00fckenmez kalem\"]]},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"pen\",\"options\":[\"desk\",\"bag\",\"pen\",\"classroom\"],\"answer\":2},{\"type\":\"choice\",\"prompt\":\"\\\"pencil\\\" ne demek?\",\"options\":[\"\\u00f6dev\",\"\\u00e7anta\",\"s\\u0131ra\",\"kur\\u015fun kalem\"],\"answer\":3,\"audio\":\"pencil\"},{\"type\":\"choice\",\"prompt\":\"\\\"s\\u0131ra\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"homework\",\"eraser\",\"notebook\",\"desk\"],\"answer\":3},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"bag\",\"options\":[\"bag\",\"pen\",\"notebook\",\"homework\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"homework\",\"answer\":\"homework\"},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"bag\",\"\\u00e7anta\"],[\"notebook\",\"defter\"],[\"desk\",\"s\\u0131ra\"],[\"classroom\",\"s\\u0131n\\u0131f\"],[\"board\",\"tahta\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"book\\\" ne demek?\",\"options\":[\"s\\u0131ra\",\"silgi\",\"kitap\",\"kur\\u015fun kalem\"],\"answer\":2,\"audio\":\"book\"}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(30,3,'Telaffuz','speaking','lesson',7,15,0,NULL,NULL,'[{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"book\",\"translation\":\"kitap\"},{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"pen\",\"translation\":\"t\\u00fckenmez kalem\"},{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"pencil\",\"translation\":\"kur\\u015fun kalem\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"These books are on my desk.\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"Can I borrow your pencil?\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"Sorry, I don\'t understand.\"}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
