(56,6,'Kelimeler','vocabulary','lesson',0,15,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"bread\",\"ekmek\"],[\"cheese\",\"peynir\"],[\"egg\",\"yumurta\"],[\"milk\",\"s\\u00fct\"],[\"water\",\"su\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"apple\\\" ne demek?\",\"options\":[\"yumurta\",\"\\u015fi\\u015fe\",\"ucuz\",\"elma\"],\"answer\":3,\"audio\":\"apple\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"A glass of water, please\",\"options\":[\"A glass of water, please\",\"A class of water, please\",\"A glass of wine, please\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Bir \\u015fi\\u015fe su alabilir miyim l\\u00fctfen?\",\"answer\":\"Can I have a bottle of water, please\",\"alternatives\":[],\"tiles\":[\"of\",\"expensive\",\"cheese\",\"have\",\"I\",\"water\",\"a\",\"Can\",\"please\",\"bottle\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"apple\",\"elma\"],[\"tomato\",\"domates\"],[\"cheap\",\"ucuz\"],[\"expensive\",\"pahal\\u0131\"],[\"bottle\",\"\\u015fi\\u015fe\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"pahal\\u0131\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"cheap\",\"milk\",\"expensive\",\"cheese\"],\"answer\":2},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Tomatoes are cheap today.\",\"translation\":\"Domatesler bug\\u00fcn ucuz.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"We need some bread and cheese\",\"answer\":\"We need some bread and cheese\"}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(57,6,'Dilbilgisi','grammar','lesson',1,15,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"Is there ___ milk in the fridge?\",\"options\":[\"some\",\"any\",\"a\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"I would ___ a sandwich, please.\",\"options\":[\"like\",\"likes\",\"liking\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"How ___ apples do you want?\",\"options\":[\"much\",\"many\",\"any\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"There is ___ cheese on the table.\",\"options\":[\"some\",\"any\",\"an\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Bir kahve l\\u00fctfen.\",\"answer\":\"A coffee please\",\"alternatives\":[\"A coffee, please\",\"One coffee please\",\"One coffee, please\"],\"tiles\":[\"A\",\"please\",\"coffee\",\"is\",\"the\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"I\",\"want\",\"two\",\"breads\",\"please\"],\"error_index\":3,\"options\":[\"loaves of bread\",\"bread\",\"breads\"],\"answer\":0,\"explanation_tr\":\"\\\"Bread\\\" say\\u0131lamayan bir isimdir, \\u00e7o\\u011ful -s almaz. \\\"\\u0130ki ekmek\\\" i\\u00e7in \\\"two loaves of bread\\\" ya da \\\"two pieces of bread\\\" denir.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Can I have the bill, please?\",\"translation\":\"Hesab\\u0131 alabilir miyim?\"}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(58,6,'Okuma: At the Market','reading','lesson',2,15,0,NULL,NULL,'[{\"type\":\"read\",\"title\":\"At the Market\",\"passage\":\"On Saturdays my mother and I go to the market. We buy bread, cheese, eggs and tomatoes. Apples are cheap today, so we buy two kilos. I want some orange juice, but it is expensive. \\\"How much is a bottle of water?\\\" my mother asks. \\\"Five lira,\\\" says the man. We go home with three full bags.\",\"prompt\":\"Why do they buy two kilos of apples?\",\"options\":[\"They are cheap today.\",\"The writer loves apples.\",\"They are for a cake.\",\"The man gives them free.\"],\"answer\":0},{\"type\":\"read\",\"title\":\"At the Market\",\"passage\":\"On Saturdays my mother and I go to the market. We buy bread, cheese, eggs and tomatoes. Apples are cheap today, so we buy two kilos. I want some orange juice, but it is expensive. \\\"How much is a bottle of water?\\\" my mother asks. \\\"Five lira,\\\" says the man. We go home with three full bags.\",\"prompt\":\"What does the writer NOT buy?\",\"options\":[\"Bread\",\"Orange juice\",\"Cheese\",\"Tomatoes\"],\"answer\":1}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(59,6,'Kelime oyunu','vocabulary','words',3,15,0,NULL,NULL,'[]','{\"game\":\"cloze\",\"words\":[{\"word\":\"bread\",\"translation\":\"ekmek\",\"example\":\"We need some bread and cheese\"},{\"word\":\"cheese\",\"translation\":\"peynir\",\"example\":\"We need some bread and cheese\"},{\"word\":\"egg\",\"translation\":\"yumurta\"},{\"word\":\"milk\",\"translation\":\"s\\u00fct\",\"example\":\"Is there any milk in the fridge?\"},{\"word\":\"water\",\"translation\":\"su\",\"example\":\"Can I have a bottle of water, please?\"},{\"word\":\"apple\",\"translation\":\"elma\"},{\"word\":\"tomato\",\"translation\":\"domates\"},{\"word\":\"cheap\",\"translation\":\"ucuz\",\"example\":\"Tomatoes are cheap today.\"},{\"word\":\"expensive\",\"translation\":\"pahal\\u0131\"},{\"word\":\"bottle\",\"translation\":\"\\u015fi\\u015fe\",\"example\":\"Can I have a bottle of water, please?\"}]}','2026-10-04 20:30:40','2026-10-04 20:30:40'),
(60,6,'Dilbilgisi pekiştir','grammar','lesson',4,15,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"There is ___ cheese on the table.\",\"options\":[\"some\",\"any\",\"an\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"How ___ apples do you want?\",\"options\":[\"much\",\"any\",\"many\"],\"answer\":2},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"I\",\"want\",\"two\",\"breads\",\"please\"],\"error_index\":3,\"options\":[\"loaves of bread\",\"bread\",\"breads\"],\"answer\":0,\"explanation_tr\":\"\\\"Bread\\\" say\\u0131lamayan bir isimdir, \\u00e7o\\u011ful -s almaz. \\\"\\u0130ki ekmek\\\" i\\u00e7in \\\"two loaves of bread\\\" ya da \\\"two pieces of bread\\\" denir.\"},{\"type\":\"translate\",\"prompt\":\"Bu ne kadar?\",\"answer\":\"How much is this\",\"alternatives\":[\"How much is it\",\"How much\'s this\"],\"tiles\":[\"are\",\"How\",\"this\",\"many\",\"is\",\"much\"]},{\"type\":\"fill\",\"prompt\":\"I would ___ a sandwich, please.\",\"options\":[\"likes\",\"like\",\"liking\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"Is there ___ milk in the fridge?\",\"options\":[\"some\",\"a\",\"any\"],\"answer\":2},{\"type\":\"translate\",\"prompt\":\"Bir kahve l\\u00fctfen.\",\"answer\":\"A coffee please\",\"alternatives\":[\"A coffee, please\",\"One coffee please\",\"One coffee, please\"],\"tiles\":[\"A\",\"please\",\"coffee\",\"is\",\"the\"]},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"How much are the apples?\",\"translation\":\"Elmalar ne kadar?\"}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(61,6,'Dinle ve konuş','listening','lesson',5,15,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Londra\'da bir kafedesin. S\\u0131ra sende.\",\"scene\":\"scenarios\\/order-at-a-cafe\",\"lines\":[{\"who\":\"Barista\",\"text\":\"Hi there! What can I get for you today?\"}],\"options\":[\"Give me one coffee.\",\"I\'d like a coffee, please.\",\"I want coffee now.\"],\"answer\":1,\"note_tr\":\"Sipari\\u015fte \\\"I want\\\" biraz sert durur, \\\"Give me\\\" ise emir gibidir. Kibar h\\u00e2li: I\\u2019d like \\u2026 , please.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"fifteen\",\"options\":[\"fifty\",\"fifteen\",\"five\"],\"answer\":1},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"How much is the cheese\",\"answer\":\"How much is the cheese\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I\'d like a cheese sandwich, please.\",\"translation\":\"Peynirli sandvi\\u00e7 istiyorum l\\u00fctfen.\"},{\"type\":\"translate\",\"prompt\":\"Bu ne kadar?\",\"answer\":\"How much is this\",\"alternatives\":[\"How much is it\",\"How much\'s this\"],\"tiles\":[\"are\",\"How\",\"this\",\"many\",\"is\",\"much\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"I would like some eggs\",\"answer\":\"I would like some eggs\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"How much are the apples?\",\"translation\":\"Elmalar ne kadar?\"}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
