(68,7,'Dilbilgisi','grammar','lesson',1,15,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"She ___ speak three languages.\",\"options\":[\"can\",\"cans\",\"is\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"I can ___ a bike.\",\"options\":[\"ride\",\"rides\",\"riding\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"___ I sit here?\",\"options\":[\"Can\",\"Do\",\"Am\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"Sorry, I ___ swim.\",\"options\":[\"can\'t\",\"don\'t can\",\"not can\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"M\\u00fcze nerede?\",\"answer\":\"Where is the museum\",\"alternatives\":[\"Where\'s the museum\"],\"tiles\":[\"a\",\"museum\",\"are\",\"the\",\"is\",\"Where\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"He\",\"can\",\"speaks\",\"English\",\"very\",\"well\"],\"error_index\":2,\"options\":[\"speak\",\"speaking\",\"to speak\"],\"answer\":0,\"explanation_tr\":\"\\\"Can\\\" kendisinden sonra yal\\u0131n fiil ister; fiile -s eklenmez. Do\\u011frusu: He can speak English very well.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Excuse me, how can I get to the station?\",\"translation\":\"Affedersiniz, istasyona nas\\u0131l gidebilirim?\"}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(69,7,'Okuma: Where Is the Museum?','reading','lesson',2,15,0,NULL,NULL,'[{\"type\":\"read\",\"title\":\"Where Is the Museum?\",\"passage\":\"A tourist stops me on the street. \\\"Excuse me, where is the museum?\\\" she asks. I say, \\\"Go straight and turn left at the bank. The museum is opposite the hospital.\\\" She can\'t speak Turkish, but she can speak a little English. She says thank you and smiles. Ten minutes later I see her in front of the museum.\",\"prompt\":\"Where is the museum?\",\"options\":[\"Next to the bank\",\"Opposite the hospital\",\"Near the station\",\"Behind the pharmacy\"],\"answer\":1},{\"type\":\"read\",\"title\":\"Where Is the Museum?\",\"passage\":\"A tourist stops me on the street. \\\"Excuse me, where is the museum?\\\" she asks. I say, \\\"Go straight and turn left at the bank. The museum is opposite the hospital.\\\" She can\'t speak Turkish, but she can speak a little English. She says thank you and smiles. Ten minutes later I see her in front of the museum.\",\"prompt\":\"Which language can the tourist speak?\",\"options\":[\"Only Turkish\",\"A little English\",\"French\",\"No language\"],\"answer\":1}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(70,7,'Kelime oyunu','vocabulary','words',3,15,0,NULL,NULL,'[]','{\"game\":\"search\",\"words\":[{\"word\":\"station\",\"translation\":\"istasyon\",\"example\":\"Excuse me, how can I get to the station?\"},{\"word\":\"pharmacy\",\"translation\":\"eczane\",\"example\":\"The pharmacy is opposite the bank.\"},{\"word\":\"hospital\",\"translation\":\"hastane\"},{\"word\":\"bank\",\"translation\":\"banka\",\"example\":\"The pharmacy is opposite the bank.\"},{\"word\":\"museum\",\"translation\":\"m\\u00fcze\",\"example\":\"Where is the museum\"},{\"word\":\"street\",\"translation\":\"sokak\"},{\"word\":\"turn left\",\"translation\":\"sola d\\u00f6n\",\"example\":\"Go straight and turn left at the lights.\"},{\"word\":\"turn right\",\"translation\":\"sa\\u011fa d\\u00f6n\"},{\"word\":\"go straight\",\"translation\":\"d\\u00fcz git\",\"example\":\"Go straight and turn left at the lights.\"},{\"word\":\"opposite\",\"translation\":\"kar\\u015f\\u0131s\\u0131nda\",\"example\":\"The pharmacy is opposite the bank.\"}]}','2026-10-04 20:30:40','2026-10-04 20:30:40'),
(71,7,'Dilbilgisi pekiştir','grammar','lesson',4,15,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"Sorry, I ___ swim.\",\"options\":[\"can\'t\",\"don\'t can\",\"not can\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"___ I sit here?\",\"options\":[\"Am\",\"Do\",\"Can\"],\"answer\":2},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"He\",\"can\",\"speaks\",\"English\",\"very\",\"well\"],\"error_index\":2,\"options\":[\"speak\",\"speaking\",\"to speak\"],\"answer\":0,\"explanation_tr\":\"\\\"Can\\\" kendisinden sonra yal\\u0131n fiil ister; fiile -s eklenmez. Do\\u011frusu: He can speak English very well.\"},{\"type\":\"translate\",\"prompt\":\"Bana yard\\u0131m edebilir misin?\",\"answer\":\"Can you help me\",\"alternatives\":[\"Could you help me\"],\"tiles\":[\"me\",\"to\",\"you\",\"helps\",\"Can\",\"help\"]},{\"type\":\"fill\",\"prompt\":\"I can ___ a bike.\",\"options\":[\"rides\",\"riding\",\"ride\"],\"answer\":2},{\"type\":\"fill\",\"prompt\":\"She ___ speak three languages.\",\"options\":[\"cans\",\"can\",\"is\"],\"answer\":1},{\"type\":\"translate\",\"prompt\":\"M\\u00fcze nerede?\",\"answer\":\"Where is the museum\",\"alternatives\":[\"Where\'s the museum\"],\"tiles\":[\"a\",\"museum\",\"are\",\"the\",\"is\",\"Where\"]},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Is it far from here?\",\"translation\":\"Buradan uzak m\\u0131?\"}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(72,7,'Dinle ve konuş','listening','lesson',5,15,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Bir turist sana yol soruyor.\",\"lines\":[{\"who\":\"Tourist\",\"text\":\"Excuse me, where is the nearest pharmacy?\"}],\"options\":[\"Go straight on and turn right. It\'s opposite the bank.\",\"Pharmacy there is.\",\"You go pharmacy right.\"],\"answer\":0,\"note_tr\":\"Yol tarifinde emir c\\u00fcmleleri kullan\\u0131l\\u0131r: Go straight on, turn right\\u2026 Hedefi en sona b\\u0131rak.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"Where is the bus stop\",\"options\":[\"Where is the bus stop\",\"Where is the bookshop\",\"When is the bus\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"Go straight on\",\"answer\":\"Go straight on\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"It\'s on your right.\",\"translation\":\"Sa\\u011f taraf\\u0131n\\u0131zda.\"},{\"type\":\"translate\",\"prompt\":\"Bana yard\\u0131m edebilir misin?\",\"answer\":\"Can you help me\",\"alternatives\":[\"Could you help me\"],\"tiles\":[\"me\",\"to\",\"you\",\"helps\",\"Can\",\"help\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"The station is on your right\",\"answer\":\"The station is on your right\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Is it far from here?\",\"translation\":\"Buradan uzak m\\u0131?\"}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
