(79,8,'Dilbilgisi','grammar','lesson',1,15,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"Look! It ___ snowing.\",\"options\":[\"is\",\"are\",\"am\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"They are ___ football in the park.\",\"options\":[\"play\",\"playing\",\"plays\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"What ___ you doing now?\",\"options\":[\"is\",\"are\",\"do\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"I ___ sleeping, I\'m reading.\",\"options\":[\"am not\",\"not\",\"don\'t\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"\\u015eu an ya\\u011fmur ya\\u011f\\u0131yor.\",\"answer\":\"It is raining now\",\"alternatives\":[\"It\'s raining now\"],\"tiles\":[\"rains\",\"is\",\"raining\",\"now\",\"are\",\"It\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"Listen!\",\"The\",\"baby\",\"cry\"],\"error_index\":3,\"options\":[\"is crying\",\"cries\",\"crying\"],\"answer\":0,\"explanation_tr\":\"\\\"Listen!\\\" konu\\u015fma an\\u0131n\\u0131 g\\u00f6sterir, bu y\\u00fczden \\u015fimdiki zaman gerekir: The baby is crying.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"It\'s very cold today.\",\"translation\":\"Bug\\u00fcn hava \\u00e7ok so\\u011fuk.\"}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(80,8,'Okuma: A Rainy Day','reading','lesson',2,15,0,NULL,NULL,'[{\"type\":\"read\",\"title\":\"A Rainy Day\",\"passage\":\"It is Saturday and it is raining in Trabzon. It is cold too. I am wearing my warm coat and my new shoes. My sister is wearing a yellow jacket. We are waiting for the bus and we are talking about the weather. \\\"I hate rainy days,\\\" she says. \\\"I don\'t,\\\" I answer. \\\"Look, the sun is coming out!\\\"\",\"prompt\":\"What is the weather like at first?\",\"options\":[\"Sunny and hot\",\"Rainy and cold\",\"Snowy\",\"Windy and warm\"],\"answer\":1},{\"type\":\"read\",\"title\":\"A Rainy Day\",\"passage\":\"It is Saturday and it is raining in Trabzon. It is cold too. I am wearing my warm coat and my new shoes. My sister is wearing a yellow jacket. We are waiting for the bus and we are talking about the weather. \\\"I hate rainy days,\\\" she says. \\\"I don\'t,\\\" I answer. \\\"Look, the sun is coming out!\\\"\",\"prompt\":\"What is the sister wearing?\",\"options\":[\"A warm coat\",\"A yellow jacket\",\"A dress\",\"A T-shirt\"],\"answer\":1}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(81,8,'Kelime oyunu','vocabulary','words',3,15,0,NULL,NULL,'[]','{\"game\":\"listen\",\"words\":[{\"word\":\"coat\",\"translation\":\"mont\",\"example\":\"It\'s raining, so I\'m wearing my coat.\"},{\"word\":\"jacket\",\"translation\":\"ceket\"},{\"word\":\"shoes\",\"translation\":\"ayakkab\\u0131\",\"example\":\"I\'m wearing my new shoes.\"},{\"word\":\"dress\",\"translation\":\"elbise\",\"example\":\"She is wearing a blue dress\"},{\"word\":\"T-shirt\",\"translation\":\"ti\\u015f\\u00f6rt\"},{\"word\":\"sunny\",\"translation\":\"g\\u00fcne\\u015fli\",\"example\":\"It is very sunny today\"},{\"word\":\"rainy\",\"translation\":\"ya\\u011fmurlu\"},{\"word\":\"cold\",\"translation\":\"so\\u011fuk\",\"example\":\"It\'s very cold today.\"},{\"word\":\"wear\",\"translation\":\"giymek\"},{\"word\":\"weather\",\"translation\":\"hava durumu\",\"example\":\"What is the weather like today?\"}]}','2026-10-04 20:30:40','2026-10-04 20:30:40'),
(82,8,'Dilbilgisi pekiştir','grammar','lesson',4,15,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"I ___ sleeping, I\'m reading.\",\"options\":[\"am not\",\"not\",\"don\'t\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"What ___ you doing now?\",\"options\":[\"do\",\"are\",\"is\"],\"answer\":1},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"Listen!\",\"The\",\"baby\",\"cry\"],\"error_index\":3,\"options\":[\"is crying\",\"cries\",\"crying\"],\"answer\":0,\"explanation_tr\":\"\\\"Listen!\\\" konu\\u015fma an\\u0131n\\u0131 g\\u00f6sterir, bu y\\u00fczden \\u015fimdiki zaman gerekir: The baby is crying.\"},{\"type\":\"translate\",\"prompt\":\"Ne yap\\u0131yorsun?\",\"answer\":\"What are you doing\",\"alternatives\":[],\"tiles\":[\"doing\",\"What\",\"do\",\"are\",\"you\",\"is\"]},{\"type\":\"fill\",\"prompt\":\"They are ___ football in the park.\",\"options\":[\"play\",\"plays\",\"playing\"],\"answer\":2},{\"type\":\"fill\",\"prompt\":\"Look! It ___ snowing.\",\"options\":[\"is\",\"are\",\"am\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"\\u015eu an ya\\u011fmur ya\\u011f\\u0131yor.\",\"answer\":\"It is raining now\",\"alternatives\":[\"It\'s raining now\"],\"tiles\":[\"rains\",\"is\",\"raining\",\"now\",\"are\",\"It\"]},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"What are you doing right now?\",\"translation\":\"\\u015eu anda ne yap\\u0131yorsun?\"}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(83,8,'Dinle ve konuş','listening','lesson',5,15,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Annen telefonla ar\\u0131yor.\",\"lines\":[{\"who\":\"Mum\",\"text\":\"Hi love! What are you doing?\"}],\"options\":[\"I\'m studying English in my room.\",\"I study English now my room.\",\"I am study English.\"],\"answer\":0,\"note_tr\":\"Konu\\u015fma an\\u0131nda yapt\\u0131\\u011f\\u0131n \\u015fey i\\u00e7in \\\"I\'m + fiil-ing\\\" kullan\\u0131l\\u0131r.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"She is wearing a jacket\",\"options\":[\"She is wearing a jacket\",\"She is washing a jacket\",\"She was wearing a jacket\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"It is very sunny today\",\"answer\":\"It is very sunny today\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I\'m wearing my new shoes.\",\"translation\":\"Yeni ayakkab\\u0131lar\\u0131m\\u0131 giyiyorum.\"},{\"type\":\"translate\",\"prompt\":\"Ne yap\\u0131yorsun?\",\"answer\":\"What are you doing\",\"alternatives\":[],\"tiles\":[\"doing\",\"What\",\"do\",\"are\",\"you\",\"is\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"They are watching a film\",\"answer\":\"They are watching a film\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"What are you doing right now?\",\"translation\":\"\\u015eu anda ne yap\\u0131yorsun?\"}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
