(89,9,'Kelimeler','vocabulary','lesson',0,15,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"hobby\",\"hobi\"],[\"swimming\",\"y\\u00fczme\"],[\"dancing\",\"dans etmek\"],[\"cooking\",\"yemek yapmak\"],[\"reading\",\"okumak\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"playing games\\\" ne demek?\",\"options\":[\"keyif almak\",\"oyun oynamak\",\"bo\\u015f zaman\",\"dans etmek\"],\"answer\":1,\"audio\":\"playing games\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"She loves dancing\",\"options\":[\"She loves dancing\",\"She loves dance\",\"She loved dancing\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Bo\\u015f zaman\\u0131mda okumay\\u0131 \\u00e7ok severim.\",\"answer\":\"I love reading in my free time\",\"alternatives\":[],\"tiles\":[\"reading\",\"in\",\"reading\",\"my\",\"time\",\"love\",\"I\",\"swimming\",\"free\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"playing games\",\"oyun oynamak\"],[\"weekend\",\"hafta sonu\"],[\"enjoy\",\"keyif almak\"],[\"hate\",\"nefret etmek\"],[\"free time\",\"bo\\u015f zaman\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"nefret etmek\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"swimming\",\"hate\",\"cooking\",\"enjoy\"],\"answer\":1},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"We enjoy cooking at the weekend.\",\"translation\":\"Hafta sonu yemek yapmaktan keyif al\\u0131r\\u0131z.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"My brother hates waking up early\",\"answer\":\"My brother hates waking up early\"}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(90,9,'Dilbilgisi','grammar','lesson',1,15,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"I like ___ to music.\",\"options\":[\"listen\",\"listening\",\"listens\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"She ___ swimming in the sea.\",\"options\":[\"love\",\"loves\",\"loving\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"___ do you go to the cinema? Once a month.\",\"options\":[\"How often\",\"How much\",\"What\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"They enjoy ___ games online.\",\"options\":[\"play\",\"playing\",\"to playing\"],\"answer\":1},{\"type\":\"translate\",\"prompt\":\"Hafta sonu yemek yapmay\\u0131 severim.\",\"answer\":\"I like cooking at the weekend\",\"alternatives\":[\"I like to cook at the weekend\",\"I love cooking at the weekend\"],\"tiles\":[\"in\",\"I\",\"the\",\"cook\",\"at\",\"weekend\",\"cooking\",\"like\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"I\",\"enjoy\",\"swim\",\"in\",\"summer\"],\"error_index\":2,\"options\":[\"swimming\",\"swims\",\"to swimming\"],\"answer\":0,\"explanation_tr\":\"\\\"Enjoy\\\" kendisinden sonra -ing ister: I enjoy swimming in summer.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"At the weekend I usually meet my friends.\",\"translation\":\"Hafta sonlar\\u0131 genellikle arkada\\u015flar\\u0131mla bulu\\u015furum.\"}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(91,9,'Okuma: My Free Time','reading','lesson',2,15,0,NULL,NULL,'[{\"type\":\"read\",\"title\":\"My Free Time\",\"passage\":\"I have a lot of free time at the weekend. I love swimming, so I go to the pool every Saturday morning. My brother enjoys cooking and he makes pancakes for us. My best friend likes playing games online, but I don\'t like it very much. On Sunday evenings we all enjoy reading together in the living room.\",\"prompt\":\"What does the writer do on Saturday mornings?\",\"options\":[\"Cooking\",\"Swimming\",\"Playing games\",\"Dancing\"],\"answer\":1},{\"type\":\"read\",\"title\":\"My Free Time\",\"passage\":\"I have a lot of free time at the weekend. I love swimming, so I go to the pool every Saturday morning. My brother enjoys cooking and he makes pancakes for us. My best friend likes playing games online, but I don\'t like it very much. On Sunday evenings we all enjoy reading together in the living room.\",\"prompt\":\"Who makes pancakes?\",\"options\":[\"The writer\",\"The best friend\",\"The brother\",\"The mother\"],\"answer\":2}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(92,9,'Kelime oyunu','vocabulary','words',3,15,0,NULL,NULL,'[]','{\"game\":\"kelimle\",\"words\":[{\"word\":\"hobby\",\"translation\":\"hobi\",\"example\":\"My favourite hobby is drawing.\"},{\"word\":\"swimming\",\"translation\":\"y\\u00fczme\",\"example\":\"She loves swimming in the sea.\"},{\"word\":\"dancing\",\"translation\":\"dans etmek\"},{\"word\":\"cooking\",\"translation\":\"yemek yapmak\",\"example\":\"We enjoy cooking at the weekend.\"},{\"word\":\"reading\",\"translation\":\"okumak\",\"example\":\"I love reading in my free time.\"},{\"word\":\"playing games\",\"translation\":\"oyun oynamak\",\"example\":\"They enjoy playing games online.\"},{\"word\":\"weekend\",\"translation\":\"hafta sonu\",\"example\":\"We enjoy cooking at the weekend.\"},{\"word\":\"enjoy\",\"translation\":\"keyif almak\",\"example\":\"We enjoy cooking at the weekend.\"},{\"word\":\"hate\",\"translation\":\"nefret etmek\"},{\"word\":\"free time\",\"translation\":\"bo\\u015f zaman\",\"example\":\"I love reading in my free time.\"}]}','2026-10-04 20:30:40','2026-10-04 20:30:40'),
(93,9,'Dilbilgisi pekiştir','grammar','lesson',4,15,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"They enjoy ___ games online.\",\"options\":[\"playing\",\"play\",\"to playing\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"___ do you go to the cinema? Once a month.\",\"options\":[\"What\",\"How often\",\"How much\"],\"answer\":1},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"I\",\"enjoy\",\"swim\",\"in\",\"summer\"],\"error_index\":2,\"options\":[\"swimming\",\"swims\",\"to swimming\"],\"answer\":0,\"explanation_tr\":\"\\\"Enjoy\\\" kendisinden sonra -ing ister: I enjoy swimming in summer.\"},{\"type\":\"translate\",\"prompt\":\"Bo\\u015f zaman\\u0131nda ne yapars\\u0131n?\",\"answer\":\"What do you do in your free time\",\"alternatives\":[],\"tiles\":[\"are\",\"free\",\"What\",\"your\",\"in\",\"does\",\"you\",\"do\",\"do\",\"time\"]},{\"type\":\"fill\",\"prompt\":\"She ___ swimming in the sea.\",\"options\":[\"loves\",\"love\",\"loving\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"I like ___ to music.\",\"options\":[\"listen\",\"listening\",\"listens\"],\"answer\":1},{\"type\":\"translate\",\"prompt\":\"Hafta sonu yemek yapmay\\u0131 severim.\",\"answer\":\"I like cooking at the weekend\",\"alternatives\":[\"I like to cook at the weekend\",\"I love cooking at the weekend\"],\"tiles\":[\"in\",\"I\",\"the\",\"cook\",\"at\",\"weekend\",\"cooking\",\"like\"]},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I don\'t like getting up early.\",\"translation\":\"Erken kalkmay\\u0131 sevmem.\"}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(94,9,'Dinle ve konuş','listening','lesson',5,15,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Yeni tan\\u0131\\u015ft\\u0131\\u011f\\u0131n biri hobilerini soruyor.\",\"lines\":[{\"who\":\"Leo\",\"text\":\"So, what do you like doing in your free time?\"}],\"options\":[\"I love playing basketball and I enjoy reading comics.\",\"I like play basketball.\",\"I am liking basketball play.\"],\"answer\":0,\"note_tr\":\"\\\"Like \\/ love \\/ enjoy\\\" + fiil-ing en do\\u011fal kal\\u0131pt\\u0131r: I love playing \\u2026\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"How often do you swim\",\"options\":[\"How often do you swim\",\"How often do you sing\",\"How old are you\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"I like reading books\",\"answer\":\"I like reading books\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"My favourite hobby is drawing.\",\"translation\":\"En sevdi\\u011fim hobi resim \\u00e7izmek.\"},{\"type\":\"translate\",\"prompt\":\"Bo\\u015f zaman\\u0131nda ne yapars\\u0131n?\",\"answer\":\"What do you do in your free time\",\"alternatives\":[],\"tiles\":[\"are\",\"free\",\"What\",\"your\",\"in\",\"does\",\"you\",\"do\",\"do\",\"time\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"What do you do at the weekend\",\"answer\":\"What do you do at the weekend\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I don\'t like getting up early.\",\"translation\":\"Erken kalkmay\\u0131 sevmem.\"}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
