[],\"tiles\":[\"doing\",\"What\",\"do\",\"are\",\"you\",\"is\"]},{\"type\":\"fill\",\"prompt\":\"She ___ swimming in the sea.\",\"options\":[\"love\",\"loves\",\"loving\"],\"answer\":1},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"I like reading books\",\"answer\":\"I like reading books\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I don\'t like getting up early.\",\"translation\":\"Erken kalkmay\\u0131 sevmem.\"}]',NULL,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(101,10,'Kelimeler','vocabulary','lesson',0,18,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"yesterday\",\"d\\u00fcn\"],[\"last week\",\"ge\\u00e7en hafta\"],[\"ago\",\"\\u00f6nce\"],[\"visit\",\"ziyaret etmek\"],[\"stay\",\"kalmak\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"travel\\\" ne demek?\",\"options\":[\"heyecanl\\u0131\",\"yorgun\",\"seyahat etmek\",\"\\u00f6nce\"],\"answer\":2,\"audio\":\"travel\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"I was really tired\",\"options\":[\"I was really tired\",\"I was really tidy\",\"I am really tired\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Ge\\u00e7en hafta sonu b\\u00fcy\\u00fckanne ve b\\u00fcy\\u00fckbabam\\u0131 ziyaret ettim.\",\"answer\":\"I visited my grandparents last weekend\",\"alternatives\":[],\"tiles\":[\"my\",\"visited\",\"I\",\"weekend\",\"visit\",\"last\",\"grandparents\",\"arrive\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"travel\",\"seyahat etmek\"],[\"arrive\",\"varmak\"],[\"tired\",\"yorgun\"],[\"bored\",\"s\\u0131k\\u0131lm\\u0131\\u015f\"],[\"excited\",\"heyecanl\\u0131\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"s\\u0131k\\u0131lm\\u0131\\u015f\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"bored\",\"visit\",\"last week\",\"tired\"],\"answer\":0},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"We arrived in Ankara two hours ago.\",\"translation\":\"\\u0130ki saat \\u00f6nce Ankara\'ya vard\\u0131k.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"She was very tired yesterday\",\"answer\":\"She was very tired yesterday\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(102,10,'Dilbilgisi','grammar','lesson',1,18,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"I ___ at the cinema last night.\",\"options\":[\"was\",\"were\",\"am\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"They ___ very excited about the trip.\",\"options\":[\"was\",\"were\",\"are\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"We ___ football after school yesterday.\",\"options\":[\"play\",\"played\",\"playing\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"___ you at home on Sunday?\",\"options\":[\"Was\",\"Were\",\"Did\"],\"answer\":1},{\"type\":\"translate\",\"prompt\":\"D\\u00fcn evdeydim.\",\"answer\":\"I was at home yesterday\",\"alternatives\":[\"Yesterday I was at home\"],\"tiles\":[\"I\",\"at\",\"in\",\"was\",\"home\",\"were\",\"yesterday\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"We\",\"was\",\"very\",\"happy\",\"at\",\"the\",\"party\"],\"error_index\":1,\"options\":[\"were\",\"are\",\"is\"],\"answer\":0,\"explanation_tr\":\"\\\"We\\\" ile ge\\u00e7mi\\u015f zamanda \\\"were\\\" kullan\\u0131l\\u0131r. \\\"Was\\\" yaln\\u0131zca I, he, she, it i\\u00e7indir.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Where were you last night?\",\"translation\":\"D\\u00fcn gece neredeydin?\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(103,10,'Okuma: A Weekend in Bursa','reading','lesson',2,18,0,NULL,NULL,'[{\"type\":\"read\",\"title\":\"A Weekend in Bursa\",\"passage\":\"Last weekend I visited my grandparents in Bursa. We travelled by bus and arrived on Friday evening. I was tired, but I was excited too. On Saturday we walked around the old town and stayed at a small caf\\u00e9 for hours. On Sunday it rained, so we played cards at home. I wasn\'t bored at all. It was a lovely weekend.\",\"prompt\":\"How did they travel?\",\"options\":[\"By car\",\"By bus\",\"By plane\",\"By train\"],\"answer\":1},{\"type\":\"read\",\"title\":\"A Weekend in Bursa\",\"passage\":\"Last weekend I visited my grandparents in Bursa. We travelled by bus and arrived on Friday evening. I was tired, but I was excited too. On Saturday we walked around the old town and stayed at a small caf\\u00e9 for hours. On Sunday it rained, so we played cards at home. I wasn\'t bored at all. It was a lovely weekend.\",\"prompt\":\"What did they do on Sunday?\",\"options\":[\"They walked in the old town.\",\"They played cards at home.\",\"They went to the beach.\",\"They came back home.\"],\"answer\":1},{\"type\":\"read\",\"title\":\"A Weekend in Bursa\",\"passage\":\"Last weekend I visited my grandparents in Bursa. We travelled by bus and arrived on Friday evening. I was tired, but I was excited too. On Saturday we walked around the old town and stayed at a small caf\\u00e9 for hours. On Sunday it rained, so we played cards at home. I wasn\'t bored at all. It was a lovely weekend.\",\"prompt\":\"How did the writer feel about the weekend?\",\"options\":[\"It was boring.\",\"It was too short.\",\"It was lovely.\",\"It was too wet.\"],\"answer\":2}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(104,10,'Kelime oyunu','vocabulary','words',3,18,0,NULL,NULL,'[]','{\"game\":\"match\",\"words\":[{\"word\":\"yesterday\",\"translation\":\"d\\u00fcn\",\"example\":\"She was very tired yesterday\"},{\"word\":\"last week\",\"translation\":\"ge\\u00e7en hafta\"},{\"word\":\"ago\",\"translation\":\"\\u00f6nce\",\"example\":\"We arrived in Ankara two hours ago.\"},{\"word\":\"visit\",\"translation\":\"ziyaret etmek\"},{\"word\":\"stay\",\"translation\":\"kalmak\"},{\"word\":\"travel\",\"translation\":\"seyahat etmek\"},{\"word\":\"arrive\",\"translation\":\"varmak\"},{\"word\":\"tired\",\"translation\":\"yorgun\",\"example\":\"She was very tired yesterday\"},{\"word\":\"bored\",\"translation\":\"s\\u0131k\\u0131lm\\u0131\\u015f\"},{\"word\":\"excited\",\"translation\":\"heyecanl\\u0131\",\"example\":\"They were very excited about the trip.\"}]}','2026-10-04 20:30:41','2026-10-04 20:30:41'),
