(106,10,'Dinle ve konuş','listening','lesson',5,18,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Pazartesi sabah\\u0131. \\u0130\\u015f arkada\\u015f\\u0131n hafta sonunu soruyor.\",\"lines\":[{\"who\":\"Jess\",\"text\":\"Hi! Where were you on Saturday? I called you.\"}],\"options\":[\"Sorry, I was at my cousin\'s wedding in Sivas.\",\"I am at wedding Saturday.\",\"I were at a wedding.\"],\"answer\":0,\"note_tr\":\"Ge\\u00e7mi\\u015fte bulundu\\u011fun yer i\\u00e7in I was \\u2026 kal\\u0131b\\u0131 kullan\\u0131l\\u0131r.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"They stayed at a hotel\",\"options\":[\"They stayed at a hotel\",\"They stay at a hotel\",\"They stayed at home\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"We visited a museum\",\"answer\":\"We visited a museum\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I watched a great film yesterday.\",\"translation\":\"D\\u00fcn harika bir film izledim.\"},{\"type\":\"translate\",\"prompt\":\"Ge\\u00e7en yaz Bodrum\'da kald\\u0131k.\",\"answer\":\"We stayed in Bodrum last summer\",\"alternatives\":[\"Last summer we stayed in Bodrum\"],\"tiles\":[\"last\",\"stayed\",\"stay\",\"at\",\"Bodrum\",\"We\",\"in\",\"summer\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"It was very cold\",\"answer\":\"It was very cold\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"The weather was lovely.\",\"translation\":\"Hava \\u00e7ok g\\u00fczeldi.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
