(110,10,'Pratik','vocabulary','lesson',9,18,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"bored\",\"s\\u0131k\\u0131lm\\u0131\\u015f\"],[\"arrive\",\"varmak\"],[\"tired\",\"yorgun\"],[\"visit\",\"ziyaret etmek\"],[\"excited\",\"heyecanl\\u0131\"]]},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"last week\",\"options\":[\"bored\",\"last week\",\"arrive\",\"stay\"],\"answer\":1},{\"type\":\"choice\",\"prompt\":\"\\\"ago\\\" ne demek?\",\"options\":[\"varmak\",\"heyecanl\\u0131\",\"kalmak\",\"\\u00f6nce\"],\"answer\":3,\"audio\":\"ago\"},{\"type\":\"choice\",\"prompt\":\"\\\"kalmak\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"stay\",\"excited\",\"visit\",\"tired\"],\"answer\":0},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"arrive\",\"options\":[\"visit\",\"excited\",\"arrive\",\"last week\"],\"answer\":2},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"excited\",\"answer\":\"excited\"},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"excited\",\"heyecanl\\u0131\"],[\"yesterday\",\"d\\u00fcn\"],[\"bored\",\"s\\u0131k\\u0131lm\\u0131\\u015f\"],[\"visit\",\"ziyaret etmek\"],[\"ago\",\"\\u00f6nce\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"yesterday\\\" ne demek?\",\"options\":[\"yorgun\",\"kalmak\",\"d\\u00fcn\",\"\\u00f6nce\"],\"answer\":2,\"audio\":\"yesterday\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
