(112,11,'Kelimeler','vocabulary','lesson',0,18,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"went\",\"gitti\"],[\"saw\",\"g\\u00f6rd\\u00fc\"],[\"bought\",\"sat\\u0131n ald\\u0131\"],[\"ate\",\"yedi\"],[\"took\",\"ald\\u0131, g\\u00f6t\\u00fcrd\\u00fc\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"found\\\" ne demek?\",\"options\":[\"sonunda\",\"buldu\",\"sat\\u0131n ald\\u0131\",\"sonra\"],\"answer\":1,\"audio\":\"found\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"Did you enjoy the concert?\",\"options\":[\"Did you enjoy the concert?\",\"Do you enjoy the concert?\",\"Did you join the concert?\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"\\u00d6nce plaja gittik, sonra bal\\u0131k yedik.\",\"answer\":\"First we went to the beach, then we ate fish\",\"alternatives\":[],\"tiles\":[\"we\",\"took\",\"ate\",\"the\",\"we\",\"went\",\"then\",\"then\",\"First\",\"to\",\"beach\",\"fish\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"found\",\"buldu\"],[\"first\",\"\\u00f6nce\"],[\"then\",\"sonra\"],[\"after that\",\"ondan sonra\"],[\"finally\",\"sonunda\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"ondan sonra\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"saw\",\"then\",\"ate\",\"after that\"],\"answer\":3},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I found my keys under the sofa.\",\"translation\":\"Anahtarlar\\u0131m\\u0131 kanepenin alt\\u0131nda buldum.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"She bought a new phone\",\"answer\":\"She bought a new phone\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(113,11,'Dilbilgisi','grammar','lesson',1,18,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"We ___ a great film yesterday.\",\"options\":[\"see\",\"saw\",\"seen\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"I didn\'t ___ to the party.\",\"options\":[\"go\",\"went\",\"gone\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"___ you buy that jacket online?\",\"options\":[\"Did\",\"Were\",\"Do\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"He ___ the bus to school this morning.\",\"options\":[\"take\",\"took\",\"taken\"],\"answer\":1},{\"type\":\"translate\",\"prompt\":\"Ge\\u00e7en yaz \\u0130talya\'ya gittik.\",\"answer\":\"We went to Italy last summer\",\"alternatives\":[\"Last summer we went to Italy\"],\"tiles\":[\"went\",\"to\",\"We\",\"last\",\"go\",\"in\",\"Italy\",\"summer\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"Yesterday\",\"I\",\"didn\'t\",\"went\",\"to\",\"school\"],\"error_index\":3,\"options\":[\"go\",\"gone\",\"going\"],\"answer\":0,\"explanation_tr\":\"\\\"didn\'t\\\" zaten ge\\u00e7mi\\u015fi ta\\u015f\\u0131r; yan\\u0131ndaki fiil yal\\u0131n kal\\u0131r. Do\\u011frusu: I didn\'t go.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I visited my grandparents last weekend.\",\"translation\":\"Ge\\u00e7en hafta sonu b\\u00fcy\\u00fckanne ve b\\u00fcy\\u00fckbabam\\u0131 ziyaret ettim.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(114,11,'Okuma: The Lost Wallet','reading','lesson',2,18,0,NULL,NULL,'[{\"type\":\"read\",\"title\":\"The Lost Wallet\",\"passage\":\"Yesterday something strange happened. I went to the park after school and sat on a bench. Then I saw a black wallet under the bench. I took it and looked inside. There was some money and an ID card. After that I went to the police station and gave it to an officer. Finally, the owner called me and said thank you. She bought me an ice cream!\",\"prompt\":\"Where did the writer find the wallet?\",\"options\":[\"On the bus\",\"Under a bench\",\"At school\",\"In a shop\"],\"answer\":1},{\"type\":\"read\",\"title\":\"The Lost Wallet\",\"passage\":\"Yesterday something strange happened. I went to the park after school and sat on a bench. Then I saw a black wallet under the bench. I took it and looked inside. There was some money and an ID card. After that I went to the police station and gave it to an officer. Finally, the owner called me and said thank you. She bought me an ice cream!\",\"prompt\":\"What did the writer do with the wallet?\",\"options\":[\"Kept the money\",\"Took it to the police\",\"Left it in the park\",\"Gave it to a friend\"],\"answer\":1}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(115,11,'Kelime oyunu','vocabulary','words',3,18,0,NULL,NULL,'[]','{\"game\":\"choice\",\"words\":[{\"word\":\"went\",\"translation\":\"gitti\",\"example\":\"First we went to the beach, then we ate fish.\"},{\"word\":\"saw\",\"translation\":\"g\\u00f6rd\\u00fc\",\"example\":\"We saw a great film yesterday.\"},{\"word\":\"bought\",\"translation\":\"sat\\u0131n ald\\u0131\",\"example\":\"She bought a new phone\"},{\"word\":\"ate\",\"translation\":\"yedi\",\"example\":\"First we went to the beach, then we ate fish.\"},{\"word\":\"took\",\"translation\":\"ald\\u0131, g\\u00f6t\\u00fcrd\\u00fc\",\"example\":\"He took the bus to school this morning.\"},{\"word\":\"found\",\"translation\":\"buldu\",\"example\":\"I found my keys under the sofa.\"},{\"word\":\"first\",\"translation\":\"\\u00f6nce\",\"example\":\"First we went to the beach, then we ate fish.\"},{\"word\":\"then\",\"translation\":\"sonra\",\"example\":\"First we went to the beach, then we ate fish.\"},{\"word\":\"after that\",\"translation\":\"ondan sonra\"},{\"word\":\"finally\",\"translation\":\"sonunda\",\"example\":\"Finally, we got home at midnight.\"}]}','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(116,11,'Dilbilgisi pekiştir','grammar','lesson',4,18,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"He ___ the bus to school this morning.\",\"options\":[\"take\",\"taken\",\"took\"],\"answer\":2},{\"type\":\"fill\",\"prompt\":\"___ you buy that jacket online?\",\"options\":[\"Did\",\"Do\",\"Were\"],\"answer\":0},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"Yesterday\",\"I\",\"didn\'t\",\"went\",\"to\",\"school\"],\"error_index\":3,\"options\":[\"go\",\"gone\",\"going\"],\"answer\":0,\"explanation_tr\":\"\\\"didn\'t\\\" zaten ge\\u00e7mi\\u015fi ta\\u015f\\u0131r; yan\\u0131ndaki fiil yal\\u0131n kal\\u0131r. Do\\u011frusu: I didn\'t go.\"},{\"type\":\"translate\",\"prompt\":\"Kahvalt\\u0131da ne yedin?\",\"answer\":\"What did you eat for breakfast\",\"alternatives\":[\"What did you have for breakfast\"],\"tiles\":[\"do\",\"eat\",\"did\",\"breakfast\",\"What\",\"ate\",\"you\",\"for\"]},{\"type\":\"fill\",\"prompt\":\"I didn\'t ___ to the party.\",\"options\":[\"went\",\"gone\",\"go\"],\"answer\":2},{\"type\":\"fill\",\"prompt\":\"We ___ a great film yesterday.\",\"options\":[\"see\",\"saw\",\"seen\"],\"answer\":1},{\"type\":\"translate\",\"prompt\":\"Ge\\u00e7en yaz \\u0130talya\'ya gittik.\",\"answer\":\"We went to Italy last summer\",\"alternatives\":[\"Last summer we went to Italy\"],\"tiles\":[\"went\",\"to\",\"We\",\"last\",\"go\",\"in\",\"Italy\",\"summer\"]},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Finally, we got home at midnight.\",\"translation\":\"Sonunda gece yar\\u0131s\\u0131 eve vard\\u0131k.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(117,11,'Dinle ve konuş','listening','lesson',5,18,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Arkada\\u015f\\u0131n tatilini soruyor.\",\"lines\":[{\"who\":\"Mia\",\"text\":\"Did you have a good holiday?\"}],\"options\":[\"Yes, I did! We went to Cappadocia and took a balloon ride.\",\"Yes, I did go Cappadocia.\",\"Yes, we goed to Cappadocia.\"],\"answer\":0,\"note_tr\":\"K\\u0131sa cevap \\\"Yes, I did\\\" ile ba\\u015fla, sonra ge\\u00e7mi\\u015f zamanla bir detay ver.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"She bought a new phone\",\"options\":[\"She bought a new phone\",\"She brought a new phone\",\"She buys a new phone\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"We went to the cinema\",\"answer\":\"We went to the cinema\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"What did you do on your holiday?\",\"translation\":\"Tatilinde ne yapt\\u0131n?\"},{\"type\":\"translate\",\"prompt\":\"Kahvalt\\u0131da ne yedin?\",\"answer\":\"What did you eat for breakfast\",\"alternatives\":[\"What did you have for breakfast\"],\"tiles\":[\"do\",\"eat\",\"did\",\"breakfast\",\"What\",\"ate\",\"you\",\"for\"]},{\"type\":\"sequence\",\"prompt\":\"D\\u00fcn ak\\u015fam\\u0131n\\u0131 anlat. C\\u00fcmleleri olay s\\u0131ras\\u0131na diz.\",\"items\":[\"I finished work at six.\",\"I met my friend at the metro station.\",\"We had dinner at a small restaurant.\",\"I got home just before midnight.\"],\"answer\":[0,1,2,3]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"What did you buy\",\"answer\":\"What did you buy\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Finally, we got home at midnight.\",\"translation\":\"Sonunda gece yar\\u0131s\\u0131 eve vard\\u0131k.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(118,11,'Kelime tekrarı','vocabulary','lesson',6,18,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"then\",\"sonra\"],[\"went\",\"gitti\"],[\"after that\",\"ondan sonra\"],[\"finally\",\"sonunda\"],[\"found\",\"buldu\"]]},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"saw\",\"options\":[\"after that\",\"saw\",\"took\",\"first\"],\"answer\":1},{\"type\":\"choice\",\"prompt\":\"\\\"bought\\\" ne demek?\",\"options\":[\"sonunda\",\"\\u00f6nce\",\"ald\\u0131, g\\u00f6t\\u00fcrd\\u00fc\",\"sat\\u0131n ald\\u0131\"],\"answer\":3,\"audio\":\"bought\"},{\"type\":\"choice\",\"prompt\":\"\\\"ald\\u0131, g\\u00f6t\\u00fcrd\\u00fc\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"then\",\"took\",\"ate\",\"finally\"],\"answer\":1},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"first\",\"options\":[\"ate\",\"first\",\"finally\",\"saw\"],\"answer\":1},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"finally\",\"answer\":\"finally\"},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"first\",\"\\u00f6nce\"],[\"saw\",\"g\\u00f6rd\\u00fc\"],[\"ate\",\"yedi\"],[\"after that\",\"ondan sonra\"],[\"took\",\"ald\\u0131, g\\u00f6t\\u00fcrd\\u00fc\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"went\\\" ne demek?\",\"options\":[\"gitti\",\"sat\\u0131n ald\\u0131\",\"sonra\",\"ald\\u0131, g\\u00f6t\\u00fcrd\\u00fc\"],\"answer\":0,\"audio\":\"went\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(119,11,'Telaffuz','speaking','lesson',7,18,0,NULL,NULL,'[{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"went\",\"translation\":\"gitti\"},{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"saw\",\"translation\":\"g\\u00f6rd\\u00fc\"},{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"bought\",\"translation\":\"sat\\u0131n ald\\u0131\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"First we went to the beach, then we ate fish.\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"I visited my grandparents last weekend.\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"What did you do on your holiday?\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
