(123,12,'Kelimeler','vocabulary','lesson',0,18,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"holiday\",\"tatil\"],[\"plan\",\"plan\"],[\"book a ticket\",\"bilet ay\\u0131rtmak\"],[\"pack\",\"bavul haz\\u0131rlamak\"],[\"beach\",\"plaj\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"mountain\\\" ne demek?\",\"options\":[\"yurt d\\u0131\\u015f\\u0131nda\",\"da\\u011f\",\"yar\\u0131n\",\"bilet ay\\u0131rtmak\"],\"answer\":1,\"audio\":\"mountain\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"It\'s going to rain\",\"options\":[\"It\'s going to rain\",\"It\'s going to train\",\"It\'s going to snow\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Biletlerimizi bu ak\\u015fam ay\\u0131rtaca\\u011f\\u0131z.\",\"answer\":\"We\'re going to book our tickets tonight\",\"alternatives\":[],\"tiles\":[\"book\",\"going\",\"tonight\",\"next week\",\"to\",\"mountain\",\"tickets\",\"our\",\"We\'re\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"mountain\",\"da\\u011f\"],[\"tent\",\"\\u00e7ad\\u0131r\"],[\"tomorrow\",\"yar\\u0131n\"],[\"next week\",\"gelecek hafta\"],[\"abroad\",\"yurt d\\u0131\\u015f\\u0131nda\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"gelecek hafta\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"plan\",\"next week\",\"tomorrow\",\"pack\"],\"answer\":1},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"She is going to study abroad next year.\",\"translation\":\"Gelecek y\\u0131l yurt d\\u0131\\u015f\\u0131nda okuyacak.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"I\'m going to pack my bag\",\"answer\":\"I\'m going to pack my bag\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(124,12,'Dilbilgisi','grammar','lesson',1,18,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"I\'m going ___ my grandparents.\",\"options\":[\"visit\",\"to visit\",\"visiting\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"They ___ going to stay in a tent.\",\"options\":[\"is\",\"are\",\"am\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"Look at the sky! It ___ to rain.\",\"options\":[\"\'s going\",\"goes\",\"\'re going\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"What ___ you going to do this summer?\",\"options\":[\"are\",\"do\",\"will\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Yar\\u0131n erken kalkaca\\u011f\\u0131m.\",\"answer\":\"I\'m going to get up early tomorrow\",\"alternatives\":[\"I am going to get up early tomorrow\"],\"tiles\":[\"will\",\"at\",\"up\",\"early\",\"going\",\"to\",\"get\",\"tomorrow\",\"I\'m\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"We\'re\",\"going\",\"to\",\"visiting\",\"Paris\",\"next\",\"month\"],\"error_index\":3,\"options\":[\"visit\",\"visited\",\"visits\"],\"answer\":0,\"explanation_tr\":\"\\\"Going to\\\"dan sonra fiil yal\\u0131n kal\\u0131r: We\'re going to visit Paris.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I\'m going to travel to Japan one day.\",\"translation\":\"Bir g\\u00fcn Japonya\'ya seyahat edece\\u011fim.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(125,12,'Okuma: Summer Plans','reading','lesson',2,18,0,NULL,NULL,'[{\"type\":\"read\",\"title\":\"Summer Plans\",\"passage\":\"This summer my family is going to travel abroad for the first time. We are going to visit Greece. My father is going to book the tickets next week, and my mother is going to plan the trip. We are going to stay near the beach for five days, and then we are going to go to the mountains. I am going to pack my bag tomorrow!\",\"prompt\":\"Who is going to book the tickets?\",\"options\":[\"The mother\",\"The writer\",\"The father\",\"A travel agent\"],\"answer\":2},{\"type\":\"read\",\"title\":\"Summer Plans\",\"passage\":\"This summer my family is going to travel abroad for the first time. We are going to visit Greece. My father is going to book the tickets next week, and my mother is going to plan the trip. We are going to stay near the beach for five days, and then we are going to go to the mountains. I am going to pack my bag tomorrow!\",\"prompt\":\"How long will they stay near the beach?\",\"options\":[\"Three days\",\"Five days\",\"One week\",\"Two weeks\"],\"answer\":1}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(126,12,'Kelime oyunu','vocabulary','words',3,18,0,NULL,NULL,'[]','{\"game\":\"scramble\",\"words\":[{\"word\":\"holiday\",\"translation\":\"tatil\"},{\"word\":\"plan\",\"translation\":\"plan\"},{\"word\":\"book a ticket\",\"translation\":\"bilet ay\\u0131rtmak\"},{\"word\":\"pack\",\"translation\":\"bavul haz\\u0131rlamak\",\"example\":\"I\'m going to pack my bag\"},{\"word\":\"beach\",\"translation\":\"plaj\"},{\"word\":\"mountain\",\"translation\":\"da\\u011f\"},{\"word\":\"tent\",\"translation\":\"\\u00e7ad\\u0131r\",\"example\":\"They are going to stay in a tent.\"},{\"word\":\"tomorrow\",\"translation\":\"yar\\u0131n\"},{\"word\":\"next week\",\"translation\":\"gelecek hafta\"},{\"word\":\"abroad\",\"translation\":\"yurt d\\u0131\\u015f\\u0131nda\",\"example\":\"She is going to study abroad next year.\"}]}','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(127,12,'Dilbilgisi pekiştir','grammar','lesson',4,18,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"What ___ you going to do this summer?\",\"options\":[\"are\",\"will\",\"do\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"Look at the sky! It ___ to rain.\",\"options\":[\"goes\",\"\'re going\",\"\'s going\"],\"answer\":2},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"We\'re\",\"going\",\"to\",\"visiting\",\"Paris\",\"next\",\"month\"],\"error_index\":3,\"options\":[\"visit\",\"visited\",\"visits\"],\"answer\":0,\"explanation_tr\":\"\\\"Going to\\\"dan sonra fiil yal\\u0131n kal\\u0131r: We\'re going to visit Paris.\"},{\"type\":\"translate\",\"prompt\":\"Bu yaz ne yapacaks\\u0131n?\",\"answer\":\"What are you going to do this summer\",\"alternatives\":[],\"tiles\":[\"do\",\"What\",\"you\",\"to\",\"this\",\"do\",\"going\",\"summer\",\"are\",\"will\"]},{\"type\":\"fill\",\"prompt\":\"They ___ going to stay in a tent.\",\"options\":[\"is\",\"are\",\"am\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"I\'m going ___ my grandparents.\",\"options\":[\"visit\",\"visiting\",\"to visit\"],\"answer\":2},{\"type\":\"translate\",\"prompt\":\"Yar\\u0131n erken kalkaca\\u011f\\u0131m.\",\"answer\":\"I\'m going to get up early tomorrow\",\"alternatives\":[\"I am going to get up early tomorrow\"],\"tiles\":[\"will\",\"at\",\"up\",\"early\",\"going\",\"to\",\"get\",\"tomorrow\",\"I\'m\"]},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"We\'re going to stay for a week.\",\"translation\":\"Bir hafta kalaca\\u011f\\u0131z.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(128,12,'Dinle ve konuş','listening','lesson',5,18,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Arkada\\u015f\\u0131n yaz planlar\\u0131n\\u0131 soruyor.\",\"lines\":[{\"who\":\"Tom\",\"text\":\"Any plans for the summer?\"}],\"options\":[\"Yes! I\'m going to work in a caf\\u00e9 and then go camping.\",\"Yes, I go work caf\\u00e9.\",\"Yes, I will going to work.\"],\"answer\":0,\"note_tr\":\"\\u00d6nceden kararla\\u015ft\\u0131r\\u0131lm\\u0131\\u015f planlar i\\u00e7in be going to kullan\\u0131l\\u0131r.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"We\'re going to book a hotel\",\"options\":[\"We\'re going to book a hotel\",\"We\'re going to look at a hotel\",\"We went to a hotel\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"I\'m going to pack my bag\",\"answer\":\"I\'m going to pack my bag\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Are you going to come to my party?\",\"translation\":\"Partime gelecek misin?\"},{\"type\":\"translate\",\"prompt\":\"Bu yaz ne yapacaks\\u0131n?\",\"answer\":\"What are you going to do this summer\",\"alternatives\":[],\"tiles\":[\"do\",\"What\",\"you\",\"to\",\"this\",\"do\",\"going\",\"summer\",\"are\",\"will\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"Are you going to come\",\"answer\":\"Are you going to come\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"We\'re going to stay for a week.\",\"translation\":\"Bir hafta kalaca\\u011f\\u0131z.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(129,12,'Kelime tekrarı','vocabulary','lesson',6,18,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"abroad\",\"yurt d\\u0131\\u015f\\u0131nda\"],[\"tent\",\"\\u00e7ad\\u0131r\"],[\"tomorrow\",\"yar\\u0131n\"],[\"mountain\",\"da\\u011f\"],[\"plan\",\"plan\"]]},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"plan\",\"options\":[\"beach\",\"tent\",\"plan\",\"next week\"],\"answer\":2},{\"type\":\"choice\",\"prompt\":\"\\\"book a ticket\\\" ne demek?\",\"options\":[\"yurt d\\u0131\\u015f\\u0131nda\",\"\\u00e7ad\\u0131r\",\"plaj\",\"bilet ay\\u0131rtmak\"],\"answer\":3,\"audio\":\"book a ticket\"},{\"type\":\"choice\",\"prompt\":\"\\\"plaj\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"abroad\",\"tomorrow\",\"pack\",\"beach\"],\"answer\":3},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"tent\",\"options\":[\"tent\",\"plan\",\"pack\",\"abroad\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"abroad\",\"answer\":\"abroad\"},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"tent\",\"\\u00e7ad\\u0131r\"],[\"pack\",\"bavul haz\\u0131rlamak\"],[\"beach\",\"plaj\"],[\"next week\",\"gelecek hafta\"],[\"mountain\",\"da\\u011f\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"holiday\\\" ne demek?\",\"options\":[\"plaj\",\"yar\\u0131n\",\"tatil\",\"bilet ay\\u0131rtmak\"],\"answer\":2,\"audio\":\"holiday\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(130,12,'Telaffuz','speaking','lesson',7,18,0,NULL,NULL,'[{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"holiday\",\"translation\":\"tatil\"},{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"plan\",\"translation\":\"plan\"},{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"pack\",\"translation\":\"bavul haz\\u0131rlamak\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"We\'re going to book our tickets tonight.\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"I\'m going to travel to Japan one day.\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"Are you going to come to my party?\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
