(134,13,'Kelimeler','vocabulary','lesson',0,18,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"bigger\",\"daha b\\u00fcy\\u00fck\"],[\"smaller\",\"daha k\\u00fc\\u00e7\\u00fck\"],[\"cheaper\",\"daha ucuz\"],[\"older\",\"daha ya\\u015fl\\u0131 \\/ eski\"],[\"crowded\",\"kalabal\\u0131k\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"quiet\\\" ne demek?\",\"options\":[\"daha ucuz\",\"sakin\",\"g\\u00fczel\",\"en iyi\"],\"answer\":1,\"audio\":\"quiet\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"Ankara is bigger than Izmir\",\"options\":[\"Ankara is bigger than Izmir\",\"Ankara is bigger then Izmir\",\"Ankara is big as Izmir\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"\\u0130zmir \\u0130stanbul\'dan daha sakin.\",\"answer\":\"Izmir is quieter than Istanbul\",\"alternatives\":[],\"tiles\":[\"Istanbul\",\"Izmir\",\"the best\",\"quieter\",\"modern\",\"than\",\"is\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"quiet\",\"sakin\"],[\"modern\",\"modern\"],[\"beautiful\",\"g\\u00fczel\"],[\"better\",\"daha iyi\"],[\"the best\",\"en iyi\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"daha iyi\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"better\",\"older\",\"beautiful\",\"smaller\"],\"answer\":0},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"This is the most beautiful beach in Turkey.\",\"translation\":\"Buras\\u0131 T\\u00fcrkiye\'nin en g\\u00fczel plaj\\u0131.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"My brother is older than me\",\"answer\":\"My brother is older than me\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(135,13,'Dilbilgisi','grammar','lesson',1,18,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"A plane is ___ than a train.\",\"options\":[\"fast\",\"faster\",\"fastest\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"This is the ___ restaurant in town.\",\"options\":[\"better\",\"good\",\"best\"],\"answer\":2},{\"type\":\"fill\",\"prompt\":\"Istanbul is ___ crowded than Rize.\",\"options\":[\"most\",\"more\",\"much\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"My bag isn\'t as heavy ___ yours.\",\"options\":[\"than\",\"as\",\"like\"],\"answer\":1},{\"type\":\"translate\",\"prompt\":\"Bu telefon \\u00f6tekinden daha ucuz.\",\"answer\":\"This phone is cheaper than that one\",\"alternatives\":[\"This phone is cheaper than the other one\"],\"tiles\":[\"one\",\"is\",\"cheaper\",\"that\",\"then\",\"more\",\"than\",\"This\",\"phone\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"Istanbul\",\"is\",\"bigger\",\"then\",\"Ankara\"],\"error_index\":3,\"options\":[\"than\",\"that\",\"as\"],\"answer\":0,\"explanation_tr\":\"Kar\\u015f\\u0131la\\u015ft\\u0131rmada \\\"than\\\" kullan\\u0131l\\u0131r. \\\"Then\\\" ise \\\"sonra\\\" demektir; yaz\\u0131l\\u0131\\u015flar\\u0131 benzedi\\u011fi i\\u00e7in s\\u0131k kar\\u0131\\u015ft\\u0131r\\u0131l\\u0131r.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Summer is better than winter.\",\"translation\":\"Yaz k\\u0131\\u015ftan daha iyidir.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(136,13,'Okuma: Big City, Small Town','reading','lesson',2,18,0,NULL,NULL,'[{\"type\":\"read\",\"title\":\"Big City, Small Town\",\"passage\":\"I live in Istanbul, but my cousin lives in a small town near Antalya. Istanbul is bigger and more crowded than her town. It is also more modern and more expensive. Her town is smaller, quieter and much cheaper. The weather there is better in winter, too. Which is the best place to live? I think both are beautiful in different ways.\",\"prompt\":\"Which city is more expensive?\",\"options\":[\"The small town\",\"Istanbul\",\"Antalya\",\"They are the same.\"],\"answer\":1},{\"type\":\"read\",\"title\":\"Big City, Small Town\",\"passage\":\"I live in Istanbul, but my cousin lives in a small town near Antalya. Istanbul is bigger and more crowded than her town. It is also more modern and more expensive. Her town is smaller, quieter and much cheaper. The weather there is better in winter, too. Which is the best place to live? I think both are beautiful in different ways.\",\"prompt\":\"What does the writer think?\",\"options\":[\"Istanbul is the best.\",\"The town is boring.\",\"Both places are beautiful.\",\"Nobody should live in cities.\"],\"answer\":2}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(137,13,'Kelime oyunu','vocabulary','words',3,18,0,NULL,NULL,'[]','{\"game\":\"truefalse\",\"words\":[{\"word\":\"bigger\",\"translation\":\"daha b\\u00fcy\\u00fck\"},{\"word\":\"smaller\",\"translation\":\"daha k\\u00fc\\u00e7\\u00fck\"},{\"word\":\"cheaper\",\"translation\":\"daha ucuz\"},{\"word\":\"older\",\"translation\":\"daha ya\\u015fl\\u0131 \\/ eski\",\"example\":\"My brother is older than me\"},{\"word\":\"crowded\",\"translation\":\"kalabal\\u0131k\",\"example\":\"Istanbul is more crowded than Rize.\"},{\"word\":\"quiet\",\"translation\":\"sakin\"},{\"word\":\"modern\",\"translation\":\"modern\"},{\"word\":\"beautiful\",\"translation\":\"g\\u00fczel\",\"example\":\"This is the most beautiful beach in Turkey.\"},{\"word\":\"better\",\"translation\":\"daha iyi\",\"example\":\"Summer is better than winter.\"},{\"word\":\"the best\",\"translation\":\"en iyi\",\"example\":\"This is the best day ever\"}]}','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(138,13,'Dilbilgisi pekiştir','grammar','lesson',4,18,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"My bag isn\'t as heavy ___ yours.\",\"options\":[\"than\",\"as\",\"like\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"Istanbul is ___ crowded than Rize.\",\"options\":[\"most\",\"much\",\"more\"],\"answer\":2},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"Istanbul\",\"is\",\"bigger\",\"then\",\"Ankara\"],\"error_index\":3,\"options\":[\"than\",\"that\",\"as\"],\"answer\":0,\"explanation_tr\":\"Kar\\u015f\\u0131la\\u015ft\\u0131rmada \\\"than\\\" kullan\\u0131l\\u0131r. \\\"Then\\\" ise \\\"sonra\\\" demektir; yaz\\u0131l\\u0131\\u015flar\\u0131 benzedi\\u011fi i\\u00e7in s\\u0131k kar\\u0131\\u015ft\\u0131r\\u0131l\\u0131r.\"},{\"type\":\"translate\",\"prompt\":\"T\\u00fcrkiye\'nin en b\\u00fcy\\u00fck \\u015fehri hangisi?\",\"answer\":\"What is the biggest city in Turkey\",\"alternatives\":[\"What\'s the biggest city in Turkey\",\"Which is the biggest city in Turkey\"],\"tiles\":[\"Turkey\",\"biggest\",\"is\",\"in\",\"What\",\"bigger\",\"city\",\"in\",\"the\"]},{\"type\":\"fill\",\"prompt\":\"This is the ___ restaurant in town.\",\"options\":[\"better\",\"good\",\"best\"],\"answer\":2},{\"type\":\"fill\",\"prompt\":\"A plane is ___ than a train.\",\"options\":[\"fast\",\"faster\",\"fastest\"],\"answer\":1},{\"type\":\"translate\",\"prompt\":\"Bu telefon \\u00f6tekinden daha ucuz.\",\"answer\":\"This phone is cheaper than that one\",\"alternatives\":[\"This phone is cheaper than the other one\"],\"tiles\":[\"one\",\"is\",\"cheaper\",\"that\",\"then\",\"more\",\"than\",\"This\",\"phone\"]},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"It isn\'t as expensive as I thought.\",\"translation\":\"D\\u00fc\\u015f\\u00fcnd\\u00fc\\u011f\\u00fcm kadar pahal\\u0131 de\\u011fil.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(139,13,'Dinle ve konuş','listening','lesson',5,18,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Arkada\\u015f\\u0131n iki telefon aras\\u0131nda karars\\u0131z.\",\"lines\":[{\"who\":\"Sara\",\"text\":\"Which one should I buy, the black phone or the white one?\"}],\"options\":[\"The black one is cheaper, but the white one has a better camera.\",\"Black one more cheap.\",\"The white is goodest.\"],\"answer\":0,\"note_tr\":\"\\u0130ki \\u015feyi tartarken comparative kullan: cheaper, better\\u2026\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"the most expensive hotel\",\"options\":[\"the most expensive hotel\",\"the more expensive hotel\",\"the most extensive hotel\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"This is the best day ever\",\"answer\":\"This is the best day ever\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Which city is the most beautiful?\",\"translation\":\"Hangi \\u015fehir en g\\u00fczeli?\"},{\"type\":\"translate\",\"prompt\":\"T\\u00fcrkiye\'nin en b\\u00fcy\\u00fck \\u015fehri hangisi?\",\"answer\":\"What is the biggest city in Turkey\",\"alternatives\":[\"What\'s the biggest city in Turkey\",\"Which is the biggest city in Turkey\"],\"tiles\":[\"Turkey\",\"biggest\",\"is\",\"in\",\"What\",\"bigger\",\"city\",\"in\",\"the\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"My sister is taller than me\",\"answer\":\"My sister is taller than me\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"It isn\'t as expensive as I thought.\",\"translation\":\"D\\u00fc\\u015f\\u00fcnd\\u00fc\\u011f\\u00fcm kadar pahal\\u0131 de\\u011fil.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(140,13,'Kelime tekrarı','vocabulary','lesson',6,18,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"modern\",\"modern\"],[\"bigger\",\"daha b\\u00fcy\\u00fck\"],[\"the best\",\"en iyi\"],[\"beautiful\",\"g\\u00fczel\"],[\"cheaper\",\"daha ucuz\"]]},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"smaller\",\"options\":[\"crowded\",\"modern\",\"better\",\"smaller\"],\"answer\":3},{\"type\":\"choice\",\"prompt\":\"\\\"cheaper\\\" ne demek?\",\"options\":[\"en iyi\",\"modern\",\"daha ucuz\",\"kalabal\\u0131k\"],\"answer\":2,\"audio\":\"cheaper\"},{\"type\":\"choice\",\"prompt\":\"\\\"kalabal\\u0131k\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"older\",\"crowded\",\"beautiful\",\"the best\"],\"answer\":1},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"modern\",\"options\":[\"modern\",\"smaller\",\"the best\",\"older\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"the best\",\"answer\":\"the best\"},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"better\",\"daha iyi\"],[\"the best\",\"en iyi\"],[\"smaller\",\"daha k\\u00fc\\u00e7\\u00fck\"],[\"quiet\",\"sakin\"],[\"crowded\",\"kalabal\\u0131k\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"bigger\\\" ne demek?\",\"options\":[\"g\\u00fczel\",\"daha b\\u00fcy\\u00fck\",\"daha ucuz\",\"kalabal\\u0131k\"],\"answer\":1,\"audio\":\"bigger\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
