(145,14,'Kelimeler','vocabulary','lesson',0,18,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"headache\",\"ba\\u015f a\\u011fr\\u0131s\\u0131\"],[\"stomach ache\",\"mide a\\u011fr\\u0131s\\u0131\"],[\"sore throat\",\"bo\\u011faz a\\u011fr\\u0131s\\u0131\"],[\"cold\",\"so\\u011fuk alg\\u0131nl\\u0131\\u011f\\u0131\"],[\"temperature\",\"ate\\u015f\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"medicine\\\" ne demek?\",\"options\":[\"ac\\u0131mak\",\"-meli \\/ -mal\\u0131\",\"ila\\u00e7\",\"bo\\u011faz a\\u011fr\\u0131s\\u0131\"],\"answer\":2,\"audio\":\"medicine\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"I\'ve got a headache\",\"options\":[\"I\'ve got a headache\",\"I\'ve got a heart ache\",\"I\'ve got a head cold\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Ba\\u015f\\u0131m \\u00e7ok a\\u011fr\\u0131yor.\",\"answer\":\"I\'ve got a terrible headache\",\"alternatives\":[],\"tiles\":[\"got\",\"a\",\"headache\",\"hurt\",\"terrible\",\"headache\",\"I\'ve\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"medicine\",\"ila\\u00e7\"],[\"rest\",\"dinlenmek\"],[\"hurt\",\"ac\\u0131mak\"],[\"healthy\",\"sa\\u011fl\\u0131kl\\u0131\"],[\"should\",\"-meli \\/ -mal\\u0131\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"sa\\u011fl\\u0131kl\\u0131\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"healthy\",\"hurt\",\"cold\",\"stomach ache\"],\"answer\":0},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"You should rest and drink some tea.\",\"translation\":\"Dinlenmeli ve biraz \\u00e7ay i\\u00e7melisin.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"My back hurts\",\"answer\":\"My back hurts\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(146,14,'Dilbilgisi','grammar','lesson',1,18,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"You ___ see a doctor.\",\"options\":[\"should\",\"shoulds\",\"should to\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"You shouldn\'t ___ so much coffee.\",\"options\":[\"drink\",\"drinks\",\"to drink\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"I\'ve got a sore ___.\",\"options\":[\"head\",\"throat\",\"back\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"What ___ I do? I can\'t sleep.\",\"options\":[\"should\",\"do\",\"am\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Daha \\u00e7ok su i\\u00e7melisin.\",\"answer\":\"You should drink more water\",\"alternatives\":[],\"tiles\":[\"water\",\"drink\",\"should\",\"to\",\"You\",\"shoulds\",\"more\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"You\",\"should\",\"eats\",\"more\",\"vegetables\"],\"error_index\":2,\"options\":[\"eat\",\"eating\",\"to eat\"],\"answer\":0,\"explanation_tr\":\"\\\"Should\\\"dan sonra fiil yal\\u0131n kal\\u0131r; -s, -ing ya da to almaz: You should eat more vegetables.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I don\'t feel very well.\",\"translation\":\"Kendimi pek iyi hissetmiyorum.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(147,14,'Okuma: At the Doctor\'s','reading','lesson',2,18,0,NULL,NULL,'[{\"type\":\"read\",\"title\":\"At the Doctor\'s\",\"passage\":\"Last Tuesday I didn\'t feel well. I had a headache and a sore throat, so I went to the doctor. She checked my temperature and said, \\\"You have a cold. You should rest for two days and drink a lot of water. You shouldn\'t go to school tomorrow.\\\" She gave me some medicine. Now I feel much better and healthy again.\",\"prompt\":\"What was wrong with the writer?\",\"options\":[\"A broken arm\",\"A cold\",\"A stomach ache\",\"Toothache\"],\"answer\":1},{\"type\":\"read\",\"title\":\"At the Doctor\'s\",\"passage\":\"Last Tuesday I didn\'t feel well. I had a headache and a sore throat, so I went to the doctor. She checked my temperature and said, \\\"You have a cold. You should rest for two days and drink a lot of water. You shouldn\'t go to school tomorrow.\\\" She gave me some medicine. Now I feel much better and healthy again.\",\"prompt\":\"What did the doctor advise?\",\"options\":[\"Go to school and exercise\",\"Rest and drink water\",\"Eat more sugar\",\"Visit a hospital\"],\"answer\":1}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(148,14,'Kelime oyunu','vocabulary','words',3,18,0,NULL,NULL,'[]','{\"game\":\"cloze\",\"words\":[{\"word\":\"headache\",\"translation\":\"ba\\u015f a\\u011fr\\u0131s\\u0131\",\"example\":\"I\'ve got a terrible headache.\"},{\"word\":\"stomach ache\",\"translation\":\"mide a\\u011fr\\u0131s\\u0131\"},{\"word\":\"sore throat\",\"translation\":\"bo\\u011faz a\\u011fr\\u0131s\\u0131\",\"example\":\"I\'ve got a sore throat.\"},{\"word\":\"cold\",\"translation\":\"so\\u011fuk alg\\u0131nl\\u0131\\u011f\\u0131\"},{\"word\":\"temperature\",\"translation\":\"ate\\u015f\"},{\"word\":\"medicine\",\"translation\":\"ila\\u00e7\"},{\"word\":\"rest\",\"translation\":\"dinlenmek\",\"example\":\"You should rest and drink some tea.\"},{\"word\":\"hurt\",\"translation\":\"ac\\u0131mak\"},{\"word\":\"healthy\",\"translation\":\"sa\\u011fl\\u0131kl\\u0131\"},{\"word\":\"should\",\"translation\":\"-meli \\/ -mal\\u0131\",\"example\":\"You should rest and drink some tea.\"}]}','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(149,14,'Dilbilgisi pekiştir','grammar','lesson',4,18,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"What ___ I do? I can\'t sleep.\",\"options\":[\"am\",\"do\",\"should\"],\"answer\":2},{\"type\":\"fill\",\"prompt\":\"I\'ve got a sore ___.\",\"options\":[\"head\",\"throat\",\"back\"],\"answer\":1},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"You\",\"should\",\"eats\",\"more\",\"vegetables\"],\"error_index\":2,\"options\":[\"eat\",\"eating\",\"to eat\"],\"answer\":0,\"explanation_tr\":\"\\\"Should\\\"dan sonra fiil yal\\u0131n kal\\u0131r; -s, -ing ya da to almaz: You should eat more vegetables.\"},{\"type\":\"translate\",\"prompt\":\"Ate\\u015fim var.\",\"answer\":\"I\'ve got a temperature\",\"alternatives\":[\"I have a temperature\",\"I have a fever\",\"I\'ve got a fever\"],\"tiles\":[\"I\'ve\",\"have\",\"fever\",\"temperature\",\"got\",\"a\"]},{\"type\":\"fill\",\"prompt\":\"You shouldn\'t ___ so much coffee.\",\"options\":[\"drink\",\"to drink\",\"drinks\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"You ___ see a doctor.\",\"options\":[\"shoulds\",\"should\",\"should to\"],\"answer\":1},{\"type\":\"translate\",\"prompt\":\"Daha \\u00e7ok su i\\u00e7melisin.\",\"answer\":\"You should drink more water\",\"alternatives\":[],\"tiles\":[\"water\",\"drink\",\"should\",\"to\",\"You\",\"shoulds\",\"more\"]},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"You should stay in bed.\",\"translation\":\"Yatakta kalmal\\u0131s\\u0131n.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(150,14,'Dinle ve konuş','listening','lesson',5,18,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Arkada\\u015f\\u0131n hasta g\\u00f6r\\u00fcn\\u00fcyor.\",\"lines\":[{\"who\":\"Ella\",\"text\":\"I\'ve got a terrible cold and a sore throat.\"}],\"options\":[\"Oh no! You should drink hot tea with honey and rest.\",\"You must should drink tea.\",\"Drinking tea you.\"],\"answer\":0,\"note_tr\":\"Tavsiye i\\u00e7in \\\"You should \\u2026\\\" kullan, sonra yal\\u0131n fiil.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"You shouldn\'t run today\",\"options\":[\"You shouldn\'t run today\",\"You should run today\",\"You should rest today\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"You should see a doctor\",\"answer\":\"You should see a doctor\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"How long have you had this pain?\",\"translation\":\"Bu a\\u011fr\\u0131 ne zamand\\u0131r var?\"},{\"type\":\"translate\",\"prompt\":\"Ate\\u015fim var.\",\"answer\":\"I\'ve got a temperature\",\"alternatives\":[\"I have a temperature\",\"I have a fever\",\"I\'ve got a fever\"],\"tiles\":[\"I\'ve\",\"have\",\"fever\",\"temperature\",\"got\",\"a\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"My throat hurts\",\"answer\":\"My throat hurts\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"You should stay in bed.\",\"translation\":\"Yatakta kalmal\\u0131s\\u0131n.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
