(156,15,'Kelimeler','vocabulary','lesson',0,18,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"ticket\",\"bilet\"],[\"return ticket\",\"gidi\\u015f-d\\u00f6n\\u00fc\\u015f bilet\"],[\"platform\",\"peron\"],[\"flight\",\"u\\u00e7u\\u015f\"],[\"passport\",\"pasaport\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"luggage\\\" ne demek?\",\"options\":[\"peron\",\"yolculuk\",\"kalk\\u0131\\u015f\",\"bagaj\"],\"answer\":3,\"audio\":\"luggage\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"The flight is delayed\",\"options\":[\"The flight is delayed\",\"The flight is delivered\",\"The fight is delayed\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Bir sonraki trene binece\\u011fim.\",\"answer\":\"I\'ll take the next train\",\"alternatives\":[],\"tiles\":[\"I\'ll\",\"return ticket\",\"next\",\"arrival\",\"train\",\"take\",\"the\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"luggage\",\"bagaj\"],[\"delay\",\"r\\u00f6tar\"],[\"departure\",\"kalk\\u0131\\u015f\"],[\"arrival\",\"var\\u0131\\u015f\"],[\"journey\",\"yolculuk\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"var\\u0131\\u015f\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"departure\",\"flight\",\"arrival\",\"return ticket\"],\"answer\":2},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Our flight has a two-hour delay.\",\"translation\":\"U\\u00e7u\\u015fumuzun iki saat r\\u00f6tar\\u0131 var.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"Can I have a return ticket please\",\"answer\":\"Can I have a return ticket please\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(157,15,'Dilbilgisi','grammar','lesson',1,18,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"The bus is late. I think I ___ walk.\",\"options\":[\"\'ll\",\"am\",\"was\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"Don\'t worry, I ___ tell anyone.\",\"options\":[\"won\'t\",\"don\'t\",\"willn\'t\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"I think it ___ rain tomorrow.\",\"options\":[\"will\",\"is\",\"does\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"Your bag is heavy. I ___ help you.\",\"options\":[\"\'ll\",\"\'m\",\"\'d to\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Sana yard\\u0131m edece\\u011fim.\",\"answer\":\"I\'ll help you\",\"alternatives\":[\"I will help you\"],\"tiles\":[\"I\'ll\",\"you\",\"helps\",\"will to\",\"help\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"I\",\"will\",\"calling\",\"you\",\"tomorrow\"],\"error_index\":2,\"options\":[\"call\",\"calls\",\"called\"],\"answer\":0,\"explanation_tr\":\"\\\"Will\\\"den sonra fiil yal\\u0131n kal\\u0131r: I will call you tomorrow.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I\'d like a return ticket to Ankara, please.\",\"translation\":\"Ankara\'ya gidi\\u015f-d\\u00f6n\\u00fc\\u015f bilet istiyorum l\\u00fctfen.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(158,15,'Okuma: A Delayed Flight','reading','lesson',2,18,0,NULL,NULL,'[{\"type\":\"read\",\"title\":\"A Delayed Flight\",\"passage\":\"Our flight to London was at ten o\'clock, but there was a long delay. The departure board said, \\\"New departure time: 1 pm.\\\" My little brother was hungry, so I said, \\\"I\'ll buy some sandwiches.\\\" My mother checked our passports and our luggage again. We finally arrived in London at four in the afternoon. It was a long journey, but we were happy.\",\"prompt\":\"What was the new departure time?\",\"options\":[\"10 am\",\"1 pm\",\"4 pm\",\"11 am\"],\"answer\":1},{\"type\":\"read\",\"title\":\"A Delayed Flight\",\"passage\":\"Our flight to London was at ten o\'clock, but there was a long delay. The departure board said, \\\"New departure time: 1 pm.\\\" My little brother was hungry, so I said, \\\"I\'ll buy some sandwiches.\\\" My mother checked our passports and our luggage again. We finally arrived in London at four in the afternoon. It was a long journey, but we were happy.\",\"prompt\":\"Why did the writer buy sandwiches?\",\"options\":[\"The flight was cancelled.\",\"The brother was hungry.\",\"The food on the plane was bad.\",\"The mother asked for coffee.\"],\"answer\":1}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(159,15,'Kelime oyunu','vocabulary','words',3,18,0,NULL,NULL,'[]','{\"game\":\"listen\",\"words\":[{\"word\":\"ticket\",\"translation\":\"bilet\",\"example\":\"Can I have a return ticket please\"},{\"word\":\"return ticket\",\"translation\":\"gidi\\u015f-d\\u00f6n\\u00fc\\u015f bilet\",\"example\":\"Can I have a return ticket please\"},{\"word\":\"platform\",\"translation\":\"peron\",\"example\":\"Which platform does the train leave from?\"},{\"word\":\"flight\",\"translation\":\"u\\u00e7u\\u015f\",\"example\":\"Our flight has a two-hour delay.\"},{\"word\":\"passport\",\"translation\":\"pasaport\"},{\"word\":\"luggage\",\"translation\":\"bagaj\"},{\"word\":\"delay\",\"translation\":\"r\\u00f6tar\",\"example\":\"Our flight has a two-hour delay.\"},{\"word\":\"departure\",\"translation\":\"kalk\\u0131\\u015f\"},{\"word\":\"arrival\",\"translation\":\"var\\u0131\\u015f\"},{\"word\":\"journey\",\"translation\":\"yolculuk\"}]}','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(160,15,'Dilbilgisi pekiştir','grammar','lesson',4,18,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"Your bag is heavy. I ___ help you.\",\"options\":[\"\'ll\",\"\'d to\",\"\'m\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"I think it ___ rain tomorrow.\",\"options\":[\"is\",\"does\",\"will\"],\"answer\":2},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"I\",\"will\",\"calling\",\"you\",\"tomorrow\"],\"error_index\":2,\"options\":[\"call\",\"calls\",\"called\"],\"answer\":0,\"explanation_tr\":\"\\\"Will\\\"den sonra fiil yal\\u0131n kal\\u0131r: I will call you tomorrow.\"},{\"type\":\"translate\",\"prompt\":\"Tren ka\\u00e7ta kalk\\u0131yor?\",\"answer\":\"What time does the train leave\",\"alternatives\":[\"When does the train leave\"],\"tiles\":[\"time\",\"leave\",\"the\",\"What\",\"train\",\"does\",\"departs\",\"is\"]},{\"type\":\"fill\",\"prompt\":\"Don\'t worry, I ___ tell anyone.\",\"options\":[\"don\'t\",\"won\'t\",\"willn\'t\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"The bus is late. I think I ___ walk.\",\"options\":[\"\'ll\",\"was\",\"am\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Sana yard\\u0131m edece\\u011fim.\",\"answer\":\"I\'ll help you\",\"alternatives\":[\"I will help you\"],\"tiles\":[\"I\'ll\",\"you\",\"helps\",\"will to\",\"help\"]},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Don\'t worry, I\'ll be on time.\",\"translation\":\"Merak etme, zaman\\u0131nda orada olaca\\u011f\\u0131m.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(161,15,'Dinle ve konuş','listening','lesson',5,18,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Gi\\u015fedesin, \\u0130zmir treninin kalkt\\u0131\\u011f\\u0131n\\u0131 \\u00f6\\u011frendin.\",\"lines\":[{\"who\":\"Clerk\",\"text\":\"I\'m sorry, the 10:15 train to Izmir just left.\"}],\"options\":[\"Oh no. I\'ll take the next one then. What time is it?\",\"I am going to take next one yesterday.\",\"I took the next one.\"],\"answer\":0,\"note_tr\":\"Konu\\u015fma an\\u0131nda verilen karar i\\u00e7in will kullan\\u0131l\\u0131r: I\'ll take the next one.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"I\'ll call you later\",\"options\":[\"I\'ll call you later\",\"I called you later\",\"I\'ll call you letter\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"Where is platform three\",\"answer\":\"Where is platform three\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Which platform does the train leave from?\",\"translation\":\"Tren hangi perondan kalk\\u0131yor?\"},{\"type\":\"translate\",\"prompt\":\"Tren ka\\u00e7ta kalk\\u0131yor?\",\"answer\":\"What time does the train leave\",\"alternatives\":[\"When does the train leave\"],\"tiles\":[\"time\",\"leave\",\"the\",\"What\",\"train\",\"does\",\"departs\",\"is\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"I will carry your bag\",\"answer\":\"I will carry your bag\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Don\'t worry, I\'ll be on time.\",\"translation\":\"Merak etme, zaman\\u0131nda orada olaca\\u011f\\u0131m.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(162,15,'Kelime tekrarı','vocabulary','lesson',6,18,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"platform\",\"peron\"],[\"delay\",\"r\\u00f6tar\"],[\"passport\",\"pasaport\"],[\"ticket\",\"bilet\"],[\"flight\",\"u\\u00e7u\\u015f\"]]},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"return ticket\",\"options\":[\"delay\",\"passport\",\"return ticket\",\"arrival\"],\"answer\":2},{\"type\":\"choice\",\"prompt\":\"\\\"platform\\\" ne demek?\",\"options\":[\"r\\u00f6tar\",\"peron\",\"yolculuk\",\"pasaport\"],\"answer\":1,\"audio\":\"platform\"},{\"type\":\"choice\",\"prompt\":\"\\\"pasaport\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"departure\",\"passport\",\"flight\",\"journey\"],\"answer\":1},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"delay\",\"options\":[\"return ticket\",\"delay\",\"flight\",\"journey\"],\"answer\":1},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"journey\",\"answer\":\"journey\"},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"journey\",\"yolculuk\"],[\"passport\",\"pasaport\"],[\"departure\",\"kalk\\u0131\\u015f\"],[\"flight\",\"u\\u00e7u\\u015f\"],[\"luggage\",\"bagaj\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"ticket\\\" ne demek?\",\"options\":[\"kalk\\u0131\\u015f\",\"pasaport\",\"peron\",\"bilet\"],\"answer\":3,\"audio\":\"ticket\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(163,15,'Telaffuz','speaking','lesson',7,18,0,NULL,NULL,'[{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"ticket\",\"translation\":\"bilet\"},{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"platform\",\"translation\":\"peron\"},{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"flight\",\"translation\":\"u\\u00e7u\\u015f\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"I\'ll take the next train.\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"I\'d like a return ticket to Ankara, please.\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"Which platform does the train leave from?\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
