(167,16,'Kelimeler','vocabulary','lesson',0,18,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"ever\",\"hi\\u00e7 (soruda)\"],[\"never\",\"hi\\u00e7, asla\"],[\"been to\",\"gitmi\\u015f olmak\"],[\"tried\",\"denedi \\/ denemi\\u015f\"],[\"eaten\",\"yemi\\u015f\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"seen\\\" ne demek?\",\"options\":[\"bir kez\",\"g\\u00f6rm\\u00fc\\u015f\",\"gitmi\\u015f olmak\",\"tan\\u0131\\u015fm\\u0131\\u015f\"],\"answer\":1,\"audio\":\"seen\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"I\'ve never been to Paris\",\"options\":[\"I\'ve never been to Paris\",\"I\'ve never seen Paris\",\"I\'ll never go to Paris\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Hi\\u00e7 u\\u00e7a\\u011fa binmedim.\",\"answer\":\"I\'ve never flown in a plane\",\"alternatives\":[],\"tiles\":[\"in\",\"been to\",\"I\'ve\",\"plane\",\"flown\",\"never\",\"a\",\"once\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"seen\",\"g\\u00f6rm\\u00fc\\u015f\"],[\"flown\",\"u\\u00e7mu\\u015f\"],[\"met\",\"tan\\u0131\\u015fm\\u0131\\u015f\"],[\"experience\",\"deneyim\"],[\"once\",\"bir kez\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"deneyim\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"met\",\"tried\",\"never\",\"experience\"],\"answer\":3},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Have you ever eaten Japanese food?\",\"translation\":\"Hi\\u00e7 Japon yeme\\u011fi yedin mi?\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"She has been to London twice\",\"answer\":\"She has been to London twice\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(168,16,'Dilbilgisi','grammar','lesson',1,18,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"Have you ever ___ a famous person?\",\"options\":[\"meet\",\"met\",\"meeting\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"I\'ve ___ been to Africa.\",\"options\":[\"ever\",\"never\",\"yet\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"She ___ visited Paris three times.\",\"options\":[\"have\",\"has\",\"is\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"___ you ever tried rafting?\",\"options\":[\"Did\",\"Have\",\"Has\"],\"answer\":1},{\"type\":\"translate\",\"prompt\":\"Hi\\u00e7 \\u0130stanbul\'a gittin mi?\",\"answer\":\"Have you ever been to Istanbul\",\"alternatives\":[],\"tiles\":[\"you\",\"Istanbul\",\"did\",\"been\",\"to\",\"went\",\"ever\",\"Have\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"I\",\"have\",\"saw\",\"that\",\"film\",\"before\"],\"error_index\":2,\"options\":[\"seen\",\"see\",\"seeing\"],\"answer\":0,\"explanation_tr\":\"Present perfect\'te fiilin 3. h\\u00e2li (V3) kullan\\u0131l\\u0131r: see \\u2192 saw \\u2192 seen. Do\\u011frusu: I have seen.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Have you ever been abroad?\",\"translation\":\"Hi\\u00e7 yurt d\\u0131\\u015f\\u0131na \\u00e7\\u0131kt\\u0131n m\\u0131?\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(169,16,'Okuma: Have You Ever...?','reading','lesson',2,18,0,NULL,NULL,'[{\"type\":\"read\",\"title\":\"Have You Ever...?\",\"passage\":\"My grandfather has had an exciting life. He has been to more than twenty countries. He has flown in a small plane over the Alps and he has eaten food from all over the world. He has met famous people, too. But he has never seen snow in the desert. \\\"That is my next experience,\\\" he says, and laughs.\",\"prompt\":\"How many countries has the grandfather been to?\",\"options\":[\"Fewer than ten\",\"Exactly twenty\",\"More than twenty\",\"Only one\"],\"answer\":2},{\"type\":\"read\",\"title\":\"Have You Ever...?\",\"passage\":\"My grandfather has had an exciting life. He has been to more than twenty countries. He has flown in a small plane over the Alps and he has eaten food from all over the world. He has met famous people, too. But he has never seen snow in the desert. \\\"That is my next experience,\\\" he says, and laughs.\",\"prompt\":\"What has he never seen?\",\"options\":[\"The Alps\",\"Famous people\",\"Snow in the desert\",\"A small plane\"],\"answer\":2}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(170,16,'Kelime oyunu','vocabulary','words',3,18,0,NULL,NULL,'[]','{\"game\":\"memory\",\"words\":[{\"word\":\"ever\",\"translation\":\"hi\\u00e7 (soruda)\",\"example\":\"Have you ever eaten Japanese food?\"},{\"word\":\"never\",\"translation\":\"hi\\u00e7, asla\",\"example\":\"I\'ve never flown in a plane.\"},{\"word\":\"been to\",\"translation\":\"gitmi\\u015f olmak\",\"example\":\"She has been to London twice\"},{\"word\":\"tried\",\"translation\":\"denedi \\/ denemi\\u015f\",\"example\":\"I\'ve tried many Turkish dishes.\"},{\"word\":\"eaten\",\"translation\":\"yemi\\u015f\",\"example\":\"Have you ever eaten Japanese food?\"},{\"word\":\"seen\",\"translation\":\"g\\u00f6rm\\u00fc\\u015f\",\"example\":\"I\'ve never seen snow in Antalya.\"},{\"word\":\"flown\",\"translation\":\"u\\u00e7mu\\u015f\",\"example\":\"I\'ve never flown in a plane.\"},{\"word\":\"met\",\"translation\":\"tan\\u0131\\u015fm\\u0131\\u015f\",\"example\":\"Have you ever met a famous person?\"},{\"word\":\"experience\",\"translation\":\"deneyim\"},{\"word\":\"once\",\"translation\":\"bir kez\"}]}','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(171,16,'Dilbilgisi pekiştir','grammar','lesson',4,18,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"___ you ever tried rafting?\",\"options\":[\"Has\",\"Have\",\"Did\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"She ___ visited Paris three times.\",\"options\":[\"have\",\"is\",\"has\"],\"answer\":2},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"I\",\"have\",\"saw\",\"that\",\"film\",\"before\"],\"error_index\":2,\"options\":[\"seen\",\"see\",\"seeing\"],\"answer\":0,\"explanation_tr\":\"Present perfect\'te fiilin 3. h\\u00e2li (V3) kullan\\u0131l\\u0131r: see \\u2192 saw \\u2192 seen. Do\\u011frusu: I have seen.\"},{\"type\":\"translate\",\"prompt\":\"Bu filmi iki kez izledim.\",\"answer\":\"I\'ve seen this film twice\",\"alternatives\":[\"I have seen this film twice\",\"I\'ve watched this film twice\",\"I have watched this film twice\"],\"tiles\":[\"twice\",\"I\'ve\",\"this\",\"watched\",\"saw\",\"seen\",\"film\"]},{\"type\":\"fill\",\"prompt\":\"I\'ve ___ been to Africa.\",\"options\":[\"yet\",\"never\",\"ever\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"Have you ever ___ a famous person?\",\"options\":[\"meet\",\"meeting\",\"met\"],\"answer\":2},{\"type\":\"translate\",\"prompt\":\"Hi\\u00e7 \\u0130stanbul\'a gittin mi?\",\"answer\":\"Have you ever been to Istanbul\",\"alternatives\":[],\"tiles\":[\"you\",\"Istanbul\",\"did\",\"been\",\"to\",\"went\",\"ever\",\"Have\"]},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I\'ve never seen snow in Antalya.\",\"translation\":\"Antalya\'da hi\\u00e7 kar g\\u00f6rmedim.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(172,16,'Dinle ve konuş','listening','lesson',5,18,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Bir oyunda \\\"Hi\\u00e7 \\u2026 yapt\\u0131n m\\u0131?\\\" sorular\\u0131 soruluyor.\",\"lines\":[{\"who\":\"Leo\",\"text\":\"Have you ever swum in a lake?\"}],\"options\":[\"Yes, I have. I swam in Lake Abant last summer.\",\"Yes, I did swum.\",\"Yes, I have swim.\"],\"answer\":0,\"note_tr\":\"K\\u0131sa cevap present perfect ile, detay (ne zaman) ge\\u00e7mi\\u015f zamanla verilir.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"Have you ever met him\",\"options\":[\"Have you ever met him\",\"Have you ever let him\",\"Did you ever meet him\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"Have you ever been to Rize\",\"answer\":\"Have you ever been to Rize\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I\'ve tried many Turkish dishes.\",\"translation\":\"Bir\\u00e7ok T\\u00fcrk yeme\\u011fi denedim.\"},{\"type\":\"translate\",\"prompt\":\"Bu filmi iki kez izledim.\",\"answer\":\"I\'ve seen this film twice\",\"alternatives\":[\"I have seen this film twice\",\"I\'ve watched this film twice\",\"I have watched this film twice\"],\"tiles\":[\"twice\",\"I\'ve\",\"this\",\"watched\",\"saw\",\"seen\",\"film\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"She has never flown\",\"answer\":\"She has never flown\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I\'ve never seen snow in Antalya.\",\"translation\":\"Antalya\'da hi\\u00e7 kar g\\u00f6rmedim.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(173,16,'Kelime tekrarı','vocabulary','lesson',6,18,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"seen\",\"g\\u00f6rm\\u00fc\\u015f\"],[\"tried\",\"denedi \\/ denemi\\u015f\"],[\"never\",\"hi\\u00e7, asla\"],[\"ever\",\"hi\\u00e7 (soruda)\"],[\"eaten\",\"yemi\\u015f\"]]},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"never\",\"options\":[\"experience\",\"never\",\"eaten\",\"flown\"],\"answer\":1},{\"type\":\"choice\",\"prompt\":\"\\\"been to\\\" ne demek?\",\"options\":[\"yemi\\u015f\",\"gitmi\\u015f olmak\",\"bir kez\",\"u\\u00e7mu\\u015f\"],\"answer\":1,\"audio\":\"been to\"},{\"type\":\"choice\",\"prompt\":\"\\\"yemi\\u015f\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"met\",\"eaten\",\"once\",\"tried\"],\"answer\":1},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"flown\",\"options\":[\"once\",\"flown\",\"never\",\"tried\"],\"answer\":1},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"once\",\"answer\":\"once\"},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"met\",\"tan\\u0131\\u015fm\\u0131\\u015f\"],[\"been to\",\"gitmi\\u015f olmak\"],[\"once\",\"bir kez\"],[\"seen\",\"g\\u00f6rm\\u00fc\\u015f\"],[\"flown\",\"u\\u00e7mu\\u015f\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"ever\\\" ne demek?\",\"options\":[\"yemi\\u015f\",\"hi\\u00e7 (soruda)\",\"gitmi\\u015f olmak\",\"tan\\u0131\\u015fm\\u0131\\u015f\"],\"answer\":1,\"audio\":\"ever\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
