(176,16,'Pratik','vocabulary','lesson',9,18,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"never\",\"hi\\u00e7, asla\"],[\"seen\",\"g\\u00f6rm\\u00fc\\u015f\"],[\"once\",\"bir kez\"],[\"met\",\"tan\\u0131\\u015fm\\u0131\\u015f\"],[\"been to\",\"gitmi\\u015f olmak\"]]},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"never\",\"options\":[\"never\",\"flown\",\"eaten\",\"experience\"],\"answer\":0},{\"type\":\"choice\",\"prompt\":\"\\\"been to\\\" ne demek?\",\"options\":[\"u\\u00e7mu\\u015f\",\"bir kez\",\"gitmi\\u015f olmak\",\"yemi\\u015f\"],\"answer\":2,\"audio\":\"been to\"},{\"type\":\"choice\",\"prompt\":\"\\\"yemi\\u015f\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"tried\",\"met\",\"once\",\"eaten\"],\"answer\":3},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"flown\",\"options\":[\"never\",\"flown\",\"once\",\"tried\"],\"answer\":1},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"once\",\"answer\":\"once\"},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"once\",\"bir kez\"],[\"flown\",\"u\\u00e7mu\\u015f\"],[\"met\",\"tan\\u0131\\u015fm\\u0131\\u015f\"],[\"seen\",\"g\\u00f6rm\\u00fc\\u015f\"],[\"never\",\"hi\\u00e7, asla\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"ever\\\" ne demek?\",\"options\":[\"tan\\u0131\\u015fm\\u0131\\u015f\",\"hi\\u00e7 (soruda)\",\"yemi\\u015f\",\"gitmi\\u015f olmak\"],\"answer\":1,\"audio\":\"ever\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
