(178,17,'Kelimeler','vocabulary','lesson',0,18,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"must\",\"zorunda olmak, -meli\"],[\"mustn\'t\",\"-memeli (yasak)\"],[\"have to\",\"zorunda olmak\"],[\"don\'t have to\",\"gerek yok\"],[\"rule\",\"kural\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"allowed\\\" ne demek?\",\"options\":[\"zorunda olmak\",\"emniyet kemeri\",\"izinli\",\"zaman\\u0131nda\"],\"answer\":2,\"audio\":\"allowed\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"You mustn\'t park here\",\"options\":[\"You mustn\'t park here\",\"You must park here\",\"You mustn\'t pack here\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Arabada emniyet kemeri takmal\\u0131s\\u0131n.\",\"answer\":\"You must wear a seatbelt in the car\",\"alternatives\":[],\"tiles\":[\"seatbelt\",\"wear\",\"must\",\"must\",\"don\'t have to\",\"a\",\"You\",\"car\",\"in\",\"the\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"allowed\",\"izinli\"],[\"uniform\",\"\\u00fcniforma\"],[\"seatbelt\",\"emniyet kemeri\"],[\"quiet\",\"sessiz\"],[\"on time\",\"zaman\\u0131nda\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"sessiz\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"seatbelt\",\"quiet\",\"don\'t have to\",\"mustn\'t\"],\"answer\":1},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"We don\'t have to wear a uniform on Fridays.\",\"translation\":\"Cuma g\\u00fcnleri \\u00fcniforma giymek zorunda de\\u011filiz.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"You mustn\'t run in the corridor\",\"answer\":\"You mustn\'t run in the corridor\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(179,17,'Dilbilgisi','grammar','lesson',1,18,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"You ___ smoke in the hospital.\",\"options\":[\"mustn\'t\",\"don\'t have to\",\"must\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"It\'s Saturday. I ___ get up early.\",\"options\":[\"don\'t have to\",\"mustn\'t\",\"must\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"She ___ wear glasses to read.\",\"options\":[\"has to\",\"have to\",\"must to\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"Yesterday I ___ work until nine.\",\"options\":[\"must\",\"had to\",\"have to\"],\"answer\":1},{\"type\":\"translate\",\"prompt\":\"Zaman\\u0131nda gelmelisin.\",\"answer\":\"You must be on time\",\"alternatives\":[\"You have to be on time\"],\"tiles\":[\"to\",\"must\",\"time\",\"be\",\"You\",\"have\",\"on\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"Yesterday\",\"I\",\"must\",\"work\",\"until\",\"nine\"],\"error_index\":2,\"options\":[\"had to\",\"have to\",\"must to\"],\"answer\":0,\"explanation_tr\":\"\\\"Must\\\"\\u0131n ge\\u00e7mi\\u015f h\\u00e2li yoktur; ge\\u00e7mi\\u015fteki zorunluluk i\\u00e7in \\\"had to\\\" kullan\\u0131l\\u0131r: Yesterday I had to work until nine.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Do I have to pay now?\",\"translation\":\"\\u015eimdi \\u00f6demek zorunda m\\u0131y\\u0131m?\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(180,17,'Okuma: School Rules','reading','lesson',2,18,0,NULL,NULL,'[{\"type\":\"read\",\"title\":\"School Rules\",\"passage\":\"At my new school there are some important rules. We must wear a uniform and we must be on time for every lesson. We mustn\'t use our phones in class, and we have to be quiet in the library. We don\'t have to bring lunch, because there is a school canteen. Students are allowed to play football in the garden at lunchtime.\",\"prompt\":\"What mustn\'t students do?\",\"options\":[\"Wear a uniform\",\"Use phones in class\",\"Play football\",\"Eat in the canteen\"],\"answer\":1},{\"type\":\"read\",\"title\":\"School Rules\",\"passage\":\"At my new school there are some important rules. We must wear a uniform and we must be on time for every lesson. We mustn\'t use our phones in class, and we have to be quiet in the library. We don\'t have to bring lunch, because there is a school canteen. Students are allowed to play football in the garden at lunchtime.\",\"prompt\":\"Why don\'t students have to bring lunch?\",\"options\":[\"There is a canteen.\",\"School finishes early.\",\"They eat at home.\",\"Food is not allowed.\"],\"answer\":0}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(181,17,'Kelime oyunu','vocabulary','words',3,18,0,NULL,NULL,'[]','{\"game\":\"kelimle\",\"words\":[{\"word\":\"must\",\"translation\":\"zorunda olmak, -meli\",\"example\":\"You must wear a seatbelt in the car.\"},{\"word\":\"mustn\'t\",\"translation\":\"-memeli (yasak)\",\"example\":\"You mustn\'t run in the corridor\"},{\"word\":\"have to\",\"translation\":\"zorunda olmak\",\"example\":\"We don\'t have to wear a uniform on Fridays.\"},{\"word\":\"don\'t have to\",\"translation\":\"gerek yok\",\"example\":\"We don\'t have to wear a uniform on Fridays.\"},{\"word\":\"rule\",\"translation\":\"kural\"},{\"word\":\"allowed\",\"translation\":\"izinli\"},{\"word\":\"uniform\",\"translation\":\"\\u00fcniforma\",\"example\":\"We don\'t have to wear a uniform on Fridays.\"},{\"word\":\"seatbelt\",\"translation\":\"emniyet kemeri\",\"example\":\"You must wear a seatbelt in the car.\"},{\"word\":\"quiet\",\"translation\":\"sessiz\",\"example\":\"We must be quiet in the library.\"},{\"word\":\"on time\",\"translation\":\"zaman\\u0131nda\"}]}','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(182,17,'Dilbilgisi pekiştir','grammar','lesson',4,18,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"Yesterday I ___ work until nine.\",\"options\":[\"must\",\"have to\",\"had to\"],\"answer\":2},{\"type\":\"fill\",\"prompt\":\"She ___ wear glasses to read.\",\"options\":[\"have to\",\"has to\",\"must to\"],\"answer\":1},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"Yesterday\",\"I\",\"must\",\"work\",\"until\",\"nine\"],\"error_index\":2,\"options\":[\"had to\",\"have to\",\"must to\"],\"answer\":0,\"explanation_tr\":\"\\\"Must\\\"\\u0131n ge\\u00e7mi\\u015f h\\u00e2li yoktur; ge\\u00e7mi\\u015fteki zorunluluk i\\u00e7in \\\"had to\\\" kullan\\u0131l\\u0131r: Yesterday I had to work until nine.\"},{\"type\":\"translate\",\"prompt\":\"Burada foto\\u011fraf \\u00e7ekmek yasak.\",\"answer\":\"You mustn\'t take photos here\",\"alternatives\":[\"You must not take photos here\"],\"tiles\":[\"take\",\"mustn\'t\",\"photos\",\"don\'t\",\"have\",\"here\",\"You\"]},{\"type\":\"fill\",\"prompt\":\"It\'s Saturday. I ___ get up early.\",\"options\":[\"don\'t have to\",\"must\",\"mustn\'t\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"You ___ smoke in the hospital.\",\"options\":[\"mustn\'t\",\"must\",\"don\'t have to\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Zaman\\u0131nda gelmelisin.\",\"answer\":\"You must be on time\",\"alternatives\":[\"You have to be on time\"],\"tiles\":[\"to\",\"must\",\"time\",\"be\",\"You\",\"have\",\"on\"]},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"We must be quiet in the library.\",\"translation\":\"K\\u00fct\\u00fcphanede sessiz olmal\\u0131y\\u0131z.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(183,17,'Dinle ve konuş','listening','lesson',5,18,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Yeni bir spor salonuna kaydoluyorsun.\",\"lines\":[{\"who\":\"Receptionist\",\"text\":\"Any questions about the gym rules?\"}],\"options\":[\"Do I have to bring my own towel?\",\"I must to bring towel?\",\"Have I to bring towel?\"],\"answer\":0,\"note_tr\":\"Bir zorunlulu\\u011fu sormak i\\u00e7in \\\"Do I have to \\u2026?\\\" kal\\u0131b\\u0131 kullan\\u0131l\\u0131r.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"We don\'t have to hurry\",\"options\":[\"We don\'t have to hurry\",\"We have to hurry\",\"We don\'t have to worry\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"You must wear a seatbelt\",\"answer\":\"You must wear a seatbelt\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"You don\'t have to bring anything.\",\"translation\":\"Bir \\u015fey getirmek zorunda de\\u011filsin.\"},{\"type\":\"translate\",\"prompt\":\"Burada foto\\u011fraf \\u00e7ekmek yasak.\",\"answer\":\"You mustn\'t take photos here\",\"alternatives\":[\"You must not take photos here\"],\"tiles\":[\"take\",\"mustn\'t\",\"photos\",\"don\'t\",\"have\",\"here\",\"You\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"I had to work late\",\"answer\":\"I had to work late\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"We must be quiet in the library.\",\"translation\":\"K\\u00fct\\u00fcphanede sessiz olmal\\u0131y\\u0131z.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
