kmek yasak.\",\"answer\":\"You mustn\'t take photos here\",\"alternatives\":[\"You must not take photos here\"],\"tiles\":[\"take\",\"mustn\'t\",\"photos\",\"don\'t\",\"have\",\"here\",\"You\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"You must wear a seatbelt\",\"answer\":\"You must wear a seatbelt\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"We must be quiet in the library.\",\"translation\":\"K\\u00fct\\u00fcphanede sessiz olmal\\u0131y\\u0131z.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(190,18,'Kelimeler','vocabulary','lesson',0,20,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"since\",\"-den beri\"],[\"for\",\"s\\u00fcredir\"],[\"already\",\"\\u00e7oktan\"],[\"yet\",\"hen\\u00fcz\"],[\"just\",\"az \\u00f6nce\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"recently\\\" ne demek?\",\"options\":[\"\\u00f6m\\u00fcr boyu\",\"geli\\u015ftirmek\",\"son zamanlarda\",\"\\u00e7oktan\"],\"answer\":2,\"audio\":\"recently\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"I\'ve never been to Japan\",\"options\":[\"I\'ve never been to Japan\",\"I never went to Japan\",\"I\'d never been to Japan\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Projemi az \\u00f6nce bitirdim.\",\"answer\":\"I\'ve just finished my project\",\"alternatives\":[],\"tiles\":[\"finished\",\"just\",\"achieve\",\"my\",\"project\",\"yet\",\"I\'ve\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"recently\",\"son zamanlarda\"],[\"achieve\",\"ba\\u015farmak\"],[\"improve\",\"geli\\u015ftirmek\"],[\"career\",\"kariyer\"],[\"lifetime\",\"\\u00f6m\\u00fcr boyu\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"kariyer\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"career\",\"yet\",\"for\",\"improve\"],\"answer\":0},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"She has worked here since 2019.\",\"translation\":\"2019\'dan beri burada \\u00e7al\\u0131\\u015f\\u0131yor.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"Have you finished your homework yet\",\"answer\":\"Have you finished your homework yet\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(191,18,'Dilbilgisi','grammar','lesson',1,20,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"Have you ever ___ sushi?\",\"options\":[\"eat\",\"ate\",\"eaten\"],\"answer\":2},{\"type\":\"fill\",\"prompt\":\"I\'ve lived here ___ 2019.\",\"options\":[\"for\",\"since\",\"from\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"She\'s worked here ___ five years.\",\"options\":[\"for\",\"since\",\"during\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"I ___ my keys yesterday.\",\"options\":[\"lost\",\"\'ve lost\",\"lose\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Bu filmi \\u00fc\\u00e7 kez izledim.\",\"answer\":\"I\'ve watched this film three times\",\"alternatives\":[\"I have watched this film three times\",\"I\'ve seen this film three times\",\"I have seen this film three times\"],\"tiles\":[\"three\",\"times\",\"watched\",\"this\",\"film\",\"I\'ve\",\"watch\",\"did\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"I\",\"live\",\"in\",\"Ankara\",\"since\",\"2015\"],\"error_index\":1,\"options\":[\"have lived\",\"lived\",\"am living\"],\"answer\":0,\"explanation_tr\":\"H\\u00e2l\\u00e2 devam eden bir durum \\\"since\\\" ile anlat\\u0131l\\u0131yorsa present perfect gerekir: I\'ve lived in Ankara since 2015. T\\u00fcrk\\u00e7edeki \\\"-den beri ya\\u015f\\u0131yorum\\\" yap\\u0131s\\u0131 bu hatay\\u0131 \\u00e7ok yapt\\u0131r\\u0131r.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I\'ve been learning English for two years.\",\"translation\":\"\\u0130ki y\\u0131ld\\u0131r \\u0130ngilizce \\u00f6\\u011freniyorum.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(192,18,'Okuma: A Late Start','reading','lesson',2,20,0,NULL,NULL,'[{\"type\":\"read\",\"title\":\"A Late Start\",\"passage\":\"Selin has worked as a nurse since 2019, but she has always wanted to be a pilot. Last year she finally decided to try. She has already finished her first flight lessons, although she hasn\'t taken the final exam yet. \\\"I\'ve just started, really,\\\" she says, \\\"but I\'ve improved a lot recently.\\\" Her friends think it is a brave career change, and she agrees that it is the biggest decision of her lifetime.\",\"prompt\":\"How long has Selin been a nurse?\",\"options\":[\"Since last year\",\"Since 2019\",\"For two months\",\"All her life\"],\"answer\":1},{\"type\":\"read\",\"title\":\"A Late Start\",\"passage\":\"Selin has worked as a nurse since 2019, but she has always wanted to be a pilot. Last year she finally decided to try. She has already finished her first flight lessons, although she hasn\'t taken the final exam yet. \\\"I\'ve just started, really,\\\" she says, \\\"but I\'ve improved a lot recently.\\\" Her friends think it is a brave career change, and she agrees that it is the biggest decision of her lifetime.\",\"prompt\":\"Which statement is true?\",\"options\":[\"She has passed the final exam.\",\"She hasn\'t started flight lessons.\",\"She has finished her first lessons.\",\"She wants to stop flying.\"],\"answer\":2}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(193,18,'Kelime oyunu','vocabulary','words',3,20,0,NULL,NULL,'[]','{\"game\":\"cloze\",\"words\":[{\"word\":\"since\",\"translation\":\"-den beri\",\"example\":\"She has worked here since 2019.\"},{\"word\":\"for\",\"translation\":\"s\\u00fcredir\",\"example\":\"I\'ve been learning English for two years.\"},{\"word\":\"already\",\"translation\":\"\\u00e7oktan\"},{\"word\":\"yet\",\"translation\":\"hen\\u00fcz\",\"example\":\"Have you finished your homework yet\"},{\"word\":\"just\",\"translation\":\"az \\u00f6nce\",\"example\":\"I\'ve just finished my project.\"},{\"word\":\"recently\",\"translation\":\"son zamanlarda\"},{\"word\":\"achieve\",\"translation\":\"ba\\u015farmak\"},{\"word\":\"improve\",\"translation\":\"geli\\u015ftirmek\"},{\"word\":\"career\",\"translation\":\"kariyer\"},{\"word\":\"lifetime\",\"translation\":\"\\u00f6m\\u00fcr boyu\"}]}','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(194,18,'Dilbilgisi pekiştir','grammar','lesson',4,20,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"I ___ my keys yesterday.\",\"options\":[\"lost\",\"\'ve lost\",\"lose\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"She\'s worked here ___ five years.\",\"options\":[\"during\",\"since\",\"for\"],\"answer\":2},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"I\",\"live\",\"in\",\"Ankara\",\"since\",\"2015\"],\"error_index\":1,\"options\":[\"have lived\",\"lived\",\"am living\"],\"answer\":0,\"explanation_tr\":\"H\\u00e2l\\u00e2 devam eden bir durum \\\"since\\\" ile anlat\\u0131l\\u0131yorsa present perfect gerekir: I\'ve lived in Ankara since 2015. T\\u00fcrk\\u00e7edeki \\\"-den beri ya\\u015f\\u0131yorum\\\" yap\\u0131s\\u0131 bu hatay\\u0131 \\u00e7ok yapt\\u0131r\\u0131r.\"},{\"type\":\"translate\",\"prompt\":\"\\u0130ki y\\u0131ld\\u0131r \\u0130ngilizce \\u00f6\\u011freniyorum.\",\"answer\":\"I\'ve been learning English for two years\",\"alternatives\":[\"I have been learning English for two years\",\"I\'ve studied English for two years\"],\"tiles\":[\"years\",\"been\",\"learning\",\"since\",\"two\",\"for\",\"English\",\"I\'ve\",\"am\"]},{\"type\":\"fill\",\"prompt\":\"I\'ve lived here ___ 2019.\",\"options\":[\"since\",\"for\",\"from\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"Have you ever ___ sushi?\",\"options\":[\"eat\",\"ate\",\"eaten\"],\"answer\":2},{\"type\":\"translate\",\"prompt\":\"Bu filmi \\u00fc\\u00e7 kez izledim.\",\"answer\":\"I\'ve watched this film three times\",\"alternatives\":[\"I have watched this film three times\",\"I\'ve seen this film three times\",\"I have seen this film three times\"],\"tiles\":[\"three\",\"times\",\"watched\",\"this\",\"film\",\"I\'ve\",\"watch\",\"did\"]},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"How long have you known her?\",\"translation\":\"Onu ne zama