(195,18,'Dinle ve konuş','listening','lesson',5,20,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Bir i\\u015f g\\u00f6r\\u00fc\\u015fmesinde deneyimin soruluyor.\",\"lines\":[{\"who\":\"Interviewer\",\"text\":\"How long have you worked in tourism?\"}],\"options\":[\"I\'ve worked in tourism for six years, since I finished university.\",\"I work in tourism since six years.\",\"I am working six years.\"],\"answer\":0,\"note_tr\":\"S\\u00fcren deneyimler i\\u00e7in present perfect + for \\/ since. \\\"Since six years\\\" yanl\\u0131\\u015ft\\u0131r; s\\u00fcre \\\"for\\\" ile verilir.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"She\'s just left\",\"options\":[\"She\'s just left\",\"She\'s just laughed\",\"She just left\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"Have you finished your homework\",\"answer\":\"Have you finished your homework\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I haven\'t decided yet.\",\"translation\":\"Hen\\u00fcz karar vermedim.\"},{\"type\":\"translate\",\"prompt\":\"\\u0130ki y\\u0131ld\\u0131r \\u0130ngilizce \\u00f6\\u011freniyorum.\",\"answer\":\"I\'ve been learning English for two years\",\"alternatives\":[\"I have been learning English for two years\",\"I\'ve studied English for two years\"],\"tiles\":[\"years\",\"been\",\"learning\",\"since\",\"two\",\"for\",\"English\",\"I\'ve\",\"am\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"I have known him since school\",\"answer\":\"I have known him since school\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"How long have you known her?\",\"translation\":\"Onu ne zamand\\u0131r tan\\u0131yorsun?\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
