(201,19,'Kelimeler','vocabulary','lesson',0,20,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"while\",\"-iken\"],[\"suddenly\",\"aniden\"],[\"used to\",\"eskiden \\u2026-irdi\"],[\"childhood\",\"\\u00e7ocukluk\"],[\"remember\",\"hat\\u0131rlamak\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"neighbourhood\\\" ne demek?\",\"options\":[\"an\\u0131\",\"mahalle\",\"eskiden \\u2026-irdi\",\"\\u00e7almak (telefon)\"],\"answer\":1,\"audio\":\"neighbourhood\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"I was walking home when it started to rain\",\"options\":[\"I was walking home when it started to rain\",\"I walked home when it started to rain\",\"I was waking home when it started to rain\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"I\\u015f\\u0131klar gitti\\u011finde kitap okuyordum.\",\"answer\":\"I was reading when the lights went out\",\"alternatives\":[],\"tiles\":[\"remember\",\"ring\",\"when\",\"the\",\"went\",\"lights\",\"was\",\"reading\",\"I\",\"out\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"neighbourhood\",\"mahalle\"],[\"happen\",\"olmak, meydana gelmek\"],[\"ring\",\"\\u00e7almak (telefon)\"],[\"notice\",\"fark etmek\"],[\"memory\",\"an\\u0131\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"fark etmek\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"suddenly\",\"ring\",\"childhood\",\"notice\"],\"answer\":3},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"We used to play in the street every evening.\",\"translation\":\"Eskiden her ak\\u015fam sokakta oynard\\u0131k.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"What were you doing at nine\",\"answer\":\"What were you doing at nine\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(202,19,'Dilbilgisi','grammar','lesson',1,20,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"I ___ dinner when you called.\",\"options\":[\"was having\",\"had\",\"have\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"While they ___ football, it started to rain.\",\"options\":[\"were playing\",\"played\",\"was playing\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"I ___ to have long hair.\",\"options\":[\"used\",\"use\",\"was used\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"Did you ___ to live in Adana?\",\"options\":[\"used\",\"use\",\"using\"],\"answer\":1},{\"type\":\"translate\",\"prompt\":\"Sen arad\\u0131\\u011f\\u0131nda du\\u015f al\\u0131yordum.\",\"answer\":\"I was having a shower when you called\",\"alternatives\":[\"I was taking a shower when you called\"],\"tiles\":[\"was\",\"a\",\"shower\",\"called\",\"when\",\"had\",\"I\",\"you\",\"having\",\"were\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"When\",\"I\",\"was\",\"a\",\"child\",\"I\",\"use\",\"to\",\"play\",\"outside\"],\"error_index\":6,\"options\":[\"used\",\"using\",\"uses\"],\"answer\":0,\"explanation_tr\":\"Ge\\u00e7mi\\u015fteki al\\u0131\\u015fkanl\\u0131klar i\\u00e7in \\\"used to\\\" kullan\\u0131l\\u0131r: I used to play outside. Olumsuz ve soruda ise \\\"use to\\\" olur: Did you use to \\u2026?\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I used to be very shy at school.\",\"translation\":\"Okulda eskiden \\u00e7ok utanga\\u00e7t\\u0131m.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(203,19,'Okuma: The Old Neighbourhood','reading','lesson',2,20,0,NULL,NULL,'[{\"type\":\"read\",\"title\":\"The Old Neighbourhood\",\"passage\":\"When I was a child, we used to live in a narrow street in Izmir. Every evening the neighbours used to sit outside and chat while the children played. One night, while we were playing hide and seek, the electricity suddenly went off. Nobody was frightened; instead, someone started to sing. I still remember that evening as one of my happiest childhood memories.\",\"prompt\":\"What happened while the children were playing?\",\"options\":[\"It started to rain.\",\"The electricity went off.\",\"A neighbour shouted.\",\"The police came.\"],\"answer\":1},{\"type\":\"read\",\"title\":\"The Old Neighbourhood\",\"passage\":\"When I was a child, we used to live in a narrow street in Izmir. Every evening the neighbours used to sit outside and chat while the children played. One night, while we were playing hide and seek, the electricity suddenly went off. Nobody was frightened; instead, someone started to sing. I still remember that evening as one of my happiest childhood memories.\",\"prompt\":\"How did people react?\",\"options\":[\"They were frightened.\",\"Someone started to sing.\",\"Everyone went home.\",\"They called a doctor.\"],\"answer\":1}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(204,19,'Kelime oyunu','vocabulary','words',3,20,0,NULL,NULL,'[]','{\"game\":\"swipe\",\"words\":[{\"word\":\"while\",\"translation\":\"-iken\",\"example\":\"While they were playing football, it started to rain.\"},{\"word\":\"suddenly\",\"translation\":\"aniden\",\"example\":\"Suddenly, someone knocked on the door.\"},{\"word\":\"used to\",\"translation\":\"eskiden \\u2026-irdi\",\"example\":\"We used to play in the street every evening.\"},{\"word\":\"childhood\",\"translation\":\"\\u00e7ocukluk\"},{\"word\":\"remember\",\"translation\":\"hat\\u0131rlamak\"},{\"word\":\"neighbourhood\",\"translation\":\"mahalle\"},{\"word\":\"happen\",\"translation\":\"olmak, meydana gelmek\"},{\"word\":\"ring\",\"translation\":\"\\u00e7almak (telefon)\"},{\"word\":\"notice\",\"translation\":\"fark etmek\"},{\"word\":\"memory\",\"translation\":\"an\\u0131\"}]}','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(205,19,'Dilbilgisi pekiştir','grammar','lesson',4,20,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"Did you ___ to live in Adana?\",\"options\":[\"using\",\"use\",\"used\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"I ___ to have long hair.\",\"options\":[\"use\",\"used\",\"was used\"],\"answer\":1},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"When\",\"I\",\"was\",\"a\",\"child\",\"I\",\"use\",\"to\",\"play\",\"outside\"],\"error_index\":6,\"options\":[\"used\",\"using\",\"uses\"],\"answer\":0,\"explanation_tr\":\"Ge\\u00e7mi\\u015fteki al\\u0131\\u015fkanl\\u0131klar i\\u00e7in \\\"used to\\\" kullan\\u0131l\\u0131r: I used to play outside. Olumsuz ve soruda ise \\\"use to\\\" olur: Did you use to \\u2026?\"},{\"type\":\"translate\",\"prompt\":\"Eskiden \\u00e7ok \\u00e7ay i\\u00e7erdim.\",\"answer\":\"I used to drink a lot of tea\",\"alternatives\":[],\"tiles\":[\"a\",\"used\",\"drink\",\"I\",\"was\",\"of\",\"lot\",\"use\",\"to\",\"tea\"]},{\"type\":\"fill\",\"prompt\":\"While they ___ football, it started to rain.\",\"options\":[\"played\",\"were playing\",\"was playing\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"I ___ dinner when you called.\",\"options\":[\"have\",\"had\",\"was having\"],\"answer\":2},{\"type\":\"translate\",\"prompt\":\"Sen arad\\u0131\\u011f\\u0131nda du\\u015f al\\u0131yordum.\",\"answer\":\"I was having a shower when you called\",\"alternatives\":[\"I was taking a shower when you called\"],\"tiles\":[\"was\",\"a\",\"shower\",\"called\",\"when\",\"had\",\"I\",\"you\",\"having\",\"were\"]},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Suddenly, someone knocked on the door.\",\"translation\":\"Aniden biri kap\\u0131y\\u0131 \\u00e7ald\\u0131.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(206,19,'Dinle ve konuş','listening','lesson',5,20,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Bir arkada\\u015f\\u0131n \\u00e7ocuklu\\u011funu soruyor.\",\"lines\":[{\"who\":\"Ava\",\"text\":\"What did you use to do in the summer holidays?\"}],\"options\":[\"We used to go to my grandparents\' village and swim in the river.\",\"We use to went village.\",\"I was used to go village.\"],\"answer\":0,\"note_tr\":\"Eski al\\u0131\\u015fkanl\\u0131klar i\\u00e7in \\\"used to + yal\\u0131n fiil\\\".\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"She used to live in Adana\",\"options\":[\"She used to live in Adana\",\"She uses to live in Adana\",\"She used to leave Adana\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"What were you doing last night\",\"answer\":\"What were you doing last night\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"What were you doing at this time yesterday?\",\"translation\":\"D\\u00fcn bu saatte ne yap\\u0131yordun?\"},{\"type\":\"translate\",\"prompt\":\"Eskiden \\u00e7ok \\u00e7ay i\\u00e7erdim.\",\"answer\":\"I used to drink a lot of tea\",\"alternatives\":[],\"tiles\":[\"a\",\"used\",\"drink\",\"I\",\"was\",\"of\",\"lot\",\"use\",\"to\",\"tea\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"I used to play the guitar\",\"answer\":\"I used to play the guitar\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Suddenly, someone knocked on the door.\",\"translation\":\"Aniden biri kap\\u0131y\\u0131 \\u00e7ald\\u0131.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(207,19,'Kelime tekrarı','vocabulary','lesson',6,20,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"ring\",\"\\u00e7almak (telefon)\"],[\"while\",\"-iken\"],[\"notice\",\"fark etmek\"],[\"memory\",\"an\\u0131\"],[\"neighbourhood\",\"mahalle\"]]},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"suddenly\",\"options\":[\"notice\",\"suddenly\",\"remember\",\"happen\"],\"answer\":1},{\"type\":\"choice\",\"prompt\":\"\\\"used to\\\" ne demek?\",\"options\":[\"an\\u0131\",\"olmak, meydana gelmek\",\"hat\\u0131rlamak\",\"eskiden \\u2026-irdi\"],\"answer\":3,\"audio\":\"used to\"},{\"type\":\"choice\",\"prompt\":\"\\\"hat\\u0131rlamak\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"ring\",\"remember\",\"childhood\",\"memory\"],\"answer\":1},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"happen\",\"options\":[\"childhood\",\"happen\",\"memory\",\"suddenly\"],\"answer\":1},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"memory\",\"answer\":\"memory\"},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"happen\",\"olmak, meydana gelmek\"],[\"suddenly\",\"aniden\"],[\"childhood\",\"\\u00e7ocukluk\"],[\"notice\",\"fark etmek\"],[\"remember\",\"hat\\u0131rlamak\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"while\\\" ne demek?\",\"options\":[\"-iken\",\"eskiden \\u2026-irdi\",\"\\u00e7almak (telefon)\",\"hat\\u0131rlamak\"],\"answer\":0,\"audio\":\"while\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(208,19,'Telaffuz','speaking','lesson',7,20,0,NULL,NULL,'[{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"while\",\"translation\":\"-iken\"},{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"suddenly\",\"translation\":\"aniden\"},{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"childhood\",\"translation\":\"\\u00e7ocukluk\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"I was reading when the lights went out.\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"I used to be very shy at school.\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"What were you doing at this time yesterday?\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
