(212,20,'Kelimeler','vocabulary','lesson',0,20,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"apply\",\"ba\\u015fvurmak\"],[\"unless\",\"-mezse\"],[\"as soon as\",\"-ir -mez\"],[\"probably\",\"muhtemelen\"],[\"definitely\",\"kesinlikle\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"appointment\\\" ne demek?\",\"options\":[\"hedef\",\"randevu\",\"mezun olmak\",\"-ir -mez\"],\"answer\":1,\"audio\":\"appointment\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"If it rains, we\'ll stay home\",\"options\":[\"If it rains, we\'ll stay home\",\"If it rained, we\'d stay home\",\"If it rains, we stay home\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Bursu al\\u0131rsam Almanya\'da okuyaca\\u011f\\u0131m.\",\"answer\":\"If I get the scholarship, I\'ll study in Germany\",\"alternatives\":[],\"tiles\":[\"study\",\"If\",\"scholarship\",\"appointment\",\"the\",\"get\",\"opportunity\",\"I\",\"in\",\"Germany\",\"I\'ll\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"appointment\",\"randevu\"],[\"decide\",\"karar vermek\"],[\"graduate\",\"mezun olmak\"],[\"opportunity\",\"f\\u0131rsat\"],[\"goal\",\"hedef\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"f\\u0131rsat\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"unless\",\"opportunity\",\"graduate\",\"probably\"],\"answer\":1},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I\'m meeting my advisor tomorrow at ten.\",\"translation\":\"Yar\\u0131n saat onda dan\\u0131\\u015fman\\u0131mla g\\u00f6r\\u00fc\\u015f\\u00fcyorum.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"I will call you as soon as I arrive\",\"answer\":\"I will call you as soon as I arrive\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(213,20,'Dilbilgisi','grammar','lesson',1,20,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"If it ___ tomorrow, we\'ll cancel the picnic.\",\"options\":[\"rains\",\"will rain\",\"rained\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"I\'ll text you as soon as I ___ home.\",\"options\":[\"get\",\"will get\",\"got\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"You won\'t pass ___ you study.\",\"options\":[\"if\",\"unless\",\"when\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"Look at that driver! He ___ crash.\",\"options\":[\"\'s going to\",\"will\",\"is\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Erken \\u00e7\\u0131karsak treni yakalar\\u0131z.\",\"answer\":\"If we leave early, we\'ll catch the train\",\"alternatives\":[\"If we leave early we will catch the train\",\"We will catch the train if we leave early\"],\"tiles\":[\"the\",\"we\",\"will leave\",\"train\",\"catch\",\"leave\",\"early\",\"If\",\"we\'ll\",\"catches\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"If\",\"I\",\"see\",\"him\",\"I\",\"tell\",\"him\",\"the\",\"news\"],\"error_index\":5,\"options\":[\"will tell\",\"told\",\"telling\"],\"answer\":0,\"explanation_tr\":\"First conditional\'da sonu\\u00e7 k\\u0131sm\\u0131 \\\"will + fiil\\\" olur: If I see him, I will tell him the news. (\\\"If\\\" k\\u0131sm\\u0131nda ise will kullan\\u0131lmaz.)\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"If I pass the exam, I\'ll celebrate with my friends.\",\"translation\":\"S\\u0131nav\\u0131 ge\\u00e7ersem arkada\\u015flar\\u0131mla kutlayaca\\u011f\\u0131m.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(214,20,'Okuma: After Graduation','reading','lesson',2,20,0,NULL,NULL,'[{\"type\":\"read\",\"title\":\"After Graduation\",\"passage\":\"Burak will graduate next June. He hasn\'t decided what to do yet, but he will probably apply for a master\'s programme abroad. \\\"If I get a scholarship, I\'ll go to Canada,\\\" he says. \\\"Unless I find a good opportunity there, I\'ll stay in Turkey and look for a job.\\\" He has an appointment with a career advisor next week, and he will definitely ask her for advice as soon as he gets there.\",\"prompt\":\"What will Burak do if he gets a scholarship?\",\"options\":[\"Stay in Turkey\",\"Go to Canada\",\"Find a job\",\"Start a company\"],\"answer\":1},{\"type\":\"read\",\"title\":\"After Graduation\",\"passage\":\"Burak will graduate next June. He hasn\'t decided what to do yet, but he will probably apply for a master\'s programme abroad. \\\"If I get a scholarship, I\'ll go to Canada,\\\" he says. \\\"Unless I find a good opportunity there, I\'ll stay in Turkey and look for a job.\\\" He has an appointment with a career advisor next week, and he will definitely ask her for advice as soon as he gets there.\",\"prompt\":\"Why has he made an appointment?\",\"options\":[\"To get career advice\",\"To see a doctor\",\"To apply for a visa\",\"To buy a ticket\"],\"answer\":0}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(215,20,'Kelime oyunu','vocabulary','words',3,20,0,NULL,NULL,'[]','{\"game\":\"choice\",\"words\":[{\"word\":\"apply\",\"translation\":\"ba\\u015fvurmak\",\"example\":\"I\'m going to apply for the job\"},{\"word\":\"unless\",\"translation\":\"-mezse\",\"example\":\"You won\'t pass unless you study.\"},{\"word\":\"as soon as\",\"translation\":\"-ir -mez\",\"example\":\"I will call you as soon as I arrive\"},{\"word\":\"probably\",\"translation\":\"muhtemelen\",\"example\":\"I\'m probably going to study engineering.\"},{\"word\":\"definitely\",\"translation\":\"kesinlikle\"},{\"word\":\"appointment\",\"translation\":\"randevu\"},{\"word\":\"decide\",\"translation\":\"karar vermek\"},{\"word\":\"graduate\",\"translation\":\"mezun olmak\"},{\"word\":\"opportunity\",\"translation\":\"f\\u0131rsat\"},{\"word\":\"goal\",\"translation\":\"hedef\"}]}','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(216,20,'Dilbilgisi pekiştir','grammar','lesson',4,20,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"Look at that driver! He ___ crash.\",\"options\":[\"will\",\"\'s going to\",\"is\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"You won\'t pass ___ you study.\",\"options\":[\"if\",\"unless\",\"when\"],\"answer\":1},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"If\",\"I\",\"see\",\"him\",\"I\",\"tell\",\"him\",\"the\",\"news\"],\"error_index\":5,\"options\":[\"will tell\",\"told\",\"telling\"],\"answer\":0,\"explanation_tr\":\"First conditional\'da sonu\\u00e7 k\\u0131sm\\u0131 \\\"will + fiil\\\" olur: If I see him, I will tell him the news. (\\\"If\\\" k\\u0131sm\\u0131nda ise will kullan\\u0131lmaz.)\"},{\"type\":\"translate\",\"prompt\":\"Yar\\u0131n ak\\u015fam annemlerle yemek yiyorum.\",\"answer\":\"I\'m having dinner with my parents tomorrow evening\",\"alternatives\":[\"I am having dinner with my parents tomorrow evening\",\"I\'m going to have dinner with my parents tomorrow evening\"],\"tiles\":[\"will\",\"parents\",\"tomorrow\",\"have\",\"I\'m\",\"my\",\"having\",\"dinner\",\"evening\",\"with\"]},{\"type\":\"fill\",\"prompt\":\"I\'ll text you as soon as I ___ home.\",\"options\":[\"get\",\"will get\",\"got\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"If it ___ tomorrow, we\'ll cancel the picnic.\",\"options\":[\"rained\",\"will rain\",\"rains\"],\"answer\":2},{\"type\":\"translate\",\"prompt\":\"Erken \\u00e7\\u0131karsak treni yakalar\\u0131z.\",\"answer\":\"If we leave early, we\'ll catch the train\",\"alternatives\":[\"If we leave early we will catch the train\",\"We will catch the train if we leave early\"],\"tiles\":[\"the\",\"we\",\"will leave\",\"train\",\"catch\",\"leave\",\"early\",\"If\",\"we\'ll\",\"catches\"]},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"What will you do if you don\'t get in?\",\"translation\":\"Kazanamazsan ne yapacaks\\u0131n?\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(217,20,'Dinle ve konuş','listening','lesson',5,20,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Bir kariyer dan\\u0131\\u015fman\\u0131yla konu\\u015fuyorsun.\",\"lines\":[{\"who\":\"Advisor\",\"text\":\"What will you do if you don\'t get into your first choice?\"}],\"options\":[\"If I don\'t get in, I\'ll take a gap year and work.\",\"If I will not get in, I take gap year.\",\"If I didn\'t get, I work.\"],\"answer\":0,\"note_tr\":\"Olas\\u0131 bir durumu anlat\\u0131rken: If + present simple, will + fiil.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"I\'m meeting her at six\",\"options\":[\"I\'m meeting her at six\",\"I\'ll meet her at six\",\"I met her at six\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"If you hurry you will catch the bus\",\"answer\":\"If you hurry you will catch the bus\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I\'m probably going to study engineering.\",\"translation\":\"Muhtemelen m\\u00fchendislik okuyaca\\u011f\\u0131m.\"},{\"type\":\"translate\",\"prompt\":\"Yar\\u0131n ak\\u015fam annemlerle yemek yiyorum.\",\"answer\":\"I\'m having dinner with my parents tomorrow evening\",\"alternatives\":[\"I am having dinner with my parents tomorrow evening\",\"I\'m going to have dinner with my parents tomorrow evening\"],\"tiles\":[\"will\",\"parents\",\"tomorrow\",\"have\",\"I\'m\",\"my\",\"having\",\"dinner\",\"evening\",\"with\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"I\'m going to apply for the job\",\"answer\":\"I\'m going to apply for the job\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"What will you do if you don\'t get in?\",\"translation\":\"Kazanamazsan ne yapacaks\\u0131n?\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(218,20,'Kelime tekrarı','vocabulary','lesson',6,20,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"goal\",\"hedef\"],[\"decide\",\"karar vermek\"],[\"graduate\",\"mezun olmak\"],[\"appointment\",\"randevu\"],[\"unless\",\"-mezse\"]]},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"unless\",\"options\":[\"definitely\",\"decide\",\"unless\",\"opportunity\"],\"answer\":2},{\"type\":\"choice\",\"prompt\":\"\\\"as soon as\\\" ne demek?\",\"options\":[\"hedef\",\"karar vermek\",\"kesinlikle\",\"-ir -mez\"],\"answer\":3,\"audio\":\"as soon as\"},{\"type\":\"choice\",\"prompt\":\"\\\"kesinlikle\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"goal\",\"graduate\",\"probably\",\"definitely\"],\"answer\":3},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"decide\",\"options\":[\"decide\",\"unless\",\"probably\",\"goal\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"goal\",\"answer\":\"goal\"},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"decide\",\"karar vermek\"],[\"probably\",\"muhtemelen\"],[\"definitely\",\"kesinlikle\"],[\"opportunity\",\"f\\u0131rsat\"],[\"appointment\",\"randevu\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"apply\\\" ne demek?\",\"options\":[\"kesinlikle\",\"mezun olmak\",\"ba\\u015fvurmak\",\"-ir -mez\"],\"answer\":2,\"audio\":\"apply\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(219,20,'Telaffuz','speaking','lesson',7,20,0,NULL,NULL,'[{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"apply\",\"translation\":\"ba\\u015fvurmak\"},{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"unless\",\"translation\":\"-mezse\"},{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"probably\",\"translation\":\"muhtemelen\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"If I get the scholarship, I\'ll study in Germany.\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"If I pass the exam, I\'ll celebrate with my friends.\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"I\'m probably going to study engineering.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
