(221,20,'Pratik','vocabulary','lesson',9,20,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"probably\",\"muhtemelen\"],[\"apply\",\"ba\\u015fvurmak\"],[\"unless\",\"-mezse\"],[\"graduate\",\"mezun olmak\"],[\"definitely\",\"kesinlikle\"]]},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"unless\",\"options\":[\"unless\",\"definitely\",\"opportunity\",\"decide\"],\"answer\":0},{\"type\":\"choice\",\"prompt\":\"\\\"as soon as\\\" ne demek?\",\"options\":[\"-ir -mez\",\"hedef\",\"kesinlikle\",\"karar vermek\"],\"answer\":0,\"audio\":\"as soon as\"},{\"type\":\"choice\",\"prompt\":\"\\\"kesinlikle\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"goal\",\"probably\",\"graduate\",\"definitely\"],\"answer\":3},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"decide\",\"options\":[\"decide\",\"unless\",\"goal\",\"probably\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"goal\",\"answer\":\"goal\"},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"goal\",\"hedef\"],[\"appointment\",\"randevu\"],[\"unless\",\"-mezse\"],[\"graduate\",\"mezun olmak\"],[\"probably\",\"muhtemelen\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"apply\\\" ne demek?\",\"options\":[\"kesinlikle\",\"mezun olmak\",\"-ir -mez\",\"ba\\u015fvurmak\"],\"answer\":3,\"audio\":\"apply\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
