(238,22,'Dilbilgisi pekiştir','grammar','lesson',4,20,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"The thief ___ by the police last night.\",\"options\":[\"has arrest\",\"arrested\",\"was arrested\"],\"answer\":2},{\"type\":\"fill\",\"prompt\":\"A new hospital ___ next year.\",\"options\":[\"opens\",\"will be opened\",\"will open\"],\"answer\":1},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"The\",\"new\",\"bridge\",\"was\",\"build\",\"last\",\"year\"],\"error_index\":4,\"options\":[\"built\",\"builded\",\"building\"],\"answer\":0,\"explanation_tr\":\"Passive\'de fiilin 3. h\\u00e2li kullan\\u0131l\\u0131r: build \\u2192 built \\u2192 built. Do\\u011frusu: was built.\"},{\"type\":\"translate\",\"prompt\":\"Toplant\\u0131 ertelendi.\",\"answer\":\"The meeting has been postponed\",\"alternatives\":[\"The meeting was postponed\"],\"tiles\":[\"meeting\",\"has\",\"The\",\"is\",\"postponed\",\"been\",\"postponed\"]},{\"type\":\"fill\",\"prompt\":\"The Galata Tower ___ in 1348.\",\"options\":[\"is building\",\"was built\",\"built\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"English ___ in many countries.\",\"options\":[\"is spoken\",\"spoke\",\"speaks\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Bu roman Elif \\u015eafak taraf\\u0131ndan yaz\\u0131ld\\u0131.\",\"answer\":\"This novel was written by Elif Shafak\",\"alternatives\":[\"This novel was written by Elif \\u015eafak\"],\"tiles\":[\"from\",\"was\",\"written\",\"wrote\",\"novel\",\"by\",\"This\",\"Elif\",\"Shafak\"]},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"The match has been cancelled because of the rain.\",\"translation\":\"Ma\\u00e7 ya\\u011fmur y\\u00fcz\\u00fcnden iptal edildi.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(239,22,'Dinle ve konuş','listening','lesson',5,20,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Bir haber sunucusu olarak son dakika haberini okuyorsun.\",\"lines\":[{\"who\":\"Producer\",\"text\":\"We\'re live in ten seconds. What happened at the stadium?\"}],\"options\":[\"The match was stopped after the lights were damaged by the storm.\",\"Storm damaged lights was stopped match.\",\"The match stopping by storm.\"],\"answer\":0,\"note_tr\":\"Haber dilinde olay\\u0131 \\u00f6ne almak i\\u00e7in passive kullan\\u0131l\\u0131r.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"It was built in 1973\",\"options\":[\"It was built in 1973\",\"It was filled in 1973\",\"It is built in 1973\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"The road was closed\",\"answer\":\"The road was closed\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Nobody was injured in the accident.\",\"translation\":\"Kazada kimse yaralanmad\\u0131.\"},{\"type\":\"translate\",\"prompt\":\"Toplant\\u0131 ertelendi.\",\"answer\":\"The meeting has been postponed\",\"alternatives\":[\"The meeting was postponed\"],\"tiles\":[\"meeting\",\"has\",\"The\",\"is\",\"postponed\",\"been\",\"postponed\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"The letter has been sent\",\"answer\":\"The letter has been sent\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"The match has been cancelled because of the rain.\",\"translation\":\"Ma\\u00e7 ya\\u011fmur y\\u00fcz\\u00fcnden iptal edildi.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(240,22,'Kelime tekrarı','vocabulary','lesson',6,20,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"discover\",\"ke\\u015ffetmek\"],[\"publish\",\"yay\\u0131mlamak\"],[\"headline\",\"man\\u015fet\"],[\"news\",\"haber\"],[\"damage\",\"hasar (vermek)\"]]},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"headline\",\"options\":[\"headline\",\"discover\",\"damage\",\"announce\"],\"answer\":0},{\"type\":\"choice\",\"prompt\":\"\\\"journalist\\\" ne demek?\",\"options\":[\"yay\\u0131mlamak\",\"gazeteci\",\"hasar (vermek)\",\"duyurmak\"],\"answer\":1,\"audio\":\"journalist\"},{\"type\":\"choice\",\"prompt\":\"\\\"duyurmak\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"announce\",\"report\",\"arrest\",\"publish\"],\"answer\":0},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"damage\",\"options\":[\"report\",\"headline\",\"damage\",\"publish\"],\"answer\":2},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"publish\",\"answer\":\"publish\"},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"report\",\"haber vermek, rapor\"],[\"damage\",\"hasar (vermek)\"],[\"headline\",\"man\\u015fet\"],[\"build\",\"in\\u015fa etmek\"],[\"journalist\",\"gazeteci\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"news\\\" ne demek?\",\"options\":[\"duyurmak\",\"tutuklamak\",\"haber\",\"gazeteci\"],\"answer\":2,\"audio\":\"news\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
