(245,23,'Kelimeler','vocabulary','lesson',0,20,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"said\",\"s\\u00f6yledi\"],[\"told\",\"anlatt\\u0131, s\\u00f6yledi (birine)\"],[\"asked\",\"sordu\"],[\"explain\",\"a\\u00e7\\u0131klamak\"],[\"promise\",\"s\\u00f6z vermek\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"complain\\\" ne demek?\",\"options\":[\"sordu\",\"mesaj\",\"cevap vermek\",\"\\u015fik\\u00e2yet etmek\"],\"answer\":3,\"audio\":\"complain\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"She said she was tired\",\"options\":[\"She said she was tired\",\"She says she is tired\",\"She said she was tied\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Bana \\u0130zmir\'e ta\\u015f\\u0131nd\\u0131\\u011f\\u0131n\\u0131 s\\u00f6yledi.\",\"answer\":\"She told me she was moving to Izmir\",\"alternatives\":[],\"tiles\":[\"She\",\"was\",\"me\",\"moving\",\"Izmir\",\"told\",\"whether\",\"she\",\"to\",\"told\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"complain\",\"\\u015fik\\u00e2yet etmek\"],[\"suggest\",\"\\u00f6nermek\"],[\"reply\",\"cevap vermek\"],[\"whether\",\"-ip -medi\\u011fini\"],[\"message\",\"mesaj\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"-ip -medi\\u011fini\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"reply\",\"explain\",\"whether\",\"told\"],\"answer\":2},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"He asked me where I lived.\",\"translation\":\"Bana nerede ya\\u015fad\\u0131\\u011f\\u0131m\\u0131 sordu.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"They said they would be late\",\"answer\":\"They said they would be late\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(246,23,'Dilbilgisi','grammar','lesson',1,20,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"She said she ___ tired.\",\"options\":[\"is\",\"was\",\"were\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"He ___ me that he was busy.\",\"options\":[\"said\",\"told\",\"asked\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"They asked me where I ___.\",\"options\":[\"live\",\"lived\",\"do live\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"The teacher told us ___ quiet.\",\"options\":[\"be\",\"to be\",\"being\"],\"answer\":1},{\"type\":\"translate\",\"prompt\":\"Bana yar\\u0131n arayaca\\u011f\\u0131n\\u0131 s\\u00f6yledi.\",\"answer\":\"He told me he would call the next day\",\"alternatives\":[\"He said he would call me the next day\",\"He told me that he would call the next day\"],\"tiles\":[\"he\",\"He\",\"told\",\"will\",\"me\",\"said\",\"call\",\"next\",\"day\",\"would\",\"the\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"He\",\"said\",\"me\",\"that\",\"he\",\"was\",\"hungry\"],\"error_index\":1,\"options\":[\"told\",\"asked\",\"spoke\"],\"answer\":0,\"explanation_tr\":\"\\\"Say\\\" ki\\u015fi nesnesi almaz. Ki\\u015fiyi s\\u00f6yleyeceksen \\\"tell\\\" kullan: He told me that he was hungry. Ya da: He said that he was hungry.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"She told me she would be there by eight.\",\"translation\":\"Sekize kadar orada olaca\\u011f\\u0131n\\u0131 s\\u00f6yledi.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(247,23,'Okuma: A Message from Ms Kaya','reading','lesson',2,20,0,NULL,NULL,'[{\"type\":\"read\",\"title\":\"A Message from Ms Kaya\",\"passage\":\"Yesterday our English teacher told us that the exam had been moved to Friday. She explained that the classroom was needed for a meeting on Wednesday. Ali asked whether the exam would be longer, and she replied that it wouldn\'t. Some students complained that Friday was too late, but she promised to return our papers before the weekend. She also suggested that we revise units five and six.\",\"prompt\":\"Why was the exam moved?\",\"options\":[\"The teacher was ill.\",\"The classroom was needed for a meeting.\",\"Students asked for more time.\",\"It was a holiday.\"],\"answer\":1},{\"type\":\"read\",\"title\":\"A Message from Ms Kaya\",\"passage\":\"Yesterday our English teacher told us that the exam had been moved to Friday. She explained that the classroom was needed for a meeting on Wednesday. Ali asked whether the exam would be longer, and she replied that it wouldn\'t. Some students complained that Friday was too late, but she promised to return our papers before the weekend. She also suggested that we revise units five and six.\",\"prompt\":\"What did the teacher promise?\",\"options\":[\"To make the exam easier\",\"To return the papers before the weekend\",\"To cancel the exam\",\"To give extra marks\"],\"answer\":1}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(248,23,'Kelime oyunu','vocabulary','words',3,20,0,NULL,NULL,'[]','{\"game\":\"memory\",\"words\":[{\"word\":\"said\",\"translation\":\"s\\u00f6yledi\",\"example\":\"They said they would be late\"},{\"word\":\"told\",\"translation\":\"anlatt\\u0131, s\\u00f6yledi (birine)\",\"example\":\"She told me she was moving to Izmir.\"},{\"word\":\"asked\",\"translation\":\"sordu\",\"example\":\"He asked me where I lived.\"},{\"word\":\"explain\",\"translation\":\"a\\u00e7\\u0131klamak\"},{\"word\":\"promise\",\"translation\":\"s\\u00f6z vermek\"},{\"word\":\"complain\",\"translation\":\"\\u015fik\\u00e2yet etmek\"},{\"word\":\"suggest\",\"translation\":\"\\u00f6nermek\"},{\"word\":\"reply\",\"translation\":\"cevap vermek\"},{\"word\":\"whether\",\"translation\":\"-ip -medi\\u011fini\"},{\"word\":\"message\",\"translation\":\"mesaj\"}]}','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(249,23,'Dilbilgisi pekiştir','grammar','lesson',4,20,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"The teacher told us ___ quiet.\",\"options\":[\"be\",\"to be\",\"being\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"They asked me where I ___.\",\"options\":[\"live\",\"lived\",\"do live\"],\"answer\":1},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"He\",\"said\",\"me\",\"that\",\"he\",\"was\",\"hungry\"],\"error_index\":1,\"options\":[\"told\",\"asked\",\"spoke\"],\"answer\":0,\"explanation_tr\":\"\\\"Say\\\" ki\\u015fi nesnesi almaz. Ki\\u015fiyi s\\u00f6yleyeceksen \\\"tell\\\" kullan: He told me that he was hungry. Ya da: He said that he was hungry.\"},{\"type\":\"translate\",\"prompt\":\"Bana nerede \\u00e7al\\u0131\\u015ft\\u0131\\u011f\\u0131m\\u0131 sordu.\",\"answer\":\"She asked me where I worked\",\"alternatives\":[\"She asked where I worked\"],\"tiles\":[\"She\",\"do\",\"where\",\"me\",\"I\",\"asked\",\"worked\",\"work\"]},{\"type\":\"fill\",\"prompt\":\"He ___ me that he was busy.\",\"options\":[\"said\",\"asked\",\"told\"],\"answer\":2},{\"type\":\"fill\",\"prompt\":\"She said she ___ tired.\",\"options\":[\"is\",\"was\",\"were\"],\"answer\":1},{\"type\":\"translate\",\"prompt\":\"Bana yar\\u0131n arayaca\\u011f\\u0131n\\u0131 s\\u00f6yledi.\",\"answer\":\"He told me he would call the next day\",\"alternatives\":[\"He said he would call me the next day\",\"He told me that he would call the next day\"],\"tiles\":[\"he\",\"He\",\"told\",\"will\",\"me\",\"said\",\"call\",\"next\",\"day\",\"would\",\"the\"]},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"They said the shop was closed.\",\"translation\":\"D\\u00fckk\\u00e2n\\u0131n kapal\\u0131 oldu\\u011funu s\\u00f6ylediler.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(250,23,'Dinle ve konuş','listening','lesson',5,20,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Patronun arad\\u0131, mesaj\\u0131n\\u0131 i\\u015f arkada\\u015f\\u0131na aktar\\u0131yorsun.\",\"lines\":[{\"who\":\"Colleague\",\"text\":\"What did the boss say on the phone?\"}],\"options\":[\"She said the meeting was cancelled and told us to send the report by Friday.\",\"She said us meeting is cancel.\",\"She told that meeting cancelled.\"],\"answer\":0,\"note_tr\":\"Aktar\\u0131rken zaman bir geri gider; \\\"tell\\\" ki\\u015fiyle, \\\"say\\\" ki\\u015fisiz kullan\\u0131l\\u0131r.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"He asked where I lived\",\"options\":[\"He asked where I lived\",\"He asked where I left\",\"He asked where do I live\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"She told me to wait\",\"answer\":\"She told me to wait\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"He asked if I wanted to join them.\",\"translation\":\"Onlara kat\\u0131lmak isteyip istemedi\\u011fimi sordu.\"},{\"type\":\"translate\",\"prompt\":\"Bana nerede \\u00e7al\\u0131\\u015ft\\u0131\\u011f\\u0131m\\u0131 sordu.\",\"answer\":\"She asked me where I worked\",\"alternatives\":[\"She asked where I worked\"],\"tiles\":[\"She\",\"do\",\"where\",\"me\",\"I\",\"asked\",\"worked\",\"work\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"He said he would help\",\"answer\":\"He said he would help\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"They said the shop was closed.\",\"translation\":\"D\\u00fckk\\u00e2n\\u0131n kapal\\u0131 oldu\\u011funu s\\u00f6ylediler.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(251,23,'Kelime tekrarı','vocabulary','lesson',6,20,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"asked\",\"sordu\"],[\"suggest\",\"\\u00f6nermek\"],[\"promise\",\"s\\u00f6z vermek\"],[\"said\",\"s\\u00f6yledi\"],[\"explain\",\"a\\u00e7\\u0131klamak\"]]},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"told\",\"options\":[\"suggest\",\"promise\",\"told\",\"whether\"],\"answer\":2},{\"type\":\"choice\",\"prompt\":\"\\\"asked\\\" ne demek?\",\"options\":[\"\\u00f6nermek\",\"sordu\",\"mesaj\",\"s\\u00f6z vermek\"],\"answer\":1,\"audio\":\"asked\"},{\"type\":\"choice\",\"prompt\":\"\\\"s\\u00f6z vermek\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"reply\",\"promise\",\"explain\",\"message\"],\"answer\":1},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"suggest\",\"options\":[\"told\",\"suggest\",\"explain\",\"message\"],\"answer\":1},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"message\",\"answer\":\"message\"},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"message\",\"mesaj\"],[\"promise\",\"s\\u00f6z vermek\"],[\"reply\",\"cevap vermek\"],[\"explain\",\"a\\u00e7\\u0131klamak\"],[\"complain\",\"\\u015fik\\u00e2yet etmek\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"said\\\" ne demek?\",\"options\":[\"cevap vermek\",\"s\\u00f6z vermek\",\"sordu\",\"s\\u00f6yledi\"],\"answer\":3,\"audio\":\"said\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
