(254,23,'Pratik','vocabulary','lesson',9,20,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"message\",\"mesaj\"],[\"suggest\",\"\\u00f6nermek\"],[\"complain\",\"\\u015fik\\u00e2yet etmek\"],[\"promise\",\"s\\u00f6z vermek\"],[\"said\",\"s\\u00f6yledi\"]]},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"told\",\"options\":[\"whether\",\"promise\",\"told\",\"suggest\"],\"answer\":2},{\"type\":\"choice\",\"prompt\":\"\\\"asked\\\" ne demek?\",\"options\":[\"mesaj\",\"s\\u00f6z vermek\",\"sordu\",\"\\u00f6nermek\"],\"answer\":2,\"audio\":\"asked\"},{\"type\":\"choice\",\"prompt\":\"\\\"s\\u00f6z vermek\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"explain\",\"promise\",\"reply\",\"message\"],\"answer\":1},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"suggest\",\"options\":[\"explain\",\"told\",\"suggest\",\"message\"],\"answer\":2},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"message\",\"answer\":\"message\"},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"reply\",\"cevap vermek\"],[\"said\",\"s\\u00f6yledi\"],[\"whether\",\"-ip -medi\\u011fini\"],[\"message\",\"mesaj\"],[\"complain\",\"\\u015fik\\u00e2yet etmek\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"said\\\" ne demek?\",\"options\":[\"s\\u00f6yledi\",\"sordu\",\"cevap vermek\",\"s\\u00f6z vermek\"],\"answer\":0,\"audio\":\"said\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
