(276,25,'Pratik','vocabulary','lesson',9,20,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"hire\",\"i\\u015fe almak\"],[\"apply for\",\"ba\\u015fvurmak\"],[\"avoid\",\"ka\\u00e7\\u0131nmak\"],[\"deadline\",\"son teslim tarihi\"],[\"CV\",\"\\u00f6zge\\u00e7mi\\u015f\"]]},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"position\",\"options\":[\"position\",\"salary\",\"colleague\",\"avoid\"],\"answer\":0},{\"type\":\"choice\",\"prompt\":\"\\\"CV\\\" ne demek?\",\"options\":[\"i\\u015f arkada\\u015f\\u0131\",\"i\\u015fe almak\",\"\\u00f6zge\\u00e7mi\\u015f\",\"maa\\u015f\"],\"answer\":2,\"audio\":\"CV\"},{\"type\":\"choice\",\"prompt\":\"\\\"i\\u015f arkada\\u015f\\u0131\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"look forward to\",\"deadline\",\"hire\",\"colleague\"],\"answer\":3},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"salary\",\"options\":[\"deadline\",\"salary\",\"hire\",\"position\"],\"answer\":1},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"hire\",\"answer\":\"hire\"},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"salary\",\"maa\\u015f\"],[\"apply for\",\"ba\\u015fvurmak\"],[\"hire\",\"i\\u015fe almak\"],[\"look forward to\",\"d\\u00f6rt g\\u00f6zle beklemek\"],[\"CV\",\"\\u00f6zge\\u00e7mi\\u015f\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"apply for\\\" ne demek?\",\"options\":[\"\\u00f6zge\\u00e7mi\\u015f\",\"ba\\u015fvurmak\",\"d\\u00f6rt g\\u00f6zle beklemek\",\"i\\u015f arkada\\u015f\\u0131\"],\"answer\":1,\"audio\":\"apply for\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
