(278,25,'B1 seviye sınavı','mixed','checkpoint',11,50,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"I\'ve lived here ___ 2019.\",\"options\":[\"for\",\"since\",\"from\"],\"answer\":1},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"When\",\"I\",\"was\",\"a\",\"child\",\"I\",\"use\",\"to\",\"play\",\"outside\"],\"error_index\":6,\"options\":[\"used\",\"using\",\"uses\"],\"answer\":0,\"explanation_tr\":\"Ge\\u00e7mi\\u015fteki al\\u0131\\u015fkanl\\u0131klar i\\u00e7in \\\"used to\\\" kullan\\u0131l\\u0131r: I used to play outside. Olumsuz ve soruda ise \\\"use to\\\" olur: Did you use to \\u2026?\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"If it rains, we\'ll stay home\",\"options\":[\"If it rains, we\'ll stay home\",\"If it rained, we\'d stay home\",\"If it rains, we stay home\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Ke\\u015fke denize yak\\u0131n ya\\u015fasam.\",\"answer\":\"I wish I lived near the sea\",\"alternatives\":[\"I wish I lived by the sea\"],\"tiles\":[\"would\",\"lived\",\"near\",\"sea\",\"I\",\"I\",\"the\",\"wish\",\"live\"]},{\"type\":\"fill\",\"prompt\":\"The Galata Tower ___ in 1348.\",\"options\":[\"built\",\"was built\",\"is building\"],\"answer\":1},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"He\",\"said\",\"me\",\"that\",\"he\",\"was\",\"hungry\"],\"error_index\":1,\"options\":[\"told\",\"asked\",\"spoke\"],\"answer\":0,\"explanation_tr\":\"\\\"Say\\\" ki\\u015fi nesnesi almaz. Ki\\u015fiyi s\\u00f6yleyeceksen \\\"tell\\\" kullan: He told me that he was hungry. Ya da: He said that he was hungry.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"the woman who lives next door\",\"options\":[\"the woman who lives next door\",\"the woman who leaves next door\",\"the woman who lived next door\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Raporu cumaya kadar bitirmeyi planl\\u0131yoruz.\",\"answer\":\"We plan to finish the report by Friday\",\"alternatives\":[\"We are planning to finish the report by Friday\"],\"tiles\":[\"finish\",\"Friday\",\"by\",\"finishing\",\"until\",\"report\",\"to\",\"the\",\"We\",\"plan\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"Thank you for your email\",\"answer\":\"Thank you for your email\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Thank you for considering my application.\",\"translation\":\"Ba\\u015fvurumu de\\u011ferlendirdi\\u011finiz i\\u00e7in te\\u015fekk\\u00fcr ederim.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(279,26,'Kelimeler','vocabulary','lesson',0,22,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"regret\",\"pi\\u015fmanl\\u0131k, pi\\u015fman olmak\"],[\"opportunity\",\"f\\u0131rsat\"],[\"miss\",\"ka\\u00e7\\u0131rmak\"],[\"consequence\",\"sonu\\u00e7\"],[\"otherwise\",\"aksi takdirde\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"hindsight\\\" ne demek?\",\"options\":[\"ders\",\"su\\u00e7lamak\",\"sonradan anlama\",\"ka\\u00e7\\u0131rmak\"],\"answer\":2,\"audio\":\"hindsight\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"If I\'d known, I would have come\",\"options\":[\"If I\'d known, I would have come\",\"If I know, I will come\",\"If I\'d known, I would come\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Bilseydim sana yard\\u0131m ederdim.\",\"answer\":\"If I had known, I would have helped you\",\"alternatives\":[],\"tiles\":[\"had\",\"have\",\"I\",\"I\",\"decision\",\"consequence\",\"helped\",\"known\",\"If\",\"you\",\"would\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"hindsight\",\"sonradan anlama\"],[\"decision\",\"karar\"],[\"blame\",\"su\\u00e7lamak\"],[\"avoid\",\"\\u00f6nlemek\"],[\"lesson\",\"ders\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"\\u00f6nlemek\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"avoid\",\"consequence\",\"opportunity\",\"blame\"],\"answer\":0},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I wish I had studied harder at school.\",\"translation\":\"Ke\\u015fke okulda daha \\u00e7ok \\u00e7al\\u0131\\u015fsayd\\u0131m.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"You should have called me earlier\",\"answer\":\"You should have called me earlier\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(280,26,'Dilbilgisi','grammar','lesson',1,22,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"If we ___ the map, we wouldn\'t have got lost.\",\"options\":[\"had checked\",\"checked\",\"would check\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"She would have come if you ___ her.\",\"options\":[\"invited\",\"had invited\",\"have invited\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"I wish I ___ that email.\",\"options\":[\"hadn\'t sent\",\"didn\'t send\",\"wouldn\'t send\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"If I had taken the job, I ___ in London now.\",\"options\":[\"would live\",\"would have lived\",\"will live\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Daha erken \\u00e7\\u0131ksayd\\u0131k treni ka\\u00e7\\u0131rmazd\\u0131k.\",\"answer\":\"If we had left earlier, we wouldn\'t have missed the train\",\"alternatives\":[\"If we had left earlier we wouldn\'t have missed the train\",\"If we had left earlier, we would not have missed the train\"],\"tiles\":[\"missed\",\"we\",\"left\",\"had\",\"didn\'t\",\"If\",\"the\",\"would leave\",\"have\",\"train\",\"wouldn\'t\",\"earlier\",\"we\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"If\",\"I\",\"knew\",\"about\",\"the\",\"party\",\"I\",\"would\",\"have\",\"come\"],\"error_index\":2,\"options\":[\"had known\",\"would know\",\"have known\"],\"answer\":0,\"explanation_tr\":\"Ge\\u00e7mi\\u015fteki ger\\u00e7ek d\\u0131\\u015f\\u0131 ko\\u015fulda \\\"if\\\" k\\u0131sm\\u0131nda past perfect kullan\\u0131l\\u0131r: If I had known about the party, I would have come.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"If I\'d known about the party, I would have come.\",\"translation\":\"Partiyi bilseydim gelirdim.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(281,26,'Okuma: The Train I Missed','reading','lesson',2,22,0,NULL,NULL,'[{\"type\":\"read\",\"title\":\"The Train I Missed\",\"passage\":\"Ten years ago I missed a train that would have changed my life. I had been offered an interview at a company in Berlin, but I overslept and arrived at the station two minutes late. If I had caught that train, I would probably be living in Germany now. At the time I blamed myself for weeks. In hindsight, however, missing it taught me a valuable lesson: had I not stayed, I would never have met my wife, who started working at my office a month later.\",\"prompt\":\"Why did the writer miss the train?\",\"options\":[\"The train left early.\",\"He overslept.\",\"He lost his ticket.\",\"There was a strike.\"],\"answer\":1},{\"type\":\"read\",\"title\":\"The Train I Missed\",\"passage\":\"Ten years ago I missed a train that would have changed my life. I had been offered an interview at a company in Berlin, but I overslept and arrived at the station two minutes late. If I had caught that train, I would probably be living in Germany now. At the time I blamed myself for weeks. In hindsight, however, missing it taught me a valuable lesson: had I not stayed, I would never have met my wife, who started working at my office a month later.\",\"prompt\":\"How does the writer see the event now?\",\"options\":[\"As a terrible mistake\",\"As a valuable lesson\",\"As unimportant\",\"As his wife\'s fault\"],\"answer\":1},{\"type\":\"read\",\"title\":\"The Train I Missed\",\"passage\":\"Ten years ago I missed a train that would have changed my life. I had been offered an interview at a company in Berlin, but I overslept and arrived at the station two minutes late. If I had caught that train, I would probably be living in Germany now. At the time I blamed myself for weeks. In hindsight, however, missing it taught me a valuable lesson: had I not stayed, I would never have met my wife, who started working at my office a month later.\",\"prompt\":\"What would have happened if he had caught the train?\",\"options\":[\"He would have met his wife.\",\"He would probably live in Germany.\",\"He would have lost his job.\",\"He would have stayed in Turkey.\"],\"answer\":1}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(282,26,'Kelime oyunu','vocabulary','words',3,22,0,NULL,NULL,'[]','{\"game\":\"match\",\"words\":[{\"word\":\"regret\",\"translation\":\"pi\\u015fmanl\\u0131k, pi\\u015fman olmak\"},{\"word\":\"opportunity\",\"translation\":\"f\\u0131rsat\"},{\"word\":\"miss\",\"translation\":\"ka\\u00e7\\u0131rmak\"},{\"word\":\"consequence\",\"translation\":\"sonu\\u00e7\"},{\"word\":\"otherwise\",\"translation\":\"aksi takdirde\"},{\"word\":\"hindsight\",\"translation\":\"sonradan anlama\"},{\"word\":\"decision\",\"translation\":\"karar\"},{\"word\":\"blame\",\"translation\":\"su\\u00e7lamak\"},{\"word\":\"avoid\",\"translation\":\"\\u00f6nlemek\"},{\"word\":\"lesson\",\"translation\":\"ders\"}]}','2026-10-04 20:30:41','2026-10-04 20:30:41'),
