(291,27,'Dilbilgisi','grammar','lesson',1,22,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"The lights are off. They ___ gone to bed.\",\"options\":[\"must have\",\"can\'t have\",\"should\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"He ___ be at work. It\'s Sunday.\",\"options\":[\"can\'t\",\"must\",\"might have\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"I\'m not sure where Ece is. She ___ be in the library.\",\"options\":[\"might\",\"must\",\"can\'t\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"You ___ seen Ali yesterday. He was in Paris.\",\"options\":[\"can\'t have\",\"must have\",\"might\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Anahtarlar\\u0131m\\u0131 otob\\u00fcste unutmu\\u015f olmal\\u0131y\\u0131m.\",\"answer\":\"I must have left my keys on the bus\",\"alternatives\":[\"I must have forgotten my keys on the bus\"],\"tiles\":[\"bus\",\"have\",\"I\",\"keys\",\"on\",\"should\",\"must\",\"forgot\",\"my\",\"left\",\"the\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"He\",\"mustn\'t\",\"be\",\"at\",\"home,\",\"his\",\"car\",\"isn\'t\",\"here\"],\"error_index\":1,\"options\":[\"can\'t\",\"should\",\"might\"],\"answer\":0,\"explanation_tr\":\"Kesin olumsuz \\u00e7\\u0131kar\\u0131m i\\u00e7in \\\"can\'t\\\" kullan\\u0131l\\u0131r; \\\"mustn\'t\\\" yasak anlam\\u0131 ta\\u015f\\u0131r: He can\'t be at home.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Someone must have opened the window.\",\"translation\":\"Biri pencereyi a\\u00e7m\\u0131\\u015f olmal\\u0131.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(292,27,'Okuma: The Empty Office','reading','lesson',2,22,0,NULL,NULL,'[{\"type\":\"read\",\"title\":\"The Empty Office\",\"passage\":\"When the security guard arrived on Monday morning, the office was empty but the lights were on. A cup of coffee on the desk was still warm, so someone must have been there only minutes earlier. The window couldn\'t have been opened from outside, because it had been locked. There were muddy footprints near the door. The police assumed it might have been an employee, but the only witness, a cleaner, insisted that nobody had entered. The mystery remained unsolved for weeks.\",\"prompt\":\"Why did the guard think someone had just been there?\",\"options\":[\"The door was open.\",\"The coffee was still warm.\",\"The window was broken.\",\"The computer was on.\"],\"answer\":1},{\"type\":\"read\",\"title\":\"The Empty Office\",\"passage\":\"When the security guard arrived on Monday morning, the office was empty but the lights were on. A cup of coffee on the desk was still warm, so someone must have been there only minutes earlier. The window couldn\'t have been opened from outside, because it had been locked. There were muddy footprints near the door. The police assumed it might have been an employee, but the only witness, a cleaner, insisted that nobody had entered. The mystery remained unsolved for weeks.\",\"prompt\":\"What did the cleaner say?\",\"options\":[\"A stranger entered.\",\"Nobody had entered.\",\"She saw an employee.\",\"The guard was lying.\"],\"answer\":1}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
