(299,27,'Pratik','vocabulary','lesson',9,22,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"evidence\",\"kan\\u0131t\"],[\"conclusion\",\"sonu\\u00e7\"],[\"suspect\",\"\\u015f\\u00fcpheli\"],[\"assume\",\"varsaymak\"],[\"witness\",\"tan\\u0131k\"]]},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"clue\",\"options\":[\"witness\",\"certainly\",\"conclusion\",\"clue\"],\"answer\":3},{\"type\":\"choice\",\"prompt\":\"\\\"suspect\\\" ne demek?\",\"options\":[\"tan\\u0131k\",\"kesinlikle\",\"gizem\",\"\\u015f\\u00fcpheli\"],\"answer\":3,\"audio\":\"suspect\"},{\"type\":\"choice\",\"prompt\":\"\\\"kesinlikle\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"certainly\",\"mystery\",\"probably\",\"assume\"],\"answer\":0},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"witness\",\"options\":[\"witness\",\"clue\",\"mystery\",\"probably\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"mystery\",\"answer\":\"mystery\"},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"conclusion\",\"sonu\\u00e7\"],[\"witness\",\"tan\\u0131k\"],[\"mystery\",\"gizem\"],[\"evidence\",\"kan\\u0131t\"],[\"footprint\",\"ayak izi\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"evidence\\\" ne demek?\",\"options\":[\"kan\\u0131t\",\"\\u015f\\u00fcpheli\",\"varsaymak\",\"kesinlikle\"],\"answer\":0,\"audio\":\"evidence\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
