(301,28,'Kelimeler','vocabulary','lesson',0,22,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"research\",\"ara\\u015ft\\u0131rma\"],[\"data\",\"veri\"],[\"experiment\",\"deney\"],[\"device\",\"cihaz\"],[\"invention\",\"icat\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"artificial intelligence\\\" ne demek?\",\"options\":[\"\\u00f6nemli, kayda de\\u011fer\",\"yapay zek\\u00e2\",\"yerini almak\",\"deney\"],\"answer\":1,\"audio\":\"artificial intelligence\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"It is believed to be safe\",\"options\":[\"It is believed to be safe\",\"It is believing to be safe\",\"It was believed to be safe\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Cihaz\\u0131n \\u00c7in\'de icat edildi\\u011fine inan\\u0131l\\u0131yor.\",\"answer\":\"It is believed that the device was invented in China\",\"alternatives\":[],\"tiles\":[\"artificial intelligence\",\"in\",\"is\",\"reliable\",\"the\",\"invented\",\"that\",\"device\",\"It\",\"was\",\"believed\",\"China\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"artificial intelligence\",\"yapay zek\\u00e2\"],[\"develop\",\"geli\\u015ftirmek\"],[\"replace\",\"yerini almak\"],[\"reliable\",\"g\\u00fcvenilir\"],[\"significant\",\"\\u00f6nemli, kayda de\\u011fer\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"g\\u00fcvenilir\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"data\",\"reliable\",\"replace\",\"device\"],\"answer\":1},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I need to have my laptop repaired.\",\"translation\":\"Diz\\u00fcst\\u00fc bilgisayar\\u0131m\\u0131 tamir ettirmem gerekiyor.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"The experiment must be repeated\",\"answer\":\"The experiment must be repeated\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(302,28,'Dilbilgisi','grammar','lesson',1,22,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"The data ___ before the report is published.\",\"options\":[\"must be checked\",\"must check\",\"must checked\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"It ___ that the virus spread from bats.\",\"options\":[\"is thought\",\"thinks\",\"is thinking\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"I\'m having my car ___ tomorrow.\",\"options\":[\"service\",\"serviced\",\"servicing\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"The city is said ___ over 3,000 years old.\",\"options\":[\"being\",\"to be\",\"be\"],\"answer\":1},{\"type\":\"translate\",\"prompt\":\"Telefonumu tamir ettirdim.\",\"answer\":\"I had my phone repaired\",\"alternatives\":[\"I got my phone repaired\",\"I\'ve had my phone repaired\"],\"tiles\":[\"repaired\",\"I\",\"made\",\"phone\",\"had\",\"repair\",\"my\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"I\'m\",\"having\",\"my\",\"car\",\"repair\",\"tomorrow\"],\"error_index\":4,\"options\":[\"repaired\",\"repairing\",\"to repair\"],\"answer\":0,\"explanation_tr\":\"\\\"Have something done\\\" kal\\u0131b\\u0131nda fiilin 3. h\\u00e2li kullan\\u0131l\\u0131r: I\'m having my car repaired tomorrow. (Arabay\\u0131 ben tamir etmiyorum, tamir ettiriyorum.)\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"The results were published in a scientific journal.\",\"translation\":\"Sonu\\u00e7lar bilimsel bir dergide yay\\u0131mland\\u0131.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(303,28,'Okuma: Machines That Learn','reading','lesson',2,22,0,NULL,NULL,'[{\"type\":\"read\",\"title\":\"Machines That Learn\",\"passage\":\"Artificial intelligence is being used in more areas than ever before. In hospitals, scans are now analysed by programs that have been trained on millions of images, and some studies suggest that their results are as reliable as those of experienced doctors. However, researchers warn that the data these systems are given can contain hidden biases. Many hospitals therefore have every decision checked by a human specialist. The aim, they argue, is not to replace doctors but to give them more time for patients.\",\"prompt\":\"What risk do researchers mention?\",\"options\":[\"Programs are too expensive.\",\"The data can contain hidden biases.\",\"Doctors refuse to use them.\",\"Scans are not accurate.\"],\"answer\":1},{\"type\":\"read\",\"title\":\"Machines That Learn\",\"passage\":\"Artificial intelligence is being used in more areas than ever before. In hospitals, scans are now analysed by programs that have been trained on millions of images, and some studies suggest that their results are as reliable as those of experienced doctors. However, researchers warn that the data these systems are given can contain hidden biases. Many hospitals therefore have every decision checked by a human specialist. The aim, they argue, is not to replace doctors but to give them more time for patients.\",\"prompt\":\"According to the text, what is the aim of AI in hospitals?\",\"options\":[\"To replace doctors\",\"To give doctors more time for patients\",\"To reduce the number of hospitals\",\"To train new doctors\"],\"answer\":1}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(304,28,'Kelime oyunu','vocabulary','words',3,22,0,NULL,NULL,'[]','{\"game\":\"swipe\",\"words\":[{\"word\":\"research\",\"translation\":\"ara\\u015ft\\u0131rma\"},{\"word\":\"data\",\"translation\":\"veri\",\"example\":\"The data must be checked before the report is published.\"},{\"word\":\"experiment\",\"translation\":\"deney\",\"example\":\"The experiment must be repeated\"},{\"word\":\"device\",\"translation\":\"cihaz\",\"example\":\"It is believed that the device was invented in China.\"},{\"word\":\"invention\",\"translation\":\"icat\"},{\"word\":\"artificial intelligence\",\"translation\":\"yapay zek\\u00e2\"},{\"word\":\"develop\",\"translation\":\"geli\\u015ftirmek\"},{\"word\":\"replace\",\"translation\":\"yerini almak\",\"example\":\"It is said that robots will replace many jobs.\"},{\"word\":\"reliable\",\"translation\":\"g\\u00fcvenilir\"},{\"word\":\"significant\",\"translation\":\"\\u00f6nemli, kayda de\\u011fer\"}]}','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(305,28,'Dilbilgisi pekiştir','grammar','lesson',4,22,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"The city is said ___ over 3,000 years old.\",\"options\":[\"being\",\"be\",\"to be\"],\"answer\":2},{\"type\":\"fill\",\"prompt\":\"I\'m having my car ___ tomorrow.\",\"options\":[\"servicing\",\"serviced\",\"service\"],\"answer\":1},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"I\'m\",\"having\",\"my\",\"car\",\"repair\",\"tomorrow\"],\"error_index\":4,\"options\":[\"repaired\",\"repairing\",\"to repair\"],\"answer\":0,\"explanation_tr\":\"\\\"Have something done\\\" kal\\u0131b\\u0131nda fiilin 3. h\\u00e2li kullan\\u0131l\\u0131r: I\'m having my car repaired tomorrow. (Arabay\\u0131 ben tamir etmiyorum, tamir ettiriyorum.)\"},{\"type\":\"translate\",\"prompt\":\"Bu cihaz\\u0131n 2030\'a kadar yayg\\u0131nla\\u015fmas\\u0131 bekleniyor.\",\"answer\":\"This device is expected to become common by 2030\",\"alternatives\":[\"This device is expected to be common by 2030\"],\"tiles\":[\"expected\",\"common\",\"expects\",\"to\",\"device\",\"This\",\"become\",\"2030\",\"by\",\"will\",\"is\"]},{\"type\":\"fill\",\"prompt\":\"It ___ that the virus spread from bats.\",\"options\":[\"is thought\",\"is thinking\",\"thinks\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"The data ___ before the report is published.\",\"options\":[\"must checked\",\"must check\",\"must be checked\"],\"answer\":2},{\"type\":\"translate\",\"prompt\":\"Telefonumu tamir ettirdim.\",\"answer\":\"I had my phone repaired\",\"alternatives\":[\"I got my phone repaired\",\"I\'ve had my phone repaired\"],\"tiles\":[\"repaired\",\"I\",\"made\",\"phone\",\"had\",\"repair\",\"my\"]},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I\'m getting my eyes tested next week.\",\"translation\":\"Gelecek hafta g\\u00f6zlerimi test ettirece\\u011fim.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(306,28,'Dinle ve konuş','listening','lesson',5,22,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Bir bilim fuar\\u0131nda projeni anlat\\u0131yorsun.\",\"lines\":[{\"who\":\"Judge\",\"text\":\"How was the data collected?\"}],\"options\":[\"The data was collected from 200 students and then analysed with a simple program.\",\"We collect data students and analyse.\",\"Data collecting by students.\"],\"answer\":0,\"note_tr\":\"Y\\u00f6ntem anlat\\u0131rken passive kullanmak bilimsel ve nesnel durur.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"I had my phone repaired\",\"options\":[\"I had my phone repaired\",\"I had my phone replaced\",\"I have my phone repaired\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"The results were published last year\",\"answer\":\"The results were published last year\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"It is said that robots will replace many jobs.\",\"translation\":\"Robotlar\\u0131n bir\\u00e7ok i\\u015fin yerini alaca\\u011f\\u0131 s\\u00f6yleniyor.\"},{\"type\":\"translate\",\"prompt\":\"Bu cihaz\\u0131n 2030\'a kadar yayg\\u0131nla\\u015fmas\\u0131 bekleniyor.\",\"answer\":\"This device is expected to become common by 2030\",\"alternatives\":[\"This device is expected to be common by 2030\"],\"tiles\":[\"expected\",\"common\",\"expects\",\"to\",\"device\",\"This\",\"become\",\"2030\",\"by\",\"will\",\"is\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"I need to have my car fixed\",\"answer\":\"I need to have my car fixed\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I\'m getting my eyes tested next week.\",\"translation\":\"Gelecek hafta g\\u00f6zlerimi test ettirece\\u011fim.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(307,28,'Kelime tekrarı','vocabulary','lesson',6,22,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"significant\",\"\\u00f6nemli, kayda de\\u011fer\"],[\"develop\",\"geli\\u015ftirmek\"],[\"replace\",\"yerini almak\"],[\"artificial intelligence\",\"yapay zek\\u00e2\"],[\"data\",\"veri\"]]},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"data\",\"options\":[\"invention\",\"develop\",\"data\",\"reliable\"],\"answer\":2},{\"type\":\"choice\",\"prompt\":\"\\\"experiment\\\" ne demek?\",\"options\":[\"\\u00f6nemli, kayda de\\u011fer\",\"geli\\u015ftirmek\",\"icat\",\"deney\"],\"answer\":3,\"audio\":\"experiment\"},{\"type\":\"choice\",\"prompt\":\"\\\"icat\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"significant\",\"replace\",\"device\",\"invention\"],\"answer\":3},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"develop\",\"options\":[\"develop\",\"data\",\"device\",\"significant\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"significant\",\"answer\":\"significant\"},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"develop\",\"geli\\u015ftirmek\"],[\"device\",\"cihaz\"],[\"invention\",\"icat\"],[\"reliable\",\"g\\u00fcvenilir\"],[\"artificial intelligence\",\"yapay zek\\u00e2\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"research\\\" ne demek?\",\"options\":[\"icat\",\"yerini almak\",\"ara\\u015ft\\u0131rma\",\"deney\"],\"answer\":2,\"audio\":\"research\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
