(312,29,'Kelimeler','vocabulary','lesson',0,22,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"climate change\",\"iklim de\\u011fi\\u015fikli\\u011fi\"],[\"pollution\",\"kirlilik\"],[\"renewable\",\"yenilenebilir\"],[\"recycle\",\"geri d\\u00f6n\\u00fc\\u015ft\\u00fcrmek\"],[\"waste\",\"at\\u0131k\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"drought\\\" ne demek?\",\"options\":[\"yenilenebilir\",\"kurakl\\u0131k\",\"sal\\u0131n\\u0131m\",\"azaltmak\"],\"answer\":1,\"audio\":\"drought\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"By 2030 we\'ll have reduced emissions\",\"options\":[\"By 2030 we\'ll have reduced emissions\",\"By 2030 we\'ll reduce emissions\",\"By 2030 we reduced emissions\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"2040\'a kadar bir\\u00e7ok \\u015fehir benzinli arabalar\\u0131 yasaklam\\u0131\\u015f olacak.\",\"answer\":\"By 2040, many cities will have banned petrol cars\",\"alternatives\":[],\"tiles\":[\"many\",\"By\",\"species\",\"petrol\",\"banned\",\"cars\",\"have\",\"reduce\",\"2040\",\"will\",\"cities\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"drought\",\"kurakl\\u0131k\"],[\"species\",\"t\\u00fcr\"],[\"emission\",\"sal\\u0131n\\u0131m\"],[\"sustainable\",\"s\\u00fcrd\\u00fcr\\u00fclebilir\"],[\"reduce\",\"azaltmak\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"s\\u00fcrd\\u00fcr\\u00fclebilir\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"sustainable\",\"recycle\",\"emission\",\"pollution\"],\"answer\":0},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"This time tomorrow, we\'ll be planting trees in the park.\",\"translation\":\"Yar\\u0131n bu saatte parkta a\\u011fa\\u00e7 dikiyor olaca\\u011f\\u0131z.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"We must reduce plastic waste\",\"answer\":\"We must reduce plastic waste\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(313,29,'Dilbilgisi','grammar','lesson',1,22,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"By 2030, the factory ___ its emissions by half.\",\"options\":[\"will have reduced\",\"will reduce\",\"reduces\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"At 10 am tomorrow, I ___ an exam.\",\"options\":[\"\'ll be taking\",\"\'ll have taken\",\"take\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"By the time you get here, the film ___.\",\"options\":[\"will have started\",\"will start\",\"starts\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"Solar energy is a ___ source of energy.\",\"options\":[\"renewable\",\"renewing\",\"renew\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"2050\'ye kadar d\\u00fcnya n\\u00fcfusu 10 milyara ula\\u015fm\\u0131\\u015f olacak.\",\"answer\":\"By 2050, the world population will have reached 10 billion\",\"alternatives\":[\"By 2050 the world population will have reached 10 billion\"],\"tiles\":[\"By\",\"reached\",\"billion\",\"will\",\"2050\",\"10\",\"have\",\"will reach\",\"population\",\"world\",\"until\",\"the\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"By\",\"next\",\"year\",\"we\",\"will\",\"finish\",\"the\",\"project\"],\"error_index\":5,\"options\":[\"have finished\",\"finished\",\"be finish\"],\"answer\":0,\"explanation_tr\":\"\\\"By next year\\\" gelecekte bir noktaya kadar tamamlanmay\\u0131 anlat\\u0131r; future perfect gerekir: we will have finished the project.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"We need to switch to renewable energy.\",\"translation\":\"Yenilenebilir enerjiye ge\\u00e7memiz gerekiyor.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(314,29,'Okuma: A Greener Future','reading','lesson',2,22,0,NULL,NULL,'[{\"type\":\"read\",\"title\":\"A Greener Future\",\"passage\":\"By 2040, experts predict, most new cars sold in Europe will be electric, and many cities will have reduced their emissions by half. Renewable energy is already cheaper than coal in several countries. Yet the challenge remains enormous. Droughts are becoming more frequent, and thousands of species are at risk. Recycling helps, but scientists stress that reducing waste in the first place matters more. A sustainable future, they say, depends on decisions we will be making in the next ten years.\",\"prompt\":\"What do scientists say matters more than recycling?\",\"options\":[\"Buying electric cars\",\"Reducing waste in the first place\",\"Using coal\",\"Planting trees\"],\"answer\":1},{\"type\":\"read\",\"title\":\"A Greener Future\",\"passage\":\"By 2040, experts predict, most new cars sold in Europe will be electric, and many cities will have reduced their emissions by half. Renewable energy is already cheaper than coal in several countries. Yet the challenge remains enormous. Droughts are becoming more frequent, and thousands of species are at risk. Recycling helps, but scientists stress that reducing waste in the first place matters more. A sustainable future, they say, depends on decisions we will be making in the next ten years.\",\"prompt\":\"Which statement is true?\",\"options\":[\"Renewable energy is always more expensive.\",\"Droughts are becoming less frequent.\",\"Renewable energy is cheaper than coal in some countries.\",\"Emissions have already fallen by half.\"],\"answer\":2}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(315,29,'Kelime oyunu','vocabulary','words',3,22,0,NULL,NULL,'[]','{\"game\":\"search\",\"words\":[{\"word\":\"climate change\",\"translation\":\"iklim de\\u011fi\\u015fikli\\u011fi\",\"example\":\"Recycling alone is not enough to stop climate change.\"},{\"word\":\"pollution\",\"translation\":\"kirlilik\"},{\"word\":\"renewable\",\"translation\":\"yenilenebilir\",\"example\":\"We need to switch to renewable energy.\"},{\"word\":\"recycle\",\"translation\":\"geri d\\u00f6n\\u00fc\\u015ft\\u00fcrmek\"},{\"word\":\"waste\",\"translation\":\"at\\u0131k\",\"example\":\"We must reduce plastic waste\"},{\"word\":\"drought\",\"translation\":\"kurakl\\u0131k\"},{\"word\":\"species\",\"translation\":\"t\\u00fcr\"},{\"word\":\"emission\",\"translation\":\"sal\\u0131n\\u0131m\"},{\"word\":\"sustainable\",\"translation\":\"s\\u00fcrd\\u00fcr\\u00fclebilir\"},{\"word\":\"reduce\",\"translation\":\"azaltmak\",\"example\":\"We must reduce plastic waste\"}]}','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(316,29,'Dilbilgisi pekiştir','grammar','lesson',4,22,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"Solar energy is a ___ source of energy.\",\"options\":[\"renew\",\"renewing\",\"renewable\"],\"answer\":2},{\"type\":\"fill\",\"prompt\":\"By the time you get here, the film ___.\",\"options\":[\"starts\",\"will start\",\"will have started\"],\"answer\":2},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"By\",\"next\",\"year\",\"we\",\"will\",\"finish\",\"the\",\"project\"],\"error_index\":5,\"options\":[\"have finished\",\"finished\",\"be finish\"],\"answer\":0,\"explanation_tr\":\"\\\"By next year\\\" gelecekte bir noktaya kadar tamamlanmay\\u0131 anlat\\u0131r; future perfect gerekir: we will have finished the project.\"},{\"type\":\"translate\",\"prompt\":\"Gelecek y\\u0131l bu zamanlar Kanada\'da \\u00e7al\\u0131\\u015f\\u0131yor olaca\\u011f\\u0131m.\",\"answer\":\"This time next year, I\'ll be working in Canada\",\"alternatives\":[\"This time next year I will be working in Canada\"],\"tiles\":[\"will work\",\"Canada\",\"am\",\"working\",\"be\",\"in\",\"I\'ll\",\"next\",\"year\",\"This\",\"time\"]},{\"type\":\"fill\",\"prompt\":\"At 10 am tomorrow, I ___ an exam.\",\"options\":[\"\'ll have taken\",\"\'ll be taking\",\"take\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"By 2030, the factory ___ its emissions by half.\",\"options\":[\"reduces\",\"will have reduced\",\"will reduce\"],\"answer\":1},{\"type\":\"translate\",\"prompt\":\"2050\'ye kadar d\\u00fcnya n\\u00fcfusu 10 milyara ula\\u015fm\\u0131\\u015f olacak.\",\"answer\":\"By 2050, the world population will have reached 10 billion\",\"alternatives\":[\"By 2050 the world population will have reached 10 billion\"],\"tiles\":[\"By\",\"reached\",\"billion\",\"will\",\"2050\",\"10\",\"have\",\"will reach\",\"population\",\"world\",\"until\",\"the\"]},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Recycling alone is not enough to stop climate change.\",\"translation\":\"\\u0130klim de\\u011fi\\u015fikli\\u011fini durdurmak i\\u00e7in tek ba\\u015f\\u0131na geri d\\u00f6n\\u00fc\\u015f\\u00fcm yeterli de\\u011fil.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(317,29,'Dinle ve konuş','listening','lesson',5,22,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Belediye toplant\\u0131s\\u0131nda bir \\u00f6neri sunuyorsun.\",\"lines\":[{\"who\":\"Mayor\",\"text\":\"What will your plan have achieved in five years?\"}],\"options\":[\"In five years, we will have planted 50,000 trees and reduced plastic waste by 30 percent.\",\"In five years we plant trees.\",\"We will planting trees five years.\"],\"answer\":0,\"note_tr\":\"Bir hedefin belli bir zamana kadar tamamlanaca\\u011f\\u0131n\\u0131 s\\u00f6ylerken future perfect kullan\\u0131l\\u0131r.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"I\'ll be working late tonight\",\"options\":[\"I\'ll be working late tonight\",\"I\'ll have worked late tonight\",\"I was working late tonight\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"We should reduce our waste\",\"answer\":\"We should reduce our waste\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"By 2030, we\'ll have cut our emissions in half.\",\"translation\":\"2030\'a kadar sal\\u0131n\\u0131mlar\\u0131m\\u0131z\\u0131 yar\\u0131ya indirmi\\u015f olaca\\u011f\\u0131z.\"},{\"type\":\"translate\",\"prompt\":\"Gelecek y\\u0131l bu zamanlar Kanada\'da \\u00e7al\\u0131\\u015f\\u0131yor olaca\\u011f\\u0131m.\",\"answer\":\"This time next year, I\'ll be working in Canada\",\"alternatives\":[\"This time next year I will be working in Canada\"],\"tiles\":[\"will work\",\"Canada\",\"am\",\"working\",\"be\",\"in\",\"I\'ll\",\"next\",\"year\",\"This\",\"time\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"By then we will have finished\",\"answer\":\"By then we will have finished\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Recycling alone is not enough to stop climate change.\",\"translation\":\"\\u0130klim de\\u011fi\\u015fikli\\u011fini durdurmak i\\u00e7in tek ba\\u015f\\u0131na geri d\\u00f6n\\u00fc\\u015f\\u00fcm yeterli de\\u011fil.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(318,29,'Kelime tekrarı','vocabulary','lesson',6,22,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"species\",\"t\\u00fcr\"],[\"climate change\",\"iklim de\\u011fi\\u015fikli\\u011fi\"],[\"reduce\",\"azaltmak\"],[\"emission\",\"sal\\u0131n\\u0131m\"],[\"renewable\",\"yenilenebilir\"]]},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"pollution\",\"options\":[\"waste\",\"species\",\"sustainable\",\"pollution\"],\"answer\":3},{\"type\":\"choice\",\"prompt\":\"\\\"renewable\\\" ne demek?\",\"options\":[\"azaltmak\",\"t\\u00fcr\",\"yenilenebilir\",\"at\\u0131k\"],\"answer\":2,\"audio\":\"renewable\"},{\"type\":\"choice\",\"prompt\":\"\\\"at\\u0131k\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"recycle\",\"waste\",\"emission\",\"reduce\"],\"answer\":1},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"species\",\"options\":[\"species\",\"pollution\",\"reduce\",\"recycle\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"reduce\",\"answer\":\"reduce\"},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"sustainable\",\"s\\u00fcrd\\u00fcr\\u00fclebilir\"],[\"reduce\",\"azaltmak\"],[\"pollution\",\"kirlilik\"],[\"drought\",\"kurakl\\u0131k\"],[\"waste\",\"at\\u0131k\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"climate change\\\" ne demek?\",\"options\":[\"sal\\u0131n\\u0131m\",\"iklim de\\u011fi\\u015fikli\\u011fi\",\"yenilenebilir\",\"at\\u0131k\"],\"answer\":1,\"audio\":\"climate change\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(319,29,'Telaffuz','speaking','lesson',7,22,0,NULL,NULL,'[{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"pollution\",\"translation\":\"kirlilik\"},{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"renewable\",\"translation\":\"yenilenebilir\"},{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"recycle\",\"translation\":\"geri d\\u00f6n\\u00fc\\u015ft\\u00fcrmek\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"By 2040, many cities will have banned petrol cars.\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"We need to switch to renewable energy.\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"By 2030, we\'ll have cut our emissions in half.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
