(321,29,'Pratik','vocabulary','lesson',9,22,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"recycle\",\"geri d\\u00f6n\\u00fc\\u015ft\\u00fcrmek\"],[\"emission\",\"sal\\u0131n\\u0131m\"],[\"renewable\",\"yenilenebilir\"],[\"sustainable\",\"s\\u00fcrd\\u00fcr\\u00fclebilir\"],[\"climate change\",\"iklim de\\u011fi\\u015fikli\\u011fi\"]]},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"pollution\",\"options\":[\"sustainable\",\"waste\",\"pollution\",\"species\"],\"answer\":2},{\"type\":\"choice\",\"prompt\":\"\\\"renewable\\\" ne demek?\",\"options\":[\"at\\u0131k\",\"yenilenebilir\",\"azaltmak\",\"t\\u00fcr\"],\"answer\":1,\"audio\":\"renewable\"},{\"type\":\"choice\",\"prompt\":\"\\\"at\\u0131k\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"emission\",\"reduce\",\"waste\",\"recycle\"],\"answer\":2},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"species\",\"options\":[\"recycle\",\"species\",\"reduce\",\"pollution\"],\"answer\":1},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"reduce\",\"answer\":\"reduce\"},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"reduce\",\"azaltmak\"],[\"renewable\",\"yenilenebilir\"],[\"species\",\"t\\u00fcr\"],[\"sustainable\",\"s\\u00fcrd\\u00fcr\\u00fclebilir\"],[\"drought\",\"kurakl\\u0131k\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"climate change\\\" ne demek?\",\"options\":[\"iklim de\\u011fi\\u015fikli\\u011fi\",\"sal\\u0131n\\u0131m\",\"at\\u0131k\",\"yenilenebilir\"],\"answer\":0,\"audio\":\"climate change\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
