(323,30,'Kelimeler','vocabulary','lesson',0,22,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"although\",\"-e ra\\u011fmen (c\\u00fcmle)\"],[\"despite\",\"-e ra\\u011fmen (isim)\"],[\"however\",\"ancak\"],[\"whereas\",\"oysa, -iken\"],[\"therefore\",\"bu nedenle\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"argue\\\" ne demek?\",\"options\":[\"bak\\u0131\\u015f a\\u00e7\\u0131s\\u0131\",\"\\u00fcstelik\",\"savunmak, tart\\u0131\\u015fmak\",\"ancak\"],\"answer\":2,\"audio\":\"argue\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"Despite the rain, we went out\",\"options\":[\"Despite the rain, we went out\",\"Despite of the rain, we went out\",\"Because of the rain, we went out\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"S\\u0131nav zor olmas\\u0131na ra\\u011fmen \\u00f6\\u011frencilerin \\u00e7o\\u011fu ge\\u00e7ti.\",\"answer\":\"Although the test was hard, most students passed\",\"alternatives\":[],\"tiles\":[\"test\",\"most\",\"passed\",\"students\",\"point of view\",\"was\",\"the\",\"although\",\"hard\",\"Although\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"argue\",\"savunmak, tart\\u0131\\u015fmak\"],[\"convince\",\"ikna etmek\"],[\"point of view\",\"bak\\u0131\\u015f a\\u00e7\\u0131s\\u0131\"],[\"evidence\",\"kan\\u0131t\"],[\"moreover\",\"\\u00fcstelik\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"kan\\u0131t\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"evidence\",\"point of view\",\"whereas\",\"despite\"],\"answer\":0},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Despite the rain, the concert continued.\",\"translation\":\"Ya\\u011fmura ra\\u011fmen konser devam etti.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"Some people love cities whereas others prefer villages\",\"answer\":\"Some people love cities whereas others prefer villages\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(324,30,'Dilbilgisi','grammar','lesson',1,22,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"___ the traffic, we arrived on time.\",\"options\":[\"Although\",\"Despite\",\"However\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"___ he studied hard, he failed the test.\",\"options\":[\"Although\",\"Despite\",\"Because of\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"The flat is small. ___, it is very bright.\",\"options\":[\"However\",\"Although\",\"Despite\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"My brother is quiet, ___ I talk all the time.\",\"options\":[\"whereas\",\"despite\",\"therefore\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Yorgun olmas\\u0131na ra\\u011fmen i\\u015fini bitirdi.\",\"answer\":\"Although she was tired, she finished her work\",\"alternatives\":[\"Despite being tired, she finished her work\",\"Even though she was tired, she finished her work\"],\"tiles\":[\"her\",\"finished\",\"despite\",\"she\",\"was\",\"she\",\"work\",\"Although\",\"tired\",\"but\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"Despite\",\"it\",\"was\",\"raining\",\"we\",\"played\",\"football\"],\"error_index\":0,\"options\":[\"Although\",\"However\",\"Because of\"],\"answer\":0,\"explanation_tr\":\"\\\"Despite\\\" arkas\\u0131ndan c\\u00fcmle almaz, isim ya da -ing al\\u0131r. C\\u00fcmle geliyorsa \\\"Although\\\" kullan: Although it was raining, we played football. (Ya da: Despite the rain\\u2026)\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"In my view, schools should start later.\",\"translation\":\"Bence okullar daha ge\\u00e7 ba\\u015flamal\\u0131.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(325,30,'Okuma: Should Homework Be Banned?','reading','lesson',2,22,0,NULL,NULL,'[{\"type\":\"read\",\"title\":\"Should Homework Be Banned?\",\"passage\":\"Some educators argue that homework should be banned in primary schools. Although it is meant to strengthen learning, research suggests that young children gain little from it. Moreover, long assignments can cause stress and leave less time for play, which is essential for development. Supporters, however, point out that homework teaches responsibility and helps parents follow their children\'s progress. Despite the disagreement, most experts agree on one point: whereas short, meaningful tasks can help, hours of repetitive work rarely do.\",\"prompt\":\"What do supporters say homework teaches?\",\"options\":[\"Creativity\",\"Responsibility\",\"Sports\",\"Music\"],\"answer\":1},{\"type\":\"read\",\"title\":\"Should Homework Be Banned?\",\"passage\":\"Some educators argue that homework should be banned in primary schools. Although it is meant to strengthen learning, research suggests that young children gain little from it. Moreover, long assignments can cause stress and leave less time for play, which is essential for development. Supporters, however, point out that homework teaches responsibility and helps parents follow their children\'s progress. Despite the disagreement, most experts agree on one point: whereas short, meaningful tasks can help, hours of repetitive work rarely do.\",\"prompt\":\"What do most experts agree on?\",\"options\":[\"Homework should be banned completely.\",\"Short, meaningful tasks can help.\",\"Children should do more homework.\",\"Play is not important.\"],\"answer\":1}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(326,30,'Kelime oyunu','vocabulary','words',3,22,0,NULL,NULL,'[]','{\"game\":\"truefalse\",\"words\":[{\"word\":\"although\",\"translation\":\"-e ra\\u011fmen (c\\u00fcmle)\",\"example\":\"Although the test was hard, most students passed.\"},{\"word\":\"despite\",\"translation\":\"-e ra\\u011fmen (isim)\",\"example\":\"Despite the rain, the concert continued.\"},{\"word\":\"however\",\"translation\":\"ancak\",\"example\":\"I see your point; however, I don\'t agree.\"},{\"word\":\"whereas\",\"translation\":\"oysa, -iken\",\"example\":\"Some people love cities whereas others prefer villages\"},{\"word\":\"therefore\",\"translation\":\"bu nedenle\"},{\"word\":\"argue\",\"translation\":\"savunmak, tart\\u0131\\u015fmak\"},{\"word\":\"convince\",\"translation\":\"ikna etmek\"},{\"word\":\"point of view\",\"translation\":\"bak\\u0131\\u015f a\\u00e7\\u0131s\\u0131\"},{\"word\":\"evidence\",\"translation\":\"kan\\u0131t\"},{\"word\":\"moreover\",\"translation\":\"\\u00fcstelik\"}]}','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(327,30,'Dilbilgisi pekiştir','grammar','lesson',4,22,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"My brother is quiet, ___ I talk all the time.\",\"options\":[\"whereas\",\"despite\",\"therefore\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"The flat is small. ___, it is very bright.\",\"options\":[\"Despite\",\"Although\",\"However\"],\"answer\":2},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"Despite\",\"it\",\"was\",\"raining\",\"we\",\"played\",\"football\"],\"error_index\":0,\"options\":[\"Although\",\"However\",\"Because of\"],\"answer\":0,\"explanation_tr\":\"\\\"Despite\\\" arkas\\u0131ndan c\\u00fcmle almaz, isim ya da -ing al\\u0131r. C\\u00fcmle geliyorsa \\\"Although\\\" kullan: Although it was raining, we played football. (Ya da: Despite the rain\\u2026)\"},{\"type\":\"translate\",\"prompt\":\"K\\u00f6t\\u00fc hava nedeniyle u\\u00e7u\\u015f iptal edildi.\",\"answer\":\"The flight was cancelled due to bad weather\",\"alternatives\":[\"The flight was cancelled because of bad weather\",\"The flight was cancelled because of the bad weather\"],\"tiles\":[\"The\",\"cancelled\",\"for\",\"weather\",\"was\",\"to\",\"because\",\"due\",\"flight\",\"bad\"]},{\"type\":\"fill\",\"prompt\":\"___ he studied hard, he failed the test.\",\"options\":[\"Although\",\"Because of\",\"Despite\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"___ the traffic, we arrived on time.\",\"options\":[\"Although\",\"However\",\"Despite\"],\"answer\":2},{\"type\":\"translate\",\"prompt\":\"Yorgun olmas\\u0131na ra\\u011fmen i\\u015fini bitirdi.\",\"answer\":\"Although she was tired, she finished her work\",\"alternatives\":[\"Despite being tired, she finished her work\",\"Even though she was tired, she finished her work\"],\"tiles\":[\"her\",\"finished\",\"despite\",\"she\",\"was\",\"she\",\"work\",\"Although\",\"tired\",\"but\"]},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I see your point; however, I don\'t agree.\",\"translation\":\"Ne demek istedi\\u011fini anl\\u0131yorum, ancak kat\\u0131lm\\u0131yorum.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(328,30,'Dinle ve konuş','listening','lesson',5,22,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"M\\u00fcnazarada rakibin bir arg\\u00fcman sundu.\",\"lines\":[{\"who\":\"Opponent\",\"text\":\"Homework is useless. Students learn everything in class.\"}],\"options\":[\"I see your point. However, research shows that regular practice at home improves long-term memory.\",\"No, you are wrong totally.\",\"Although homework, it is useful despite.\"],\"answer\":0,\"note_tr\":\"\\u00d6nce kar\\u015f\\u0131 g\\u00f6r\\u00fc\\u015f\\u00fc kabul et (I see your point), sonra however ile kendi kan\\u0131t\\u0131n\\u0131 sun.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"Although it was late, she called\",\"options\":[\"Although it was late, she called\",\"Already it was late, she called\",\"Although it was late, she cold\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"However I do not agree\",\"answer\":\"However I do not agree\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"It could be argued that social media connects people.\",\"translation\":\"Sosyal medyan\\u0131n insanlar\\u0131 bir araya getirdi\\u011fi savunulabilir.\"},{\"type\":\"translate\",\"prompt\":\"K\\u00f6t\\u00fc hava nedeniyle u\\u00e7u\\u015f iptal edildi.\",\"answer\":\"The flight was cancelled due to bad weather\",\"alternatives\":[\"The flight was cancelled because of bad weather\",\"The flight was cancelled because of the bad weather\"],\"tiles\":[\"The\",\"cancelled\",\"for\",\"weather\",\"was\",\"to\",\"because\",\"due\",\"flight\",\"bad\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"Despite the traffic we arrived on time\",\"answer\":\"Despite the traffic we arrived on time\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I see your point; however, I don\'t agree.\",\"translation\":\"Ne demek istedi\\u011fini anl\\u0131yorum, ancak kat\\u0131lm\\u0131yorum.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(329,30,'Kelime tekrarı','vocabulary','lesson',6,22,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"evidence\",\"kan\\u0131t\"],[\"moreover\",\"\\u00fcstelik\"],[\"despite\",\"-e ra\\u011fmen (isim)\"],[\"although\",\"-e ra\\u011fmen (c\\u00fcmle)\"],[\"convince\",\"ikna etmek\"]]},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"despite\",\"options\":[\"despite\",\"evidence\",\"convince\",\"therefore\"],\"answer\":0},{\"type\":\"choice\",\"prompt\":\"\\\"however\\\" ne demek?\",\"options\":[\"\\u00fcstelik\",\"ancak\",\"ikna etmek\",\"bu nedenle\"],\"answer\":1,\"audio\":\"however\"},{\"type\":\"choice\",\"prompt\":\"\\\"bu nedenle\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"therefore\",\"whereas\",\"point of view\",\"moreover\"],\"answer\":0},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"convince\",\"options\":[\"whereas\",\"despite\",\"convince\",\"moreover\"],\"answer\":2},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"moreover\",\"answer\":\"moreover\"},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"whereas\",\"oysa, -iken\"],[\"convince\",\"ikna etmek\"],[\"despite\",\"-e ra\\u011fmen (isim)\"],[\"argue\",\"savunmak, tart\\u0131\\u015fmak\"],[\"however\",\"ancak\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"although\\\" ne demek?\",\"options\":[\"bu nedenle\",\"bak\\u0131\\u015f a\\u00e7\\u0131s\\u0131\",\"-e ra\\u011fmen (c\\u00fcmle)\",\"ancak\"],\"answer\":2,\"audio\":\"although\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(330,30,'Telaffuz','speaking','lesson',7,22,0,NULL,NULL,'[{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"although\",\"translation\":\"-e ra\\u011fmen (c\\u00fcmle)\"},{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"despite\",\"translation\":\"-e ra\\u011fmen (isim)\"},{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"however\",\"translation\":\"ancak\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"Although the test was hard, most students passed.\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"In my view, schools should start later.\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"It could be argued that social media connects people.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
