(345,32,'Kelimeler','vocabulary','lesson',0,22,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"significant\",\"\\u00f6nemli, anlaml\\u0131\"],[\"consequently\",\"sonu\\u00e7 olarak\"],[\"furthermore\",\"ayr\\u0131ca\"],[\"nevertheless\",\"yine de\"],[\"indicate\",\"g\\u00f6stermek, i\\u015faret etmek\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"approximately\\\" ne demek?\",\"options\":[\"de\\u011ferlendirmek\",\"yakla\\u015f\\u0131k olarak\",\"ayr\\u0131ca\",\"azalmak, d\\u00fc\\u015f\\u00fc\\u015f\"],\"answer\":1,\"audio\":\"approximately\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"The results indicate a significant decline\",\"options\":[\"The results indicate a significant decline\",\"The results indicate a significant design\",\"The result indicates a slight decline\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Sonu\\u00e7lar okuma al\\u0131\\u015fkanl\\u0131klar\\u0131nda \\u00f6nemli bir d\\u00fc\\u015f\\u00fc\\u015fe i\\u015faret ediyor.\",\"answer\":\"The results indicate a significant decline in reading habits\",\"alternatives\":[],\"tiles\":[\"habits\",\"significant\",\"reading\",\"decline\",\"indicate\",\"The\",\"furthermore\",\"a\",\"results\",\"assess\",\"in\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"approximately\",\"yakla\\u015f\\u0131k olarak\"],[\"crucial\",\"\\u00e7ok \\u00f6nemli\"],[\"decline\",\"azalmak, d\\u00fc\\u015f\\u00fc\\u015f\"],[\"enhance\",\"art\\u0131rmak, geli\\u015ftirmek\"],[\"assess\",\"de\\u011ferlendirmek\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"art\\u0131rmak, geli\\u015ftirmek\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"decline\",\"nevertheless\",\"consequently\",\"enhance\"],\"answer\":3},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Consequently, further research is needed.\",\"translation\":\"Sonu\\u00e7 olarak daha fazla ara\\u015ft\\u0131rmaya ihtiya\\u00e7 var.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"Approximately half of the participants agreed\",\"answer\":\"Approximately half of the participants agreed\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(346,32,'Dilbilgisi','grammar','lesson',1,22,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"The study was small; ___, its results are important.\",\"options\":[\"nevertheless\",\"consequently\",\"for instance\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"Many species, ___ the Anatolian leopard, are now extinct.\",\"options\":[\"such as\",\"whereas\",\"therefore\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"Sleep is ___ for memory and learning.\",\"options\":[\"crucial\",\"approximately\",\"decline\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"The prices rose sharply. ___, sales fell.\",\"options\":[\"Consequently\",\"Moreover\",\"For example\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Bulgular, d\\u00fczenli egzersizin haf\\u0131zay\\u0131 g\\u00fc\\u00e7lendirdi\\u011fini g\\u00f6steriyor.\",\"answer\":\"The findings indicate that regular exercise improves memory\",\"alternatives\":[\"The findings show that regular exercise improves memory\",\"The findings indicate that regular exercise enhances memory\"],\"tiles\":[\"regular\",\"shows\",\"improves\",\"indicate\",\"The\",\"memory\",\"strong\",\"exercise\",\"findings\",\"that\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"The\",\"research\",\"shows\",\"that\",\"sleep\",\"effects\",\"memory\"],\"error_index\":5,\"options\":[\"affects\",\"affect\",\"effect\"],\"answer\":0,\"explanation_tr\":\"\\\"Effect\\\" isimdir (etki), \\\"affect\\\" fiildir (etkilemek). Burada fiil gerekiyor: sleep affects memory.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"The data suggests that the number of readers is declining.\",\"translation\":\"Veriler okur say\\u0131s\\u0131n\\u0131n azald\\u0131\\u011f\\u0131n\\u0131 g\\u00f6steriyor.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(347,32,'Okuma: Sleep and Memory','reading','lesson',2,22,0,NULL,NULL,'[{\"type\":\"read\",\"title\":\"Sleep and Memory\",\"passage\":\"A growing body of research indicates that sleep plays a crucial role in learning. In one study, approximately 200 students were asked to memorise a list of words. Those who slept for eight hours performed significantly better the following day than those who stayed awake. Furthermore, the benefit was greatest for difficult material. Nevertheless, the researchers caution that the sample consisted only of university students; consequently, the findings may not apply to other age groups. Further studies are needed to assess these effects more widely.\",\"prompt\":\"What did the study find?\",\"options\":[\"Sleep has no effect on memory.\",\"Students who slept performed better.\",\"Staying awake improves memory.\",\"Only easy material is remembered.\"],\"answer\":1},{\"type\":\"read\",\"title\":\"Sleep and Memory\",\"passage\":\"A growing body of research indicates that sleep plays a crucial role in learning. In one study, approximately 200 students were asked to memorise a list of words. Those who slept for eight hours performed significantly better the following day than those who stayed awake. Furthermore, the benefit was greatest for difficult material. Nevertheless, the researchers caution that the sample consisted only of university students; consequently, the findings may not apply to other age groups. Further studies are needed to assess these effects more widely.\",\"prompt\":\"Why are the researchers cautious?\",\"options\":[\"The study was too long.\",\"The sample included only university students.\",\"The words were too easy.\",\"The results were lost.\"],\"answer\":1},{\"type\":\"read\",\"title\":\"Sleep and Memory\",\"passage\":\"A growing body of research indicates that sleep plays a crucial role in learning. In one study, approximately 200 students were asked to memorise a list of words. Those who slept for eight hours performed significantly better the following day than those who stayed awake. Furthermore, the benefit was greatest for difficult material. Nevertheless, the researchers caution that the sample consisted only of university students; consequently, the findings may not apply to other age groups. Further studies are needed to assess these effects more widely.\",\"prompt\":\"In this text, \'crucial\' is closest in meaning to ...\",\"options\":[\"minor\",\"essential\",\"harmful\",\"surprising\"],\"answer\":1}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(348,32,'Kelime oyunu','vocabulary','words',3,22,0,NULL,NULL,'[]','{\"game\":\"cloze\",\"words\":[{\"word\":\"significant\",\"translation\":\"\\u00f6nemli, anlaml\\u0131\",\"example\":\"The results indicate a significant decline in reading habits.\"},{\"word\":\"consequently\",\"translation\":\"sonu\\u00e7 olarak\",\"example\":\"Consequently, further research is needed.\"},{\"word\":\"furthermore\",\"translation\":\"ayr\\u0131ca\",\"example\":\"Furthermore, the cost of the project was underestimated.\"},{\"word\":\"nevertheless\",\"translation\":\"yine de\",\"example\":\"The study was small; nevertheless, its results are important.\"},{\"word\":\"indicate\",\"translation\":\"g\\u00f6stermek, i\\u015faret etmek\",\"example\":\"The results indicate a significant decline in reading habits.\"},{\"word\":\"approximately\",\"translation\":\"yakla\\u015f\\u0131k olarak\",\"example\":\"Approximately half of the participants agreed\"},{\"word\":\"crucial\",\"translation\":\"\\u00e7ok \\u00f6nemli\",\"example\":\"It is crucial to assess the long-term effects.\"},{\"word\":\"decline\",\"translation\":\"azalmak, d\\u00fc\\u015f\\u00fc\\u015f\",\"example\":\"The results indicate a significant decline in reading habits.\"},{\"word\":\"enhance\",\"translation\":\"art\\u0131rmak, geli\\u015ftirmek\"},{\"word\":\"assess\",\"translation\":\"de\\u011ferlendirmek\",\"example\":\"It is crucial to assess the long-term effects.\"}]}','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(349,32,'Dilbilgisi pekiştir','grammar','lesson',4,22,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"The prices rose sharply. ___, sales fell.\",\"options\":[\"For example\",\"Consequently\",\"Moreover\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"Sleep is ___ for memory and learning.\",\"options\":[\"decline\",\"crucial\",\"approximately\"],\"answer\":1},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"The\",\"research\",\"shows\",\"that\",\"sleep\",\"effects\",\"memory\"],\"error_index\":5,\"options\":[\"affects\",\"affect\",\"effect\"],\"answer\":0,\"explanation_tr\":\"\\\"Effect\\\" isimdir (etki), \\\"affect\\\" fiildir (etkilemek). Burada fiil gerekiyor: sleep affects memory.\"},{\"type\":\"translate\",\"prompt\":\"Kat\\u0131l\\u0131mc\\u0131lar\\u0131n yakla\\u015f\\u0131k y\\u00fczde altm\\u0131\\u015f\\u0131 soruyu yan\\u0131tlad\\u0131.\",\"answer\":\"Approximately sixty percent of the participants answered the question\",\"alternatives\":[\"About sixty percent of the participants answered the question\",\"Approximately 60 percent of the participants answered the question\"],\"tiles\":[\"of\",\"answered\",\"Approximately\",\"sixty\",\"participants\",\"the\",\"persons\",\"the\",\"question\",\"percent\",\"about\"]},{\"type\":\"fill\",\"prompt\":\"Many species, ___ the Anatolian leopard, are now extinct.\",\"options\":[\"therefore\",\"such as\",\"whereas\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"The study was small; ___, its results are important.\",\"options\":[\"consequently\",\"for instance\",\"nevertheless\"],\"answer\":2},{\"type\":\"translate\",\"prompt\":\"Bulgular, d\\u00fczenli egzersizin haf\\u0131zay\\u0131 g\\u00fc\\u00e7lendirdi\\u011fini g\\u00f6steriyor.\",\"answer\":\"The findings indicate that regular exercise improves memory\",\"alternatives\":[\"The findings show that regular exercise improves memory\",\"The findings indicate that regular exercise enhances memory\"],\"tiles\":[\"regular\",\"shows\",\"improves\",\"indicate\",\"The\",\"memory\",\"strong\",\"exercise\",\"findings\",\"that\"]},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"It is crucial to assess the long-term effects.\",\"translation\":\"Uzun vadeli etkileri de\\u011ferlendirmek \\u00e7ok \\u00f6nemli.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(350,32,'Dinle ve konuş','listening','lesson',5,22,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Bir paragraf tamamlama sorusundas\\u0131n. Bo\\u015flu\\u011fa en uygun c\\u00fcmleyi se\\u00e7.\",\"lines\":[{\"who\":\"Paragraf\",\"text\":\"Bilingual children often switch between languages with ease. ___ For instance, they can focus on a task while ignoring distractions more effectively than monolingual children.\"}],\"options\":[\"Research suggests that this ability may also improve their attention skills.\",\"Many adults find learning languages difficult.\",\"However, bilingual children are rare in Turkey.\"],\"answer\":0,\"note_tr\":\"Bo\\u015fluktan sonra \\\"For instance\\\" ile bir \\u00f6rnek geliyor; bo\\u015fluk bu \\u00f6rne\\u011fin destekledi\\u011fi genel iddiay\\u0131 i\\u00e7ermeli: dikkat becerileri.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"Consequently, further research is needed\",\"options\":[\"Consequently, further research is needed\",\"Consequently, further research isn\'t needed\",\"Conversely, further research is needed\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"Further research is needed\",\"answer\":\"Further research is needed\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Furthermore, the cost of the project was underestimated.\",\"translation\":\"Ayr\\u0131ca projenin maliyeti oldu\\u011fundan d\\u00fc\\u015f\\u00fck tahmin edildi.\"},{\"type\":\"translate\",\"prompt\":\"Kat\\u0131l\\u0131mc\\u0131lar\\u0131n yakla\\u015f\\u0131k y\\u00fczde altm\\u0131\\u015f\\u0131 soruyu yan\\u0131tlad\\u0131.\",\"answer\":\"Approximately sixty percent of the participants answered the question\",\"alternatives\":[\"About sixty percent of the participants answered the question\",\"Approximately 60 percent of the participants answered the question\"],\"tiles\":[\"of\",\"answered\",\"Approximately\",\"sixty\",\"participants\",\"the\",\"persons\",\"the\",\"question\",\"percent\",\"about\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"The findings were significant\",\"answer\":\"The findings were significant\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"It is crucial to assess the long-term effects.\",\"translation\":\"Uzun vadeli etkileri de\\u011ferlendirmek \\u00e7ok \\u00f6nemli.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(351,32,'Kelime tekrarı','vocabulary','lesson',6,22,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"approximately\",\"yakla\\u015f\\u0131k olarak\"],[\"nevertheless\",\"yine de\"],[\"consequently\",\"sonu\\u00e7 olarak\"],[\"significant\",\"\\u00f6nemli, anlaml\\u0131\"],[\"indicate\",\"g\\u00f6stermek, i\\u015faret etmek\"]]},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"consequently\",\"options\":[\"enhance\",\"consequently\",\"indicate\",\"crucial\"],\"answer\":1},{\"type\":\"choice\",\"prompt\":\"\\\"furthermore\\\" ne demek?\",\"options\":[\"g\\u00f6stermek, i\\u015faret etmek\",\"ayr\\u0131ca\",\"de\\u011ferlendirmek\",\"\\u00e7ok \\u00f6nemli\"],\"answer\":1,\"audio\":\"furthermore\"},{\"type\":\"choice\",\"prompt\":\"\\\"g\\u00f6stermek, i\\u015faret etmek\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"decline\",\"indicate\",\"assess\",\"nevertheless\"],\"answer\":1},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"crucial\",\"options\":[\"assess\",\"crucial\",\"consequently\",\"nevertheless\"],\"answer\":1},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"assess\",\"answer\":\"assess\"},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"decline\",\"azalmak, d\\u00fc\\u015f\\u00fc\\u015f\"],[\"furthermore\",\"ayr\\u0131ca\"],[\"assess\",\"de\\u011ferlendirmek\"],[\"approximately\",\"yakla\\u015f\\u0131k olarak\"],[\"crucial\",\"\\u00e7ok \\u00f6nemli\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"significant\\\" ne demek?\",\"options\":[\"g\\u00f6stermek, i\\u015faret etmek\",\"\\u00f6nemli, anlaml\\u0131\",\"ayr\\u0131ca\",\"azalmak, d\\u00fc\\u015f\\u00fc\\u015f\"],\"answer\":1,\"audio\":\"significant\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(352,32,'Telaffuz','speaking','lesson',7,22,0,NULL,NULL,'[{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"significant\",\"translation\":\"\\u00f6nemli, anlaml\\u0131\"},{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"consequently\",\"translation\":\"sonu\\u00e7 olarak\"},{\"type\":\"pronounce\",\"prompt\":\"Kelimeyi s\\u00f6yle\",\"text\":\"furthermore\",\"translation\":\"ayr\\u0131ca\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"The results indicate a significant decline in reading habits.\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"The data suggests that the number of readers is declining.\"},{\"type\":\"pronounce\",\"prompt\":\"C\\u00fcmleyi s\\u00f6yle\",\"text\":\"Furthermore, the cost of the project was underestimated.\"}]',NULL,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
