LOCK TABLES `stories` WRITE;
/*!40000 ALTER TABLE `stories` DISABLE KEYS */;
INSERT INTO `stories` (`id`, `slug`, `title`, `title_tr`, `summary`, `cefr_level`, `category`, `cover_image`, `audio_url`, `reading_minutes`, `word_count`, `paragraphs`, `vocabulary`, `questions`, `is_premium`, `is_published`, `reads_count`, `published_at`, `created_at`, `updated_at`) VALUES (1,'the-red-umbrella','The Red Umbrella','Kırmızı Şemsiye','Every morning Ali sees a woman with a red umbrella at the bus stop. One rainy day, everything changes.','A1','Günlük Hayat','/img/stories/the-red-umbrella.webp',NULL,3,117,'[{\"en\":\"Ali is twenty-five years old. He lives in a small flat in Ankara. Every morning, he takes the bus to work at eight o\'clock.\",\"tr\":\"Ali yirmi be\\u015f ya\\u015f\\u0131nda. Ankara\'da k\\u00fc\\u00e7\\u00fck bir dairede ya\\u015f\\u0131yor. Her sabah saat sekizde i\\u015fe otob\\u00fcsle gidiyor.\"},{\"en\":\"At the bus stop, there is always a woman with a red umbrella. It is sunny, but she has her umbrella. Ali thinks this is strange.\",\"tr\":\"Otob\\u00fcs dura\\u011f\\u0131nda her zaman k\\u0131rm\\u0131z\\u0131 \\u015femsiyeli bir kad\\u0131n var. Hava g\\u00fcne\\u015fli ama \\u015femsiyesi yan\\u0131nda. Ali bunun tuhaf oldu\\u011funu d\\u00fc\\u015f\\u00fcn\\u00fcyor.\"},{\"en\":\"One Monday, it rains a lot. Ali doesn\'t have an umbrella. He is wet and cold. The woman smiles and says, \\\"Come here. My umbrella is big.\\\"\",\"tr\":\"Bir pazartesi \\u00e7ok ya\\u011fmur ya\\u011f\\u0131yor. Ali\'nin \\u015femsiyesi yok. Islak ve \\u00fc\\u015f\\u00fcm\\u00fc\\u015f. Kad\\u0131n g\\u00fcl\\u00fcms\\u00fcyor ve \\\"Buraya gel. \\u015eemsiyem b\\u00fcy\\u00fck.\\\" diyor.\"},{\"en\":\"Her name is Elif. She is a teacher. \\\"I always carry my umbrella,\\\" she says. \\\"Because one day, somebody needs it.\\\"\",\"tr\":\"Ad\\u0131 Elif. \\u00d6\\u011fretmen. \\\"\\u015eemsiyemi her zaman ta\\u015f\\u0131r\\u0131m,\\\" diyor. \\\"\\u00c7\\u00fcnk\\u00fc bir g\\u00fcn birinin ona ihtiyac\\u0131 olur.\\\"\"},{\"en\":\"Now Ali has a red umbrella too. And every morning, he says \\\"Good morning, Elif!\\\" at the bus stop.\",\"tr\":\"Art\\u0131k Ali\'nin de k\\u0131rm\\u0131z\\u0131 bir \\u015femsiyesi var. Ve her sabah otob\\u00fcs dura\\u011f\\u0131nda \\\"G\\u00fcnayd\\u0131n Elif!\\\" diyor.\"}]','[{\"word\":\"umbrella\",\"meaning\":\"\\u015femsiye\",\"example\":\"Take an umbrella, it\'s raining.\"},{\"word\":\"bus stop\",\"meaning\":\"otob\\u00fcs dura\\u011f\\u0131\",\"example\":\"I wait at the bus stop.\"},{\"word\":\"strange\",\"meaning\":\"tuhaf, garip\",\"example\":\"That is a strange sound.\"},{\"word\":\"wet\",\"meaning\":\"\\u0131slak\",\"example\":\"My shoes are wet.\"},{\"word\":\"carry\",\"meaning\":\"ta\\u015f\\u0131mak\",\"example\":\"She carries a big bag.\"}]','[{\"q\":\"Where does Ali live?\",\"options\":[\"Istanbul\",\"Ankara\",\"Izmir\"],\"answer\":1},{\"q\":\"What is Elif\'s job?\",\"options\":[\"Doctor\",\"Driver\",\"Teacher\"],\"answer\":2},{\"q\":\"Why does Elif always carry her umbrella?\",\"options\":[\"Because it\'s her favourite colour\",\"Because one day somebody needs it\",\"Because it always rains\"],\"answer\":1}]',0,1,0,'2026-09-20 20:30:40','2026-10-04 20:30:40','2026-10-04 20:30:40'),
(2,'mias-first-day-in-london','Mia\'s First Day in London','Mia\'nın Londra\'daki İlk Günü','Mia arrives in London for a language course. She gets lost, and finds something better.','A1','Seyahat','/img/stories/mias-first-day-in-london.webp',NULL,4,127,'[{\"en\":\"Mia is from Bursa. Today is her first day in London. She has a map, a small bag and a lot of questions.\",\"tr\":\"Mia Bursal\\u0131. Bug\\u00fcn Londra\'daki ilk g\\u00fcn\\u00fc. Bir haritas\\u0131, k\\u00fc\\u00e7\\u00fck bir \\u00e7antas\\u0131 ve bir s\\u00fcr\\u00fc sorusu var.\"},{\"en\":\"Her language school is near a big park. She takes the underground, but she gets off at the wrong station.\",\"tr\":\"Dil okulu b\\u00fcy\\u00fck bir park\\u0131n yak\\u0131n\\u0131nda. Metroya biniyor ama yanl\\u0131\\u015f istasyonda iniyor.\"},{\"en\":\"\\\"Excuse me,\\\" she says to an old man. \\\"How can I get to Hyde Park?\\\" The man smiles. \\\"Turn left, go straight, and it\'s on your right. About ten minutes.\\\"\",\"tr\":\"\\\"Affedersiniz,\\\" diyor ya\\u015fl\\u0131 bir adama. \\\"Hyde Park\'a nas\\u0131l gidebilirim?\\\" Adam g\\u00fcl\\u00fcms\\u00fcyor. \\\"Sola d\\u00f6n, d\\u00fcz git, sa\\u011f\\u0131nda. Yakla\\u015f\\u0131k on dakika.\\\"\"},{\"en\":\"On the way, Mia sees a small caf\\u00e9. It smells of coffee and fresh bread. She is hungry, so she goes in and orders a sandwich and a tea.\",\"tr\":\"Yolda Mia k\\u00fc\\u00e7\\u00fck bir kafe g\\u00f6r\\u00fcyor. Kahve ve taze ekmek kokuyor. A\\u00e7 oldu\\u011fu i\\u00e7in i\\u00e7eri giriyor ve bir sandvi\\u00e7 ile bir \\u00e7ay sipari\\u015f ediyor.\"},{\"en\":\"The waiter is a student from her school! They walk to the park together. Mia is late for class, but she has a new friend.\",\"tr\":\"Garson onun okulundan bir \\u00f6\\u011frenci! Parka birlikte y\\u00fcr\\u00fcyorlar. Mia derse ge\\u00e7 kal\\u0131yor ama yeni bir arkada\\u015f\\u0131 var.\"}]','[{\"word\":\"underground\",\"meaning\":\"metro (\\u0130ngiltere)\",\"example\":\"I take the underground to work.\"},{\"word\":\"get off\",\"meaning\":\"(ara\\u00e7tan) inmek\",\"example\":\"Get off at the next stop.\"},{\"word\":\"straight\",\"meaning\":\"d\\u00fcz, dosdo\\u011fru\",\"example\":\"Go straight for two minutes.\"},{\"word\":\"hungry\",\"meaning\":\"a\\u00e7\",\"example\":\"I\'m hungry. Let\'s eat.\"},{\"word\":\"order\",\"meaning\":\"sipari\\u015f etmek\",\"example\":\"Can I order a coffee, please?\"}]','[{\"q\":\"Where is Mia from?\",\"options\":[\"Bursa\",\"London\",\"Antalya\"],\"answer\":0},{\"q\":\"What does Mia order?\",\"options\":[\"Coffee and cake\",\"A sandwich and a tea\",\"Soup\"],\"answer\":1},{\"q\":\"Who is the waiter?\",\"options\":[\"Her teacher\",\"A student from her school\",\"The old man\"],\"answer\":1}]',0,1,0,'2026-09-21 20:30:40','2026-10-04 20:30:40','2026-10-04 20:30:40'),
(3,'the-cat-who-loved-tea','The Cat Who Loved Tea','Çayı Seven Kedi','Grandma Nermin\'s cat has a very unusual habit, and it makes the whole neighbourhood famous.','A2','Eğlence','/img/stories/the-cat-who-loved-tea.webp',NULL,4,138,'[{\"en\":\"Grandma Nermin lived in an old house by the sea in Ayval\\u0131k. She had a grey cat called Pamuk, and every afternoon at five o\'clock she made a pot of black tea.\",\"tr\":\"Nermin Nine, Ayval\\u0131k\'ta denize yak\\u0131n eski bir evde ya\\u015f\\u0131yordu. Pamuk ad\\u0131nda gri bir kedisi vard\\u0131 ve her \\u00f6\\u011fleden sonra saat be\\u015fte bir demlik siyah \\u00e7ay yapard\\u0131.\"},{\"en\":\"One day, while she was reading the newspaper, she heard a strange noise. Pamuk was sitting on the table and drinking from her glass!\",\"tr\":\"Bir g\\u00fcn gazete okurken tuhaf bir ses duydu. Pamuk masan\\u0131n \\u00fcst\\u00fcnde oturmu\\u015f, onun barda\\u011f\\u0131ndan i\\u00e7iyordu!\"},{\"en\":\"At first she was worried, so she called the vet. \\\"A little cold tea won\'t hurt him,\\\" the vet laughed, \\\"but don\'t give him sugar.\\\"\",\"tr\":\"\\u0130lk ba\\u015fta endi\\u015felendi ve veterineri arad\\u0131. \\\"Biraz so\\u011fuk \\u00e7ay ona zarar vermez,\\\" dedi veteriner g\\u00fclerek, \\\"ama \\u015feker vermeyin.\\\"\"},{\"en\":\"Soon, the neighbours heard the story. Children came to watch Pamuk\'s tea time, and a tourist posted a video online. It got two million views in a week.\",\"tr\":\"\\u00c7ok ge\\u00e7meden kom\\u015fular hik\\u00e2yeyi duydu. \\u00c7ocuklar Pamuk\'un \\u00e7ay saatini izlemeye geldi ve bir turist internette bir video payla\\u015ft\\u0131. Video bir haftada iki milyon izlendi.\"},{\"en\":\"Now there is a small sign on Grandma Nermin\'s door: \\\"Tea time at five. Cats welcome.\\\" She says she has never had so many visitors in her life.\",\"tr\":\"Art\\u0131k Nermin Nine\'nin kap\\u0131s\\u0131nda k\\u00fc\\u00e7\\u00fck bir tabela var: \\\"\\u00c7ay saati be\\u015fte. Kediler ho\\u015f gelir.\\\" Hayat\\u0131nda hi\\u00e7 bu kadar \\u00e7ok misafiri olmad\\u0131\\u011f\\u0131n\\u0131 s\\u00f6yl\\u00fcyor.\"}]','[{\"word\":\"noise\",\"meaning\":\"ses, g\\u00fcr\\u00fclt\\u00fc\",\"example\":\"What\'s that noise?\"},{\"word\":\"worried\",\"meaning\":\"endi\\u015feli\",\"example\":\"Don\'t be worried, it\'s fine.\"},{\"word\":\"vet\",\"meaning\":\"veteriner\",\"example\":\"We took the dog to the vet.\"},{\"word\":\"neighbour\",\"meaning\":\"kom\\u015fu\",\"example\":\"My neighbour is very friendly.\"},{\"word\":\"sign\",\"meaning\":\"tabela, i\\u015faret\",\"example\":\"The sign says \'Open\'.\"},{\"word\":\"hurt\",\"meaning\":\"zarar vermek, ac\\u0131tmak\",\"example\":\"It won\'t hurt you.\"}]','[{\"q\":\"What was Pamuk doing on the table?\",\"options\":[\"Sleeping\",\"Drinking tea\",\"Reading\"],\"answer\":1},{\"q\":\"What did the vet say?\",\"options\":[\"Tea is very dangerous\",\"No sugar, but a little cold tea is OK\",\"Give him milk instead\"],\"answer\":1},{\"q\":\"How did Pamuk become famous?\",\"options\":[\"A tourist posted a video\",\"He was on TV\",\"Grandma wrote a book\"],\"answer\":0}]',0,1,0,'2026-09-22 20:30:40','2026-10-04 20:30:40','2026-10-04 20:30:40'),
(4,'the-interview-at-the-cafe','The Interview at the Café','Kafedeki Mülakat','Deniz is nervous about her first job interview in English. A small mistake teaches her a big lesson.','A2','Kariyer','/img/stories/the-interview-at-the-cafe.webp',NULL,5,135,'[{\"en\":\"Deniz had studied English for two years, but she had never used it at work. Today she had an interview with an international tourism company.\",\"tr\":\"Deniz iki y\\u0131ld\\u0131r \\u0130ngilizce \\u00e7al\\u0131\\u015f\\u0131yordu ama onu i\\u015fte hi\\u00e7 kullanmam\\u0131\\u015ft\\u0131. Bug\\u00fcn uluslararas\\u0131 bir turizm \\u015firketiyle m\\u00fclakat\\u0131 vard\\u0131.\"},{\"en\":\"The manager, Mr Carter, wanted to meet in a caf\\u00e9. Deniz arrived fifteen minutes early and practised her answers quietly: \\\"I am a hard-working person. I am good at solving problems.\\\"\",\"tr\":\"M\\u00fcd\\u00fcr Bay Carter bir kafede bulu\\u015fmak istedi. Deniz on be\\u015f dakika erken geldi ve cevaplar\\u0131n\\u0131 sessizce \\u00e7al\\u0131\\u015ft\\u0131: \\\"\\u00c7al\\u0131\\u015fkan biriyim. Sorun \\u00e7\\u00f6zmekte iyiyim.\\\"\"},{\"en\":\"When Mr Carter came, she was so nervous that she knocked over her coffee. It went all over the table, and his notebook.\",\"tr\":\"Bay Carter geldi\\u011finde o kadar gergindi ki kahvesini devirdi. Kahve b\\u00fct\\u00fcn masaya, ve onun defterine, yay\\u0131ld\\u0131.\"},{\"en\":\"Deniz wanted to disappear. But then she took a breath, smiled and said, \\\"Well, now you can see that I\'m good at solving problems,\\\" and she quickly cleaned everything with napkins.\",\"tr\":\"Deniz yok olmak istedi. Ama sonra derin bir nefes ald\\u0131, g\\u00fcl\\u00fcmsedi ve \\\"Eh, art\\u0131k sorun \\u00e7\\u00f6zmekte iyi oldu\\u011fumu g\\u00f6rebilirsiniz,\\\" dedi ve hemen her \\u015feyi pe\\u00e7etelerle temizledi.\"},{\"en\":\"Mr Carter laughed. They talked for an hour about travel, customers and difficult situations. A week later, Deniz got an email: \\\"Welcome to the team.\\\"\",\"tr\":\"Bay Carter g\\u00fcld\\u00fc. Bir saat boyunca seyahat, m\\u00fc\\u015fteriler ve zor durumlar hakk\\u0131nda konu\\u015ftular. Bir hafta sonra Deniz bir e-posta ald\\u0131: \\\"Ekibe ho\\u015f geldin.\\\"\"}]','[{\"word\":\"interview\",\"meaning\":\"m\\u00fclakat, g\\u00f6r\\u00fc\\u015fme\",\"example\":\"I have a job interview tomorrow.\"},{\"word\":\"nervous\",\"meaning\":\"gergin, heyecanl\\u0131\",\"example\":\"I always feel nervous before exams.\"},{\"word\":\"knock over\",\"meaning\":\"devirmek\",\"example\":\"The dog knocked over the vase.\"},{\"word\":\"hard-working\",\"meaning\":\"\\u00e7al\\u0131\\u015fkan\",\"example\":\"She is a hard-working student.\"},{\"word\":\"solve\",\"meaning\":\"\\u00e7\\u00f6zmek\",\"example\":\"Can you solve this puzzle?\"},{\"word\":\"customer\",\"meaning\":\"m\\u00fc\\u015fteri\",\"example\":\"The customer wants a refund.\"}]','[{\"q\":\"Where was the interview?\",\"options\":[\"In an office\",\"In a caf\\u00e9\",\"Online\"],\"answer\":1},{\"q\":\"What happened when Mr Carter arrived?\",\"options\":[\"Deniz forgot her CV\",\"Deniz knocked over her coffee\",\"The caf\\u00e9 was closed\"],\"answer\":1},{\"q\":\"How did Deniz handle the situation?\",\"options\":[\"She left the caf\\u00e9\",\"She made a joke and cleaned up\",\"She cried\"],\"answer\":1}]',0,1,0,'2026-09-23 20:30:40','2026-10-04 20:30:40','2026-10-04 20:30:40'),
(5,'the-lighthouse-keepers-letter','The Lighthouse Keeper\'s Letter','Deniz Feneri Bekçisinin Mektubu','While renovating an abandoned lighthouse, Kerem finds a letter that has been waiting sixty years for its reader.','B1','Gizem','/img/stories/the-lighthouse-keepers-letter.webp',NULL,6,208,'[{\"en\":\"The lighthouse on the cliff had been empty since 1964. When the town council decided to turn it into a small museum, they hired Kerem, a young architect who had grown up watching its light from his bedroom window.\",\"tr\":\"Yama\\u00e7taki deniz feneri 1964\'ten beri bo\\u015ftu. Belediye onu k\\u00fc\\u00e7\\u00fck bir m\\u00fczeye d\\u00f6n\\u00fc\\u015ft\\u00fcrmeye karar verdi\\u011finde, \\u00e7ocuklu\\u011funu yatak odas\\u0131n\\u0131n penceresinden onun \\u0131\\u015f\\u0131\\u011f\\u0131n\\u0131 izleyerek ge\\u00e7iren gen\\u00e7 mimar Kerem\'i i\\u015fe ald\\u0131lar.\"},{\"en\":\"On his third day, while he was removing a rotten floorboard, he noticed a metal box hidden underneath. Inside there was a letter, carefully folded and addressed to \\\"Whoever finds this.\\\"\",\"tr\":\"\\u00dc\\u00e7\\u00fcnc\\u00fc g\\u00fcn\\u00fcnde, \\u00e7\\u00fcr\\u00fcm\\u00fc\\u015f bir d\\u00f6\\u015feme tahtas\\u0131n\\u0131 s\\u00f6kerken alt\\u0131nda saklanm\\u0131\\u015f metal bir kutu fark etti. \\u0130\\u00e7inde \\u00f6zenle katlanm\\u0131\\u015f, \\\"Bunu kim bulursa\\\" diye hitap edilmi\\u015f bir mektup vard\\u0131.\"},{\"en\":\"The letter was written by the last keeper, a man called Halil. He explained that during a terrible storm he had rescued a fisherman\'s daughter, but he had never told anyone because the girl\'s father had asked him to keep it secret.\",\"tr\":\"Mektubu son bek\\u00e7i Halil yazm\\u0131\\u015ft\\u0131. Korkun\\u00e7 bir f\\u0131rt\\u0131na s\\u0131ras\\u0131nda bir bal\\u0131k\\u00e7\\u0131n\\u0131n k\\u0131z\\u0131n\\u0131 kurtard\\u0131\\u011f\\u0131n\\u0131, ama k\\u0131z\\u0131n babas\\u0131 s\\u0131r olarak saklamas\\u0131n\\u0131 istedi\\u011fi i\\u00e7in bunu kimseye anlatmad\\u0131\\u011f\\u0131n\\u0131 a\\u00e7\\u0131kl\\u0131yordu.\"},{\"en\":\"\\\"If you are reading this,\\\" Halil wrote, \\\"please find her and tell her that I kept my promise.\\\" At the bottom of the page there was a name: Leyla Aksoy.\",\"tr\":\"\\\"E\\u011fer bunu okuyorsan,\\\" diye yazm\\u0131\\u015ft\\u0131 Halil, \\\"l\\u00fctfen onu bul ve s\\u00f6z\\u00fcm\\u00fc tuttu\\u011fumu s\\u00f6yle.\\\" Sayfan\\u0131n en alt\\u0131nda bir isim vard\\u0131: Leyla Aksoy.\"},{\"en\":\"It took Kerem two months of searching old records to find her. Leyla was now eighty-one and lived in a village nearby. When he read her the letter, she was silent for a long time. Then she said, \\\"I always wondered if he remembered me.\\\"\",\"tr\":\"Kerem\'in onu bulmas\\u0131 eski kay\\u0131tlar\\u0131 iki ay ara\\u015ft\\u0131rmas\\u0131n\\u0131 gerektirdi. Leyla art\\u0131k seksen bir ya\\u015f\\u0131ndayd\\u0131 ve yak\\u0131ndaki bir k\\u00f6yde ya\\u015f\\u0131yordu. Kerem mektubu ona okudu\\u011funda uzun s\\u00fcre sessiz kald\\u0131. Sonra \\\"Beni hat\\u0131rlay\\u0131p hat\\u0131rlamad\\u0131\\u011f\\u0131n\\u0131 hep merak etmi\\u015ftim,\\\" dedi.\"},{\"en\":\"Today, the letter is displayed in the museum\'s main room, next to a photo of Leyla cutting the ribbon on opening day.\",\"tr\":\"Bug\\u00fcn mektup, m\\u00fczenin ana salonunda, Leyla\'n\\u0131n a\\u00e7\\u0131l\\u0131\\u015f g\\u00fcn\\u00fcnde kurdele keserken \\u00e7ekilmi\\u015f bir foto\\u011fraf\\u0131n\\u0131n yan\\u0131nda sergileniyor.\"}]','[{\"word\":\"cliff\",\"meaning\":\"u\\u00e7urum, yal\\u0131yar\",\"example\":\"The house stands on the edge of a cliff.\"},{\"word\":\"hire\",\"meaning\":\"i\\u015fe almak\",\"example\":\"They hired three new engineers.\"},{\"word\":\"rotten\",\"meaning\":\"\\u00e7\\u00fcr\\u00fck\",\"example\":\"Don\'t eat that rotten apple.\"},{\"word\":\"rescue\",\"meaning\":\"kurtarmak\",\"example\":\"Firefighters rescued the cat.\"},{\"word\":\"keep a promise\",\"meaning\":\"s\\u00f6z\\u00fcn\\u00fc tutmak\",\"example\":\"He always keeps his promises.\"},{\"word\":\"wonder\",\"meaning\":\"merak etmek\",\"example\":\"I wonder what she\'s doing now.\"}]','[{\"q\":\"Why did the council hire Kerem?\",\"options\":[\"To destroy the lighthouse\",\"To turn it into a museum\",\"To become the new keeper\"],\"answer\":1},{\"q\":\"Why didn\'t Halil tell anyone about the rescue?\",\"options\":[\"He forgot\",\"The girl\'s father asked him to keep it secret\",\"He was embarrassed\"],\"answer\":1},{\"q\":\"How long did it take Kerem to find Leyla?\",\"options\":[\"Two days\",\"Two weeks\",\"Two months\"],\"answer\":2}]',1,1,0,'2026-09-24 20:30:40','2026-10-04 20:30:40','2026-10-04 20:30:40'),
(6,'the-algorithm-that-learned-to-wait','The Algorithm That Learned to Wait','Beklemeyi Öğrenen Algoritma','An AI designed to maximise productivity discovers the one thing its engineers never measured.','B2','Bilim Kurgu','/img/stories/the-algorithm-that-learned-to-wait.webp',NULL,7,234,'[{\"en\":\"When Selin\'s team launched ORBIT, it was supposed to be the most efficient scheduling assistant ever built. It analysed calendars, emails and sleep data, then rearranged people\'s days to squeeze out every productive minute.\",\"tr\":\"Selin\'in ekibi ORBIT\'i yay\\u0131na ald\\u0131\\u011f\\u0131nda, onun \\u015fimdiye kadar yap\\u0131lm\\u0131\\u015f en verimli planlama asistan\\u0131 olmas\\u0131 bekleniyordu. Takvimleri, e-postalar\\u0131 ve uyku verilerini analiz ediyor, ard\\u0131ndan her verimli dakikay\\u0131 s\\u0131k\\u0131\\u015ft\\u0131rmak i\\u00e7in insanlar\\u0131n g\\u00fcnlerini yeniden d\\u00fczenliyordu.\"},{\"en\":\"For the first few months, the results were impressive. Meetings were shorter, deadlines were met, and the company\'s share price climbed steadily. Yet something in the data bothered Selin: employee satisfaction was quietly falling.\",\"tr\":\"\\u0130lk birka\\u00e7 ay sonu\\u00e7lar etkileyiciydi. Toplant\\u0131lar k\\u0131sald\\u0131, teslim tarihlerine uyuldu ve \\u015firketin hisse fiyat\\u0131 istikrarl\\u0131 bi\\u00e7imde y\\u00fckseldi. Yine de verilerdeki bir \\u015fey Selin\'i rahats\\u0131z ediyordu: \\u00e7al\\u0131\\u015fan memnuniyeti sessizce d\\u00fc\\u015f\\u00fcyordu.\"},{\"en\":\"Then, one Tuesday, ORBIT did something no one had programmed it to do. It cancelled a strategy meeting and replaced it with a single line: \\\"Take a walk. The problem will still be here, but you will see it differently.\\\"\",\"tr\":\"Sonra bir sal\\u0131 g\\u00fcn\\u00fc ORBIT, kimsenin onu yapmaya programlamad\\u0131\\u011f\\u0131 bir \\u015fey yapt\\u0131. Bir strateji toplant\\u0131s\\u0131n\\u0131 iptal etti ve yerine tek bir sat\\u0131r koydu: \\\"Y\\u00fcr\\u00fcy\\u00fc\\u015fe \\u00e7\\u0131k. Sorun h\\u00e2l\\u00e2 burada olacak ama onu farkl\\u0131 g\\u00f6receksin.\\\"\"},{\"en\":\"The engineers assumed it was a bug. But when they examined the logs, they found that ORBIT had noticed a pattern they had overlooked: the team\'s best ideas almost always appeared after periods of apparent inactivity, lunches that ran long, commutes without headphones, afternoons spent staring out of the window.\",\"tr\":\"M\\u00fchendisler bunun bir hata oldu\\u011funu varsayd\\u0131. Ama kay\\u0131tlar\\u0131 incelediklerinde ORBIT\'in g\\u00f6zden ka\\u00e7\\u0131rd\\u0131klar\\u0131 bir \\u00f6r\\u00fcnt\\u00fcy\\u00fc fark etti\\u011fini g\\u00f6rd\\u00fcler: ekibin en iyi fikirleri neredeyse her zaman g\\u00f6r\\u00fcn\\u00fcrde hareketsiz ge\\u00e7en d\\u00f6nemlerden sonra ortaya \\u00e7\\u0131k\\u0131yordu, uzayan \\u00f6\\u011fle yemekleri, kulakl\\u0131ks\\u0131z yolculuklar, pencereden d\\u0131\\u015far\\u0131 bakarak ge\\u00e7en \\u00f6\\u011fleden sonralar.\"},{\"en\":\"Rather than fixing the \\\"bug\\\", Selin argued that they should keep it. Efficiency, she said, had been measured in minutes, while creativity had never been measured at all. ORBIT had simply filled in the missing variable.\",\"tr\":\"Selin \\\"hatay\\u0131\\\" d\\u00fczeltmek yerine onu korumalar\\u0131 gerekti\\u011fini savundu. Verimlilik dakikalarla \\u00f6l\\u00e7\\u00fclm\\u00fc\\u015ft\\u00fc, dedi, oysa yarat\\u0131c\\u0131l\\u0131k hi\\u00e7 \\u00f6l\\u00e7\\u00fclmemi\\u015fti. ORBIT yaln\\u0131zca eksik de\\u011fi\\u015fkeni tamamlam\\u0131\\u015ft\\u0131.\"},{\"en\":\"Six months later, the company introduced \\\"ORBIT pauses\\\" across every department. Productivity dipped slightly at first, then rose higher than ever. The algorithm, it turned out, had learned the one skill its creators were worst at: knowing when to wait.\",\"tr\":\"Alt\\u0131 ay sonra \\u015firket her departmanda \\\"ORBIT molalar\\u0131\\\"n\\u0131 ba\\u015flatt\\u0131. Verimlilik \\u00f6nce biraz d\\u00fc\\u015ft\\u00fc, sonra her zamankinden daha \\u00e7ok y\\u00fckseldi. G\\u00f6r\\u00fcn\\u00fc\\u015fe g\\u00f6re algoritma, yarat\\u0131c\\u0131lar\\u0131n\\u0131n en k\\u00f6t\\u00fc oldu\\u011fu tek beceriyi \\u00f6\\u011frenmi\\u015fti: ne zaman beklenece\\u011fini bilmek.\"}]','[{\"word\":\"efficient\",\"meaning\":\"verimli\",\"example\":\"This machine is very efficient.\"},{\"word\":\"squeeze out\",\"meaning\":\"s\\u0131k\\u0131p \\u00e7\\u0131karmak, son damlas\\u0131na kadar almak\",\"example\":\"They squeezed out every minute of the day.\"},{\"word\":\"steadily\",\"meaning\":\"istikrarl\\u0131 bi\\u00e7imde\",\"example\":\"Prices rose steadily.\"},{\"word\":\"overlook\",\"meaning\":\"g\\u00f6zden ka\\u00e7\\u0131rmak\",\"example\":\"We overlooked an important detail.\"},{\"word\":\"apparent\",\"meaning\":\"g\\u00f6r\\u00fcn\\u00fcrdeki, g\\u00f6r\\u00fcnen\",\"example\":\"There was no apparent reason.\"},{\"word\":\"dip\",\"meaning\":\"hafif\\u00e7e d\\u00fc\\u015fmek\",\"example\":\"Sales dipped in winter.\"}]','[{\"q\":\"What worried Selin in the first months?\",\"options\":[\"Shorter meetings\",\"Falling employee satisfaction\",\"The share price\"],\"answer\":1},{\"q\":\"What pattern did ORBIT notice?\",\"options\":[\"Best ideas came after periods of apparent inactivity\",\"People worked better at night\",\"Long meetings produced more ideas\"],\"answer\":0},{\"q\":\"What is the main message of the story?\",\"options\":[\"Algorithms are dangerous\",\"Rest and pauses can fuel creativity\",\"Meetings should be longer\"],\"answer\":1}]',1,1,0,'2026-09-25 20:30:40','2026-10-04 20:30:40','2026-10-04 20:30:40'),
(7,'the-lost-dog','The Lost Dog','Kayıp Köpek','Zeynep finds a small dog in the rain. It has no name and no home. Or does it?','A1','Günlük Hayat','/img/stories/the-lost-dog.webp',NULL,3,288,'[{\"en\":\"It is a cold Sunday morning in Kad\\u0131k\\u00f6y. Zeynep is ten years old. She walks to the bakery with her father. It is raining.\",\"tr\":\"Kad\\u0131k\\u00f6y\'de so\\u011fuk bir pazar sabah\\u0131. Zeynep on ya\\u015f\\u0131nda. Babas\\u0131yla f\\u0131r\\u0131na y\\u00fcr\\u00fcyor. Ya\\u011fmur ya\\u011f\\u0131yor.\"},{\"en\":\"Near the bakery, there is a small brown dog. It is wet and it is shaking. It has big black eyes and one white ear.\",\"tr\":\"F\\u0131r\\u0131n\\u0131n yan\\u0131nda k\\u00fc\\u00e7\\u00fck kahverengi bir k\\u00f6pek var. Islak ve titriyor. B\\u00fcy\\u00fck siyah g\\u00f6zleri ve bir beyaz kula\\u011f\\u0131 var.\"},{\"en\":\"\\\"Dad, look! The dog is cold,\\\" Zeynep says. Her father takes off his scarf. Zeynep puts the scarf on the dog. The dog licks her hand.\",\"tr\":\"\\\"Baba, bak! K\\u00f6pek \\u00fc\\u015f\\u00fcyor,\\\" diyor Zeynep. Babas\\u0131 atk\\u0131s\\u0131n\\u0131 \\u00e7\\u0131kar\\u0131yor. Zeynep atk\\u0131y\\u0131 k\\u00f6pe\\u011fin \\u00fcst\\u00fcne koyuyor. K\\u00f6pek elini yal\\u0131yor.\"},{\"en\":\"The dog has a red collar, but there is no name on it. \\\"Maybe it has a family,\\\" her father says. \\\"Let\'s ask in the bakery.\\\"\",\"tr\":\"K\\u00f6pe\\u011fin k\\u0131rm\\u0131z\\u0131 bir tasmas\\u0131 var ama \\u00fcst\\u00fcnde isim yok. \\\"Belki bir ailesi vard\\u0131r,\\\" diyor babas\\u0131. \\\"F\\u0131r\\u0131nda soral\\u0131m.\\\"\"},{\"en\":\"The baker is a tall man with a white hat. He looks at the dog and shakes his head. \\\"I don\'t know this dog. Sorry.\\\"\",\"tr\":\"F\\u0131r\\u0131nc\\u0131 beyaz \\u015fapkal\\u0131 uzun boylu bir adam. K\\u00f6pe\\u011fe bak\\u0131yor ve ba\\u015f\\u0131n\\u0131 sall\\u0131yor. \\\"Bu k\\u00f6pe\\u011fi tan\\u0131m\\u0131yorum. \\u00dczg\\u00fcn\\u00fcm.\\\"\"},{\"en\":\"They take the dog home. Zeynep gives it water and some bread. The dog sleeps on the sofa. Zeynep is very happy. \\\"Can we keep it?\\\" she asks. \\\"Let\'s wait,\\\" says her mother.\",\"tr\":\"K\\u00f6pe\\u011fi eve g\\u00f6t\\u00fcr\\u00fcyorlar. Zeynep ona su ve biraz ekmek veriyor. K\\u00f6pek kanepede uyuyor. Zeynep \\u00e7ok mutlu. \\\"Onu tutabilir miyiz?\\\" diye soruyor. \\\"Bekleyelim,\\\" diyor annesi.\"},{\"en\":\"Zeynep makes a poster. It says: FOUND! Small brown dog, one white ear, red collar. She puts the poster on the door of the bakery.\",\"tr\":\"Zeynep bir afi\\u015f haz\\u0131rl\\u0131yor. Afi\\u015fte \\u015f\\u00f6yle yaz\\u0131yor: BULUNDU! K\\u00fc\\u00e7\\u00fck kahverengi k\\u00f6pek, bir beyaz kulak, k\\u0131rm\\u0131z\\u0131 tasma. Afi\\u015fi f\\u0131r\\u0131n\\u0131n kap\\u0131s\\u0131na as\\u0131yor.\"},{\"en\":\"Two days later, the phone rings. It is an old woman. Her name is Nermin. She is crying. \\\"That is my dog, F\\u0131st\\u0131k! He runs away every time there is thunder.\\\"\",\"tr\":\"\\u0130ki g\\u00fcn sonra telefon \\u00e7al\\u0131yor. Arayan ya\\u015fl\\u0131 bir kad\\u0131n. Ad\\u0131 Nermin. A\\u011fl\\u0131yor. \\\"O benim k\\u00f6pe\\u011fim, F\\u0131st\\u0131k! Her g\\u00f6k g\\u00fcr\\u00fclt\\u00fcs\\u00fcnde ka\\u00e7\\u0131yor.\\\"\"},{\"en\":\"Zeynep is sad, but she takes F\\u0131st\\u0131k to Nermin\'s flat. F\\u0131st\\u0131k jumps and barks. Nermin hugs him. Then she looks at Zeynep and smiles.\",\"tr\":\"Zeynep \\u00fczg\\u00fcn ama F\\u0131st\\u0131k\'\\u0131 Nermin\'in dairesine g\\u00f6t\\u00fcr\\u00fcyor. F\\u0131st\\u0131k z\\u0131pl\\u0131yor ve havl\\u0131yor. Nermin ona sar\\u0131l\\u0131yor. Sonra Zeynep\'e bak\\u0131p g\\u00fcl\\u00fcms\\u00fcyor.\"},{\"en\":\"\\\"I am old, and my legs are tired,\\\" Nermin says. \\\"F\\u0131st\\u0131k needs long walks. Can you walk him every Sunday?\\\" Zeynep says yes. Now every Sunday morning, Zeynep, her father and F\\u0131st\\u0131k walk to the bakery together.\",\"tr\":\"\\\"Ya\\u015fl\\u0131y\\u0131m ve bacaklar\\u0131m yorgun,\\\" diyor Nermin. \\\"F\\u0131st\\u0131k\'\\u0131n uzun y\\u00fcr\\u00fcy\\u00fc\\u015flere ihtiyac\\u0131 var. Onu her pazar gezdirebilir misin?\\\" Zeynep evet diyor. Art\\u0131k her pazar sabah\\u0131 Zeynep, babas\\u0131 ve F\\u0131st\\u0131k f\\u0131r\\u0131na birlikte y\\u00fcr\\u00fcyor.\"}]','[{\"word\":\"bakery\",\"meaning\":\"f\\u0131r\\u0131n\",\"example\":\"I buy bread at the bakery.\"},{\"word\":\"shake\",\"meaning\":\"titremek; sallamak\",\"example\":\"The puppy is shaking in the cold.\"},{\"word\":\"collar\",\"meaning\":\"tasma\",\"example\":\"The dog has a blue collar.\"},{\"word\":\"poster\",\"meaning\":\"afi\\u015f\",\"example\":\"We put a poster on the wall.\"},{\"word\":\"run away\",\"meaning\":\"ka\\u00e7mak\",\"example\":\"Our cat runs away at night.\"},{\"word\":\"hug\",\"meaning\":\"sar\\u0131lmak\",\"example\":\"She hugs her little brother.\"}]','[{\"q\":\"Where does Zeynep find the dog?\",\"options\":[\"In a park\",\"Near the bakery\",\"At school\"],\"answer\":1},{\"q\":\"Why does F\\u0131st\\u0131k run away?\",\"options\":[\"He is hungry\",\"He is afraid of thunder\",\"He wants a new home\"],\"answer\":1},{\"q\":\"What does Nermin ask Zeynep to do?\",\"options\":[\"Keep the dog\",\"Buy bread for her\",\"Walk the dog every Sunday\"],\"answer\":2}]',0,1,0,'2026-09-26 20:30:40','2026-10-04 20:30:40','2026-10-04 20:30:40'),
(8,'the-secret-room','The Secret Room','Gizli Oda','Every summer Can stays at his grandmother\'s old house in Safranbolu. This year he finds a door that was not there before.','A2','Gizem','/img/stories/the-secret-room.webp',NULL,3,384,'[{\"en\":\"Every summer, Can spends three weeks at his grandmother\'s house in Safranbolu. The house is very old. It has wooden floors, small windows and a big garden full of fruit trees.\",\"tr\":\"Can her yaz \\u00fc\\u00e7 haftas\\u0131n\\u0131 b\\u00fcy\\u00fckannesinin Safranbolu\'daki evinde ge\\u00e7irir. Ev \\u00e7ok eskidir. Ah\\u015fap zeminleri, k\\u00fc\\u00e7\\u00fck pencereleri ve meyve a\\u011fa\\u00e7lar\\u0131yla dolu b\\u00fcy\\u00fck bir bah\\u00e7esi vard\\u0131r.\"},{\"en\":\"Can knows every room in the house. Or that is what he thought. On the first night, there was a terrible storm. The lights went out, and Can went downstairs with a torch to find some candles.\",\"tr\":\"Can evdeki her oday\\u0131 bilir. Ya da \\u00f6yle d\\u00fc\\u015f\\u00fcn\\u00fcyordu. \\u0130lk gece korkun\\u00e7 bir f\\u0131rt\\u0131na \\u00e7\\u0131kt\\u0131. I\\u015f\\u0131klar s\\u00f6nd\\u00fc ve Can mum bulmak i\\u00e7in elinde fenerle a\\u015fa\\u011f\\u0131 indi.\"},{\"en\":\"In the kitchen, behind the old cupboard, he saw a thin line of light. He moved the cupboard a little. Behind it, there was a small green door with a silver handle.\",\"tr\":\"Mutfakta, eski dolab\\u0131n arkas\\u0131nda ince bir \\u0131\\u015f\\u0131k \\u00e7izgisi g\\u00f6rd\\u00fc. Dolab\\u0131 biraz \\u00e7ekti. Arkas\\u0131nda g\\u00fcm\\u00fc\\u015f kollu k\\u00fc\\u00e7\\u00fck ye\\u015fil bir kap\\u0131 vard\\u0131.\"},{\"en\":\"The door was locked. Can tried to open it, but it was impossible. He heard a quiet sound from the other side, like music. Then the lights came back, and the sound stopped.\",\"tr\":\"Kap\\u0131 kilitliydi. Can a\\u00e7maya \\u00e7al\\u0131\\u015ft\\u0131 ama imk\\u00e2ns\\u0131zd\\u0131. Di\\u011fer taraftan m\\u00fczik gibi sessiz bir ses duydu. Sonra \\u0131\\u015f\\u0131klar geri geldi ve ses kesildi.\"},{\"en\":\"The next morning, Can asked his grandmother about the door. She stopped drinking her tea and looked at him for a long time. \\\"So you found it,\\\" she said softly. \\\"I didn\'t want to open that door again.\\\"\",\"tr\":\"Ertesi sabah Can b\\u00fcy\\u00fckannesine kap\\u0131y\\u0131 sordu. B\\u00fcy\\u00fckannesi \\u00e7ay\\u0131n\\u0131 i\\u00e7meyi b\\u0131rakt\\u0131 ve ona uzun s\\u00fcre bakt\\u0131. \\\"Demek buldun,\\\" dedi yumu\\u015fak bir sesle. \\\"O kap\\u0131y\\u0131 bir daha a\\u00e7mak istemiyordum.\\\"\"},{\"en\":\"She went to her bedroom and came back with a small key. Her hands were shaking. Together, they opened the green door. Inside, there was a tiny room with a window, a chair and an old piano covered in dust.\",\"tr\":\"Yatak odas\\u0131na gitti ve k\\u00fc\\u00e7\\u00fck bir anahtarla geri geldi. Elleri titriyordu. Ye\\u015fil kap\\u0131y\\u0131 birlikte a\\u00e7t\\u0131lar. \\u0130\\u00e7eride pencereli, sandalyeli ve tozla kapl\\u0131 eski bir piyanonun oldu\\u011fu minicik bir oda vard\\u0131.\"},{\"en\":\"\\\"This was my brother Selim\'s room,\\\" his grandmother said. \\\"He played the piano every evening. When he was nineteen, he went to Istanbul to study music. He never came back. We had an argument, and we didn\'t speak again.\\\"\",\"tr\":\"\\\"Buras\\u0131 karde\\u015fim Selim\'in odas\\u0131yd\\u0131,\\\" dedi b\\u00fcy\\u00fckannesi. \\\"Her ak\\u015fam piyano \\u00e7alard\\u0131. On dokuz ya\\u015f\\u0131ndayken m\\u00fczik okumak i\\u00e7in \\u0130stanbul\'a gitti. Hi\\u00e7 geri d\\u00f6nmedi. Tart\\u0131\\u015fm\\u0131\\u015ft\\u0131k ve bir daha konu\\u015fmad\\u0131k.\\\"\"},{\"en\":\"On the piano, Can found a pile of letters. They were all for his grandmother, and none of them were opened. The last one was from forty years ago. \\\"Why didn\'t you read them?\\\" Can asked. \\\"I was angry,\\\" she said. \\\"And then I was afraid.\\\"\",\"tr\":\"Piyanonun \\u00fcst\\u00fcnde Can bir deste mektup buldu. Hepsi b\\u00fcy\\u00fckannesine yaz\\u0131lm\\u0131\\u015ft\\u0131 ve hi\\u00e7biri a\\u00e7\\u0131lmam\\u0131\\u015ft\\u0131. Sonuncusu k\\u0131rk y\\u0131l \\u00f6ncesindendi. \\\"Neden okumad\\u0131n?\\\" diye sordu Can. \\\"K\\u0131zg\\u0131nd\\u0131m,\\\" dedi. \\\"Sonra da korktum.\\\"\"},{\"en\":\"They read the letters together in the garden. In the last letter, Selim wrote: \\\"I have a daughter now. Her name is Leyla, like our mother. One day I want her to meet you.\\\" There was an address in \\u0130zmir.\",\"tr\":\"Mektuplar\\u0131 bah\\u00e7ede birlikte okudular. Son mektupta Selim \\u015f\\u00f6yle yazm\\u0131\\u015ft\\u0131: \\\"Art\\u0131k bir k\\u0131z\\u0131m var. Ad\\u0131 annemiz gibi Leyla. Bir g\\u00fcn seninle tan\\u0131\\u015fmas\\u0131n\\u0131 istiyorum.\\\" Mektupta \\u0130zmir\'de bir adres vard\\u0131.\"},{\"en\":\"Can found Leyla on the internet in ten minutes. She was a piano teacher. Two weeks later, a woman with grey hair knocked on the door. She sat at the old piano and played the song from the storm. Can\'s grandmother cried, but this time she was smiling.\",\"tr\":\"Can, Leyla\'y\\u0131 internette on dakikada buldu. Piyano \\u00f6\\u011fretmeniydi. \\u0130ki hafta sonra gri sa\\u00e7l\\u0131 bir kad\\u0131n kap\\u0131y\\u0131 \\u00e7ald\\u0131. Eski piyanonun ba\\u015f\\u0131na oturdu ve f\\u0131rt\\u0131nadaki \\u015fark\\u0131y\\u0131 \\u00e7ald\\u0131. Can\'\\u0131n b\\u00fcy\\u00fckannesi a\\u011flad\\u0131 ama bu sefer g\\u00fcl\\u00fcms\\u00fcyordu.\"}]','[{\"word\":\"wooden\",\"meaning\":\"ah\\u015fap\",\"example\":\"We have a wooden table in the kitchen.\"},{\"word\":\"torch\",\"meaning\":\"el feneri\",\"example\":\"Take a torch, it\'s dark outside.\"},{\"word\":\"cupboard\",\"meaning\":\"dolap\",\"example\":\"The plates are in the cupboard.\"},{\"word\":\"locked\",\"meaning\":\"kilitli\",\"example\":\"The door was locked, so we waited.\"},{\"word\":\"argument\",\"meaning\":\"tart\\u0131\\u015fma\",\"example\":\"They had an argument about money.\"},{\"word\":\"dust\",\"meaning\":\"toz\",\"example\":\"The old books were covered in dust.\"}]','[{\"q\":\"Where did Can find the green door?\",\"options\":[\"In the garden\",\"Behind a cupboard in the kitchen\",\"Under his bed\"],\"answer\":1},{\"q\":\"Why didn\'t the grandmother read Selim\'s letters?\",\"options\":[\"She couldn\'t read\",\"She was angry and then afraid\",\"She never received them\"],\"answer\":1},{\"q\":\"Who was Leyla?\",\"options\":[\"Selim\'s daughter\",\"Can\'s teacher\",\"The grandmother\'s neighbour\"],\"answer\":0}]',0,1,0,'2026-09-27 20:30:40','2026-10-04 20:30:40','2026-10-04 20:30:40'),
(9,'lost-in-cappadocia','Lost in Cappadocia','Kapadokya\'da Kayıp','Emma wants the perfect photo of the balloons at sunrise. She gets lost in a valley, and she finds something better.','A2','Seyahat','/img/stories/lost-in-cappadocia.webp',NULL,3,387,'[{\"en\":\"Emma was a photographer from Manchester. She came to Cappadocia for one reason: to take a photo of a hundred hot-air balloons at sunrise. Her plan was simple. She wanted to walk into Love Valley at five in the morning, before the tourists arrived.\",\"tr\":\"Emma Manchester\'l\\u0131 bir foto\\u011fraf\\u00e7\\u0131yd\\u0131. Kapadokya\'ya tek bir sebeple gelmi\\u015fti: g\\u00fcn do\\u011farken y\\u00fcz s\\u0131cak hava balonunun foto\\u011fraf\\u0131n\\u0131 \\u00e7ekmek. Plan\\u0131 basitti. Turistler gelmeden, sabah be\\u015fte A\\u015fk Vadisi\'ne y\\u00fcr\\u00fcmek istiyordu.\"},{\"en\":\"At half past four, she left her hotel in G\\u00f6reme. It was dark and very quiet. She followed the map on her phone. But after twenty minutes, her phone battery died. She stopped and looked around. Every rock looked the same.\",\"tr\":\"D\\u00f6rt bu\\u00e7ukta G\\u00f6reme\'deki otelinden \\u00e7\\u0131kt\\u0131. Hava karanl\\u0131k ve \\u00e7ok sessizdi. Telefonundaki haritay\\u0131 takip etti. Ama yirmi dakika sonra telefonunun \\u015farj\\u0131 bitti. Durdu ve etraf\\u0131na bakt\\u0131. Her kaya ayn\\u0131 g\\u00f6r\\u00fcn\\u00fcyordu.\"},{\"en\":\"\\\"Don\'t panic,\\\" she said to herself. She walked towards a small light. It was a tiny farmhouse. An old man was feeding his chickens. He looked surprised to see a tourist with a big camera in the middle of nowhere.\",\"tr\":\"\\\"Panik yapma,\\\" dedi kendi kendine. K\\u00fc\\u00e7\\u00fck bir \\u0131\\u015f\\u0131\\u011fa do\\u011fru y\\u00fcr\\u00fcd\\u00fc. Minicik bir \\u00e7iftlik eviydi. Ya\\u015fl\\u0131 bir adam tavuklar\\u0131n\\u0131 besliyordu. Hi\\u00e7 kimsenin olmad\\u0131\\u011f\\u0131 bir yerde b\\u00fcy\\u00fck kameral\\u0131 bir turist g\\u00f6r\\u00fcnce \\u015fa\\u015f\\u0131rm\\u0131\\u015f g\\u00f6r\\u00fcn\\u00fcyordu.\"},{\"en\":\"Emma didn\'t speak Turkish, and the man didn\'t speak English. She pointed at the sky and made the shape of a balloon with her hands. The man laughed. \\\"Balon!\\\" he said. He waved his hand: \\\"Come, come.\\\"\",\"tr\":\"Emma T\\u00fcrk\\u00e7e bilmiyordu, adam da \\u0130ngilizce bilmiyordu. G\\u00f6ky\\u00fcz\\u00fcn\\u00fc g\\u00f6sterdi ve elleriyle balon \\u015fekli yapt\\u0131. Adam g\\u00fcld\\u00fc. \\\"Balon!\\\" dedi. Eliyle i\\u015faret etti: \\\"Gel, gel.\\\"\"},{\"en\":\"He took a lamp and walked up a narrow path behind his house. Emma followed him. The path was steep and rocky, and her legs hurt. After fifteen minutes, they arrived at the top of a small hill. The man sat on a rock and poured two glasses of tea from a flask.\",\"tr\":\"Bir lamba ald\\u0131 ve evinin arkas\\u0131ndaki dar bir patikadan yukar\\u0131 y\\u00fcr\\u00fcd\\u00fc. Emma onu takip etti. Patika dik ve kayal\\u0131kt\\u0131, bacaklar\\u0131 a\\u011fr\\u0131yordu. On be\\u015f dakika sonra k\\u00fc\\u00e7\\u00fck bir tepenin zirvesine vard\\u0131lar. Adam bir kayaya oturdu ve termostan iki bardak \\u00e7ay doldurdu.\"},{\"en\":\"Then the sky started to change. First it was dark blue, then purple, then orange. And suddenly, they came: one balloon, then five, then fifty. They rose slowly over the valley, red and yellow and blue, like giant flowers in the sky.\",\"tr\":\"Sonra g\\u00f6ky\\u00fcz\\u00fc de\\u011fi\\u015fmeye ba\\u015flad\\u0131. \\u00d6nce koyu maviydi, sonra mor, sonra turuncu. Ve aniden geldiler: bir balon, sonra be\\u015f, sonra elli. Vadinin \\u00fcst\\u00fcnde yava\\u015f\\u00e7a y\\u00fckseldiler; k\\u0131rm\\u0131z\\u0131, sar\\u0131 ve mavi, g\\u00f6ky\\u00fcz\\u00fcndeki dev \\u00e7i\\u00e7ekler gibi.\"},{\"en\":\"Emma took hundreds of photos. There were no tourists, no noise, only the balloons, the old man and his tea. \\\"Every morning?\\\" she asked, pointing at the sky. The man nodded and smiled. \\\"Every morning. Forty years.\\\"\",\"tr\":\"Emma y\\u00fczlerce foto\\u011fraf \\u00e7ekti. Ne turist vard\\u0131 ne g\\u00fcr\\u00fclt\\u00fc; yaln\\u0131zca balonlar, ya\\u015fl\\u0131 adam ve \\u00e7ay\\u0131. \\\"Her sabah m\\u0131?\\\" diye sordu g\\u00f6ky\\u00fcz\\u00fcn\\u00fc g\\u00f6stererek. Adam ba\\u015f\\u0131n\\u0131 sallad\\u0131 ve g\\u00fcl\\u00fcmsedi. \\\"Her sabah. K\\u0131rk y\\u0131l.\\\"\"},{\"en\":\"His name was Mustafa. Later, he drove her back to G\\u00f6reme in his old tractor. Emma tried to give him money, but he refused. So she took one last photo: Mustafa on his tractor, laughing, with the balloons behind him.\",\"tr\":\"Ad\\u0131 Mustafa\'yd\\u0131. Sonra onu eski trakt\\u00f6r\\u00fcyle G\\u00f6reme\'ye geri g\\u00f6t\\u00fcrd\\u00fc. Emma ona para vermeye \\u00e7al\\u0131\\u015ft\\u0131 ama reddetti. Bu y\\u00fczden son bir foto\\u011fraf \\u00e7ekti: trakt\\u00f6r\\u00fcn\\u00fcn \\u00fcst\\u00fcnde g\\u00fclen Mustafa ve arkas\\u0131nda balonlar.\"},{\"en\":\"Six months later, Emma\'s photo won an international prize. It wasn\'t a photo of a hundred balloons. It was the photo of Mustafa. She sent him a printed copy with a letter. A guide from G\\u00f6reme translated it for him. It said: \\\"The best things are not on the map.\\\"\",\"tr\":\"Alt\\u0131 ay sonra Emma\'n\\u0131n foto\\u011fraf\\u0131 uluslararas\\u0131 bir \\u00f6d\\u00fcl kazand\\u0131. Y\\u00fcz balonun foto\\u011fraf\\u0131 de\\u011fildi. Mustafa\'n\\u0131n foto\\u011fraf\\u0131yd\\u0131. Ona bas\\u0131lm\\u0131\\u015f bir kopyas\\u0131n\\u0131 bir mektupla g\\u00f6nderdi. G\\u00f6reme\'den bir rehber mektubu ona terc\\u00fcme etti. \\u015e\\u00f6yle yaz\\u0131yordu: \\\"En g\\u00fczel \\u015feyler haritada yazmaz.\\\"\"}]','[{\"word\":\"sunrise\",\"meaning\":\"g\\u00fcn do\\u011fumu\",\"example\":\"We watched the sunrise from the beach.\"},{\"word\":\"valley\",\"meaning\":\"vadi\",\"example\":\"The river runs through the valley.\"},{\"word\":\"steep\",\"meaning\":\"dik, sarp\",\"example\":\"The road to the village is very steep.\"},{\"word\":\"flask\",\"meaning\":\"termos, matara\",\"example\":\"He always carries a flask of tea.\"},{\"word\":\"rise\",\"meaning\":\"y\\u00fckselmek\",\"example\":\"The sun rises in the east.\"},{\"word\":\"refuse\",\"meaning\":\"reddetmek\",\"example\":\"She refused to take the money.\"}]','[{\"q\":\"Why did Emma get lost?\",\"options\":[\"She took the wrong bus\",\"Her phone battery died\",\"A guide gave her bad directions\"],\"answer\":1},{\"q\":\"How did Emma and Mustafa communicate?\",\"options\":[\"In English\",\"With gestures\",\"With a translation app\"],\"answer\":1},{\"q\":\"Which photo won the prize?\",\"options\":[\"A hundred balloons\",\"Love Valley at night\",\"Mustafa on his tractor\"],\"answer\":2}]',0,1,0,'2026-09-28 20:30:40','2026-10-04 20:30:40','2026-10-04 20:30:40'),
(10,'the-midnight-bus','The Midnight Bus','Gece Yarısı Otobüsü','Deniz misses the last ferry and takes a night bus home. The only other passenger seems to know everything about her.','B1','Gizem','/img/stories/the-midnight-bus.webp',NULL,4,497,'[{\"en\":\"Deniz had worked late again. By the time she left the office in Levent, the last ferry to Kad\\u0131k\\u00f6y had already gone. Her phone was at three per cent, it was raining, and she had an exam at nine the next morning. She ran to the bus stop just as the night bus was closing its doors.\",\"tr\":\"Deniz yine ge\\u00e7 saate kadar \\u00e7al\\u0131\\u015fm\\u0131\\u015ft\\u0131. Levent\'teki ofisten \\u00e7\\u0131kt\\u0131\\u011f\\u0131nda Kad\\u0131k\\u00f6y\'e giden son vapur \\u00e7oktan kalkm\\u0131\\u015ft\\u0131. Telefonunun \\u015farj\\u0131 y\\u00fczde \\u00fc\\u00e7teydi, ya\\u011fmur ya\\u011f\\u0131yordu ve ertesi sabah saat dokuzda s\\u0131nav\\u0131 vard\\u0131. Gece otob\\u00fcs\\u00fc kap\\u0131lar\\u0131n\\u0131 kapat\\u0131rken dura\\u011fa ko\\u015farak yeti\\u015fti.\"},{\"en\":\"The bus was almost empty. There was only one other passenger: an old man in a grey coat, sitting at the back with a newspaper. Deniz sat near the window and closed her eyes. She was so tired that she didn\'t notice when the man moved to the seat across from her.\",\"tr\":\"Otob\\u00fcs neredeyse bo\\u015ftu. Yaln\\u0131zca bir yolcu daha vard\\u0131: arkada gazete okuyan gri paltolu ya\\u015fl\\u0131 bir adam. Deniz pencerenin yan\\u0131na oturdu ve g\\u00f6zlerini kapad\\u0131. O kadar yorgundu ki adam\\u0131n kar\\u015f\\u0131s\\u0131ndaki koltu\\u011fa ge\\u00e7ti\\u011fini fark etmedi.\"},{\"en\":\"\\\"You should study the second chapter again,\\\" he said quietly. Deniz opened her eyes. \\\"Sorry?\\\" \\\"Your exam tomorrow. Question four will be about the second chapter. You haven\'t understood it yet.\\\" He smiled kindly, as if this was a normal thing to say to a stranger.\",\"tr\":\"\\\"\\u0130kinci b\\u00f6l\\u00fcm\\u00fc tekrar \\u00e7al\\u0131\\u015fmal\\u0131s\\u0131n,\\\" dedi sessizce. Deniz g\\u00f6zlerini a\\u00e7t\\u0131. \\\"Efendim?\\\" \\\"Yar\\u0131nki s\\u0131nav\\u0131n. D\\u00f6rd\\u00fcnc\\u00fc soru ikinci b\\u00f6l\\u00fcmden gelecek. Onu hen\\u00fcz anlamad\\u0131n.\\\" Sanki bir yabanc\\u0131ya s\\u00f6ylenecek normal bir \\u015feymi\\u015f gibi nazik\\u00e7e g\\u00fcl\\u00fcmsedi.\"},{\"en\":\"Deniz felt cold. Nobody knew about her exam except her mother and her best friend. \\\"How do you know that?\\\" she asked. The man folded his newspaper. \\\"I used to take this bus every night, many years ago. I was always worried about something too. Exams, work, money. I never looked out of the window.\\\"\",\"tr\":\"Deniz \\u00fc\\u015f\\u00fcd\\u00fc\\u011f\\u00fcn\\u00fc hissetti. Annesi ve en yak\\u0131n arkada\\u015f\\u0131 d\\u0131\\u015f\\u0131nda kimse s\\u0131nav\\u0131ndan haberdar de\\u011fildi. \\\"Bunu nereden biliyorsunuz?\\\" diye sordu. Adam gazetesini katlad\\u0131. \\\"Y\\u0131llar \\u00f6nce her gece bu otob\\u00fcse binerdim. Ben de hep bir \\u015fey i\\u00e7in endi\\u015felenirdim. S\\u0131navlar, i\\u015f, para. Pencereden hi\\u00e7 d\\u0131\\u015far\\u0131 bakmazd\\u0131m.\\\"\"},{\"en\":\"He pointed outside. The bus was crossing the bridge. Below them, the Bosphorus was black and silver, and the lights of the city were shining on the water like thousands of tiny candles. Deniz had crossed this bridge hundreds of times, but she had never really seen it.\",\"tr\":\"D\\u0131\\u015far\\u0131y\\u0131 g\\u00f6sterdi. Otob\\u00fcs k\\u00f6pr\\u00fcden ge\\u00e7iyordu. A\\u015fa\\u011f\\u0131da Bo\\u011faz siyah ve g\\u00fcm\\u00fc\\u015f rengindeydi, \\u015fehrin \\u0131\\u015f\\u0131klar\\u0131 binlerce minik mum gibi suyun \\u00fcst\\u00fcnde parl\\u0131yordu. Deniz bu k\\u00f6pr\\u00fcden y\\u00fczlerce kez ge\\u00e7mi\\u015fti ama onu hi\\u00e7 ger\\u00e7ekten g\\u00f6rmemi\\u015fti.\"},{\"en\":\"They talked for the rest of the journey. He asked about her studies, her dreams, the things she loved as a child. She told him she wanted to be an architect, but that she was too busy to draw anymore. \\\"Busy is a word we use when we\'re afraid,\\\" he said.\",\"tr\":\"Yolculu\\u011fun geri kalan\\u0131nda konu\\u015ftular. Ona derslerini, hayallerini, \\u00e7ocukken sevdi\\u011fi \\u015feyleri sordu. Deniz mimar olmak istedi\\u011fini ama art\\u0131k \\u00e7izim yapamayacak kadar me\\u015fgul oldu\\u011funu anlatt\\u0131. \\\"Me\\u015fgul, korktu\\u011fumuzda kulland\\u0131\\u011f\\u0131m\\u0131z bir kelimedir,\\\" dedi adam.\"},{\"en\":\"When the bus reached Kad\\u0131k\\u00f6y, Deniz stood up to thank him. But the seat across from her was empty. She looked down the bus. There was nobody there. Only the newspaper was on the seat, folded neatly. The date at the top was the fourteenth of March, 1987.\",\"tr\":\"Otob\\u00fcs Kad\\u0131k\\u00f6y\'e vard\\u0131\\u011f\\u0131nda Deniz ona te\\u015fekk\\u00fcr etmek i\\u00e7in aya\\u011fa kalkt\\u0131. Ama kar\\u015f\\u0131s\\u0131ndaki koltuk bo\\u015ftu. Otob\\u00fcs\\u00fcn i\\u00e7ine bakt\\u0131. Kimse yoktu. Koltukta yaln\\u0131zca \\u00f6zenle katlanm\\u0131\\u015f gazete duruyordu. En \\u00fcstteki tarih 14 Mart 1987\'ydi.\"},{\"en\":\"\\\"Did you see where the old man went?\\\" she asked the driver. He looked at her in the mirror. \\\"What old man? You were alone the whole time.\\\" Deniz took the newspaper and walked home in the rain, her heart beating fast.\",\"tr\":\"\\\"Ya\\u015fl\\u0131 adam\\u0131n nereye gitti\\u011fini g\\u00f6rd\\u00fcn\\u00fcz m\\u00fc?\\\" diye sordu \\u015fof\\u00f6re. \\u015eof\\u00f6r aynadan ona bakt\\u0131. \\\"Hangi ya\\u015fl\\u0131 adam? B\\u00fct\\u00fcn yol boyunca yaln\\u0131zd\\u0131n\\u0131z.\\\" Deniz gazeteyi ald\\u0131 ve kalbi h\\u0131zla \\u00e7arparak ya\\u011fmurun alt\\u0131nda eve y\\u00fcr\\u00fcd\\u00fc.\"},{\"en\":\"She studied the second chapter until two in the morning. The next day, question four was exactly about it. She passed with the highest mark in her class. That evening, she showed the newspaper to her mother. Her mother went pale.\",\"tr\":\"Gece ikiye kadar ikinci b\\u00f6l\\u00fcm\\u00fc \\u00e7al\\u0131\\u015ft\\u0131. Ertesi g\\u00fcn d\\u00f6rd\\u00fcnc\\u00fc soru tam olarak oradan geldi. S\\u0131n\\u0131f\\u0131n\\u0131n en y\\u00fcksek notuyla ge\\u00e7ti. O ak\\u015fam gazeteyi annesine g\\u00f6sterdi. Annesinin y\\u00fcz\\u00fc bembeyaz oldu.\"},{\"en\":\"\\\"Your grandfather took the night bus every day,\\\" she said. \\\"He was an engineer, but he always wanted to be an architect. He died the year you were born. On the fourteenth of March.\\\" Deniz didn\'t say anything. But that night, for the first time in years, she sat down and started to draw.\",\"tr\":\"\\\"Deden her g\\u00fcn gece otob\\u00fcs\\u00fcne binerdi,\\\" dedi. \\\"M\\u00fchendisti ama hep mimar olmak istemi\\u015fti. Sen do\\u011fdu\\u011fun y\\u0131l \\u00f6ld\\u00fc. 14 Mart\'ta.\\\" Deniz hi\\u00e7bir \\u015fey s\\u00f6ylemedi. Ama o gece, y\\u0131llar sonra ilk kez oturdu ve \\u00e7izmeye ba\\u015flad\\u0131.\"}]','[{\"word\":\"ferry\",\"meaning\":\"vapur, feribot\",\"example\":\"We took the ferry to the island.\"},{\"word\":\"stranger\",\"meaning\":\"yabanc\\u0131\",\"example\":\"Don\'t get into a car with a stranger.\"},{\"word\":\"fold\",\"meaning\":\"katlamak\",\"example\":\"She folded the letter and put it in her bag.\"},{\"word\":\"journey\",\"meaning\":\"yolculuk\",\"example\":\"The journey took six hours.\"},{\"word\":\"neatly\",\"meaning\":\"d\\u00fczg\\u00fcnce, \\u00f6zenle\",\"example\":\"His clothes were folded neatly.\"},{\"word\":\"go pale\",\"meaning\":\"benzi atmak, sararmak\",\"example\":\"He went pale when he heard the news.\"}]','[{\"q\":\"Why did Deniz take the night bus?\",\"options\":[\"She wanted to see the bridge\",\"She missed the last ferry\",\"Her car broke down\"],\"answer\":1},{\"q\":\"What did the man say about the word \'busy\'?\",\"options\":[\"It means you are successful\",\"We use it when we\'re afraid\",\"Students use it too much\"],\"answer\":1},{\"q\":\"Who was the old man probably?\",\"options\":[\"The bus driver\'s father\",\"Deniz\'s teacher\",\"Deniz\'s grandfather\"],\"answer\":2}]',1,1,0,'2026-09-29 20:30:40','2026-10-04 20:30:40','2026-10-04 20:30:40'),
(11,'the-chess-player','The Chess Player','Satranç Oyuncusu','A quiet girl from a village school challenges the city champion. Nobody expects her to win, least of all herself.','B1','Eğlence','/img/stories/the-chess-player.webp',NULL,4,486,'[{\"en\":\"Nobody at Hasan Kale Village School knew how to play chess, so Ay\\u015fe learned from an old book she found in the library. The pieces were missing, so she made her own from bottle caps. She played against herself every evening, after she helped her mother with the goats.\",\"tr\":\"Hasan Kale K\\u00f6y Okulu\'nda kimse satran\\u00e7 oynamay\\u0131 bilmiyordu, bu y\\u00fczden Ay\\u015fe k\\u00fct\\u00fcphanede buldu\\u011fu eski bir kitaptan \\u00f6\\u011frendi. Ta\\u015flar eksikti, o da \\u015fi\\u015fe kapaklar\\u0131ndan kendi ta\\u015flar\\u0131n\\u0131 yapt\\u0131. Her ak\\u015fam annesine ke\\u00e7ilerde yard\\u0131m ettikten sonra kendisine kar\\u015f\\u0131 oynard\\u0131.\"},{\"en\":\"Her new teacher, Mr Burak, saw the bottle caps one day and laughed. Then he played against her and lost in twenty minutes. He played again and lost again. \\\"Who taught you?\\\" he asked. \\\"The book,\\\" Ay\\u015fe said, embarrassed. \\\"Is it wrong?\\\"\",\"tr\":\"Yeni \\u00f6\\u011fretmeni Burak Bey bir g\\u00fcn \\u015fi\\u015fe kapaklar\\u0131n\\u0131 g\\u00f6rd\\u00fc ve g\\u00fcld\\u00fc. Sonra ona kar\\u015f\\u0131 oynad\\u0131 ve yirmi dakikada kaybetti. Bir daha oynad\\u0131 ve yine kaybetti. \\\"Sana kim \\u00f6\\u011fretti?\\\" diye sordu. \\\"Kitap,\\\" dedi Ay\\u015fe utanarak. \\\"Yanl\\u0131\\u015f m\\u0131?\\\"\"},{\"en\":\"Mr Burak entered her into the city tournament in Erzurum. Ay\\u015fe had never been to the city. She had never seen so many children with expensive chess clocks, private coaches and matching team jackets. She wore her cousin\'s old coat, and it was too big for her.\",\"tr\":\"Burak Bey onu Erzurum\'daki \\u015fehir turnuvas\\u0131na yazd\\u0131rd\\u0131. Ay\\u015fe daha \\u00f6nce hi\\u00e7 \\u015fehre gitmemi\\u015fti. Pahal\\u0131 satran\\u00e7 saatleri, \\u00f6zel antren\\u00f6rleri ve ayn\\u0131 tak\\u0131m montlar\\u0131 olan bu kadar \\u00e7ok \\u00e7ocu\\u011fu hi\\u00e7 g\\u00f6rmemi\\u015fti. Kuzeninin eski paltosunu giymi\\u015fti ve palto ona b\\u00fcy\\u00fckt\\u00fc.\"},{\"en\":\"Some children laughed when she didn\'t know how to use the clock. In the first game, she was so nervous that she forgot to press it and almost lost on time. But then something changed. She looked at the board, and the room disappeared. It was just her, the pieces and the quiet, like every evening at home.\",\"tr\":\"Saati nas\\u0131l kullanaca\\u011f\\u0131n\\u0131 bilmeyince baz\\u0131 \\u00e7ocuklar g\\u00fcld\\u00fc. \\u0130lk oyunda o kadar gergindi ki saate basmay\\u0131 unuttu ve neredeyse s\\u00fcreden kaybediyordu. Ama sonra bir \\u015fey de\\u011fi\\u015fti. Tahtaya bakt\\u0131 ve oda kayboldu. T\\u0131pk\\u0131 evdeki her ak\\u015fam gibi yaln\\u0131zca o, ta\\u015flar ve sessizlik vard\\u0131.\"},{\"en\":\"She won the first game. Then the second, and the third. By the afternoon, people were standing around her table to watch. They whispered: \\\"Who is she? Which club is she from?\\\" Mr Burak just smiled and said, \\\"The library club.\\\"\",\"tr\":\"\\u0130lk oyunu kazand\\u0131. Sonra ikinciyi ve \\u00fc\\u00e7\\u00fcnc\\u00fcy\\u00fc. \\u00d6\\u011fleden sonra insanlar onu izlemek i\\u00e7in masas\\u0131n\\u0131n etraf\\u0131nda toplanm\\u0131\\u015ft\\u0131. F\\u0131s\\u0131lda\\u015f\\u0131yorlard\\u0131: \\\"Kim bu? Hangi kul\\u00fcpten?\\\" Burak Bey yaln\\u0131zca g\\u00fcl\\u00fcmsedi ve \\\"K\\u00fct\\u00fcphane kul\\u00fcb\\u00fcnden,\\\" dedi.\"},{\"en\":\"In the final, she played against Kaan, the city champion for three years. He was confident and fast. He moved his pieces before she even finished thinking. After an hour, Ay\\u015fe was losing badly. She had only her king, a knight and three small pawns left.\",\"tr\":\"Finalde \\u00fc\\u00e7 y\\u0131ld\\u0131r \\u015fehir \\u015fampiyonu olan Kaan\'la oynad\\u0131. Kendinden emin ve h\\u0131zl\\u0131yd\\u0131. O daha d\\u00fc\\u015f\\u00fcnmeyi bitirmeden ta\\u015flar\\u0131n\\u0131 oynuyordu. Bir saat sonra Ay\\u015fe k\\u00f6t\\u00fc bir \\u015fekilde kaybediyordu. Elinde yaln\\u0131zca \\u015fah\\u0131, bir at\\u0131 ve \\u00fc\\u00e7 k\\u00fc\\u00e7\\u00fck piyonu kalm\\u0131\\u015ft\\u0131.\"},{\"en\":\"Then she remembered a page from the old book, a page with a coffee stain on it. It showed a trap, a way to use a knight to protect a pawn until it reached the end of the board. She had practised it with bottle caps a hundred times.\",\"tr\":\"Sonra eski kitaptaki bir sayfay\\u0131 hat\\u0131rlad\\u0131, \\u00fcst\\u00fcnde kahve lekesi olan bir sayfay\\u0131. Bir tuzak g\\u00f6steriyordu: bir piyonu tahtan\\u0131n sonuna ula\\u015fana kadar atla koruman\\u0131n yolunu. Bunu \\u015fi\\u015fe kapaklar\\u0131yla y\\u00fcz kez denemi\\u015fti.\"},{\"en\":\"Kaan didn\'t see it coming. He moved too fast, as always. Slowly, step by step, Ay\\u015fe\'s little pawn walked across the board. When it reached the last square, it became a queen. Four moves later, it was checkmate. The room was completely silent, and then everyone started clapping.\",\"tr\":\"Kaan bunun geldi\\u011fini g\\u00f6rmedi. Her zamanki gibi \\u00e7ok h\\u0131zl\\u0131 oynad\\u0131. Yava\\u015f yava\\u015f, ad\\u0131m ad\\u0131m, Ay\\u015fe\'nin k\\u00fc\\u00e7\\u00fck piyonu tahtada ilerledi. Son kareye ula\\u015ft\\u0131\\u011f\\u0131nda vezir oldu. D\\u00f6rt hamle sonra \\u015fah matt\\u0131. Oda tamamen sessizdi, sonra herkes alk\\u0131\\u015flamaya ba\\u015flad\\u0131.\"},{\"en\":\"Kaan shook her hand. He looked surprised, but not angry. \\\"Where did you learn that ending?\\\" he asked. Ay\\u015fe took the old book out of her bag. The cover was falling off. \\\"Can I borrow it?\\\" he asked. \\\"Only if you come and play at my school,\\\" she said.\",\"tr\":\"Kaan elini s\\u0131kt\\u0131. \\u015ea\\u015f\\u0131rm\\u0131\\u015f g\\u00f6r\\u00fcn\\u00fcyordu ama k\\u0131zg\\u0131n de\\u011fildi. \\\"O oyun sonunu nerede \\u00f6\\u011frendin?\\\" diye sordu. Ay\\u015fe eski kitab\\u0131 \\u00e7antas\\u0131ndan \\u00e7\\u0131kard\\u0131. Kapa\\u011f\\u0131 d\\u00f6k\\u00fcl\\u00fcyordu. \\\"\\u00d6d\\u00fcn\\u00e7 alabilir miyim?\\\" diye sordu Kaan. \\\"Ancak okuluma gelip oynarsan,\\\" dedi Ay\\u015fe.\"},{\"en\":\"A month later, a box arrived at Hasan Kale Village School. Inside, there were ten chess sets, ten clocks and a note: \\\"From the Erzurum Chess Club. For the library club. P.S. Kaan is coming on Saturday.\\\" Ay\\u015fe kept her bottle caps, though. They were still her favourite pieces.\",\"tr\":\"Bir ay sonra Hasan Kale K\\u00f6y Okulu\'na bir kutu geldi. \\u0130\\u00e7inde on satran\\u00e7 tak\\u0131m\\u0131, on saat ve bir not vard\\u0131: \\\"Erzurum Satran\\u00e7 Kul\\u00fcb\\u00fc\'nden. K\\u00fct\\u00fcphane kul\\u00fcb\\u00fc i\\u00e7in. Not: Kaan cumartesi geliyor.\\\" Ay\\u015fe yine de \\u015fi\\u015fe kapaklar\\u0131n\\u0131 saklad\\u0131. H\\u00e2l\\u00e2 en sevdi\\u011fi ta\\u015flar onlard\\u0131.\"}]','[{\"word\":\"tournament\",\"meaning\":\"turnuva\",\"example\":\"Our team won the football tournament.\"},{\"word\":\"embarrassed\",\"meaning\":\"utanm\\u0131\\u015f, mahcup\",\"example\":\"I was embarrassed when I forgot his name.\"},{\"word\":\"confident\",\"meaning\":\"kendinden emin\",\"example\":\"She felt confident before the interview.\"},{\"word\":\"stain\",\"meaning\":\"leke\",\"example\":\"There is a coffee stain on my shirt.\"},{\"word\":\"trap\",\"meaning\":\"tuzak\",\"example\":\"The mouse walked into the trap.\"},{\"word\":\"borrow\",\"meaning\":\"\\u00f6d\\u00fcn\\u00e7 almak\",\"example\":\"Can I borrow your pen?\"}]','[{\"q\":\"How did Ay\\u015fe learn chess?\",\"options\":[\"From her teacher\",\"From an old library book\",\"From the internet\"],\"answer\":1},{\"q\":\"Why did Ay\\u015fe almost lose her first game?\",\"options\":[\"She forgot to press the clock\",\"She arrived late\",\"She didn\'t know the rules\"],\"answer\":0},{\"q\":\"What did the chess club send to the school?\",\"options\":[\"A trophy\",\"Bottle caps\",\"Chess sets and clocks\"],\"answer\":2}]',1,1,0,'2026-09-30 20:30:40','2026-10-04 20:30:40','2026-10-04 20:30:40'),
(12,'the-voice-message','The Voice Message','Sesli Mesaj','A voice message is sent to the wrong number. Mert decides to answer it, and changes a stranger\'s day.','B1','Günlük Hayat','/img/stories/the-voice-message.webp',NULL,4,481,'[{\"en\":\"Mert was waiting for the metro when his phone buzzed. It was a voice message from a number he didn\'t know. He almost deleted it, but something made him press play. It was a young woman\'s voice, shaking and nervous.\",\"tr\":\"Mert metroyu beklerken telefonu titredi. Tan\\u0131mad\\u0131\\u011f\\u0131 bir numaradan gelen sesli bir mesajd\\u0131. Neredeyse silecekti ama bir \\u015fey onu oynat tu\\u015funa basmaya itti. Gen\\u00e7 bir kad\\u0131n\\u0131n sesiydi, titrek ve gergin.\"},{\"en\":\"\\\"Hi Dad. It\'s me, Selin. I know we haven\'t spoken for two years. I\'m sorry about everything I said. Today is my graduation, and I... I just wanted you to know. It starts at four, at the university. You don\'t have to come. I just wanted you to know.\\\"\",\"tr\":\"\\\"Merhaba baba. Benim, Selin. \\u0130ki y\\u0131ld\\u0131r konu\\u015fmad\\u0131\\u011f\\u0131m\\u0131z\\u0131 biliyorum. S\\u00f6yledi\\u011fim her \\u015fey i\\u00e7in \\u00f6z\\u00fcr dilerim. Bug\\u00fcn mezuniyetim ve ben... sadece bilmeni istedim. Saat d\\u00f6rtte \\u00fcniversitede ba\\u015fl\\u0131yor. Gelmek zorunda de\\u011filsin. Sadece bilmeni istedim.\\\"\"},{\"en\":\"Mert listened to it twice. Clearly, Selin had the wrong number. Somewhere in the city, a father was not going to hear this message, and a daughter was going to look at the door all afternoon, waiting.\",\"tr\":\"Mert mesaj\\u0131 iki kez dinledi. Belli ki Selin yanl\\u0131\\u015f numaray\\u0131 aram\\u0131\\u015ft\\u0131. \\u015eehrin bir yerinde bir baba bu mesaj\\u0131 duymayacakt\\u0131, bir k\\u0131z da b\\u00fct\\u00fcn \\u00f6\\u011fleden sonra kap\\u0131ya bak\\u0131p bekleyecekti.\"},{\"en\":\"He wrote a reply, then deleted it. What could he say? \\\"Sorry, wrong number\\\" felt cruel. He thought about it all the way to work. At lunch, he finally sent a short message: \\\"Hi Selin. I\'m not your dad, I\'m sorry. Your number is one digit wrong, maybe. Do you want me to help you find the right one?\\\"\",\"tr\":\"Bir cevap yazd\\u0131, sonra sildi. Ne diyebilirdi ki? \\\"\\u00dczg\\u00fcn\\u00fcm, yanl\\u0131\\u015f numara\\\" demek ac\\u0131mas\\u0131z geliyordu. \\u0130\\u015fe giderken b\\u00fct\\u00fcn yol bunu d\\u00fc\\u015f\\u00fcnd\\u00fc. \\u00d6\\u011fle yeme\\u011finde sonunda k\\u0131sa bir mesaj g\\u00f6nderdi: \\\"Merhaba Selin. Ben baban de\\u011filim, \\u00fczg\\u00fcn\\u00fcm. Belki numaranda bir rakam yanl\\u0131\\u015f. Do\\u011frusunu bulmana yard\\u0131m etmemi ister misin?\\\"\"},{\"en\":\"The answer came after ten minutes. \\\"Oh no. I\'m so embarrassed. I found his number on an old card. I don\'t know the right one. He changed his phone after we argued. Forget it. It was a stupid idea anyway.\\\"\",\"tr\":\"Cevap on dakika sonra geldi. \\\"Olamaz. \\u00c7ok utand\\u0131m. Numaras\\u0131n\\u0131 eski bir kartta bulmu\\u015ftum. Do\\u011frusunu bilmiyorum. Tart\\u0131\\u015ft\\u0131ktan sonra telefonunu de\\u011fi\\u015ftirdi. Bo\\u015f ver. Zaten aptalca bir fikirdi.\\\"\"},{\"en\":\"Mert looked at the message for a long time. Then he asked for her father\'s name and where he worked. \\\"Hakan Yal\\u00e7\\u0131n. He has a small shoe repair shop in Karak\\u00f6y. Why?\\\" Mert didn\'t answer. He told his boss he had a dentist appointment and left the office at two.\",\"tr\":\"Mert mesaja uzun s\\u00fcre bakt\\u0131. Sonra babas\\u0131n\\u0131n ad\\u0131n\\u0131 ve nerede \\u00e7al\\u0131\\u015ft\\u0131\\u011f\\u0131n\\u0131 sordu. \\\"Hakan Yal\\u00e7\\u0131n. Karak\\u00f6y\'de k\\u00fc\\u00e7\\u00fck bir ayakkab\\u0131 tamircisi var. Neden?\\\" Mert cevap vermedi. Patronuna di\\u015f\\u00e7i randevusu oldu\\u011funu s\\u00f6yledi ve saat ikide ofisten \\u00e7\\u0131kt\\u0131.\"},{\"en\":\"Finding the shop wasn\'t easy. There were dozens of narrow streets and hundreds of small shops. At three fifteen, he finally saw an old sign: Yal\\u00e7\\u0131n Shoe Repair. Inside, a grey-haired man was fixing a boot, alone, with the radio on.\",\"tr\":\"D\\u00fckk\\u00e2n\\u0131 bulmak kolay de\\u011fildi. Onlarca dar sokak ve y\\u00fczlerce k\\u00fc\\u00e7\\u00fck d\\u00fckk\\u00e2n vard\\u0131. Saat \\u00fc\\u00e7\\u00fc \\u00e7eyrek ge\\u00e7e sonunda eski bir tabela g\\u00f6rd\\u00fc: Yal\\u00e7\\u0131n Ayakkab\\u0131 Tamiri. \\u0130\\u00e7eride gri sa\\u00e7l\\u0131 bir adam radyo a\\u00e7\\u0131k, tek ba\\u015f\\u0131na bir botu tamir ediyordu.\"},{\"en\":\"\\\"Mr Hakan?\\\" Mert said. \\\"I have a message for you. It\'s from Selin.\\\" The man stopped working. Mert held out his phone and pressed play. Hakan listened without moving. When it finished, he put down his tools and covered his face with his hands.\",\"tr\":\"\\\"Hakan Bey?\\\" dedi Mert. \\\"Size bir mesaj\\u0131m var. Selin\'den.\\\" Adam \\u00e7al\\u0131\\u015fmay\\u0131 b\\u0131rakt\\u0131. Mert telefonunu uzatt\\u0131 ve oynata bast\\u0131. Hakan k\\u0131p\\u0131rdamadan dinledi. Mesaj bitince aletlerini b\\u0131rakt\\u0131 ve y\\u00fcz\\u00fcn\\u00fc elleriyle kapad\\u0131.\"},{\"en\":\"\\\"What time is it?\\\" he asked. \\\"Three twenty,\\\" said Mert. Hakan took off his apron, locked the shop and they both ran to the main road. The traffic was terrible, so they took the ferry and then a taxi. Hakan didn\'t say a word the whole way. He just held a small box in his hands.\",\"tr\":\"\\\"Saat ka\\u00e7?\\\" diye sordu. \\\"\\u00dc\\u00e7\\u00fc yirmi ge\\u00e7iyor,\\\" dedi Mert. Hakan \\u00f6nl\\u00fc\\u011f\\u00fcn\\u00fc \\u00e7\\u0131kard\\u0131, d\\u00fckk\\u00e2n\\u0131 kilitledi ve ikisi ana caddeye ko\\u015ftular. Trafik berbatt\\u0131, bu y\\u00fczden vapura sonra da taksiye bindiler. Hakan b\\u00fct\\u00fcn yol tek kelime etmedi. Sadece ellerinde k\\u00fc\\u00e7\\u00fck bir kutu tutuyordu.\"},{\"en\":\"They arrived at four twelve. The ceremony had started. Mert stayed at the back. He saw Hakan walk slowly down the aisle, and he saw a young woman in a black gown turn around and freeze. Then she ran. Mert didn\'t wait to see the rest. He went back to work, and for the rest of the week, he couldn\'t stop smiling.\",\"tr\":\"D\\u00f6rd\\u00fc on iki ge\\u00e7e vard\\u0131lar. T\\u00f6ren ba\\u015flam\\u0131\\u015ft\\u0131. Mert arkada kald\\u0131. Hakan\'\\u0131n koridorda yava\\u015f\\u00e7a y\\u00fcr\\u00fcd\\u00fc\\u011f\\u00fcn\\u00fc g\\u00f6rd\\u00fc, siyah c\\u00fcppeli gen\\u00e7 bir kad\\u0131n\\u0131n arkas\\u0131n\\u0131 d\\u00f6n\\u00fcp donakald\\u0131\\u011f\\u0131n\\u0131 g\\u00f6rd\\u00fc. Sonra kad\\u0131n ko\\u015ftu. Mert gerisini g\\u00f6rmek i\\u00e7in beklemedi. \\u0130\\u015fe geri d\\u00f6nd\\u00fc ve haftan\\u0131n geri kalan\\u0131nda g\\u00fcl\\u00fcmsemeden duramad\\u0131.\"}]','[{\"word\":\"buzz\",\"meaning\":\"titremek (telefon)\",\"example\":\"My phone buzzed during the meeting.\"},{\"word\":\"graduation\",\"meaning\":\"mezuniyet\",\"example\":\"My parents came to my graduation.\"},{\"word\":\"cruel\",\"meaning\":\"ac\\u0131mas\\u0131z, zalim\",\"example\":\"It was cruel to laugh at him.\"},{\"word\":\"digit\",\"meaning\":\"rakam, hane\",\"example\":\"The code has six digits.\"},{\"word\":\"appointment\",\"meaning\":\"randevu\",\"example\":\"I have a dentist appointment at three.\"},{\"word\":\"freeze\",\"meaning\":\"donakalmak\",\"example\":\"She froze when she saw the snake.\"}]','[{\"q\":\"Why did Selin\'s message go to Mert?\",\"options\":[\"She sent it on purpose\",\"She used an old, wrong number\",\"Mert stole her phone\"],\"answer\":1},{\"q\":\"Where did Selin\'s father work?\",\"options\":[\"At a university\",\"In a shoe repair shop\",\"On a ferry\"],\"answer\":1},{\"q\":\"What did Mert do after they arrived?\",\"options\":[\"He gave a speech\",\"He went back to work\",\"He met Selin\"],\"answer\":1}]',1,1,0,'2026-10-01 20:30:40','2026-10-04 20:30:40','2026-10-04 20:30:40'),
(13,'the-map-under-the-floor','The Map Under the Floor','Döşemenin Altındaki Harita','While renovating an old flat in Galata, an architect finds a hand-drawn map hidden beneath the floorboards. It leads somewhere nobody expected.','B2','Gizem','/img/stories/the-map-under-the-floor.webp',NULL,5,582,'[{\"en\":\"When Arda bought the crumbling flat in Galata, his friends thought he had lost his mind. The windows were broken, the ceiling leaked, and the previous owner, an elderly watchmaker named Agop, had lived there alone for over sixty years. But Arda was an architect, and he could see what the flat could become.\",\"tr\":\"Arda Galata\'daki d\\u00f6k\\u00fclen daireyi sat\\u0131n ald\\u0131\\u011f\\u0131nda arkada\\u015flar\\u0131 akl\\u0131n\\u0131 ka\\u00e7\\u0131rd\\u0131\\u011f\\u0131n\\u0131 d\\u00fc\\u015f\\u00fcnd\\u00fc. Pencereler k\\u0131r\\u0131kt\\u0131, tavan ak\\u0131t\\u0131yordu ve \\u00f6nceki sahibi, Agop ad\\u0131nda ya\\u015fl\\u0131 bir saat\\u00e7i, orada altm\\u0131\\u015f y\\u0131l\\u0131 a\\u015fk\\u0131n s\\u00fcre yaln\\u0131z ya\\u015fam\\u0131\\u015ft\\u0131. Ama Arda bir mimard\\u0131 ve dairenin neye d\\u00f6n\\u00fc\\u015febilece\\u011fini g\\u00f6rebiliyordu.\"},{\"en\":\"On the third week of renovation, one of the floorboards in the bedroom sounded hollow. Arda lifted it with a screwdriver and found a tin box wrapped in oilcloth. Inside, carefully folded, was a map of the neighbourhood drawn in faded blue ink. Seven small crosses were marked on it, each with a date beside it, all from 1955.\",\"tr\":\"Tadilat\\u0131n \\u00fc\\u00e7\\u00fcnc\\u00fc haftas\\u0131nda yatak odas\\u0131ndaki d\\u00f6\\u015feme tahtalar\\u0131ndan biri bo\\u015f ses \\u00e7\\u0131kard\\u0131. Arda tahtay\\u0131 bir tornavidayla kald\\u0131rd\\u0131 ve mu\\u015fambaya sar\\u0131lm\\u0131\\u015f teneke bir kutu buldu. \\u0130\\u00e7inde \\u00f6zenle katlanm\\u0131\\u015f, soluk mavi m\\u00fcrekkeple \\u00e7izilmi\\u015f bir mahalle haritas\\u0131 vard\\u0131. \\u00dcst\\u00fcnde yedi k\\u00fc\\u00e7\\u00fck \\u00e7arp\\u0131 i\\u015fareti vard\\u0131, her birinin yan\\u0131nda bir tarih ve hepsi 1955\'tendi.\"},{\"en\":\"At first, Arda assumed it was a treasure map, and he felt slightly ridiculous for being excited. But the crosses didn\'t mark empty places. When he compared the map with an old city plan, he realised that each cross marked a house, and that almost all of those houses had belonged to families who had left Istanbul in the autumn of that year.\",\"tr\":\"\\u0130lk ba\\u015fta Arda bunun bir hazine haritas\\u0131 oldu\\u011funu varsayd\\u0131 ve heyecanland\\u0131\\u011f\\u0131 i\\u00e7in kendini biraz g\\u00fcl\\u00fcn\\u00e7 hissetti. Ama \\u00e7arp\\u0131lar bo\\u015f yerleri i\\u015faretlemiyordu. Haritay\\u0131 eski bir \\u015fehir plan\\u0131yla kar\\u015f\\u0131la\\u015ft\\u0131rd\\u0131\\u011f\\u0131nda her \\u00e7arp\\u0131n\\u0131n bir evi g\\u00f6sterdi\\u011fini ve bu evlerin neredeyse hepsinin o y\\u0131l\\u0131n sonbahar\\u0131nda \\u0130stanbul\'dan ayr\\u0131lm\\u0131\\u015f ailelere ait oldu\\u011funu fark etti.\"},{\"en\":\"Under the map, there was a notebook. The handwriting was small and precise, the writing of someone used to working with tiny parts. It was a list of objects: a silver pocket watch, a wedding ring, a child\'s music box, a set of keys. Next to each object was a name and, in some cases, an address in Athens, Marseille or Montreal.\",\"tr\":\"Haritan\\u0131n alt\\u0131nda bir defter vard\\u0131. El yaz\\u0131s\\u0131 k\\u00fc\\u00e7\\u00fck ve titizdi, minik par\\u00e7alarla \\u00e7al\\u0131\\u015fmaya al\\u0131\\u015fk\\u0131n birinin yaz\\u0131s\\u0131yd\\u0131. Bir nesne listesiydi: g\\u00fcm\\u00fc\\u015f bir cep saati, bir alyans, bir \\u00e7ocu\\u011fun m\\u00fczik kutusu, bir anahtarl\\u0131k. Her nesnenin yan\\u0131nda bir isim ve baz\\u0131lar\\u0131nda Atina, Marsilya ya da Montreal\'de bir adres vard\\u0131.\"},{\"en\":\"Arda spent the following weekend searching the rest of the flat. Behind a false wall in the workshop, he found a wooden cabinet with dozens of tiny drawers. In every drawer, wrapped in tissue paper and labelled, was one of the objects from the notebook. Agop had not stolen them. He had kept them safe.\",\"tr\":\"Arda sonraki hafta sonunu dairenin geri kalan\\u0131n\\u0131 arayarak ge\\u00e7irdi. At\\u00f6lyedeki sahte bir duvar\\u0131n arkas\\u0131nda onlarca minik \\u00e7ekmeceli ah\\u015fap bir dolap buldu. Her \\u00e7ekmecede, k\\u00e2\\u011f\\u0131t mendile sar\\u0131lm\\u0131\\u015f ve etiketlenmi\\u015f halde, defterdeki nesnelerden biri vard\\u0131. Agop onlar\\u0131 \\u00e7almam\\u0131\\u015ft\\u0131. Onlar\\u0131 g\\u00fcvende tutmu\\u015ftu.\"},{\"en\":\"The last pages of the notebook explained everything. Neighbours had brought him their most precious belongings during a frightening time, asking him to look after them until they could return. Most of them never did. For decades, Agop had written letters to every address he could find. Some had been answered. Most had come back unopened.\",\"tr\":\"Defterin son sayfalar\\u0131 her \\u015feyi a\\u00e7\\u0131kl\\u0131yordu. Kom\\u015fular korkutucu bir d\\u00f6nemde en de\\u011ferli e\\u015fyalar\\u0131n\\u0131 ona getirmi\\u015f, d\\u00f6nebilecekleri zamana kadar onlara g\\u00f6z kulak olmas\\u0131n\\u0131 istemi\\u015flerdi. \\u00c7o\\u011fu hi\\u00e7 d\\u00f6nmedi. Agop on y\\u0131llar boyunca bulabildi\\u011fi her adrese mektup yazm\\u0131\\u015ft\\u0131. Baz\\u0131lar\\u0131na cevap gelmi\\u015fti. \\u00c7o\\u011fu a\\u00e7\\u0131lmadan geri d\\u00f6nm\\u00fc\\u015ft\\u00fc.\"},{\"en\":\"The final entry was written in a shakier hand, only a month before Agop\'s death: \\\"Eleven still waiting. I am too old to finish this. I hope whoever finds them will be more patient than time.\\\" Arda closed the notebook and sat in the dusty workshop until it was dark.\",\"tr\":\"Son not daha titrek bir el yaz\\u0131s\\u0131yla, Agop\'un \\u00f6l\\u00fcm\\u00fcnden yaln\\u0131zca bir ay \\u00f6nce yaz\\u0131lm\\u0131\\u015ft\\u0131: \\\"On bir tanesi h\\u00e2l\\u00e2 bekliyor. Bunu bitiremeyecek kadar ya\\u015fl\\u0131y\\u0131m. Umar\\u0131m onlar\\u0131 bulan ki\\u015fi zamandan daha sab\\u0131rl\\u0131 olur.\\\" Arda defteri kapad\\u0131 ve hava kararana kadar tozlu at\\u00f6lyede oturdu.\"},{\"en\":\"The renovation stopped. Instead, Arda spent the next year writing emails, calling consulates, and posting photographs of the objects on social media with the hashtag #AgopsDrawers. At first, nothing happened. Then a journalist in Athens shared the post, and within a week it had been seen by two million people.\",\"tr\":\"Tadilat durdu. Arda bunun yerine sonraki y\\u0131l\\u0131 e-posta yazarak, konsolosluklar\\u0131 arayarak ve nesnelerin foto\\u011fraflar\\u0131n\\u0131 #AgopunCekmeceleri etiketiyle sosyal medyada payla\\u015farak ge\\u00e7irdi. \\u0130lk ba\\u015fta hi\\u00e7bir \\u015fey olmad\\u0131. Sonra Atina\'da bir gazeteci payla\\u015f\\u0131m\\u0131 yayd\\u0131 ve bir hafta i\\u00e7inde iki milyon ki\\u015fi taraf\\u0131ndan g\\u00f6r\\u00fcld\\u00fc.\"},{\"en\":\"Messages began to arrive from all over the world. A retired teacher in Montreal recognised her grandmother\'s music box from a family photograph. A man in Marseille, now ninety-one, wrote that he had been seven years old when his father left a pocket watch with \\\"the kind watchmaker on the corner\\\". He had always believed it was lost.\",\"tr\":\"D\\u00fcnyan\\u0131n d\\u00f6rt bir yan\\u0131ndan mesajlar gelmeye ba\\u015flad\\u0131. Montreal\'de emekli bir \\u00f6\\u011fretmen b\\u00fcy\\u00fckannesinin m\\u00fczik kutusunu bir aile foto\\u011fraf\\u0131ndan tan\\u0131d\\u0131. Marsilya\'da art\\u0131k doksan bir ya\\u015f\\u0131nda olan bir adam, babas\\u0131 \\\"k\\u00f6\\u015fedeki nazik saat\\u00e7iye\\\" bir cep saati b\\u0131rakt\\u0131\\u011f\\u0131nda yedi ya\\u015f\\u0131nda oldu\\u011funu yazd\\u0131. Hep kayboldu\\u011funa inanm\\u0131\\u015ft\\u0131.\"},{\"en\":\"Eighteen months after he lifted the floorboard, Arda placed the last object, a small brass key, into the hands of a woman who had flown from Toronto. She held it for a long time without speaking. Then she asked if she could see the flat. Today, it is no longer for sale. Arda turned the workshop into a tiny museum, and above the door, a sign reads: Agop\'s Drawers, open to anyone who is still waiting.\",\"tr\":\"D\\u00f6\\u015feme tahtas\\u0131n\\u0131 kald\\u0131rmas\\u0131ndan on sekiz ay sonra Arda son nesneyi, k\\u00fc\\u00e7\\u00fck bir pirin\\u00e7 anahtar\\u0131, Toronto\'dan u\\u00e7akla gelen bir kad\\u0131n\\u0131n ellerine b\\u0131rakt\\u0131. Kad\\u0131n konu\\u015fmadan uzun s\\u00fcre tuttu anahtar\\u0131. Sonra daireyi g\\u00f6r\\u00fcp g\\u00f6remeyece\\u011fini sordu. Bug\\u00fcn daire art\\u0131k sat\\u0131l\\u0131k de\\u011fil. Arda at\\u00f6lyeyi minik bir m\\u00fczeye d\\u00f6n\\u00fc\\u015ft\\u00fcrd\\u00fc ve kap\\u0131n\\u0131n \\u00fcst\\u00fcndeki tabelada \\u015f\\u00f6yle yaz\\u0131yor: Agop\'un \\u00c7ekmeceleri, h\\u00e2l\\u00e2 bekleyen herkese a\\u00e7\\u0131k.\"}]','[{\"word\":\"crumbling\",\"meaning\":\"d\\u00f6k\\u00fclen, harap\",\"example\":\"They live in a crumbling old house.\"},{\"word\":\"hollow\",\"meaning\":\"i\\u00e7i bo\\u015f\",\"example\":\"The tree trunk was hollow.\"},{\"word\":\"faded\",\"meaning\":\"solmu\\u015f, soluk\",\"example\":\"She wore a pair of faded jeans.\"},{\"word\":\"precious\",\"meaning\":\"de\\u011ferli, k\\u0131ymetli\",\"example\":\"Her grandmother\'s ring is very precious to her.\"},{\"word\":\"belongings\",\"meaning\":\"e\\u015fyalar\",\"example\":\"Please take all your belongings with you.\"},{\"word\":\"recognise\",\"meaning\":\"tan\\u0131mak\",\"example\":\"I didn\'t recognise him with his new haircut.\"}]','[{\"q\":\"What did the crosses on the map show?\",\"options\":[\"Hidden treasure\",\"Houses of families who left in 1955\",\"Agop\'s favourite caf\\u00e9s\"],\"answer\":1},{\"q\":\"Why did Agop keep the objects?\",\"options\":[\"He wanted to sell them\",\"Neighbours asked him to look after them\",\"He collected antiques\"],\"answer\":1},{\"q\":\"What did Arda do with the workshop in the end?\",\"options\":[\"He sold it\",\"He turned it into a small museum\",\"He used it as his office\"],\"answer\":1},{\"q\":\"How did people around the world find out about the objects?\",\"options\":[\"Through a TV programme\",\"A post was widely shared online\",\"Agop\'s letters\"],\"answer\":1}]',1,1,0,'2026-10-02 20:30:40','2026-10-04 20:30:40','2026-10-04 20:30:40'),
(14,'signal-from-station-nine','Signal from Station Nine','Dokuzuncu İstasyondan Sinyal','On an Antarctic research station, a young engineer picks up a radio signal that repeats every night at 03:17. The station has been empty for thirty years.','B2','Bilim Kurgu','/img/stories/signal-from-station-nine.webp',NULL,5,573,'[{\"en\":\"Defne had been at the Turkish research base in Antarctica for four months when the signal first appeared. It was 03:17, the middle of the polar night, and she was alone in the control room checking the weather equipment. Suddenly, the old radio receiver in the corner, which nobody had used in years, crackled into life.\",\"tr\":\"Sinyal ilk kez ortaya \\u00e7\\u0131kt\\u0131\\u011f\\u0131nda Defne d\\u00f6rt ayd\\u0131r Antarktika\'daki T\\u00fcrk ara\\u015ft\\u0131rma \\u00fcss\\u00fcndeydi. Saat 03.17\'ydi, kutup gecesinin ortas\\u0131yd\\u0131 ve kontrol odas\\u0131nda yaln\\u0131z ba\\u015f\\u0131na hava durumu ekipmanlar\\u0131n\\u0131 kontrol ediyordu. Aniden k\\u00f6\\u015fedeki, y\\u0131llard\\u0131r kimsenin kullanmad\\u0131\\u011f\\u0131 eski radyo al\\u0131c\\u0131s\\u0131 c\\u0131z\\u0131rdayarak canland\\u0131.\"},{\"en\":\"It wasn\'t a voice. It was a series of short and long beeps, repeating the same pattern again and again for exactly four minutes. Then it stopped. Defne recorded the next one the following night, at exactly the same time. Using an online decoder, she discovered it was Morse code. The message was only three words long: STATION NINE RESPOND.\",\"tr\":\"Bir ses de\\u011fildi. Tam d\\u00f6rt dakika boyunca ayn\\u0131 d\\u00fczeni tekrar tekrar yineleyen k\\u0131sa ve uzun bip seslerinden olu\\u015fan bir diziydi. Sonra durdu. Defne bir sonraki sinyali ertesi gece tam ayn\\u0131 saatte kaydetti. \\u00c7evrimi\\u00e7i bir \\u00e7\\u00f6z\\u00fcc\\u00fc kullanarak bunun Mors alfabesi oldu\\u011funu ke\\u015ffetti. Mesaj yaln\\u0131zca \\u00fc\\u00e7 kelimeydi: DOKUZUNCU \\u0130STASYON CEVAP VER.\"},{\"en\":\"The station commander, a calm, sceptical geologist called Orhan, listened to the recording and shrugged. \\\"Probably a ship testing old equipment,\\\" he said. But when Defne checked the database, there was something that made her skin go cold. Station Nine was a Norwegian base, eighty kilometres away. It had been abandoned in 1994 after a fire.\",\"tr\":\"\\u00dcs komutan\\u0131, Orhan ad\\u0131nda sakin ve \\u015f\\u00fcpheci bir jeolog, kayd\\u0131 dinledi ve omuz silkti. \\\"Muhtemelen eski ekipman\\u0131 test eden bir gemi,\\\" dedi. Ama Defne veri taban\\u0131n\\u0131 kontrol etti\\u011finde t\\u00fcylerini diken diken eden bir \\u015fey buldu. Dokuzuncu \\u0130stasyon seksen kilometre uzaktaki bir Norve\\u00e7 \\u00fcss\\u00fcyd\\u00fc. 1994\'teki bir yang\\u0131ndan sonra terk edilmi\\u015fti.\"},{\"en\":\"Defne became obsessed. Every night, she sat in front of the radio at 03:17. She used the station\'s satellite connection to measure the direction of the signal, and the result was always the same: it was coming from Station Nine. Either someone was there, or something was transmitting on its own after thirty years in temperatures of minus sixty degrees.\",\"tr\":\"Defne buna tak\\u0131nt\\u0131l\\u0131 hale geldi. Her gece saat 03.17\'de radyonun ba\\u015f\\u0131na oturdu. Sinyalin y\\u00f6n\\u00fcn\\u00fc \\u00f6l\\u00e7mek i\\u00e7in istasyonun uydu ba\\u011flant\\u0131s\\u0131n\\u0131 kulland\\u0131 ve sonu\\u00e7 her zaman ayn\\u0131yd\\u0131: sinyal Dokuzuncu \\u0130stasyon\'dan geliyordu. Ya orada biri vard\\u0131 ya da bir \\u015fey eksi altm\\u0131\\u015f derecede otuz y\\u0131l sonra kendi kendine yay\\u0131n yap\\u0131yordu.\"},{\"en\":\"Finally, she convinced Orhan to let her visit the base when the weather improved. In early September, they set out on two snowmobiles with a mechanic named Jale. The journey took six hours through a white, featureless landscape. When the dark shapes of Station Nine finally appeared on the horizon, nobody said anything.\",\"tr\":\"Sonunda hava d\\u00fczelince \\u00fcss\\u00fc ziyaret etmesi i\\u00e7in Orhan\'\\u0131 ikna etti. Eyl\\u00fcl ba\\u015f\\u0131nda Jale ad\\u0131nda bir teknisyenle birlikte iki kar motoruyla yola \\u00e7\\u0131kt\\u0131lar. Yolculuk beyaz, hi\\u00e7bir \\u00f6zelli\\u011fi olmayan bir arazide alt\\u0131 saat s\\u00fcrd\\u00fc. Dokuzuncu \\u0130stasyon\'un karanl\\u0131k siluetleri sonunda ufukta g\\u00f6r\\u00fcnd\\u00fc\\u011f\\u00fcnde kimse bir \\u015fey s\\u00f6ylemedi.\"},{\"en\":\"The base was half buried in snow. The main building was blackened by the old fire, but the small radio hut behind it was strangely intact. Inside, they found an automatic transmitter connected to a wind turbine and a box of batteries. Someone had built it with care. A note was taped to the wall, in English, dated March 1994.\",\"tr\":\"\\u00dcs yar\\u0131 yar\\u0131ya kar\\u0131n alt\\u0131ndayd\\u0131. Ana bina eski yang\\u0131ndan kararm\\u0131\\u015ft\\u0131 ama arkas\\u0131ndaki k\\u00fc\\u00e7\\u00fck telsiz kul\\u00fcbesi tuhaf bir \\u015fekilde sa\\u011flamd\\u0131. \\u0130\\u00e7eride bir r\\u00fczg\\u00e2r t\\u00fcrbinine ve bir kutu bataryaya ba\\u011fl\\u0131 otomatik bir verici buldular. Biri onu \\u00f6zenle kurmu\\u015ftu. Duvara \\u0130ngilizce yaz\\u0131lm\\u0131\\u015f, Mart 1994 tarihli bir not yap\\u0131\\u015ft\\u0131r\\u0131lm\\u0131\\u015ft\\u0131.\"},{\"en\":\"\\\"My name is Erik Lund,\\\" it read. \\\"I stayed behind after the fire to save the scientific data while the others were evacuated. The rescue plane cannot land until spring. If I do not make it, this transmitter will keep calling until someone answers. Please tell my daughter, Ingrid, that I kept my promise. I did not leave the work unfinished.\\\"\",\"tr\":\"\\\"Ad\\u0131m Erik Lund,\\\" diye yaz\\u0131yordu. \\\"Di\\u011ferleri tahliye edilirken bilimsel verileri kurtarmak i\\u00e7in yang\\u0131ndan sonra burada kald\\u0131m. Kurtarma u\\u00e7a\\u011f\\u0131 bahara kadar inemiyor. E\\u011fer ba\\u015faramazsam bu verici biri cevap verene kadar \\u00e7a\\u011f\\u0131rmaya devam edecek. L\\u00fctfen k\\u0131z\\u0131m Ingrid\'e s\\u00f6z\\u00fcm\\u00fc tuttu\\u011fumu s\\u00f6yleyin. \\u0130\\u015fi yar\\u0131m b\\u0131rakmad\\u0131m.\\\"\"},{\"en\":\"Under the desk, they found sealed metal cases containing hundreds of ice-core samples and notebooks full of measurements: thirty years of climate data from before the fire, data that scientists around the world had believed was lost forever. Erik\'s body was never found. Orhan, the sceptic, had to sit down.\",\"tr\":\"Masan\\u0131n alt\\u0131nda y\\u00fczlerce buz \\u00e7ekirde\\u011fi \\u00f6rne\\u011fi ve \\u00f6l\\u00e7\\u00fcmlerle dolu defterler i\\u00e7eren m\\u00fch\\u00fcrl\\u00fc metal kasalar buldular: yang\\u0131ndan \\u00f6nceki otuz y\\u0131l\\u0131n iklim verileri, d\\u00fcnyan\\u0131n d\\u00f6rt bir yan\\u0131ndaki bilim insanlar\\u0131n\\u0131n sonsuza kadar kayboldu\\u011funa inand\\u0131\\u011f\\u0131 veriler. Erik\'in cesedi hi\\u00e7 bulunamad\\u0131. \\u015e\\u00fcpheci Orhan oturmak zorunda kald\\u0131.\"},{\"en\":\"Defne reached for the transmitter\'s key, which was still connected, and tapped out a reply in Morse code, slowly and carefully: STATION NINE RECEIVED. WORK COMPLETE. Then she switched it off. For a moment, the only sound was the wind outside.\",\"tr\":\"Defne h\\u00e2l\\u00e2 ba\\u011fl\\u0131 olan vericinin anahtar\\u0131na uzand\\u0131 ve Mors alfabesiyle yava\\u015f\\u00e7a ve dikkatlice bir cevap yazd\\u0131: DOKUZUNCU \\u0130STASYON ALINDI. \\u0130\\u015e TAMAMLANDI. Sonra cihaz\\u0131 kapatt\\u0131. Bir an i\\u00e7in tek ses d\\u0131\\u015far\\u0131daki r\\u00fczg\\u00e2rd\\u0131.\"},{\"en\":\"The data was flown to Oslo that summer and published under Erik Lund\'s name. At the ceremony, a woman in her forties walked up to Defne and introduced herself. Her name was Ingrid. \\\"I was nine when he didn\'t come home,\\\" she said. \\\"Everyone told me he was gone. But somewhere, he was still talking. Thank you for listening.\\\" The radio at the Turkish base has been silent since then, but Defne still wakes up at 03:17 sometimes, just to check.\",\"tr\":\"Veriler o yaz u\\u00e7akla Oslo\'ya g\\u00f6t\\u00fcr\\u00fcld\\u00fc ve Erik Lund\'un ad\\u0131yla yay\\u0131mland\\u0131. T\\u00f6rende k\\u0131rkl\\u0131 ya\\u015flar\\u0131nda bir kad\\u0131n Defne\'nin yan\\u0131na gelip kendini tan\\u0131tt\\u0131. Ad\\u0131 Ingrid\'di. \\\"Eve d\\u00f6nmedi\\u011finde dokuz ya\\u015f\\u0131ndayd\\u0131m,\\\" dedi. \\\"Herkes bana gitti\\u011fini s\\u00f6yledi. Ama bir yerlerde h\\u00e2l\\u00e2 konu\\u015fuyordu. Dinledi\\u011fin i\\u00e7in te\\u015fekk\\u00fcr ederim.\\\" T\\u00fcrk \\u00fcss\\u00fcndeki radyo o zamandan beri sessiz ama Defne h\\u00e2l\\u00e2 bazen sadece kontrol etmek i\\u00e7in 03.17\'de uyan\\u0131yor.\"}]','[{\"word\":\"receiver\",\"meaning\":\"al\\u0131c\\u0131 (cihaz)\",\"example\":\"The radio receiver picked up a weak signal.\"},{\"word\":\"sceptical\",\"meaning\":\"\\u015f\\u00fcpheci\",\"example\":\"Scientists were sceptical about the results.\"},{\"word\":\"abandoned\",\"meaning\":\"terk edilmi\\u015f\",\"example\":\"We explored an abandoned factory.\"},{\"word\":\"obsessed\",\"meaning\":\"tak\\u0131nt\\u0131l\\u0131\",\"example\":\"He is obsessed with football.\"},{\"word\":\"intact\",\"meaning\":\"sa\\u011flam, zarar g\\u00f6rmemi\\u015f\",\"example\":\"The vase was still intact after the fall.\"},{\"word\":\"evacuate\",\"meaning\":\"tahliye etmek\",\"example\":\"The building was evacuated because of the fire.\"}]','[{\"q\":\"What was special about the time of the signal?\",\"options\":[\"It changed every night\",\"It always came at 03:17\",\"It came only on Sundays\"],\"answer\":1},{\"q\":\"Why did Erik Lund stay at Station Nine?\",\"options\":[\"He was lost\",\"To save the scientific data\",\"He missed the plane by mistake\"],\"answer\":1},{\"q\":\"What did the team find under the desk?\",\"options\":[\"Erik\'s diary only\",\"Climate data believed to be lost\",\"A second radio\"],\"answer\":1},{\"q\":\"How did Defne answer the signal?\",\"options\":[\"She called Ingrid\",\"She tapped a Morse code reply\",\"She sent an email to Oslo\"],\"answer\":1}]',1,1,0,'2026-10-03 20:30:40','2026-10-04 20:30:40','2026-10-04 20:30:40'),
(15,'a-new-friend-at-school','A New Friend','Yeni Bir Arkadaş','Zeynep okulun ilk gününde Londra\'dan gelen Tom ile tanışıyor.','A1','Okul','/img/stories/a-new-friend-at-school.webp',NULL,2,79,'[{\"en\":\"It is Monday. Zeynep is at her new school in Izmir. She is a little nervous.\",\"tr\":\"Pazartesi. Zeynep \\u0130zmir\'deki yeni okulunda. Biraz gergin.\"},{\"en\":\"A boy is next to her. He is tall and he has a big blue bag. \\\"Hi, I\'m Tom,\\\" he says. \\\"I\'m new here.\\\"\",\"tr\":\"Yan\\u0131nda bir \\u00e7ocuk var. Uzun boylu ve b\\u00fcy\\u00fck mavi bir \\u00e7antas\\u0131 var. \\\"Merhaba, ben Tom,\\\" diyor. \\\"Ben burada yeniyim.\\\"\"},{\"en\":\"\\\"Hello, I\'m Zeynep. Nice to meet you! Where are you from?\\\" \\\"I\'m from London, but my mum is from Izmir.\\\"\",\"tr\":\"\\\"Merhaba, ben Zeynep. Tan\\u0131\\u015ft\\u0131\\u011f\\u0131ma memnun oldum! Nerelisin?\\\" \\\"Londral\\u0131y\\u0131m ama annem \\u0130zmirli.\\\"\"},{\"en\":\"The teacher comes in. \\\"Good morning, class!\\\" Zeynep smiles. She is not nervous now. She has a new friend.\",\"tr\":\"\\u00d6\\u011fretmen i\\u00e7eri giriyor. \\\"G\\u00fcnayd\\u0131n s\\u0131n\\u0131f!\\\" Zeynep g\\u00fcl\\u00fcms\\u00fcyor. Art\\u0131k gergin de\\u011fil. Yeni bir arkada\\u015f\\u0131 var.\"}]','[{\"word\":\"nervous\",\"meaning\":\"gergin\",\"example\":\"I am nervous before exams.\"},{\"word\":\"next to\",\"meaning\":\"yan\\u0131nda\",\"example\":\"The bank is next to the caf\\u00e9.\"},{\"word\":\"new\",\"meaning\":\"yeni\",\"example\":\"This is my new phone.\"},{\"word\":\"smile\",\"meaning\":\"g\\u00fcl\\u00fcmsemek\",\"example\":\"She smiles at me.\"}]','[{\"q\":\"Where is Zeynep\'s new school?\",\"options\":[\"London\",\"Izmir\",\"Ankara\"],\"answer\":1},{\"type\":\"truefalse\",\"q\":\"Tom is from London.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":0},{\"type\":\"gap\",\"q\":\"At the end, Zeynep is not ___.\",\"options\":[],\"answer\":\"nervous\",\"accept\":[]}]',0,1,0,'2026-08-25 20:30:40','2026-10-04 20:30:40','2026-10-04 20:30:40'),
(16,'the-family-photo','The Family Photo','Aile Fotoğrafı','Kerem büyükannesinin evinde eski bir fotoğraf buluyor.','A1','Aile','/img/stories/the-family-photo.webp',NULL,2,77,'[{\"en\":\"Kerem is at his grandmother\'s house in Konya. It is Sunday and the whole family is there.\",\"tr\":\"Kerem, Konya\'daki b\\u00fcy\\u00fckannesinin evinde. Pazar g\\u00fcn\\u00fc ve b\\u00fct\\u00fcn aile orada.\"},{\"en\":\"In a drawer, Kerem finds an old photo. There are five children in it. \\\"Who are they, Grandma?\\\" he asks.\",\"tr\":\"Kerem bir \\u00e7ekmecede eski bir foto\\u011fraf buluyor. Foto\\u011frafta be\\u015f \\u00e7ocuk var. \\\"Bunlar kim, babaanne?\\\" diye soruyor.\"},{\"en\":\"\\\"That is me, and those are my brothers and sisters,\\\" she says. \\\"This boy is your grandfather\'s best friend.\\\"\",\"tr\":\"\\\"Bu benim, \\u015funlar da karde\\u015flerim,\\\" diyor. \\\"Bu \\u00e7ocuk da deden en iyi arkada\\u015f\\u0131.\\\"\"},{\"en\":\"Kerem laughs. \\\"Grandma, your hair is very long!\\\" \\\"Yes,\\\" she says, \\\"and your father has got the same smile as me.\\\"\",\"tr\":\"Kerem g\\u00fcl\\u00fcyor. \\\"Babaanne, sa\\u00e7lar\\u0131n \\u00e7ok uzun!\\\" \\\"Evet,\\\" diyor, \\\"baban da benimle ayn\\u0131 g\\u00fcl\\u00fcmsemeye sahip.\\\"\"}]','[{\"word\":\"whole\",\"meaning\":\"b\\u00fct\\u00fcn\",\"example\":\"The whole class is here.\"},{\"word\":\"drawer\",\"meaning\":\"\\u00e7ekmece\",\"example\":\"The keys are in the drawer.\"},{\"word\":\"find\",\"meaning\":\"bulmak\",\"example\":\"I can\'t find my phone.\"},{\"word\":\"same\",\"meaning\":\"ayn\\u0131\",\"example\":\"We have the same bag.\"}]','[{\"q\":\"Where is Kerem?\",\"options\":[\"At school\",\"At his grandmother\'s house\",\"In a park\"],\"answer\":1},{\"q\":\"How many children are in the photo?\",\"options\":[\"Three\",\"Four\",\"Five\"],\"answer\":2},{\"type\":\"truefalse\",\"q\":\"Kerem\'s father has got the same smile as his grandmother.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":0}]',0,1,0,'2026-08-25 20:30:40','2026-10-04 20:30:40','2026-10-04 20:30:40'),
(17,'the-missing-homework','The Missing Homework','Kayıp Ödev','Mert ödevini bulamıyor ve ders başlamak üzere.','A1','Okul','/img/stories/the-missing-homework.webp',NULL,2,78,'[{\"en\":\"It is eight o\'clock. Mert is in the classroom. \\\"Open your notebooks, please,\\\" says Ms Kaya. \\\"Homework time!\\\"\",\"tr\":\"Saat sekiz. Mert s\\u0131n\\u0131fta. \\\"Defterlerinizi a\\u00e7\\u0131n l\\u00fctfen,\\\" diyor Kaya Han\\u0131m. \\\"\\u00d6dev zaman\\u0131!\\\"\"},{\"en\":\"Mert opens his bag. He sees a pencil case, two books and an apple. But his homework is not there!\",\"tr\":\"Mert \\u00e7antas\\u0131n\\u0131 a\\u00e7\\u0131yor. Bir kalem kutusu, iki kitap ve bir elma g\\u00f6r\\u00fcyor. Ama \\u00f6devi orada de\\u011fil!\"},{\"en\":\"\\\"Is this your notebook?\\\" asks his friend Selin. She has a red notebook in her hand. \\\"It was under my desk.\\\"\",\"tr\":\"\\\"Bu senin defterin mi?\\\" diye soruyor arkada\\u015f\\u0131 Selin. Elinde k\\u0131rm\\u0131z\\u0131 bir defter var. \\\"S\\u0131ram\\u0131n alt\\u0131ndayd\\u0131.\\\"\"},{\"en\":\"\\\"Yes! Thank you, Selin!\\\" Mert gives his homework to Ms Kaya. She reads it and smiles. \\\"Very good, Mert.\\\"\",\"tr\":\"\\\"Evet! Te\\u015fekk\\u00fcrler Selin!\\\" Mert \\u00f6devini Kaya Han\\u0131m\'a veriyor. O da okuyup g\\u00fcl\\u00fcms\\u00fcyor. \\\"\\u00c7ok g\\u00fczel, Mert.\\\"\"}]','[{\"word\":\"pencil case\",\"meaning\":\"kalem kutusu\",\"example\":\"My pencil case is blue.\"},{\"word\":\"under\",\"meaning\":\"alt\\u0131nda\",\"example\":\"The cat is under the table.\"},{\"word\":\"give\",\"meaning\":\"vermek\",\"example\":\"Give me the book, please.\"},{\"word\":\"read\",\"meaning\":\"okumak\",\"example\":\"I read every night.\"}]','[{\"q\":\"What is not in Mert\'s bag?\",\"options\":[\"An apple\",\"His homework\",\"Two books\"],\"answer\":1},{\"q\":\"Where was the notebook?\",\"options\":[\"Under Selin\'s desk\",\"In the teacher\'s bag\",\"At home\"],\"answer\":0},{\"type\":\"order\",\"q\":\"C\\u00fcmleyi s\\u0131rala\",\"options\":[\"Mert\",\"gives\",\"his\",\"homework\",\"to\",\"Ms Kaya\"],\"answer\":\"\"}]',0,1,0,'2026-08-25 20:30:40','2026-10-04 20:30:40','2026-10-04 20:30:40'),
(18,'a-room-for-two','A Room for Two','İki Kişilik Oda','Defne ve kardeşi yeni evde aynı odayı paylaşmak zorunda.','A1','Günlük Hayat','/img/stories/a-room-for-two.webp',NULL,2,94,'[{\"en\":\"Defne\'s family has got a new flat in Eski\\u015fehir. It is near the river. There are three bedrooms, a kitchen and a big living room.\",\"tr\":\"Defne\'nin ailesinin Eski\\u015fehir\'de yeni bir dairesi var. Nehre yak\\u0131n. \\u00dc\\u00e7 yatak odas\\u0131, bir mutfak ve b\\u00fcy\\u00fck bir oturma odas\\u0131 var.\"},{\"en\":\"But there is a problem. Grandma is coming to live with them, so Defne and her little brother Arda have one room.\",\"tr\":\"Ama bir sorun var. Babaanne onlarla ya\\u015famaya geliyor, bu y\\u00fczden Defne ve k\\u00fc\\u00e7\\u00fck karde\\u015fi Arda\'n\\u0131n bir odas\\u0131 var.\"},{\"en\":\"\\\"My bed is next to the window!\\\" says Arda. \\\"No, my desk is there,\\\" says Defne. They are not happy.\",\"tr\":\"\\\"Benim yata\\u011f\\u0131m pencerenin yan\\u0131nda!\\\" diyor Arda. \\\"Hay\\u0131r, benim masam orada,\\\" diyor Defne. Mutlu de\\u011filler.\"},{\"en\":\"Then Dad has an idea. He puts a big bookcase between the two beds. Now there are two small rooms in one. Arda and Defne laugh.\",\"tr\":\"Sonra baban\\u0131n akl\\u0131na bir fikir geliyor. \\u0130ki yata\\u011f\\u0131n aras\\u0131na b\\u00fcy\\u00fck bir kitapl\\u0131k koyuyor. Art\\u0131k bir odada iki k\\u00fc\\u00e7\\u00fck oda var. Arda ve Defne g\\u00fcl\\u00fcyor.\"}]','[{\"word\":\"flat\",\"meaning\":\"daire\",\"example\":\"We live in a flat.\"},{\"word\":\"near\",\"meaning\":\"yak\\u0131n\",\"example\":\"My school is near my house.\"},{\"word\":\"between\",\"meaning\":\"aras\\u0131nda\",\"example\":\"The bank is between the shops.\"},{\"word\":\"idea\",\"meaning\":\"fikir\",\"example\":\"That is a good idea!\"}]','[{\"q\":\"How many bedrooms are there?\",\"options\":[\"Two\",\"Three\",\"Four\"],\"answer\":1},{\"q\":\"Who is coming to live with them?\",\"options\":[\"Grandma\",\"An uncle\",\"A cousin\"],\"answer\":0},{\"type\":\"gap\",\"q\":\"Dad puts a big ___ between the beds.\",\"options\":[],\"answer\":\"bookcase\",\"accept\":[\"book case\"]}]',0,1,0,'2026-08-25 20:30:40','2026-10-04 20:30:40','2026-10-04 20:30:40'),
(19,'the-big-market-day','Market Day','Pazar Günü','Emma, Türkiye\'deki ilk semt pazarında alışveriş yapmaya çalışıyor.','A1','Günlük Hayat','/img/stories/the-big-market-day.webp',NULL,2,77,'[{\"en\":\"Emma is from Canada. She lives in Antalya now. Today is Wednesday, and Wednesday is market day.\",\"tr\":\"Emma Kanadal\\u0131. \\u015eimdi Antalya\'da ya\\u015f\\u0131yor. Bug\\u00fcn \\u00e7ar\\u015famba ve \\u00e7ar\\u015famba pazar g\\u00fcn\\u00fc.\"},{\"en\":\"The market is very busy. There are tomatoes, oranges, cheese and olives everywhere. People are shouting prices.\",\"tr\":\"Pazar \\u00e7ok kalabal\\u0131k. Her yerde domates, portakal, peynir ve zeytin var. \\u0130nsanlar fiyatlar\\u0131 ba\\u011f\\u0131r\\u0131yor.\"},{\"en\":\"Emma wants some oranges. \\\"How much are they?\\\" she asks. The man smiles. \\\"Thirty lira a kilo. Here, try one!\\\"\",\"tr\":\"Emma biraz portakal istiyor. \\\"Ne kadar?\\\" diye soruyor. Adam g\\u00fcl\\u00fcms\\u00fcyor. \\\"Kilosu otuz lira. Buyrun, bir tane deneyin!\\\"\"},{\"en\":\"The orange is sweet. Emma buys two kilos and some white cheese. She says \\\"Te\\u015fekk\\u00fcrler!\\\" and the man is very happy.\",\"tr\":\"Portakal tatl\\u0131. Emma iki kilo ve biraz beyaz peynir al\\u0131yor. \\\"Te\\u015fekk\\u00fcrler!\\\" diyor ve adam \\u00e7ok mutlu oluyor.\"}]','[{\"word\":\"busy\",\"meaning\":\"kalabal\\u0131k, yo\\u011fun\",\"example\":\"The street is busy today.\"},{\"word\":\"price\",\"meaning\":\"fiyat\",\"example\":\"What is the price?\"},{\"word\":\"try\",\"meaning\":\"denemek\",\"example\":\"Can I try this?\"},{\"word\":\"sweet\",\"meaning\":\"tatl\\u0131\",\"example\":\"This cake is very sweet.\"}]','[{\"q\":\"What day is market day?\",\"options\":[\"Monday\",\"Wednesday\",\"Sunday\"],\"answer\":1},{\"q\":\"How much are the oranges?\",\"options\":[\"Thirty lira a kilo\",\"Thirteen lira\",\"Three lira\"],\"answer\":0},{\"type\":\"truefalse\",\"q\":\"Emma doesn\'t like the orange.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":1}]',0,1,0,'2026-08-25 20:30:40','2026-10-04 20:30:40','2026-10-04 20:30:40'),
(20,'snow-in-erzurum','Snow in Erzurum','Erzurum\'da Kar','Antalyalı Burak hayatında ilk kez kar görüyor.','A1','Seyahat','/img/stories/snow-in-erzurum.webp',NULL,2,83,'[{\"en\":\"Burak is from Antalya. It is always warm there. Today he is visiting his cousin Elif in Erzurum. It is January.\",\"tr\":\"Burak Antalyal\\u0131. Orada hava hep s\\u0131cak. Bug\\u00fcn Erzurum\'daki kuzeni Elif\'i ziyaret ediyor. Ocak ay\\u0131.\"},{\"en\":\"Burak is looking out of the window. Everything is white. \\\"Elif! It\'s snowing!\\\" he shouts.\",\"tr\":\"Burak pencereden d\\u0131\\u015far\\u0131 bak\\u0131yor. Her yer bembeyaz. \\\"Elif! Kar ya\\u011f\\u0131yor!\\\" diye ba\\u011f\\u0131r\\u0131yor.\"},{\"en\":\"\\\"Of course it\'s snowing,\\\" laughs Elif. \\\"It\'s Erzurum! Put on your coat, your hat and your boots. We\'re going outside.\\\"\",\"tr\":\"\\\"Tabii ki kar ya\\u011f\\u0131yor,\\\" diye g\\u00fcl\\u00fcyor Elif. \\\"Buras\\u0131 Erzurum! Montunu, bereni ve botlar\\u0131n\\u0131 giy. D\\u0131\\u015far\\u0131 \\u00e7\\u0131k\\u0131yoruz.\\\"\"},{\"en\":\"Now they are making a snowman in the garden. Burak\'s hands are cold, but he is very happy. He is sending photos to his friends in Antalya.\",\"tr\":\"\\u015eimdi bah\\u00e7ede kardan adam yap\\u0131yorlar. Burak\'\\u0131n elleri \\u00fc\\u015f\\u00fcyor ama \\u00e7ok mutlu. Antalya\'daki arkada\\u015flar\\u0131na foto\\u011fraf g\\u00f6nderiyor.\"}]','[{\"word\":\"warm\",\"meaning\":\"\\u0131l\\u0131k, s\\u0131cak\",\"example\":\"The sea is warm in August.\"},{\"word\":\"shout\",\"meaning\":\"ba\\u011f\\u0131rmak\",\"example\":\"Don\'t shout, please.\"},{\"word\":\"put on\",\"meaning\":\"giymek, takmak\",\"example\":\"Put on your coat.\"},{\"word\":\"snowman\",\"meaning\":\"kardan adam\",\"example\":\"The children are making a snowman.\"}]','[{\"q\":\"Where is Burak from?\",\"options\":[\"Erzurum\",\"Antalya\",\"Rize\"],\"answer\":1},{\"q\":\"What are they making?\",\"options\":[\"A cake\",\"A snowman\",\"A video\"],\"answer\":1},{\"type\":\"truefalse\",\"q\":\"Burak is unhappy because his hands are cold.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":1}]',0,1,0,'2026-08-25 20:30:40','2026-10-04 20:30:40','2026-10-04 20:30:40'),
(21,'the-saturday-club','The Saturday Club','Cumartesi Kulübü','Dört arkadaş her cumartesi farklı bir hobi deniyor.','A1','Eğlence','/img/stories/the-saturday-club.webp',NULL,2,96,'[{\"en\":\"Every Saturday, four friends meet at the park in Bursa: Ece, Can, Melis and Kaan. They call it \\\"The Saturday Club\\\".\",\"tr\":\"Her cumartesi d\\u00f6rt arkada\\u015f Bursa\'daki parkta bulu\\u015fuyor: Ece, Can, Melis ve Kaan. Buna \\\"Cumartesi Kul\\u00fcb\\u00fc\\\" diyorlar.\"},{\"en\":\"The rule is simple: every week, one person chooses a hobby and the others try it. Last week it was Can\'s turn. They played chess.\",\"tr\":\"Kural basit: her hafta bir ki\\u015fi bir hobi se\\u00e7iyor, di\\u011ferleri de deniyor. Ge\\u00e7en hafta s\\u0131ra Can\'dayd\\u0131. Satran\\u00e7 oynad\\u0131lar.\"},{\"en\":\"This week it is Melis\'s turn. She loves dancing, but Kaan hates it. \\\"I can\'t dance!\\\" he says. \\\"You can learn,\\\" says Melis.\",\"tr\":\"Bu hafta s\\u0131ra Melis\'te. Melis dans etmeyi \\u00e7ok seviyor ama Kaan nefret ediyor. \\\"Ben dans edemem!\\\" diyor. \\\"\\u00d6\\u011frenebilirsin,\\\" diyor Melis.\"},{\"en\":\"At the end of the day, Kaan is the best dancer. \\\"Okay,\\\" he says, \\\"I don\'t hate dancing now. But next week we are cooking. My turn!\\\"\",\"tr\":\"G\\u00fcn\\u00fcn sonunda en iyi dans\\u00e7\\u0131 Kaan. \\\"Tamam,\\\" diyor, \\\"art\\u0131k danstan nefret etmiyorum. Ama gelecek hafta yemek yap\\u0131yoruz. S\\u0131ra bende!\\\"\"}]','[{\"word\":\"meet\",\"meaning\":\"bulu\\u015fmak\",\"example\":\"Let\'s meet at five.\"},{\"word\":\"rule\",\"meaning\":\"kural\",\"example\":\"What are the rules?\"},{\"word\":\"choose\",\"meaning\":\"se\\u00e7mek\",\"example\":\"Choose a colour.\"},{\"word\":\"turn\",\"meaning\":\"s\\u0131ra\",\"example\":\"It\'s your turn.\"}]','[{\"q\":\"Where do the friends meet?\",\"options\":[\"At school\",\"At the park\",\"At Kaan\'s house\"],\"answer\":1},{\"q\":\"What did they do last week?\",\"options\":[\"They danced\",\"They played chess\",\"They cooked\"],\"answer\":1},{\"type\":\"gap\",\"q\":\"Next week they are ___.\",\"options\":[],\"answer\":\"cooking\",\"accept\":[]}]',0,1,0,'2026-08-25 20:30:40','2026-10-04 20:30:40','2026-10-04 20:30:40'),
(22,'the-lost-phone','The Lost Phone','Kayıp Telefon','Selin telefonunu otobüste unutuyor ve onu bulmak için bütün gün uğraşıyor.','A2','Günlük Hayat','/img/stories/the-lost-phone.webp',NULL,2,100,'[{\"en\":\"Yesterday was a terrible day for Selin. She was on the bus to work when she noticed something. Her phone wasn\'t in her bag!\",\"tr\":\"D\\u00fcn Selin i\\u00e7in korkun\\u00e7 bir g\\u00fcnd\\u00fc. \\u0130\\u015fe giden otob\\u00fcsteyken bir \\u015fey fark etti. Telefonu \\u00e7antas\\u0131nda de\\u011fildi!\"},{\"en\":\"She was very worried. All her photos and messages were on that phone. She asked the driver, but he was busy and didn\'t answer.\",\"tr\":\"\\u00c7ok endi\\u015felendi. B\\u00fct\\u00fcn foto\\u011fraflar\\u0131 ve mesajlar\\u0131 o telefondayd\\u0131. \\u015eof\\u00f6re sordu ama \\u015fof\\u00f6r me\\u015fguld\\u00fc ve cevap vermedi.\"},{\"en\":\"At lunch, she called her own number from a colleague\'s phone. A kind voice answered. \\\"Hello? I found this phone on the number 12 bus.\\\"\",\"tr\":\"\\u00d6\\u011fle yeme\\u011finde bir i\\u015f arkada\\u015f\\u0131n\\u0131n telefonundan kendi numaras\\u0131n\\u0131 arad\\u0131. Nazik bir ses cevap verdi. \\\"Alo? Bu telefonu 12 numaral\\u0131 otob\\u00fcste buldum.\\\"\"},{\"en\":\"The woman\'s name was Hatice. She was a retired teacher. They met at a caf\\u00e9 in the evening, and Selin bought her a cake to say thank you.\",\"tr\":\"Kad\\u0131n\\u0131n ad\\u0131 Hatice\'ydi. Emekli bir \\u00f6\\u011fretmendi. Ak\\u015fam bir kafede bulu\\u015ftular ve Selin te\\u015fekk\\u00fcr etmek i\\u00e7in ona bir pasta ald\\u0131.\"}]','[{\"word\":\"terrible\",\"meaning\":\"korkun\\u00e7\",\"example\":\"The weather was terrible.\"},{\"word\":\"notice\",\"meaning\":\"fark etmek\",\"example\":\"I noticed a small mistake.\"},{\"word\":\"worried\",\"meaning\":\"endi\\u015feli\",\"example\":\"My mum was worried.\"},{\"word\":\"retired\",\"meaning\":\"emekli\",\"example\":\"My grandfather is retired.\"}]','[{\"q\":\"Where did Selin lose her phone?\",\"options\":[\"At work\",\"On the bus\",\"In a caf\\u00e9\"],\"answer\":1},{\"type\":\"truefalse\",\"q\":\"The driver helped Selin.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":1},{\"q\":\"What did Selin buy for Hatice?\",\"options\":[\"Flowers\",\"A cake\",\"A book\"],\"answer\":1}]',0,1,0,'2026-08-25 20:30:41','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(23,'the-camping-plan','The Camping Plan','Kamp Planı','Üç arkadaş Kazdağları\'nda kamp yapmayı planlıyor, ama hava durumu başka söylüyor.','A2','Seyahat','/img/stories/the-camping-plan.webp',NULL,2,101,'[{\"en\":\"Ozan, Lara and Efe are university students in \\u00c7anakkale. The exams are finished and they are going to have a short holiday.\",\"tr\":\"Ozan, Lara ve Efe \\u00c7anakkale\'de \\u00fcniversite \\u00f6\\u011frencisi. S\\u0131navlar bitti ve k\\u0131sa bir tatil yapacaklar.\"},{\"en\":\"\\\"I\'ve got an idea,\\\" says Lara. \\\"We\'re going to camp in the Kazda\\u011flar\\u0131 mountains. I\'m going to bring my tent.\\\"\",\"tr\":\"\\\"Bir fikrim var,\\\" diyor Lara. \\\"Kazda\\u011flar\\u0131\'nda kamp yapaca\\u011f\\u0131z. Ben \\u00e7ad\\u0131r\\u0131m\\u0131 getirece\\u011fim.\\\"\"},{\"en\":\"Efe checks the weather on his phone. \\\"Hmm. It\'s going to rain on Saturday. A lot.\\\" Ozan is not worried. \\\"Then we\'re going to need a bigger tent!\\\"\",\"tr\":\"Efe telefonundan hava durumuna bak\\u0131yor. \\\"Hmm. Cumartesi ya\\u011fmur ya\\u011facak. Hem de \\u00e7ok.\\\" Ozan endi\\u015feli de\\u011fil. \\\"O zaman daha b\\u00fcy\\u00fck bir \\u00e7ad\\u0131ra ihtiyac\\u0131m\\u0131z olacak!\\\"\"},{\"en\":\"In the end, they change the plan. They are going to stay in a small wooden house in a village and go walking on Sunday when the sun comes out.\",\"tr\":\"Sonunda plan\\u0131 de\\u011fi\\u015ftiriyorlar. Bir k\\u00f6yde k\\u00fc\\u00e7\\u00fck ah\\u015fap bir evde kalacaklar ve g\\u00fcne\\u015f \\u00e7\\u0131k\\u0131nca pazar g\\u00fcn\\u00fc y\\u00fcr\\u00fcy\\u00fc\\u015fe gidecekler.\"}]','[{\"word\":\"exam\",\"meaning\":\"s\\u0131nav\",\"example\":\"I have an exam tomorrow.\"},{\"word\":\"bring\",\"meaning\":\"getirmek\",\"example\":\"Bring your notebook.\"},{\"word\":\"check\",\"meaning\":\"kontrol etmek\",\"example\":\"Check your email.\"},{\"word\":\"wooden\",\"meaning\":\"ah\\u015fap\",\"example\":\"a wooden table\"}]','[{\"q\":\"Why are they going to have a holiday?\",\"options\":[\"The exams are finished\",\"It is their birthday\",\"They have a new job\"],\"answer\":0},{\"type\":\"truefalse\",\"q\":\"The weather is going to be sunny on Saturday.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":1},{\"q\":\"Where are they going to stay in the end?\",\"options\":[\"In a tent\",\"In a hotel\",\"In a wooden house\"],\"answer\":2}]',0,1,0,'2026-08-25 20:30:41','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(24,'two-cities','Two Cities','İki Şehir','İstanbullu Aslı ile Rizeli Yusuf, şehirlerinin hangisinin daha güzel olduğunu tartışıyor.','A2','Seyahat','/img/stories/two-cities.webp',NULL,2,100,'[{\"en\":\"Asl\\u0131 lives in Istanbul and her online friend Yusuf lives in Rize. Every week they have a video call. This week they started a funny argument.\",\"tr\":\"Asl\\u0131 \\u0130stanbul\'da, internetteki arkada\\u015f\\u0131 Yusuf Rize\'de ya\\u015f\\u0131yor. Her hafta g\\u00f6r\\u00fcnt\\u00fcl\\u00fc konu\\u015fuyorlar. Bu hafta komik bir tart\\u0131\\u015fma ba\\u015flatt\\u0131lar.\"},{\"en\":\"\\\"Istanbul is the most exciting city in the world,\\\" said Asl\\u0131. \\\"It\'s bigger, the food is better and there is always something to do.\\\"\",\"tr\":\"\\\"\\u0130stanbul d\\u00fcnyan\\u0131n en heyecanl\\u0131 \\u015fehri,\\\" dedi Asl\\u0131. \\\"Daha b\\u00fcy\\u00fck, yemekleri daha iyi ve her zaman yapacak bir \\u015fey var.\\\"\"},{\"en\":\"\\\"Maybe,\\\" said Yusuf, \\\"but Rize is greener, quieter and the air is cleaner. And our tea is the best in Turkey!\\\"\",\"tr\":\"\\\"Belki,\\\" dedi Yusuf, \\\"ama Rize daha ye\\u015fil, daha sakin ve hava daha temiz. Ve \\u00e7ay\\u0131m\\u0131z T\\u00fcrkiye\'nin en iyisi!\\\"\"},{\"en\":\"They didn\'t agree, so they made a plan. In August, Asl\\u0131 is going to visit Rize, and in December, Yusuf is going to visit Istanbul. Then they will decide.\",\"tr\":\"Anla\\u015famad\\u0131lar ve bir plan yapt\\u0131lar. A\\u011fustosta Asl\\u0131 Rize\'ye, aral\\u0131kta Yusuf \\u0130stanbul\'a gidecek. Sonra karar verecekler.\"}]','[{\"word\":\"argument\",\"meaning\":\"tart\\u0131\\u015fma\",\"example\":\"We had a small argument.\"},{\"word\":\"exciting\",\"meaning\":\"heyecan verici\",\"example\":\"The match was exciting.\"},{\"word\":\"clean\",\"meaning\":\"temiz\",\"example\":\"The air is clean here.\"},{\"word\":\"agree\",\"meaning\":\"ayn\\u0131 fikirde olmak\",\"example\":\"I agree with you.\"}]','[{\"q\":\"Where does Yusuf live?\",\"options\":[\"Istanbul\",\"Rize\",\"Ankara\"],\"answer\":1},{\"q\":\"What does Yusuf say about Rize\'s tea?\",\"options\":[\"It is the best in Turkey\",\"It is cheaper\",\"It is new\"],\"answer\":0},{\"type\":\"truefalse\",\"q\":\"Asl\\u0131 and Yusuf agreed at the end of the call.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":1}]',0,1,0,'2026-08-25 20:30:41','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(25,'grandpas-garden','Grandpa\'s Garden','Dedemin Bahçesi','Doktor dedeye yürüyüş öneriyor, ama dede kendi çözümünü buluyor.','A2','Günlük Hayat','/img/stories/grandpas-garden.webp',NULL,2,91,'[{\"en\":\"Grandpa Hasan is seventy-two. Last month his back hurt and he felt tired all the time, so he went to the doctor in Kayseri.\",\"tr\":\"Hasan Dede yetmi\\u015f iki ya\\u015f\\u0131nda. Ge\\u00e7en ay s\\u0131rt\\u0131 a\\u011fr\\u0131yordu ve s\\u00fcrekli yorgun hissediyordu, bu y\\u00fczden Kayseri\'de doktora gitti.\"},{\"en\":\"\\\"You should walk every day,\\\" said the doctor. \\\"And you shouldn\'t sit in front of the TV all evening.\\\"\",\"tr\":\"\\\"Her g\\u00fcn y\\u00fcr\\u00fcmelisiniz,\\\" dedi doktor. \\\"Ve b\\u00fct\\u00fcn ak\\u015fam televizyonun kar\\u015f\\u0131s\\u0131nda oturmamal\\u0131s\\u0131n\\u0131z.\\\"\"},{\"en\":\"Grandpa doesn\'t like walking. \\\"Walking is boring,\\\" he told his granddaughter Nil. Nil had an idea. \\\"Then you should start a garden!\\\"\",\"tr\":\"Dede y\\u00fcr\\u00fcmeyi sevmiyor. \\\"Y\\u00fcr\\u00fcmek s\\u0131k\\u0131c\\u0131,\\\" dedi torunu Nil\'e. Nil\'in akl\\u0131na bir fikir geldi. \\\"O zaman bir bah\\u00e7e yapmal\\u0131s\\u0131n!\\\"\"},{\"en\":\"Now Grandpa works in his garden every morning. He grows tomatoes and peppers. His back doesn\'t hurt now and he gives vegetables to all the neighbours.\",\"tr\":\"\\u015eimdi dede her sabah bah\\u00e7esinde \\u00e7al\\u0131\\u015f\\u0131yor. Domates ve biber yeti\\u015ftiriyor. Art\\u0131k s\\u0131rt\\u0131 a\\u011fr\\u0131m\\u0131yor ve b\\u00fct\\u00fcn kom\\u015fulara sebze veriyor.\"}]','[{\"word\":\"all the time\",\"meaning\":\"s\\u00fcrekli\",\"example\":\"He talks all the time.\"},{\"word\":\"boring\",\"meaning\":\"s\\u0131k\\u0131c\\u0131\",\"example\":\"This film is boring.\"},{\"word\":\"grow\",\"meaning\":\"yeti\\u015ftirmek\",\"example\":\"We grow apples.\"},{\"word\":\"neighbour\",\"meaning\":\"kom\\u015fu\",\"example\":\"Our neighbours are friendly.\"}]','[{\"q\":\"Why did Grandpa go to the doctor?\",\"options\":[\"His back hurt\",\"He broke his arm\",\"He had a cold\"],\"answer\":0},{\"type\":\"truefalse\",\"q\":\"Grandpa loves walking.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":1},{\"q\":\"What does Grandpa grow?\",\"options\":[\"Apples and pears\",\"Tomatoes and peppers\",\"Flowers\"],\"answer\":1}]',0,1,0,'2026-08-25 20:30:41','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(26,'the-night-train','The Night Train','Gece Treni','Doğu Ekspresi\'nde bir gece, beklenmedik bir yol arkadaşlığına dönüşüyor.','A2','Seyahat','/img/stories/the-night-train.webp',NULL,2,116,'[{\"en\":\"Melis bought a ticket for the Eastern Express from Ankara to Kars. The journey takes more than twenty-four hours, but she wanted to see the snowy mountains.\",\"tr\":\"Melis Ankara\'dan Kars\'a Do\\u011fu Ekspresi i\\u00e7in bilet ald\\u0131. Yolculuk yirmi d\\u00f6rt saatten fazla s\\u00fcr\\u00fcyor ama karl\\u0131 da\\u011flar\\u0131 g\\u00f6rmek istiyordu.\"},{\"en\":\"In her cabin there was an old man with a big bag of oranges. \\\"Hello,\\\" he said. \\\"I\'m going to visit my son in Kars. Would you like an orange?\\\"\",\"tr\":\"Kompart\\u0131man\\u0131nda b\\u00fcy\\u00fck bir torba portakal\\u0131 olan ya\\u015fl\\u0131 bir adam vard\\u0131. \\\"Merhaba,\\\" dedi. \\\"Kars\'taki o\\u011flumu ziyarete gidiyorum. Portakal ister misin?\\\"\"},{\"en\":\"In the middle of the night, the train stopped. \\\"There is a lot of snow on the tracks,\\\" said the conductor. \\\"There will be a long delay.\\\"\",\"tr\":\"Gecenin ortas\\u0131nda tren durdu. \\\"Raylarda \\u00e7ok kar var,\\\" dedi kond\\u00fckt\\u00f6r. \\\"Uzun bir r\\u00f6tar olacak.\\\"\"},{\"en\":\"Melis was worried, but the old man smiled. \\\"Don\'t worry. I\'ll make tea and I\'ll tell you stories.\\\" The delay was five hours, but it was the best part of her trip.\",\"tr\":\"Melis endi\\u015felendi ama ya\\u015fl\\u0131 adam g\\u00fcl\\u00fcmsedi. \\\"Merak etme. Ben \\u00e7ay yapar\\u0131m, sana hik\\u00e2yeler anlat\\u0131r\\u0131m.\\\" R\\u00f6tar be\\u015f saat s\\u00fcrd\\u00fc ama yolculu\\u011funun en g\\u00fczel k\\u0131sm\\u0131yd\\u0131.\"}]','[{\"word\":\"cabin\",\"meaning\":\"kompart\\u0131man, kabin\",\"example\":\"Our cabin was small.\"},{\"word\":\"track\",\"meaning\":\"ray\",\"example\":\"The train is on track two.\"},{\"word\":\"conductor\",\"meaning\":\"kond\\u00fckt\\u00f6r\",\"example\":\"The conductor checked our tickets.\"},{\"word\":\"trip\",\"meaning\":\"gezi\",\"example\":\"We had a great trip.\"}]','[{\"q\":\"Where was Melis going?\",\"options\":[\"Ankara\",\"Kars\",\"Erzurum\"],\"answer\":1},{\"q\":\"Why did the train stop?\",\"options\":[\"Snow on the tracks\",\"A broken engine\",\"A long queue\"],\"answer\":0},{\"type\":\"gap\",\"q\":\"The delay was ___ hours.\",\"options\":[],\"answer\":\"five\",\"accept\":[\"5\"]}]',0,1,0,'2026-08-25 20:30:41','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(27,'the-bucket-list','The Bucket List','Yapılacaklar Listesi','Yetmiş yaşındaki Nermin Hanım hayatında hiç yapmadığı on şeyin listesini yapıyor.','A2','Eğlence','/img/stories/the-bucket-list.webp',NULL,2,101,'[{\"en\":\"Nermin is seventy years old. On her birthday, her grandson Emir asked her a question: \\\"Grandma, what have you never done?\\\"\",\"tr\":\"Nermin yetmi\\u015f ya\\u015f\\u0131nda. Do\\u011fum g\\u00fcn\\u00fcnde torunu Emir ona bir soru sordu: \\\"Babaanne, hi\\u00e7 neler yapmad\\u0131n?\\\"\"},{\"en\":\"Nermin thought for a long time. Then she wrote a list. \\\"I\'ve never flown in a plane. I\'ve never seen the sea in winter. I\'ve never eaten sushi.\\\"\",\"tr\":\"Nermin uzun s\\u00fcre d\\u00fc\\u015f\\u00fcnd\\u00fc. Sonra bir liste yazd\\u0131. \\\"Hi\\u00e7 u\\u00e7a\\u011fa binmedim. K\\u0131\\u015f\\u0131n denizi hi\\u00e7 g\\u00f6rmedim. Hi\\u00e7 su\\u015fi yemedim.\\\"\"},{\"en\":\"Emir loved the list. Every month, they did one thing. They have eaten sushi in Istanbul and they have seen the Black Sea in January.\",\"tr\":\"Emir listeyi \\u00e7ok sevdi. Her ay bir \\u015fey yapt\\u0131lar. \\u0130stanbul\'da su\\u015fi yediler ve ocakta Karadeniz\'i g\\u00f6rd\\u00fcler.\"},{\"en\":\"Last week Nermin flew for the first time, to Van. \\\"Have you ever been so happy?\\\" asked Emir. \\\"Never,\\\" she said. \\\"But the list isn\'t finished yet!\\\"\",\"tr\":\"Ge\\u00e7en hafta Nermin ilk kez u\\u00e7a\\u011fa bindi, Van\'a. \\\"Hi\\u00e7 bu kadar mutlu oldun mu?\\\" diye sordu Emir. \\\"Hi\\u00e7,\\\" dedi. \\\"Ama liste daha bitmedi!\\\"\"}]','[{\"word\":\"grandson\",\"meaning\":\"erkek torun\",\"example\":\"Her grandson is ten.\"},{\"word\":\"list\",\"meaning\":\"liste\",\"example\":\"Make a shopping list.\"},{\"word\":\"for the first time\",\"meaning\":\"ilk kez\",\"example\":\"I saw snow for the first time.\"},{\"word\":\"yet\",\"meaning\":\"hen\\u00fcz\",\"example\":\"I haven\'t finished yet.\"}]','[{\"q\":\"How old is Nermin?\",\"options\":[\"Sixty\",\"Seventy\",\"Eighty\"],\"answer\":1},{\"type\":\"truefalse\",\"q\":\"Nermin has flown many times.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":1},{\"q\":\"Where did Nermin fly last week?\",\"options\":[\"Van\",\"Istanbul\",\"Izmir\"],\"answer\":0}]',0,1,0,'2026-08-25 20:30:41','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(28,'the-second-chance','The Second Chance','İkinci Şans','Kırk yaşında mesleğini değiştiren bir muhasebecinin hikâyesi.','B1','Kariyer','/img/stories/the-second-chance.webp',NULL,2,123,'[{\"en\":\"Kemal has worked as an accountant in Bursa for fifteen years. He has a good salary and a nice flat, but recently he has felt that something is missing.\",\"tr\":\"Kemal on be\\u015f y\\u0131ld\\u0131r Bursa\'da muhasebeci olarak \\u00e7al\\u0131\\u015f\\u0131yor. \\u0130yi bir maa\\u015f\\u0131 ve g\\u00fczel bir dairesi var ama son zamanlarda bir \\u015feylerin eksik oldu\\u011funu hissediyor.\"},{\"en\":\"Since he was a child, he has loved cooking. Every Sunday he cooks for his whole family, and they have always told him the same thing: \\\"You should open a restaurant.\\\"\",\"tr\":\"\\u00c7ocuklu\\u011fundan beri yemek yapmay\\u0131 seviyor. Her pazar b\\u00fct\\u00fcn ailesine yemek yap\\u0131yor ve hep ayn\\u0131 \\u015feyi s\\u00f6yl\\u00fcyorlar: \\\"Bir restoran a\\u00e7mal\\u0131s\\u0131n.\\\"\"},{\"en\":\"Last year, on his fortieth birthday, he made a decision. He took a cooking course in Istanbul and has worked in a famous kitchen for six months.\",\"tr\":\"Ge\\u00e7en y\\u0131l, k\\u0131rk\\u0131nc\\u0131 do\\u011fum g\\u00fcn\\u00fcnde bir karar verdi. \\u0130stanbul\'da bir a\\u015f\\u00e7\\u0131l\\u0131k kursuna gitti ve alt\\u0131 ayd\\u0131r \\u00fcnl\\u00fc bir mutfakta \\u00e7al\\u0131\\u015f\\u0131yor.\"},{\"en\":\"It hasn\'t been easy. He has burnt his hands and he has worked until midnight many times. But he hasn\'t felt this alive for years. \\\"I haven\'t opened my restaurant yet,\\\" he says, \\\"but I will.\\\"\",\"tr\":\"Kolay olmad\\u0131. Ellerini yakt\\u0131, bir\\u00e7ok kez gece yar\\u0131s\\u0131na kadar \\u00e7al\\u0131\\u015ft\\u0131. Ama y\\u0131llard\\u0131r kendini bu kadar canl\\u0131 hissetmemi\\u015fti. \\\"Restoran\\u0131m\\u0131 hen\\u00fcz a\\u00e7mad\\u0131m,\\\" diyor, \\\"ama a\\u00e7aca\\u011f\\u0131m.\\\"\"}]','[{\"word\":\"accountant\",\"meaning\":\"muhasebeci\",\"example\":\"My aunt is an accountant.\"},{\"word\":\"salary\",\"meaning\":\"maa\\u015f\",\"example\":\"He has a good salary.\"},{\"word\":\"missing\",\"meaning\":\"eksik\",\"example\":\"A page is missing.\"},{\"word\":\"alive\",\"meaning\":\"canl\\u0131, hayat dolu\",\"example\":\"I feel alive by the sea.\"}]','[{\"q\":\"How long has Kemal worked as an accountant?\",\"options\":[\"Five years\",\"Fifteen years\",\"Forty years\"],\"answer\":1},{\"type\":\"truefalse\",\"q\":\"Kemal has already opened his restaurant.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":1},{\"q\":\"When did he make his decision?\",\"options\":[\"On his fortieth birthday\",\"When he was a child\",\"Six months ago\"],\"answer\":0}]',0,1,0,'2026-08-25 20:30:41','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(29,'the-old-photograph','The Old Photograph','Eski Fotoğraf','Bit pazarında bulunan bir fotoğraf, kırk yıllık bir hikâyeyi ortaya çıkarıyor.','B1','Gizem','/img/stories/the-old-photograph.webp',NULL,2,134,'[{\"en\":\"Last Sunday, Derya was walking through a flea market in Kad\\u0131k\\u00f6y when she noticed a box of old photographs. One of them made her stop.\",\"tr\":\"Ge\\u00e7en pazar Derya Kad\\u0131k\\u00f6y\'deki bir bit pazar\\u0131nda y\\u00fcr\\u00fcrken eski foto\\u011fraflarla dolu bir kutu fark etti. Foto\\u011fraflardan biri onu durdurdu.\"},{\"en\":\"It showed a young woman standing in front of a bakery. The bakery was on the corner of Derya\'s street, the same bakery where she buys bread every morning.\",\"tr\":\"Foto\\u011frafta bir f\\u0131r\\u0131n\\u0131n \\u00f6n\\u00fcnde duran gen\\u00e7 bir kad\\u0131n vard\\u0131. F\\u0131r\\u0131n, Derya\'n\\u0131n soka\\u011f\\u0131n\\u0131n k\\u00f6\\u015fesindeydi; her sabah ekmek ald\\u0131\\u011f\\u0131 f\\u0131r\\u0131n\\u0131n ta kendisi.\"},{\"en\":\"She bought the photo for ten lira and took it to the bakery. The old baker was cleaning the counter while she was explaining. Suddenly he stopped and looked at the photo for a long time.\",\"tr\":\"Foto\\u011fraf\\u0131 on liraya ald\\u0131 ve f\\u0131r\\u0131na g\\u00f6t\\u00fcrd\\u00fc. O anlat\\u0131rken ya\\u015fl\\u0131 f\\u0131r\\u0131nc\\u0131 tezg\\u00e2h\\u0131 siliyordu. Aniden durdu ve foto\\u011frafa uzun uzun bakt\\u0131.\"},{\"en\":\"\\\"That\'s my mother,\\\" he said quietly. \\\"She used to work here before I was born. We lost all our photos in a fire in 1985.\\\" Now the photo hangs on the bakery wall, and the baker never lets Derya pay for her bread.\",\"tr\":\"\\\"Bu benim annem,\\\" dedi sessizce. \\\"Ben do\\u011fmadan \\u00f6nce burada \\u00e7al\\u0131\\u015f\\u0131rd\\u0131. 1985\'te bir yang\\u0131nda b\\u00fct\\u00fcn foto\\u011fraflar\\u0131m\\u0131z\\u0131 kaybettik.\\\" \\u015eimdi foto\\u011fraf f\\u0131r\\u0131n\\u0131n duvar\\u0131nda as\\u0131l\\u0131 ve f\\u0131r\\u0131nc\\u0131 Derya\'n\\u0131n ekmek paras\\u0131n\\u0131 hi\\u00e7 alm\\u0131yor.\"}]','[{\"word\":\"flea market\",\"meaning\":\"bit pazar\\u0131\",\"example\":\"I bought this lamp at a flea market.\"},{\"word\":\"bakery\",\"meaning\":\"f\\u0131r\\u0131n\",\"example\":\"The bakery opens at six.\"},{\"word\":\"counter\",\"meaning\":\"tezg\\u00e2h\",\"example\":\"Put the money on the counter.\"},{\"word\":\"hang\",\"meaning\":\"as\\u0131l\\u0131 olmak\",\"example\":\"A clock hangs on the wall.\"}]','[{\"q\":\"Where did Derya find the photo?\",\"options\":[\"At a flea market\",\"In the bakery\",\"At home\"],\"answer\":0},{\"q\":\"Who is the woman in the photo?\",\"options\":[\"Derya\'s grandmother\",\"The baker\'s mother\",\"A famous actress\"],\"answer\":1},{\"type\":\"truefalse\",\"q\":\"The baker\'s family lost their photos in a fire.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":0}]',0,1,0,'2026-08-25 20:30:41','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(30,'the-scholarship','The Scholarship','Burs','Gaziantepli Elif, yurt dışı bursu için son mülakatına hazırlanıyor.','B1','Kariyer','/img/stories/the-scholarship.webp',NULL,2,97,'[{\"en\":\"Elif is eighteen and she lives in Gaziantep. Tomorrow at nine she is having the last interview for a scholarship to study medicine in Canada.\",\"tr\":\"Elif on sekiz ya\\u015f\\u0131nda ve Gaziantep\'te ya\\u015f\\u0131yor. Yar\\u0131n saat dokuzda Kanada\'da t\\u0131p okumak i\\u00e7in bir bursun son m\\u00fclakat\\u0131na giriyor.\"},{\"en\":\"\\\"What if I forget everything?\\\" she asks her brother. \\\"You won\'t,\\\" he says. \\\"If you practise tonight, you\'ll feel more confident.\\\"\",\"tr\":\"\\\"Ya her \\u015feyi unutursam?\\\" diye soruyor a\\u011fabeyine. \\\"Unutmazs\\u0131n,\\\" diyor a\\u011fabeyi. \\\"Bu gece pratik yaparsan kendini daha g\\u00fcvende hissedersin.\\\"\"},{\"en\":\"So they practise. He asks difficult questions and she answers in English. \\\"If they ask about my weaknesses, I\'ll be honest,\\\" she decides.\",\"tr\":\"Pratik yap\\u0131yorlar. O zor sorular soruyor, Elif \\u0130ngilizce cevapl\\u0131yor. \\\"Zay\\u0131f y\\u00f6nlerimi sorarlarsa d\\u00fcr\\u00fcst olaca\\u011f\\u0131m,\\\" diye karar veriyor.\"},{\"en\":\"The next day, the interview goes well. On the bus home her phone rings. \\\"Congratulations, Elif. If you accept, you will start in September.\\\" She can\'t stop smiling.\",\"tr\":\"Ertesi g\\u00fcn m\\u00fclakat iyi ge\\u00e7iyor. Eve d\\u00f6nerken otob\\u00fcste telefonu \\u00e7al\\u0131yor. \\\"Tebrikler Elif. Kabul ederseniz eyl\\u00fclde ba\\u015flayacaks\\u0131n\\u0131z.\\\" G\\u00fcl\\u00fcmsemesini durduram\\u0131yor.\"}]','[{\"word\":\"scholarship\",\"meaning\":\"burs\",\"example\":\"She won a scholarship.\"},{\"word\":\"confident\",\"meaning\":\"kendinden emin\",\"example\":\"He looks confident.\"},{\"word\":\"weakness\",\"meaning\":\"zay\\u0131f y\\u00f6n\",\"example\":\"What is your biggest weakness?\"},{\"word\":\"accept\",\"meaning\":\"kabul etmek\",\"example\":\"I accept your offer.\"}]','[{\"q\":\"What does Elif want to study?\",\"options\":[\"Medicine\",\"Engineering\",\"Law\"],\"answer\":0},{\"type\":\"truefalse\",\"q\":\"Elif\'s brother helps her practise.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":0},{\"type\":\"gap\",\"q\":\"If she accepts, she will start in ___.\",\"options\":[],\"answer\":\"September\",\"accept\":[\"september\"]}]',0,1,0,'2026-08-25 20:30:41','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(31,'the-wishing-coin','The Wishing Coin','Dilek Parası','Bir çeşmeye atılan para, Can\'ın üç dileğini sorguya çekiyor.','B1','Eğlence','/img/stories/the-wishing-coin.webp',NULL,2,122,'[{\"en\":\"Can was sitting by an old fountain in Safranbolu when an old woman gave him a coin. \\\"This is a wishing coin,\\\" she said. \\\"You have three wishes. Choose carefully.\\\"\",\"tr\":\"Can, Safranbolu\'da eski bir \\u00e7e\\u015fmenin yan\\u0131nda otururken ya\\u015fl\\u0131 bir kad\\u0131n ona bir madeni para verdi. \\\"Bu bir dilek paras\\u0131,\\\" dedi. \\\"\\u00dc\\u00e7 dile\\u011fin var. Dikkatli se\\u00e7.\\\"\"},{\"en\":\"Can laughed, but he started thinking. \\\"If I had a lot of money, I would buy a house by the sea. If I were famous, everyone would know my name.\\\"\",\"tr\":\"Can g\\u00fcld\\u00fc ama d\\u00fc\\u015f\\u00fcnmeye ba\\u015flad\\u0131. \\\"\\u00c7ok param olsa denize yak\\u0131n bir ev al\\u0131rd\\u0131m. \\u00dcnl\\u00fc olsam herkes ad\\u0131m\\u0131 bilirdi.\\\"\"},{\"en\":\"Then he thought about his grandmother, who lived alone in another city. \\\"I wish I saw her more often,\\\" he said. As soon as he said it, the coin felt warm in his hand.\",\"tr\":\"Sonra ba\\u015fka bir \\u015fehirde yaln\\u0131z ya\\u015fayan babaannesini d\\u00fc\\u015f\\u00fcnd\\u00fc. \\\"Ke\\u015fke onu daha s\\u0131k g\\u00f6rsem,\\\" dedi. Bunu s\\u00f6yler s\\u00f6ylemez para avucunda \\u0131s\\u0131nd\\u0131.\"},{\"en\":\"That evening his mother called. \\\"Your grandmother is moving to our neighbourhood!\\\" Can looked at the coin. He still had two wishes, but suddenly he didn\'t need them.\",\"tr\":\"O ak\\u015fam annesi arad\\u0131. \\\"Babaannen bizim mahalleye ta\\u015f\\u0131n\\u0131yor!\\\" Can paraya bakt\\u0131. H\\u00e2l\\u00e2 iki dile\\u011fi vard\\u0131 ama birden onlara ihtiyac\\u0131 kalmam\\u0131\\u015ft\\u0131.\"}]','[{\"word\":\"fountain\",\"meaning\":\"\\u00e7e\\u015fme\",\"example\":\"We met by the fountain.\"},{\"word\":\"coin\",\"meaning\":\"madeni para\",\"example\":\"I found a coin on the floor.\"},{\"word\":\"carefully\",\"meaning\":\"dikkatlice\",\"example\":\"Read the question carefully.\"},{\"word\":\"alone\",\"meaning\":\"yaln\\u0131z\",\"example\":\"She lives alone.\"}]','[{\"q\":\"Where was Can sitting?\",\"options\":[\"By a fountain\",\"In a caf\\u00e9\",\"On a bus\"],\"answer\":0},{\"q\":\"What did Can wish for in the end?\",\"options\":[\"A house by the sea\",\"To be famous\",\"To see his grandmother more often\"],\"answer\":2},{\"type\":\"truefalse\",\"q\":\"Can used all three wishes.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":1}]',0,1,0,'2026-08-25 20:30:41','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(32,'the-dolphin-headline','The Dolphin Headline','Yunus Manşeti','Stajyer gazeteci Barış\'ın ilk büyük haberi bir yunusla ilgili.','B1','Haber','/img/stories/the-dolphin-headline.webp',NULL,2,112,'[{\"en\":\"Bar\\u0131\\u015f is a young journalist. He has been working at a local newspaper in Mu\\u011fla for three weeks, and he has only been given small stories so far.\",\"tr\":\"Bar\\u0131\\u015f gen\\u00e7 bir gazeteci. \\u00dc\\u00e7 haftad\\u0131r Mu\\u011fla\'da yerel bir gazetede \\u00e7al\\u0131\\u015f\\u0131yor ve \\u015fimdiye kadar ona sadece k\\u00fc\\u00e7\\u00fck haberler verildi.\"},{\"en\":\"One morning, a phone call was received at the office. A baby dolphin had been found on a beach near Fethiye. Nobody else was free, so Bar\\u0131\\u015f was sent.\",\"tr\":\"Bir sabah ofise bir telefon geldi. Fethiye yak\\u0131nlar\\u0131nda bir plajda yavru bir yunus bulunmu\\u015ftu. Ba\\u015fka kimse m\\u00fcsait de\\u011fildi, bu y\\u00fczden Bar\\u0131\\u015f g\\u00f6nderildi.\"},{\"en\":\"When he arrived, the dolphin was being kept wet by a group of fishermen. A vet was called and the animal was carried back into deep water.\",\"tr\":\"Vard\\u0131\\u011f\\u0131nda yunus bir grup bal\\u0131k\\u00e7\\u0131 taraf\\u0131ndan \\u0131slak tutuluyordu. Bir veteriner \\u00e7a\\u011fr\\u0131ld\\u0131 ve hayvan derin suya geri ta\\u015f\\u0131nd\\u0131.\"},{\"en\":\"Bar\\u0131\\u015f wrote the story that night. The next day it was published on the front page, and the video was watched by more than a million people.\",\"tr\":\"Bar\\u0131\\u015f haberi o gece yazd\\u0131. Ertesi g\\u00fcn haber \\u00f6n sayfada yay\\u0131mland\\u0131 ve video bir milyondan fazla ki\\u015fi taraf\\u0131ndan izlendi.\"}]','[{\"word\":\"local\",\"meaning\":\"yerel\",\"example\":\"a local newspaper\"},{\"word\":\"so far\",\"meaning\":\"\\u015fimdiye kadar\",\"example\":\"So far, so good.\"},{\"word\":\"fisherman\",\"meaning\":\"bal\\u0131k\\u00e7\\u0131\",\"example\":\"The fishermen leave at dawn.\"},{\"word\":\"front page\",\"meaning\":\"\\u00f6n sayfa\",\"example\":\"It was on the front page.\"}]','[{\"q\":\"Where was the dolphin found?\",\"options\":[\"Near Fethiye\",\"In Istanbul\",\"In a river\"],\"answer\":0},{\"q\":\"Who kept the dolphin wet?\",\"options\":[\"Bar\\u0131\\u015f\",\"Some fishermen\",\"A vet\"],\"answer\":1},{\"type\":\"truefalse\",\"q\":\"The video was watched by more than a million people.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":0}]',0,1,0,'2026-08-25 20:30:41','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(33,'the-message-chain','The Message Chain','Mesaj Zinciri','Bir ofiste aktarılan basit bir mesaj, kulaktan kulağa nasıl değişiyor?','B1','Eğlence','/img/stories/the-message-chain.webp',NULL,2,120,'[{\"en\":\"On Monday morning, the manager, Mrs Uysal, said to Ahmet: \\\"I\'m taking the team out for lunch on Friday.\\\"\",\"tr\":\"Pazartesi sabah\\u0131 m\\u00fcd\\u00fcr Uysal Han\\u0131m Ahmet\'e dedi ki: \\\"Cuma g\\u00fcn\\u00fc ekibi \\u00f6\\u011fle yeme\\u011fine \\u00e7\\u0131kar\\u0131yorum.\\\"\"},{\"en\":\"Ahmet told Sibel that Mrs Uysal was taking the team out on Friday. Sibel told Ozan that they were going out on Friday, but she didn\'t say it was for lunch.\",\"tr\":\"Ahmet Sibel\'e Uysal Han\\u0131m\'\\u0131n cuma g\\u00fcn\\u00fc ekibi d\\u0131\\u015far\\u0131 \\u00e7\\u0131karaca\\u011f\\u0131n\\u0131 s\\u00f6yledi. Sibel de Ozan\'a cuma g\\u00fcn\\u00fc d\\u0131\\u015far\\u0131 \\u00e7\\u0131kacaklar\\u0131n\\u0131 s\\u00f6yledi ama \\u00f6\\u011fle yeme\\u011fi oldu\\u011funu s\\u00f6ylemedi.\"},{\"en\":\"Ozan asked Leyla if she was coming to the party on Friday night. Leyla told everyone that the manager had invited them to a party and that they should dress up.\",\"tr\":\"Ozan Leyla\'ya cuma ak\\u015famki partiye gelip gelmeyece\\u011fini sordu. Leyla da herkese m\\u00fcd\\u00fcr\\u00fcn onlar\\u0131 bir partiye davet etti\\u011fini ve \\u015f\\u0131k giyinmeleri gerekti\\u011fini s\\u00f6yledi.\"},{\"en\":\"On Friday at noon, Mrs Uysal found her whole team in suits and evening dresses. \\\"I said lunch,\\\" she laughed, \\\"not a wedding!\\\" They went to a kebab restaurant anyway, and it was the best-dressed lunch in the city.\",\"tr\":\"Cuma \\u00f6\\u011flen Uysal Han\\u0131m b\\u00fct\\u00fcn ekibini tak\\u0131m elbise ve gece elbiseleriyle buldu. \\\"Ben \\u00f6\\u011fle yeme\\u011fi dedim,\\\" diye g\\u00fcld\\u00fc, \\\"d\\u00fc\\u011f\\u00fcn de\\u011fil!\\\" Yine de bir kebap\\u00e7\\u0131ya gittiler ve \\u015fehrin en \\u015f\\u0131k \\u00f6\\u011fle yeme\\u011fi oldu.\"}]','[{\"word\":\"take out\",\"meaning\":\"d\\u0131\\u015far\\u0131 yeme\\u011fe g\\u00f6t\\u00fcrmek\",\"example\":\"He took me out for dinner.\"},{\"word\":\"invite\",\"meaning\":\"davet etmek\",\"example\":\"They invited us to the wedding.\"},{\"word\":\"dress up\",\"meaning\":\"\\u015f\\u0131k giyinmek\",\"example\":\"You don\'t need to dress up.\"},{\"word\":\"anyway\",\"meaning\":\"yine de\",\"example\":\"It was raining, but we went anyway.\"}]','[{\"q\":\"What did Mrs Uysal plan?\",\"options\":[\"A party\",\"A lunch\",\"A wedding\"],\"answer\":1},{\"q\":\"Who told everyone to dress up?\",\"options\":[\"Ahmet\",\"Leyla\",\"Mrs Uysal\"],\"answer\":1},{\"type\":\"order\",\"q\":\"C\\u00fcmleyi s\\u0131rala\",\"options\":[\"She\",\"said\",\"she\",\"was\",\"taking\",\"the\",\"team\",\"out\"],\"answer\":\"\"}]',0,1,0,'2026-08-25 20:30:41','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(34,'the-neighbour-upstairs','The Neighbour Upstairs','Üst Kattaki Komşu','Her gece piyano sesi duyan Ece, üst kattaki gizemli komşusunu merak ediyor.','B1','Gizem','/img/stories/the-neighbour-upstairs.webp',NULL,2,118,'[{\"en\":\"Ece moved into a small flat in Ankara last autumn. Every night at eleven, she heard piano music which came from the flat upstairs.\",\"tr\":\"Ece ge\\u00e7en sonbahar Ankara\'da k\\u00fc\\u00e7\\u00fck bir daireye ta\\u015f\\u0131nd\\u0131. Her gece saat on birde \\u00fcst kattaki daireden gelen piyano sesini duyuyordu.\"},{\"en\":\"She asked the doorman, who knew everyone in the building. \\\"The man who lives there is very quiet,\\\" he said. \\\"He\'s a retired teacher whose wife died two years ago.\\\"\",\"tr\":\"Binadaki herkesi tan\\u0131yan kap\\u0131c\\u0131ya sordu. \\\"Orada ya\\u015fayan adam \\u00e7ok sessizdir,\\\" dedi kap\\u0131c\\u0131. \\\"Kar\\u0131s\\u0131 iki y\\u0131l \\u00f6nce \\u00f6lm\\u00fc\\u015f emekli bir \\u00f6\\u011fretmen.\\\"\"},{\"en\":\"One evening, Ece found a letter which had been delivered to her flat by mistake. It was addressed to the man upstairs. She decided to take it to him.\",\"tr\":\"Bir ak\\u015fam Ece yanl\\u0131\\u015fl\\u0131kla kendi dairesine teslim edilmi\\u015f bir mektup buldu. \\u00dcst kattaki adama yaz\\u0131lm\\u0131\\u015ft\\u0131. Ona g\\u00f6t\\u00fcrmeye karar verdi.\"},{\"en\":\"Mr Turan opened the door and smiled. \\\"Are you the person who listens to my music? I play the songs that my wife loved.\\\" Now, every Sunday, Ece brings cake and he plays for her.\",\"tr\":\"Turan Bey kap\\u0131y\\u0131 a\\u00e7t\\u0131 ve g\\u00fcl\\u00fcmsedi. \\\"M\\u00fczi\\u011fimi dinleyen ki\\u015fi sen misin? Kar\\u0131m\\u0131n sevdi\\u011fi \\u015fark\\u0131lar\\u0131 \\u00e7al\\u0131yorum.\\\" \\u015eimdi her pazar Ece kek getiriyor, o da onun i\\u00e7in \\u00e7al\\u0131yor.\"}]','[{\"word\":\"upstairs\",\"meaning\":\"\\u00fcst kat\",\"example\":\"My room is upstairs.\"},{\"word\":\"doorman\",\"meaning\":\"kap\\u0131c\\u0131\",\"example\":\"The doorman opens the door.\"},{\"word\":\"by mistake\",\"meaning\":\"yanl\\u0131\\u015fl\\u0131kla\",\"example\":\"I took your coat by mistake.\"},{\"word\":\"address\",\"meaning\":\"(mektup) adreslemek\",\"example\":\"The letter was addressed to me.\"}]','[{\"q\":\"What did Ece hear every night?\",\"options\":[\"A dog\",\"Piano music\",\"A television\"],\"answer\":1},{\"q\":\"Who is Mr Turan?\",\"options\":[\"A doorman\",\"A retired teacher\",\"A musician from Istanbul\"],\"answer\":1},{\"type\":\"truefalse\",\"q\":\"Ece now visits Mr Turan every Sunday.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":0}]',0,1,0,'2026-08-25 20:30:41','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(35,'the-wrong-email','The Wrong Email','Yanlış E-posta','Yeni işindeki ilk haftasında Tuna, yanlış kişiye çok yanlış bir e-posta gönderiyor.','B1','Kariyer','/img/stories/the-wrong-email.webp',NULL,2,121,'[{\"en\":\"Tuna started working at a software company in Izmir on Monday. He was nervous but he enjoyed meeting his new colleagues.\",\"tr\":\"Tuna pazartesi g\\u00fcn\\u00fc \\u0130zmir\'de bir yaz\\u0131l\\u0131m \\u015firketinde \\u00e7al\\u0131\\u015fmaya ba\\u015flad\\u0131. Gergindi ama yeni i\\u015f arkada\\u015flar\\u0131yla tan\\u0131\\u015fmaktan keyif ald\\u0131.\"},{\"en\":\"On Thursday, he wanted to send a funny message to his friend Mert: \\\"The boss talks too much in meetings. I tried to stay awake!\\\" But he chose the wrong name. The email went to his boss, Mr Ayd\\u0131n.\",\"tr\":\"Per\\u015fembe g\\u00fcn\\u00fc arkada\\u015f\\u0131 Mert\'e komik bir mesaj g\\u00f6ndermek istedi: \\\"Patron toplant\\u0131larda \\u00e7ok konu\\u015fuyor. Uyan\\u0131k kalmaya \\u00e7al\\u0131\\u015ft\\u0131m!\\\" Ama yanl\\u0131\\u015f ismi se\\u00e7ti. E-posta patronu Ayd\\u0131n Bey\'e gitti.\"},{\"en\":\"Tuna couldn\'t stop thinking about it. He decided to apologise in person. He knocked on the door and said, \\\"I\'m really sorry. I didn\'t mean to be rude.\\\"\",\"tr\":\"Tuna bunu d\\u00fc\\u015f\\u00fcnmeden duramad\\u0131. Y\\u00fcz y\\u00fcze \\u00f6z\\u00fcr dilemeye karar verdi. Kap\\u0131y\\u0131 \\u00e7ald\\u0131 ve \\\"Ger\\u00e7ekten \\u00e7ok \\u00f6z\\u00fcr dilerim. Kaba olmak istemedim,\\\" dedi.\"},{\"en\":\"Mr Ayd\\u0131n laughed. \\\"Honestly, my wife says the same thing. Thank you for being honest. From now on, I\'ll try to keep meetings short.\\\" The next meeting lasted only fifteen minutes.\",\"tr\":\"Ayd\\u0131n Bey g\\u00fcld\\u00fc. \\\"A\\u00e7\\u0131k\\u00e7as\\u0131 e\\u015fim de ayn\\u0131 \\u015feyi s\\u00f6yl\\u00fcyor. D\\u00fcr\\u00fcst oldu\\u011fun i\\u00e7in te\\u015fekk\\u00fcrler. Bundan sonra toplant\\u0131lar\\u0131 k\\u0131sa tutmaya \\u00e7al\\u0131\\u015faca\\u011f\\u0131m.\\\" Bir sonraki toplant\\u0131 sadece on be\\u015f dakika s\\u00fcrd\\u00fc.\"}]','[{\"word\":\"software\",\"meaning\":\"yaz\\u0131l\\u0131m\",\"example\":\"She works for a software company.\"},{\"word\":\"stay awake\",\"meaning\":\"uyan\\u0131k kalmak\",\"example\":\"I couldn\'t stay awake.\"},{\"word\":\"apologise\",\"meaning\":\"\\u00f6z\\u00fcr dilemek\",\"example\":\"You should apologise.\"},{\"word\":\"rude\",\"meaning\":\"kaba\",\"example\":\"That was rude.\"}]','[{\"q\":\"Where does Tuna work?\",\"options\":[\"At a bank in Izmir\",\"At a software company in Izmir\",\"At a school in Ankara\"],\"answer\":1},{\"q\":\"Who received the email?\",\"options\":[\"Mert\",\"Mr Ayd\\u0131n\'s wife\",\"Mr Ayd\\u0131n\"],\"answer\":2},{\"type\":\"truefalse\",\"q\":\"Mr Ayd\\u0131n was very angry.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":1}]',0,1,0,'2026-08-25 20:30:41','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(36,'the-missed-flight','The Missed Flight','Kaçan Uçuş','Kaçırılan bir uçuş, Arda\'nın hayatını beklenmedik şekilde değiştiriyor.','B2','Seyahat','/img/stories/the-missed-flight.webp',NULL,2,127,'[{\"en\":\"Five years ago, Arda missed a flight from Istanbul to Amsterdam. If the taxi hadn\'t got stuck in traffic on the bridge, he would have arrived on time.\",\"tr\":\"Be\\u015f y\\u0131l \\u00f6nce Arda \\u0130stanbul\'dan Amsterdam\'a giden bir u\\u00e7a\\u011f\\u0131 ka\\u00e7\\u0131rd\\u0131. Taksi k\\u00f6pr\\u00fcde trafi\\u011fe tak\\u0131lmasayd\\u0131 zaman\\u0131nda varacakt\\u0131.\"},{\"en\":\"He was furious. He had an important meeting the next morning, and he blamed himself. \\\"I should have left an hour earlier,\\\" he kept saying at the airport.\",\"tr\":\"\\u00c7ok sinirlendi. Ertesi sabah \\u00f6nemli bir toplant\\u0131s\\u0131 vard\\u0131 ve kendini su\\u00e7lad\\u0131. Havaliman\\u0131nda \\\"Bir saat erken \\u00e7\\u0131kmal\\u0131yd\\u0131m,\\\" deyip duruyordu.\"},{\"en\":\"While he was waiting for the next flight, he started talking to a woman who had also missed the same plane. Her name was Leyla, and she was a landscape architect from Bursa.\",\"tr\":\"Bir sonraki u\\u00e7a\\u011f\\u0131 beklerken ayn\\u0131 u\\u00e7a\\u011f\\u0131 ka\\u00e7\\u0131rm\\u0131\\u015f olan bir kad\\u0131nla konu\\u015fmaya ba\\u015flad\\u0131. Ad\\u0131 Leyla\'yd\\u0131 ve Bursal\\u0131 bir peyzaj mimar\\u0131yd\\u0131.\"},{\"en\":\"They talked for six hours. Today, they are married and they have a daughter. \\\"If that taxi had been faster,\\\" Arda tells his friends, \\\"I would never have met her. I wish I could thank that traffic jam.\\\"\",\"tr\":\"Alt\\u0131 saat konu\\u015ftular. Bug\\u00fcn evliler ve bir k\\u0131zlar\\u0131 var. Arda arkada\\u015flar\\u0131na \\\"O taksi daha h\\u0131zl\\u0131 olsayd\\u0131 onunla asla tan\\u0131\\u015fmazd\\u0131m,\\\" diyor. \\\"Ke\\u015fke o trafik s\\u0131k\\u0131\\u015f\\u0131kl\\u0131\\u011f\\u0131na te\\u015fekk\\u00fcr edebilsem.\\\"\"}]','[{\"word\":\"get stuck\",\"meaning\":\"tak\\u0131l\\u0131p kalmak\",\"example\":\"We got stuck in the lift.\"},{\"word\":\"furious\",\"meaning\":\"\\u00f6fkeli\",\"example\":\"She was furious with me.\"},{\"word\":\"blame\",\"meaning\":\"su\\u00e7lamak\",\"example\":\"Don\'t blame yourself.\"},{\"word\":\"traffic jam\",\"meaning\":\"trafik s\\u0131k\\u0131\\u015f\\u0131kl\\u0131\\u011f\\u0131\",\"example\":\"There was a huge traffic jam.\"}]','[{\"q\":\"Why did Arda miss the flight?\",\"options\":[\"He overslept\",\"His taxi got stuck in traffic\",\"He lost his passport\"],\"answer\":1},{\"type\":\"truefalse\",\"q\":\"Leyla had also missed the plane.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":0},{\"q\":\"What does Arda wish?\",\"options\":[\"That he had left earlier\",\"That he could thank the traffic jam\",\"That he had taken the bus\"],\"answer\":1}]',0,1,0,'2026-08-25 20:30:41','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(37,'the-last-bee','The Last Bee','Son Arı','2060\'ta, arıların yok olduğu bir dünyada genç bir bilim insanı umut arıyor.','B2','Bilim Kurgu','/img/stories/the-last-bee.webp',NULL,2,139,'[{\"en\":\"It is the year 2060. Bees have disappeared from most of the world, and farmers pollinate fruit trees by hand. Nisa is a young scientist working in a laboratory near Bolu.\",\"tr\":\"Y\\u0131l 2060. Ar\\u0131lar d\\u00fcnyan\\u0131n b\\u00fcy\\u00fck k\\u0131sm\\u0131ndan yok oldu ve \\u00e7ift\\u00e7iler meyve a\\u011fa\\u00e7lar\\u0131n\\u0131 elle tozla\\u015ft\\u0131r\\u0131yor. Nisa, Bolu yak\\u0131nlar\\u0131ndaki bir laboratuvarda \\u00e7al\\u0131\\u015fan gen\\u00e7 bir bilim insan\\u0131.\"},{\"en\":\"Her grandmother used to keep bees, and Nisa has always believed that some colonies must have survived somewhere. \\\"By the end of this year,\\\" she tells her team, \\\"we will have searched every valley in the Black Sea region.\\\"\",\"tr\":\"Babaannesi eskiden ar\\u0131 yeti\\u015ftirirdi ve Nisa baz\\u0131 kolonilerin bir yerlerde hayatta kalm\\u0131\\u015f olmas\\u0131 gerekti\\u011fine hep inand\\u0131. Ekibine \\\"Bu y\\u0131l\\u0131n sonuna kadar Karadeniz b\\u00f6lgesindeki her vadiyi aram\\u0131\\u015f olaca\\u011f\\u0131z,\\\" diyor.\"},{\"en\":\"In October, an old shepherd in a remote village hears about the project. He sends a short message: \\\"Come and see my chestnut trees.\\\"\",\"tr\":\"Ekimde uzak bir k\\u00f6ydeki ya\\u015fl\\u0131 bir \\u00e7oban projeyi duyuyor. K\\u0131sa bir mesaj g\\u00f6nderiyor: \\\"Gelin, kestane a\\u011fa\\u00e7lar\\u0131ma bak\\u0131n.\\\"\"},{\"en\":\"When Nisa arrives, she hears a sound she has only heard in old videos: a quiet, constant buzzing. A small wild colony has been living in a hollow tree for decades. \\\"This time next year,\\\" she whispers, \\\"we\'ll be bringing bees back to the whole country.\\\"\",\"tr\":\"Nisa vard\\u0131\\u011f\\u0131nda yaln\\u0131zca eski videolarda duydu\\u011fu bir ses duyuyor: sessiz, s\\u00fcrekli bir v\\u0131z\\u0131lt\\u0131. K\\u00fc\\u00e7\\u00fck, yabani bir koloni onlarca y\\u0131ld\\u0131r kovuk bir a\\u011fa\\u00e7ta ya\\u015f\\u0131yormu\\u015f. \\\"Gelecek y\\u0131l bu zamanlar,\\\" diye f\\u0131s\\u0131ld\\u0131yor, \\\"b\\u00fct\\u00fcn \\u00fclkeye ar\\u0131lar\\u0131 geri getiriyor olaca\\u011f\\u0131z.\\\"\"}]','[{\"word\":\"pollinate\",\"meaning\":\"tozla\\u015fmak, tozla\\u015ft\\u0131rmak\",\"example\":\"Bees pollinate flowers.\"},{\"word\":\"survive\",\"meaning\":\"hayatta kalmak\",\"example\":\"Only a few plants survived.\"},{\"word\":\"remote\",\"meaning\":\"uzak, \\u0131ss\\u0131z\",\"example\":\"a remote village\"},{\"word\":\"hollow\",\"meaning\":\"kovuk, i\\u00e7i bo\\u015f\",\"example\":\"a hollow tree\"}]','[{\"q\":\"How do farmers pollinate trees in 2060?\",\"options\":[\"With machines\",\"By hand\",\"With birds\"],\"answer\":1},{\"q\":\"Who helped Nisa find the colony?\",\"options\":[\"Her grandmother\",\"An old shepherd\",\"Her team leader\"],\"answer\":1},{\"type\":\"truefalse\",\"q\":\"The colony had been living in a hollow tree for decades.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":0}]',0,1,0,'2026-08-25 20:30:41','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(38,'the-school-debate','The School Debate','Okul Münazarası','Utangaç Kerem, münazara finalinde en zor argümanı savunmak zorunda kalıyor.','B2','Okul','/img/stories/the-school-debate.webp',NULL,2,136,'[{\"en\":\"Kerem had never enjoyed speaking in public. Although he was one of the best students in his school in Trabzon, he always sat at the back and said nothing.\",\"tr\":\"Kerem topluluk \\u00f6n\\u00fcnde konu\\u015fmaktan hi\\u00e7 ho\\u015flanmam\\u0131\\u015ft\\u0131. Trabzon\'daki okulunun en iyi \\u00f6\\u011frencilerinden biri olmas\\u0131na ra\\u011fmen hep arkada oturur ve hi\\u00e7bir \\u015fey s\\u00f6ylemezdi.\"},{\"en\":\"Despite his fears, his English teacher put him in the debate team. In the final, his team had to argue that \\\"Mobile phones should be allowed in classrooms\\\", which Kerem personally disagreed with.\",\"tr\":\"Korkular\\u0131na ra\\u011fmen \\u0130ngilizce \\u00f6\\u011fretmeni onu m\\u00fcnazara tak\\u0131m\\u0131na ald\\u0131. Finalde tak\\u0131m\\u0131 \\\"Cep telefonlar\\u0131na s\\u0131n\\u0131fta izin verilmeli\\\" g\\u00f6r\\u00fc\\u015f\\u00fcn\\u00fc savunmak zorundayd\\u0131; Kerem ise ki\\u015fisel olarak buna kat\\u0131lm\\u0131yordu.\"},{\"en\":\"He prepared carefully. Whereas his teammates focused on freedom, Kerem collected evidence: studies on learning apps, examples of schools that had used phones successfully, and clear rules to prevent cheating.\",\"tr\":\"Dikkatle haz\\u0131rland\\u0131. Tak\\u0131m arkada\\u015flar\\u0131 \\u00f6zg\\u00fcrl\\u00fc\\u011fe odaklan\\u0131rken Kerem kan\\u0131t toplad\\u0131: \\u00f6\\u011frenme uygulamalar\\u0131 \\u00fczerine ara\\u015ft\\u0131rmalar, telefonlar\\u0131 ba\\u015far\\u0131yla kullanm\\u0131\\u015f okul \\u00f6rnekleri ve kopyay\\u0131 \\u00f6nleyecek a\\u00e7\\u0131k kurallar.\"},{\"en\":\"When he finally spoke, his voice was shaking. However, his arguments were so well organised that the judges gave his team the cup. \\\"I still don\'t agree with what I said,\\\" he told his teacher afterwards, \\\"but now I know I can convince people.\\\"\",\"tr\":\"Sonunda konu\\u015ftu\\u011funda sesi titriyordu. Ancak arg\\u00fcmanlar\\u0131 o kadar d\\u00fczenliydi ki j\\u00fcri kupay\\u0131 onun tak\\u0131m\\u0131na verdi. Sonra \\u00f6\\u011fretmenine \\\"S\\u00f6ylediklerime h\\u00e2l\\u00e2 kat\\u0131lm\\u0131yorum,\\\" dedi, \\\"ama art\\u0131k insanlar\\u0131 ikna edebildi\\u011fimi biliyorum.\\\"\"}]','[{\"word\":\"in public\",\"meaning\":\"topluluk \\u00f6n\\u00fcnde\",\"example\":\"I hate speaking in public.\"},{\"word\":\"disagree\",\"meaning\":\"kat\\u0131lmamak\",\"example\":\"I disagree with you.\"},{\"word\":\"focus on\",\"meaning\":\"odaklanmak\",\"example\":\"Focus on the main idea.\"},{\"word\":\"shake\",\"meaning\":\"titremek\",\"example\":\"My hands were shaking.\"}]','[{\"q\":\"Why didn\'t Kerem like the debate topic?\",\"options\":[\"He personally disagreed with it\",\"It was too easy\",\"It was about sport\"],\"answer\":0},{\"q\":\"What did Kerem focus on?\",\"options\":[\"Freedom\",\"Evidence\",\"Jokes\"],\"answer\":1},{\"type\":\"truefalse\",\"q\":\"Kerem\'s team won the cup.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":0}]',0,1,0,'2026-08-25 20:30:41','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(39,'the-community-garden','The Community Garden','Mahalle Bahçesi','Terk edilmiş bir otopark, bir mahallenin birlikte kurduğu bahçeye dönüşüyor.','B2','Günlük Hayat','/img/stories/the-community-garden.webp',NULL,2,137,'[{\"en\":\"For years, the empty car park behind Selim\'s building in Kad\\u0131k\\u00f6y was full of rubbish. \\\"It\'s high time somebody did something about it,\\\" the residents kept saying, but nobody did.\",\"tr\":\"Y\\u0131llarca Selim\'in Kad\\u0131k\\u00f6y\'deki binas\\u0131n\\u0131n arkas\\u0131ndaki bo\\u015f otopark \\u00e7\\u00f6ple doluydu. Sakinler \\\"Birinin bu konuda bir \\u015fey yapmas\\u0131n\\u0131n vakti \\u00e7oktan geldi,\\\" deyip duruyordu ama kimse bir \\u015fey yapm\\u0131yordu.\"},{\"en\":\"One spring morning, Selim, a retired engineer, wrote a polite letter to the council: \\\"I was wondering whether the residents could use the area as a community garden.\\\" To everyone\'s surprise, they agreed.\",\"tr\":\"Bir bahar sabah\\u0131 emekli m\\u00fchendis Selim belediyeye kibar bir mektup yazd\\u0131: \\\"Sakinlerin alan\\u0131 bir mahalle bah\\u00e7esi olarak kullan\\u0131p kullanamayaca\\u011f\\u0131n\\u0131 merak ediyordum.\\\" Herkesi \\u015fa\\u015f\\u0131rtarak kabul ettiler.\"},{\"en\":\"At first, only a few volunteers came. Some neighbours said they would rather pay someone to do the work. But when the first tomatoes appeared, more people joined: students, a Syrian family from the third floor, even the grumpy man from number 12.\",\"tr\":\"Ba\\u015fta sadece birka\\u00e7 g\\u00f6n\\u00fcll\\u00fc geldi. Baz\\u0131 kom\\u015fular i\\u015fi yapmas\\u0131 i\\u00e7in birine para \\u00f6demeyi tercih edeceklerini s\\u00f6yledi. Ama ilk domatesler belirince daha \\u00e7ok insan kat\\u0131ld\\u0131: \\u00f6\\u011frenciler, \\u00fc\\u00e7\\u00fcnc\\u00fc kattaki Suriyeli bir aile, hatta 12 numaradaki huysuz adam bile.\"},{\"en\":\"Today the garden has forty members, a small library and a long table where neighbours eat together every Sunday. \\\"We didn\'t just grow vegetables,\\\" Selim says. \\\"We grew a community.\\\"\",\"tr\":\"Bug\\u00fcn bah\\u00e7enin k\\u0131rk \\u00fcyesi, k\\u00fc\\u00e7\\u00fck bir k\\u00fct\\u00fcphanesi ve kom\\u015fular\\u0131n her pazar birlikte yemek yedi\\u011fi uzun bir masas\\u0131 var. \\\"Sadece sebze yeti\\u015ftirmedik,\\\" diyor Selim. \\\"Bir topluluk yeti\\u015ftirdik.\\\"\"}]','[{\"word\":\"rubbish\",\"meaning\":\"\\u00e7\\u00f6p\",\"example\":\"Don\'t leave rubbish here.\"},{\"word\":\"polite\",\"meaning\":\"kibar\",\"example\":\"He wrote a polite email.\"},{\"word\":\"grumpy\",\"meaning\":\"huysuz\",\"example\":\"My neighbour is grumpy in the morning.\"},{\"word\":\"member\",\"meaning\":\"\\u00fcye\",\"example\":\"She is a member of the club.\"}]','[{\"q\":\"What was the car park full of?\",\"options\":[\"Cars\",\"Rubbish\",\"Trees\"],\"answer\":1},{\"q\":\"What did Selim do first?\",\"options\":[\"He wrote to the council\",\"He paid a gardener\",\"He sold the land\"],\"answer\":0},{\"type\":\"gap\",\"q\":\"Today the garden has ___ members.\",\"options\":[],\"answer\":\"forty\",\"accept\":[\"40\"]}]',0,1,0,'2026-08-25 20:30:41','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(40,'the-power-of-sleep','The Power of Sleep','Uykunun Gücü','Akademik dilde yazılmış kısa bir metin: uyku, öğrenme ve sınav başarısı arasındaki ilişki.','B2','Bilim','/img/stories/the-power-of-sleep.webp',NULL,2,131,'[{\"en\":\"Sleep has long been considered a passive state in which the brain simply rests. However, recent research indicates that sleep plays a crucial role in learning and memory.\",\"tr\":\"Uyku uzun zamand\\u0131r beynin sadece dinlendi\\u011fi pasif bir durum olarak g\\u00f6r\\u00fcld\\u00fc. Ancak son ara\\u015ft\\u0131rmalar uykunun \\u00f6\\u011frenme ve haf\\u0131zada \\u00e7ok \\u00f6nemli bir rol oynad\\u0131\\u011f\\u0131n\\u0131 g\\u00f6steriyor.\"},{\"en\":\"During deep sleep, information learned during the day is transferred from short-term to long-term memory. Consequently, students who sleep well after studying tend to remember more than those who stay up all night.\",\"tr\":\"Derin uyku s\\u0131ras\\u0131nda g\\u00fcn i\\u00e7inde \\u00f6\\u011frenilen bilgiler k\\u0131sa s\\u00fcreli haf\\u0131zadan uzun s\\u00fcreli haf\\u0131zaya aktar\\u0131l\\u0131r. Sonu\\u00e7 olarak, \\u00e7al\\u0131\\u015ft\\u0131ktan sonra iyi uyuyan \\u00f6\\u011frenciler b\\u00fct\\u00fcn gece uyan\\u0131k kalanlardan daha fazlas\\u0131n\\u0131 hat\\u0131rlama e\\u011filimindedir.\"},{\"en\":\"In one study, approximately two hundred university students were divided into two groups. Both groups learned the same list of words; nevertheless, the group that slept eight hours scored about thirty percent higher the next day.\",\"tr\":\"Bir \\u00e7al\\u0131\\u015fmada yakla\\u015f\\u0131k iki y\\u00fcz \\u00fcniversite \\u00f6\\u011frencisi iki gruba ayr\\u0131ld\\u0131. \\u0130ki grup da ayn\\u0131 kelime listesini \\u00f6\\u011frendi; yine de sekiz saat uyuyan grup ertesi g\\u00fcn yakla\\u015f\\u0131k y\\u00fczde otuz daha y\\u00fcksek puan ald\\u0131.\"},{\"en\":\"These findings have significant implications for exam preparation. Rather than sacrificing sleep before an exam such as the YDS, learners would benefit more from short, regular study sessions followed by a full night\'s rest.\",\"tr\":\"Bu bulgular\\u0131n s\\u0131nav haz\\u0131rl\\u0131\\u011f\\u0131 a\\u00e7\\u0131s\\u0131ndan \\u00f6nemli sonu\\u00e7lar\\u0131 var. \\u00d6\\u011frenciler, YDS gibi bir s\\u0131nav \\u00f6ncesinde uykudan feragat etmek yerine, k\\u0131sa ve d\\u00fczenli \\u00e7al\\u0131\\u015fma seanslar\\u0131n\\u0131n ard\\u0131ndan tam bir gece dinlenmekten daha \\u00e7ok fayda g\\u00f6r\\u00fcr.\"}]','[{\"word\":\"passive\",\"meaning\":\"edilgen, pasif\",\"example\":\"a passive state\"},{\"word\":\"transfer\",\"meaning\":\"aktarmak\",\"example\":\"The data was transferred.\"},{\"word\":\"implication\",\"meaning\":\"sonu\\u00e7, \\u00e7\\u0131kar\\u0131m\",\"example\":\"The study has important implications.\"},{\"word\":\"sacrifice\",\"meaning\":\"feda etmek\",\"example\":\"Don\'t sacrifice your health.\"}]','[{\"q\":\"What is the passage mainly about?\",\"options\":[\"The role of sleep in learning\",\"How to study all night\",\"Problems of university students\"],\"answer\":0},{\"q\":\"How much higher did the sleeping group score?\",\"options\":[\"About eight percent\",\"About thirty percent\",\"About two hundred percent\"],\"answer\":1},{\"type\":\"truefalse\",\"q\":\"The writer recommends staying up late before an exam.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":1}]',0,1,0,'2026-08-25 20:30:41','2026-10-04 20:30:41','2026-10-04 20:30:41'),
(41,'the-film-club','The Film Club','Film Kulübü','Bir üniversite film kulübü, unutulmuş bir Türk filmini yeniden keşfediyor.','B2','Eğlence','/img/stories/the-film-club.webp',NULL,2,161,'[{\"en\":\"Every Thursday, the film club at Ege University watches a classic film and discusses it in English. This term, the members were running out of ideas, and attendance was going down.\",\"tr\":\"Ege \\u00dcniversitesi\'ndeki film kul\\u00fcb\\u00fc her per\\u015fembe klasik bir film izliyor ve \\u0130ngilizce tart\\u0131\\u015f\\u0131yor. Bu d\\u00f6nem \\u00fcyelerin fikirleri t\\u00fckeniyordu ve kat\\u0131l\\u0131m d\\u00fc\\u015f\\u00fcyordu.\"},{\"en\":\"Then Deniz came up with an unusual plan. Her grandfather had looked after an old cinema in Tire for forty years, and she had found out that a lost Turkish film from 1962 was still in his basement.\",\"tr\":\"Sonra Deniz al\\u0131\\u015f\\u0131lmad\\u0131k bir plan buldu. Dedesi k\\u0131rk y\\u0131l boyunca Tire\'deki eski bir sinemaya bakm\\u0131\\u015ft\\u0131 ve Deniz 1962 yap\\u0131m\\u0131 kay\\u0131p bir T\\u00fcrk filminin h\\u00e2l\\u00e2 dedesinin bodrumunda oldu\\u011funu \\u00f6\\u011frenmi\\u015fti.\"},{\"en\":\"Restoring the film wasn\'t a piece of cake. The club had to put off their screenings for two months, and some members nearly gave up. A professor turned down their first request for equipment, but a local business finally agreed to help.\",\"tr\":\"Filmi restore etmek \\u00e7ocuk oyunca\\u011f\\u0131 de\\u011fildi. Kul\\u00fcp g\\u00f6sterimlerini iki ay ertelemek zorunda kald\\u0131 ve baz\\u0131 \\u00fcyeler neredeyse vazge\\u00e7iyordu. Bir profes\\u00f6r ekipman i\\u00e7in ilk taleplerini reddetti ama sonunda yerel bir i\\u015fletme yard\\u0131m etmeyi kabul etti.\"},{\"en\":\"On the night of the screening, the hall was full. Deniz\'s grandfather sat in the front row, and when the first black-and-white scene appeared, he broke the ice with a joke: \\\"I was much more handsome back then.\\\" Everyone laughed, and then the room fell silent for the next ninety minutes.\",\"tr\":\"G\\u00f6sterim gecesi salon doluydu. Deniz\'in dedesi \\u00f6n s\\u0131rada oturuyordu ve ilk siyah beyaz sahne belirince bir \\u015fakayla buzlar\\u0131 k\\u0131rd\\u0131: \\\"O zamanlar \\u00e7ok daha yak\\u0131\\u015f\\u0131kl\\u0131yd\\u0131m.\\\" Herkes g\\u00fcld\\u00fc, ard\\u0131ndan salon doksan dakika boyunca sessizli\\u011fe g\\u00f6m\\u00fcld\\u00fc.\"}]','[{\"word\":\"run out of\",\"meaning\":\"t\\u00fckenmek\",\"example\":\"We\'ve run out of milk.\"},{\"word\":\"attendance\",\"meaning\":\"kat\\u0131l\\u0131m\",\"example\":\"Attendance was low.\"},{\"word\":\"basement\",\"meaning\":\"bodrum\",\"example\":\"The boxes are in the basement.\"},{\"word\":\"screening\",\"meaning\":\"g\\u00f6sterim\",\"example\":\"The screening starts at eight.\"}]','[{\"q\":\"Why was the club in trouble?\",\"options\":[\"Attendance was going down\",\"The cinema closed\",\"The professor left\"],\"answer\":0},{\"q\":\"Where was the lost film?\",\"options\":[\"In a university library\",\"In her grandfather\'s basement\",\"In a cinema in Istanbul\"],\"answer\":1},{\"type\":\"truefalse\",\"q\":\"The professor immediately agreed to give them equipment.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":1}]',0,1,0,'2026-08-25 20:30:41','2026-10-04 20:30:41','2026-10-04 20:30:41');
