INSERT INTO `testimonials` (`id`, `name`, `role`, `avatar`, `quote`, `highlight`, `rating`, `cefr_level`, `streak`, `is_published`, `position`, `created_at`, `updated_at`) VALUES (1,'Selin A.','Üniversite öğrencisi',NULL,'Defne ile mülakat senaryosunu on kere çalıştım. Gerçek mülakatta ilk defa heyecanlanmadan konuştum. Hikâyelerden topladığım kelimeler de işime yaradı.','Erasmus mülakatımı İngilizce geçtim.',5,'B1',96,1,0,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(2,'Mert K.','Yazılım geliştirici',NULL,'Günde 10 dakika ayırıyorum, o kadar. Altı ayın sonunda yabancı ekiple toplantılarda fikir söyleyebilir hale geldim. Seri bozulmasın diye her akşam açıyorum.','Toplantılarda artık susmuyorum.',5,'B2',210,1,1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(3,'Ayşe D.','Öğretmen',NULL,'Başka uygulamalarda hatanın neden hata olduğunu anlamıyordum. Burada Türkçe açıklıyor ve \"biz Türkler burada şunu yaparız\" diyor. Fark buradan geliyor.','Hataları Türkçe açıklaması çok iyi.',5,'A2',45,1,2,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(4,'Burak Ç.','Lise öğrencisi',NULL,'Ders çalışmak gibi değil, oyun gibi. Lig sıralamasında arkadaşlarımı geçmek için her gün giriyorum. Not ortalamam da kendiliğinden yükseldi.','Sınav notum 55’ten 84’e çıktı.',5,'A2',61,1,3,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(5,'Zeynep Y.','Hemşire',NULL,'Kursa gidecek vaktim yok. Vardiya arasında bir hikâye okuyup Defne ile iki cümle konuşuyorum. Kazandığım canlı ders kuponunu da şubede kullandım.','Vardiya aralarında 5 dakika yetiyor.',5,'B1',123,1,4,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(6,'Emre T.','İhracat uzmanı',NULL,'En çok sesli sohbet işime yaradı. Telaffuzumu anında düzeltiyor. Müşterilerle telefonda konuşurken eskisi gibi donup kalmıyorum.','Telefonda konuşmaktan korkmuyorum.',5,'B2',180,1,5,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(7,'Gülay S.','Veli · 3. sınıf','buns','Ekran süresinden korkuyordum, ama günlük hedef bitince uygulama kendisi \"yarın görüşürüz\" diyor. Kızım şarkılardaki kelimeleri evde kullanmaya başladı.','Kızım her akşam kendisi açıyor.',5,'A1',38,1,6,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(8,'Hakan B.','İngilizce öğretmeni · ortaokul','scientist','Sınıflara ödev verip kimin bitirdiğini panelden takip ediyorum. Dinleme ve konuşma pratiği derste vaktimizin yetmediği yeri tamamlıyor.','Ödevi kimin yaptığını tek ekranda görüyorum.',5,'C1',74,1,7,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(9,'Ela N.','7. sınıf öğrencisi','ponytail','Gölge Düellosu çok eğlenceli, arkadaşlarım yokken bile gölgeleriyle oynuyorum. İngilizce dersinde parmak kaldırmaya başladım.','Arkadaşlarımla düello yapıyoruz.',5,'A2',52,1,8,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(10,'Nihat A.','Okul müdürü','glasses','Hangi sınıf hangi beceride zorlanıyor, öğretmenlerimizle her ay rapordan bakıyoruz. Velilere de somut bir şey gösterebiliyoruz.','Bütün okulun İngilizcesi tek raporda.',5,'B1',20,1,9,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(11,'Can Ö.','Hazırlık öğrencisi','headphones','Akademik okuma parçaları ve yazma geri bildirimi sayesinde hazırlık muafiyet sınavını ilk denemede geçtim. Bir yıl kazandım.','Muafiyeti ilk denemede geçtim.',5,'B1',140,1,10,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(12,'Sevim K.','Emekli öğretmen','glasses','Yurt dışındaki torunlarımla birkaç cümle konuşabilmek istiyordum. Defne çok sabırlı, yanlış yapınca utandırmıyor.','Torunlarımla İngilizce konuşuyorum.',5,'A2',88,1,11,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(13,'Deniz P.','10. sınıf öğrencisi','cap','Hikâyeleri okurken bilmediğim kelimeye dokunuyorum, sonra oyunlarda tekrar karşıma çıkıyor. Artık sevdiğim diziyi altyazısız izliyorum.','Dizi izlerken altyazıyı kapattım.',5,'B1',67,1,12,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(14,'Merve İ.','Anne ve muhasebeci','braids','Akşamları oğlumla aynı anda çalışıyoruz, seri yarışı yapıyoruz. İş yerinde gelen e-postaları artık çeviri programı olmadan okuyorum.','Oğlumla birlikte öğreniyoruz.',5,'A2',101,1,13,'2026-10-04 20:30:41','2026-10-04 20:30:41');
