INSERT INTO `units` (`id`, `course_id`, `title`, `description`, `guidebook`, `color`, `position`, `created_at`, `updated_at`) VALUES (1,1,'Merhaba!','Selamlaşma, tanışma ve \"to be\"','## Merhaba, ben Higo!\nBu ünitede kendini tanıtmayı, birini selamlamayı ve İngilizcenin en temel fiili olan **to be** (olmak) fiilini öğreneceksin.\n\nTürkçede \"öğrenciyim, yorgunsun, evdeyiz\" derken kimliği ve durumu **-im, -sin, -iz** gibi eklerle söyleriz. İngilizcede bu ekler yoktur; aynı işi ayrı bir kelime yapar: **am / is / are**.\n\n- *Öğrenciyim.* → **I am** a student.\n- *Yorgunsun.* → **You are** tired.\n- *O, İzmirli.* → **She is** from Izmir.\n\n> Higo\'nun ipucu: İngilizce cümlede mutlaka bir fiil olmalı. \"I a student\" yanlıştır, **I am a student** demelisin.\n\n## to be ne anlama gelir?\n**to be** \"olmak\" demektir ama cümlede çoğu zaman Türkçedeki **-dır / -dir / -im / -sin** ekinin karşılığıdır. Üç şeyi anlatırız:\n\n| Ne anlatır? | Örnek | Türkçesi |\n|---|---|---|\n| Kimlik, meslek | I **am** a teacher. | Ben öğretmenim. |\n| Durum, duygu | We **are** happy. | Mutluyuz. |\n| Yer, köken | He **is** at home. / They **are** from Ankara. | O evde. / Onlar Ankaralı. |\n| Yaş | I **am** twelve. | On iki yaşındayım. |\n\nYaş söylerken Türkçedeki gibi \"sahip olmak\" (have) kullanılmaz: *I have twelve years* **yanlış**, **I am twelve (years old)** doğru.\n\n## am / is / are: hangisi kime?\n| Özne | Fiil | Kısa hali | Örnek |\n|---|---|---|---|\n| I (ben) | am | I\'m | I\'m Elif. *Ben Elif\'im.* |\n| he (o, erkek) | is | he\'s | He\'s my brother. *O benim erkek kardeşim.* |\n| she (o, kadın) | is | she\'s | She\'s a doctor. *O bir doktor.* |\n| it (o, eşya/hayvan) | is | it\'s | It\'s a cat. *Bu bir kedi.* |\n| you (sen / siz) | are | you\'re | You\'re right. *Haklısın.* |\n| we (biz) | are | we\'re | We\'re friends. *Biz arkadaşız.* |\n| they (onlar) | are | they\'re | They\'re late. *Onlar geç kaldı.* |\n\nTürkçede \"o\" tek kelimedir; İngilizcede erkek için **he**, kadın için **she**, eşya ve hayvan için **it** kullanılır.\n\n> Higo\'nun ipucu: Konuşurken hep kısa hali kullan: **I\'m, she\'s, we\'re**. Kulağa çok daha doğal gelir.\n\n## Olumsuz cümle: not\nOlumsuz yapmak için fiilden sonra **not** eklenir. Türkçedeki **değil** kelimesinin karşılığıdır.\n\n- I am **not** tired. → *Yorgun değilim.* (kısa: I\'m not tired.)\n- She is **not** here. → *O burada değil.* (kısa: She isn\'t here.)\n- They are **not** students. → *Onlar öğrenci değil.* (kısa: They aren\'t students.)\n\nKısaltmalar: **is not = isn\'t**, **are not = aren\'t**. Dikkat: *I amn\'t* diye bir kısaltma yoktur, sadece **I\'m not** denir.\n\n## Soru ve kısa cevap\nSoru sormak için fiil öznenin önüne geçer. Türkçede sona **mı / mi** eklediğimiz yerde İngilizce sıra değiştirir.\n\n| Düz cümle | Soru | Türkçesi |\n|---|---|---|\n| You are a student. | **Are you** a student? | Öğrenci misin? |\n| He is from Izmir. | **Is he** from Izmir? | O İzmirli mi? |\n| They are at school. | **Are they** at school? | Onlar okulda mı? |\n\nKısa cevapta fiili tekrar ederiz:\n- *Are you hungry?* **Yes, I am.** / **No, I\'m not.** (Evet. / Hayır.)\n- *Is she your sister?* **Yes, she is.** / **No, she isn\'t.**\n\n> Higo\'nun ipucu: Olumlu kısa cevapta kısaltma yapılmaz: **Yes, I am.** doğru, *Yes, I\'m.* yanlış.\n\n## Selamlaşma ve tanışma\n| İngilizce | Türkçesi | Ne zaman? |\n|---|---|---|\n| Hello! / Hi! | Merhaba! / Selam! | Her zaman; Hi daha samimi |\n| Good morning. | Günaydın. | Öğlene kadar |\n| Good afternoon. | İyi günler. | Öğleden sonra |\n| Good evening. | İyi akşamlar. | Akşam karşılaşınca |\n| Good night. | İyi geceler. | Ayrılırken ya da yatarken |\n| What\'s your name? My name is Can. | Adın ne? Benim adım Can. | Tanışırken |\n| Nice to meet you. | Tanıştığıma memnun oldum. | İlk tanışmada |\n| How are you? I\'m fine, thanks. And you? | Nasılsın? İyiyim, teşekkürler. Ya sen? | Hal hatır |\n| Goodbye! / Bye! / See you! | Hoşça kal! / Görüşürüz! | Vedalaşırken |\n\n**Örnek diyalog**\n> A: Hi! I\'m Deniz. What\'s your name?\n> B: Hello, Deniz. My name is Mert. Nice to meet you.\n> A: Nice to meet you too. Where are you from?\n> B: I\'m from Bursa.\n\n> Higo\'nun ipucu: \"Good night\" bir selam değil, vedalaşmadır. Akşam birine merhaba derken **Good evening** de.\n\n## Kendini kontrol et\nBoşlukları doldur, cevapları altta bul:\n1. My mother ___ a nurse.\n2. We ___ from Trabzon.\n3. ___ you twelve?\n4. I ___ not hungry.\n\nCevaplar: 1. is · 2. are · 3. Are · 4. am','#FF5A36',0,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(2,1,'Ailem','Aile, have got ve iyelik sıfatları','## Aileni tanıt\nBu ünitede ailendeki kişileri İngilizce adlandırmayı, **sahip olduğun şeyleri** söylemeyi (have got / has got) ve bir şeyin **kime ait olduğunu** anlatmayı (my, your, Ali\'s) öğreneceksin.\n\n| İngilizce | Türkçesi |\n|---|---|\n| mother / mum | anne |\n| father / dad | baba |\n| sister | kız kardeş, abla |\n| brother | erkek kardeş, ağabey |\n| grandmother | büyükanne (nine, babaanne, anneanne) |\n| grandfather | büyükbaba (dede) |\n| aunt | teyze, hala, yenge |\n| uncle | amca, dayı, enişte |\n| cousin | kuzen |\n| parents | anne ve baba |\n| son | oğul |\n| daughter | kız evlat |\n\nTürkçede abla ile kız kardeşi, amca ile dayıyı ayırırız; İngilizce ayırmaz. \"Ablam\" demek istersen **my older sister**, \"küçük kardeşim\" için **my younger brother / sister** dersin.\n\n## have got: \"sahibim\" demek\n**have got** ve **has got**, **sahip olmayı** anlatır. Türkçede bunu \"**var**\" ile söyleriz: *Bir kız kardeşim var. Kedim var. Mavi gözleri var.*\n\n| Türkçesi | İngilizcesi |\n|---|---|\n| Bir kız kardeşim **var**. | I **have got** a sister. |\n| Onun (erkek) bir bisikleti **var**. | He **has got** a bike. |\n| Bizim büyük bir evimiz **var**. | We **have got** a big house. |\n| Onun (kadın) kahverengi gözleri **var**. | She **has got** brown eyes. |\n\nYani **have got = sahip olmak, -si var**. Sahip olunan şey bir eşya, bir aile üyesi, bir özellik (göz, saç rengi) ya da bir hastalık olabilir: *I\'ve got a cold.* (Nezle oldum.)\n\n> Higo\'nun ipucu: \"There is\" de \"var\" diye çevrilir ama anlamı farklıdır. **There is a cat in the garden** \"bahçede bir kedi var\" (bir yerde bulunmak). **I\'ve got a cat** \"bir kedim var\" (sahip olmak).\n\n## have mı has mı?\n| Özne | Olumlu | Kısa hali |\n|---|---|---|\n| I / you / we / they | have got | I\'ve got, we\'ve got |\n| he / she / it | **has** got | he\'s got, she\'s got |\n\n- *My parents have got a car.* Annemle babamın bir arabası var.\n- *My cat has got green eyes.* Kedimin yeşil gözleri var.\n\nDikkat: **he\'s got** içindeki \'s, **has** demektir; **he\'s happy** içindeki \'s ise **is** demektir. Arkasından **got** geliyorsa \"has\"tır.\n\n## Olumsuz ve soru\n**Olumsuz:** have / has + **not** + got. Türkçede \"**yok**\" deriz.\n- I **haven\'t got** a brother. → *Erkek kardeşim yok.*\n- She **hasn\'t got** a phone. → *Onun telefonu yok.*\n\n**Soru:** have / has başa geçer. Türkçede \"**var mı?**\"\n- **Have** you **got** a pet? → *Evcil hayvanın var mı?*\n- **Has** he **got** any cousins? → *Onun hiç kuzeni var mı?*\n\n**Kısa cevap:** *Yes, I have. / No, I haven\'t.* · *Yes, she has. / No, she hasn\'t.* (Kısa cevapta **got** söylenmez.)\n\n> Higo\'nun ipucu: Amerikan İngilizcesinde aynı anlam **have** ile de söylenir: *I have a sister. Do you have a pet?* İkisi de doğrudur; sınavlarda ikisini de görürsün.\n\n## Kimin? İyelik sıfatları\nTürkçede sahipliği isme ek getirerek söyleriz: kitab**ım**, kitab**ın**, kitab**ı**. İngilizcede ismin **önüne** bir kelime gelir:\n\n| Özne | İyelik | Örnek | Türkçesi |\n|---|---|---|---|\n| I | **my** | my book | kitabım |\n| you | **your** | your bag | çantan |\n| he | **his** | his name | onun (erkek) adı |\n| she | **her** | her phone | onun (kadın) telefonu |\n| it | **its** | its tail | onun (hayvan) kuyruğu |\n| we | **our** | our teacher | öğretmenimiz |\n| they | **their** | their house | onların evi |\n\n- *This is **my** brother. **His** name is Efe.* Bu benim erkek kardeşim. Onun adı Efe.\n- *That\'s **our** grandmother. **Her** garden is beautiful.* Şu bizim büyükannemiz. Onun bahçesi çok güzel.\n\n## \'s ile sahiplik\nBir şeyin **belli bir kişiye** ait olduğunu söylemek için isme **\'s** ekleriz. Türkçedeki \"Ali\'**nin** kalemi\" yapısının karşılığıdır.\n\n- **Ali\'s** pen → *Ali\'nin kalemi*\n- **my mother\'s** car → *annemin arabası*\n- **the teacher\'s** desk → *öğretmenin masası*\n\nÇoğul isimlerde (sonu -s ile biten) sadece kesme işareti gelir: **my parents\'** room (annemle babamın odası).\n\n> Higo\'nun ipucu: **it\'s** = it is (o ... dır). **its** = onun. *It\'s a dog. Its name is Max.* (Bu bir köpek. Onun adı Max.)\n\n## Kendini kontrol et\n1. My sister ___ got long hair.\n2. ___ you got a cousin?\n3. This is Selin. ___ brother is ten.\n4. That is ___ (Mert) bike.\n\nCevaplar: 1. has · 2. Have · 3. Her · 4. Mert\'s','#FF8A3D',1,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(3,1,'Okulda','Sınıf eşyaları, this/that ve emir cümleleri','## Sınıfta neler var?\nBu ünitede sınıftaki eşyaların adlarını, **bu / şu** demeyi (this, that, these, those), öğretmeninin verdiği yönergeleri (emir cümleleri) ve **a / an** kullanımını öğreneceksin.\n\n| İngilizce | Türkçesi |\n|---|---|\n| desk | sıra, masa |\n| board | tahta |\n| pen / pencil | tükenmez / kurşun kalem |\n| rubber (eraser) | silgi |\n| notebook | defter |\n| ruler | cetvel |\n| schoolbag | okul çantası |\n| pencil case | kalem kutusu |\n| window / door | pencere / kapı |\n| classroom | sınıf |\n\n## this · that · these · those\nBu dört kelime, bir şeyin **sana yakın mı uzak mı**, **tek mi çok mu** olduğunu gösterir.\n\n| | Yakın (bu, bunlar) | Uzak (şu, şunlar) |\n|---|---|---|\n| Tekil | **this** pen *bu kalem* | **that** door *şu kapı* |\n| Çoğul | **these** books *bu kitaplar* | **those** windows *şu pencereler* |\n\n- **This is** my desk. → *Bu benim sıram.*\n- **That is** the teacher\'s bag. → *Şu öğretmenin çantası.*\n- **These are** my friends. → *Bunlar benim arkadaşlarım.*\n- **Those are** new computers. → *Şunlar yeni bilgisayarlar.*\n\nSoru: *What\'s this? It\'s a ruler.* (Bu ne? Bu bir cetvel.) · *What are those? They\'re maps.* (Şunlar ne? Haritalar.)\n\n> Higo\'nun ipucu: these ve those\'tan sonra fiil **are** olur ve isim çoğul gelir: *These **are** pencil**s**.*\n\n## Emir cümleleri (Imperatives)\nEmir cümlesi bir **yönerge, rica ya da uyarı** verir. Fiil yalın haliyle cümlenin başına gelir; özne (you) söylenmez. Türkçedeki \"Aç! Otur! Dinle!\" gibidir.\n\n| İngilizce | Türkçesi |\n|---|---|\n| **Open** your books. | Kitaplarınızı açın. |\n| **Listen** and repeat. | Dinleyin ve tekrar edin. |\n| **Sit** down, please. | Lütfen oturun. |\n| **Work** in pairs. | İkişerli çalışın. |\n| **Look** at the board. | Tahtaya bakın. |\n\n**Olumsuz emir:** başa **Don\'t** gelir. *Yapma!* anlamındadır.\n- **Don\'t** run in the corridor. → *Koridorda koşmayın.*\n- **Don\'t** forget your homework. → *Ödevini unutma.*\n\n> Higo\'nun ipucu: Emir cümlesine **please** eklersen kibar bir rica olur: *Please close the window.* (Pencereyi kapatır mısın lütfen.)\n\n## a / an: \"bir\"\n**a** ve **an**, tekil ve sayılabilen bir ismin önünde \"**bir**\" anlamına gelir. Hangisini seçeceğin, sonraki kelimenin **yazılışına değil, okunuşuna** bağlıdır:\n\n| Kural | Örnek |\n|---|---|\n| Ünsüz sesle başlıyorsa **a** | **a** pen, **a** book, **a** university (/yu/ diye okunur) |\n| Ünlü sesle başlıyorsa **an** | **an** apple, **an** eraser, **an** hour (h okunmaz) |\n\n- *I\'ve got **a** dictionary and **an** umbrella.* Bir sözlüğüm ve bir şemsiyem var.\n- Meslekten önce de kullanılır: *She\'s **an** engineer.* (O bir mühendis.) Türkçede \"bir\" demesek de İngilizcede şarttır.\n\nÇoğul isimlerde a / an kullanılmaz: *a pens* yanlış, **pens** ya da **some pens** doğru.\n\n## Sınıf İngilizcesi: işine yarayacak cümleler\n| İngilizce | Türkçesi |\n|---|---|\n| Can you repeat that, please? | Tekrar eder misiniz, lütfen? |\n| How do you say \"silgi\" in English? | \"Silgi\" İngilizcede nasıl denir? |\n| What does \"ruler\" mean? | \"Ruler\" ne demek? |\n| Can I go to the toilet? | Tuvalete gidebilir miyim? |\n| I don\'t understand. | Anlamadım. |\n| Sorry, I\'m late. | Özür dilerim, geç kaldım. |\n\n## Kendini kontrol et\n1. ___ (bunlar) are my pencils.\n2. Don\'t ___ (konuşmak) in the library.\n3. She\'s got ___ orange bag.\n4. Is ___ (şu) your teacher?\n\nCevaplar: 1. These · 2. talk · 3. an · 4. that','#FFB400',2,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(4,1,'Günüm','Geniş zaman, saatler ve sıklık zarfları','## Bir günün İngilizcesi\nBu ünitede günlük rutinini anlatmayı, **geniş zamanı** (Present Simple), ne sıklıkla bir şey yaptığını ve saati söylemeyi öğreneceksin.\n\n| İngilizce | Türkçesi |\n|---|---|\n| wake up / get up | uyanmak / kalkmak |\n| have breakfast | kahvaltı yapmak |\n| go to school | okula gitmek |\n| do homework | ödev yapmak |\n| have a shower | duş almak |\n| go to bed | yatmak |\n\n## Present Simple ne anlatır?\nPresent Simple, Türkçedeki **geniş zaman** gibidir. **Her zaman, düzenli olarak** olan şeyleri ve **genel doğruları** anlatır. Şu an olanı anlatmaz.\n\n| Ne anlatır? | Örnek | Türkçesi |\n|---|---|---|\n| Alışkanlık, rutin | I **get up** at seven. | Yedide kalkarım. |\n| Genel doğru | Water **boils** at 100°C. | Su 100 derecede kaynar. |\n| Kalıcı durum | She **lives** in Konya. | O Konya\'da yaşıyor. |\n| Program, tarife | The bus **leaves** at 8:15. | Otobüs 8.15\'te kalkar. |\n\n## he / she / it ile -s eki\nÖzne **he, she, it** (ya da tek bir kişi) olunca fiile **-s** eklenir. Bu, Türklerin en sık unuttuğu kuraldır.\n\n| Özne | Fiil | Örnek |\n|---|---|---|\n| I / you / we / they | yalın | I **play** football. |\n| he / she / it | **-s** | He **plays** football. |\n\n**Yazım kuralları**\n- Çoğu fiil: + s → work**s**, read**s**\n- -s, -sh, -ch, -x, -o ile bitenler: + es → watch**es**, go**es**, do**es**\n- ünsüz + y: y düşer, **-ies** → study → stud**ies**\n- **have → has** (düzensiz)\n\n> Higo\'nun ipucu: Cümlenin öznesi \"Ali\", \"my mother\" ya da \"the cat\" ise de **-s** gelir: *My mother **works** in a hospital.*\n\n## Olumsuz ve soru: do / does\nOlumsuz ve soru cümlelerinde yardımcı fiil **do / does** kullanılır. **does** gelince ana fiilin -s\'si düşer.\n\n**Olumsuz** (-maz / -mez)\n- I **don\'t** eat meat. → *Et yemem.*\n- He **doesn\'t** like coffee. → *O kahve sevmez.* (doesn\'t like**s** yanlış)\n\n**Soru** (-r mı?)\n- **Do** you speak English? → *İngilizce konuşur musun?*\n- **Does** she live here? → *O burada mı yaşıyor?*\n- **What time do** you get up? → *Kaçta kalkarsın?*\n\n**Kısa cevap:** *Yes, I do. / No, I don\'t.* · *Yes, he does. / No, he doesn\'t.*\n\n## Ne sıklıkla? Sıklık zarfları\n| Zarf | Türkçesi | Sıklık |\n|---|---|---|\n| always | her zaman | %100 |\n| usually | genellikle | %80 |\n| often | sık sık | %60 |\n| sometimes | bazen | %40 |\n| rarely | nadiren | %10 |\n| never | asla, hiç | %0 |\n\n**Yeri:** ana fiilden **önce**, ama **am / is / are**\'dan **sonra** gelir.\n- I **always** have breakfast. → *Her zaman kahvaltı yaparım.*\n- She is **never** late. → *O asla geç kalmaz.*\n\nSoru: **How often** do you go to the cinema? *Ne sıklıkla sinemaya gidersin?* · *Once a week.* (Haftada bir.) *Twice a month.* (Ayda iki kez.)\n\n> Higo\'nun ipucu: **never** zaten olumsuz anlam taşır. *I don\'t never* yanlış; **I never** doğru.\n\n## Saat kaç?\n**What time is it?** (Saat kaç?) · **What time do you...?** (Kaçta ...?)\n\n| Saat | İngilizce |\n|---|---|\n| 7:00 | It\'s seven o\'clock. |\n| 7:15 | It\'s quarter past seven. / seven fifteen |\n| 7:30 | It\'s half past seven. / seven thirty |\n| 7:45 | It\'s quarter to eight. / seven forty-five |\n| 7:10 | It\'s ten past seven. |\n| 7:50 | It\'s ten to eight. |\n\n**past** = geçiyor, **to** = var. *at* ile \"-de/-da\": *I go to bed **at** ten.* (Onda yatarım.)\n\n## Kendini kontrol et\n1. My brother ___ (watch) TV every evening.\n2. ___ your father work on Saturdays?\n3. I ___ (not / like) tea.\n4. She is ___ (her zaman) happy.\n\nCevaplar: 1. watches · 2. Does · 3. don\'t like · 4. always','#2EC4A0',3,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(5,1,'Evim','Ev, odalar, there is/are ve yer edatları','## Evini anlat\nBu ünitede evindeki odaları ve eşyaları, bir yerde ne **bulunduğunu** (There is / There are) ve eşyaların **nerede** olduğunu (yer edatları) anlatmayı öğreneceksin.\n\n| İngilizce | Türkçesi |\n|---|---|\n| living room | oturma odası |\n| kitchen | mutfak |\n| bedroom | yatak odası |\n| bathroom | banyo |\n| garden | bahçe |\n| balcony | balkon |\n| sofa | kanepe |\n| wardrobe | gardırop |\n| fridge | buzdolabı |\n| carpet | halı |\n\n## There is / There are: \"... var\"\nBir yerde bir şeyin **bulunduğunu** söylerken kullanılır. Türkçede \"**... var**\" deriz.\n\n| | Yapı | Örnek | Türkçesi |\n|---|---|---|---|\n| Tekil | **There is** (There\'s) + a/an | There\'s a sofa in the living room. | Oturma odasında bir kanepe var. |\n| Sayılamayan | **There is** + isim | There\'s some milk in the fridge. | Buzdolabında biraz süt var. |\n| Çoğul | **There are** + çoğul | There are two bedrooms. | İki yatak odası var. |\n\n> Higo\'nun ipucu: \"Var\" deyince hemen **have got** deme. Bir yerde bulunmak için **there is**, sahip olmak için **have got**: *There\'s a TV in my room.* (Odamda TV var.) · *I\'ve got a TV.* (TV\'m var.)\n\n## Olumsuz ve soru\n**Olumsuz** (\"yok\"):\n- There **isn\'t** a garden. → *Bahçe yok.*\n- There **aren\'t any** chairs in the kitchen. → *Mutfakta hiç sandalye yok.*\n\n**Soru** (\"var mı?\"):\n- **Is there** a lift in your building? → *Binanızda asansör var mı?* · *Yes, there is. / No, there isn\'t.*\n- **Are there any** shops near your house? → *Evinin yakınında dükkan var mı?* · *Yes, there are. / No, there aren\'t.*\n- **How many** rooms **are there**? → *Kaç oda var?*\n\nÇoğul olumsuz ve sorularda genellikle **any** kullanılır (\"hiç\").\n\n## Nerede? Yer edatları\nTürkçede yer bildirmek için ismin sonuna ek koyarız (masa**da**, kutu**nun içinde**). İngilizcede ismin **önüne** bir edat gelir.\n\n| Edat | Türkçesi | Örnek |\n|---|---|---|\n| in | içinde, -de | The keys are **in** the bag. *Anahtarlar çantada.* |\n| on | üstünde | The book is **on** the table. *Kitap masanın üstünde.* |\n| under | altında | The cat is **under** the bed. *Kedi yatağın altında.* |\n| next to | yanında | The lamp is **next to** the sofa. *Lamba kanepenin yanında.* |\n| between | arasında | The shop is **between** the bank and the café. *Dükkan bankayla kafenin arasında.* |\n| behind | arkasında | The garden is **behind** the house. *Bahçe evin arkasında.* |\n| in front of | önünde | There\'s a car **in front of** the door. *Kapının önünde bir araba var.* |\n| opposite | karşısında | The school is **opposite** the park. *Okul parkın karşısında.* |\n\n## Odanı anlatan bir paragraf\n> My bedroom is small but cosy. There\'s a bed next to the window and there\'s a desk opposite the bed. There are some posters on the wall. My books are on the shelf and my guitar is behind the door. There isn\'t a TV in my room.\n\n*Yatak odam küçük ama sıcacık. Pencerenin yanında bir yatak, yatağın karşısında bir masa var. Duvarda birkaç poster var. Kitaplarım rafta, gitarım kapının arkasında. Odamda televizyon yok.*\n\n## Kendini kontrol et\n1. There ___ three windows in my room.\n2. ___ there a bathroom upstairs?\n3. The ball is ___ (altında) the chair.\n4. There ___ any milk. (olumsuz)\n\nCevaplar: 1. are · 2. Is · 3. under · 4. isn\'t','#3A6FF7',4,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(6,1,'Yemek ve Alışveriş','Yiyecekler, some/any ve fiyat sormak','## Mutfakta ve markette\nBu ünitede yiyecek ve içecekleri, **sayılabilen / sayılamayan** isimleri, **some / any** ile miktar söylemeyi ve **How much / How many** ile miktar sormayı öğreneceksin.\n\n| İngilizce | Türkçesi |\n|---|---|\n| bread | ekmek |\n| cheese | peynir |\n| egg | yumurta |\n| tomato | domates |\n| rice | pirinç |\n| water | su |\n| apple | elma |\n| sugar | şeker |\n| a bottle of | bir şişe |\n| a kilo of | bir kilo |\n| a loaf of | bir somun |\n| a packet of | bir paket |\n\n## Sayılabilen ve sayılamayan isimler\n**Sayılabilen** isimler tek tek sayılır; tekil ve çoğul halleri vardır: *an apple, two apples*.\n**Sayılamayan** isimler bir bütündür, tanelere ayrılmaz; çoğul olmaz ve **a / an** almaz: *water, milk, rice, bread, money, information*.\n\n| Sayılabilen | Sayılamayan |\n|---|---|\n| an egg, three eggs | some milk |\n| a tomato, tomatoes | some cheese |\n| a sandwich, sandwiches | some bread |\n\nSayılamayan bir şeyi saymak istersen bir ölçü kullanırsın: **a glass of** water (bir bardak su), **a slice of** bread (bir dilim ekmek), **two kilos of** rice (iki kilo pirinç).\n\n> Higo\'nun ipucu: Türkçede \"iki ekmek\" deriz ama İngilizcede *two breads* denmez: **two loaves of bread**. Aynı şekilde *an information* yerine **some information**.\n\n## some / any\nİkisi de \"**biraz, birkaç, hiç**\" gibi belirsiz bir miktarı anlatır.\n\n| Nerede? | Kelime | Örnek | Türkçesi |\n|---|---|---|---|\n| Olumlu cümle | **some** | There are **some** eggs. | Birkaç yumurta var. |\n| Olumsuz cümle | **any** | We haven\'t got **any** sugar. | Hiç şekerimiz yok. |\n| Soru | **any** | Is there **any** juice? | Hiç meyve suyu var mı? |\n| Teklif ve rica | **some** | Would you like **some** tea? | Biraz çay ister misin? |\n\n## How much / How many\n| Soru | Hangi isimle? | Örnek | Türkçesi |\n|---|---|---|---|\n| **How many** | sayılabilen, çoğul | How many eggs do we need? | Kaç yumurtaya ihtiyacımız var? |\n| **How much** | sayılamayan | How much milk is there? | Ne kadar süt var? |\n| **How much** | fiyat | How much is this? / How much are these? | Bu ne kadar? / Bunlar ne kadar? |\n\nCevapta: **a lot of / lots of** (çok), **a few** (birkaç, sayılabilen), **a little** (biraz, sayılamayan).\n- *There are a few apples.* Birkaç elma var. · *There\'s a little cheese.* Biraz peynir var.\n\n## Markette konuşma\n| İngilizce | Türkçesi |\n|---|---|\n| Can I have a kilo of tomatoes, please? | Bir kilo domates alabilir miyim? |\n| How much is it? It\'s 40 lira. | Ne kadar? 40 lira. |\n| Anything else? No, thanks. | Başka bir şey? Hayır, teşekkürler. |\n| Here you are. | Buyurun. |\n| Can I pay by card? | Kartla ödeyebilir miyim? |\n\n> Higo\'nun ipucu: Restoranda sipariş verirken **I\'d like ...** (... istiyorum) de; *I want* biraz kaba kaçar. *I\'d like a lentil soup, please.*\n\n## Kendini kontrol et\n1. Is there ___ bread? (soru)\n2. How ___ apples are there?\n3. I\'d like ___ water, please.\n4. There are ___ (birkaç) oranges in the bag.\n\nCevaplar: 1. any · 2. many · 3. some · 4. a few','#22B573',5,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(7,1,'Şehirde','Yol tarifi, yerler ve can / can\'t','## Şehirde kaybolma!\nBu ünitede şehirdeki yerleri, **yol sormayı ve tarif etmeyi** ve **can / can\'t** ile yetenek, izin ve rica cümleleri kurmayı öğreneceksin.\n\n| İngilizce | Türkçesi |\n|---|---|\n| bank | banka |\n| hospital | hastane |\n| pharmacy | eczane |\n| post office | postane |\n| bus stop | otobüs durağı |\n| train station | tren istasyonu |\n| museum | müze |\n| square | meydan |\n| bridge | köprü |\n| traffic lights | trafik ışıkları |\n\n## Yol sormak\nYabancı birine yol sorarken önce **Excuse me** (Affedersiniz) ile başla.\n\n| İngilizce | Türkçesi |\n|---|---|\n| Excuse me, where is the museum? | Affedersiniz, müze nerede? |\n| How can I get to the station? | İstasyona nasıl gidebilirim? |\n| Is there a pharmacy near here? | Buralarda eczane var mı? |\n| Is it far? / Is it near? | Uzak mı? / Yakın mı? |\n| How long does it take? | Ne kadar sürer? |\n\n## Yol tarif etmek\nTarif verirken **emir cümleleri** kullanılır.\n\n| İngilizce | Türkçesi |\n|---|---|\n| Go straight on. | Düz gidin. |\n| Turn left / right. | Sola / sağa dönün. |\n| Take the first / second street on the left. | Soldaki ilk / ikinci sokağa girin. |\n| Go past the bank. | Bankayı geçin. |\n| Cross the road. | Karşıya geçin. |\n| It\'s on your left / right. | Solunuzda / sağınızda. |\n| It\'s at the end of the street. | Sokağın sonunda. |\n| It\'s on the corner. | Köşede. |\n\n**Örnek diyalog**\n> A: Excuse me, how can I get to the post office?\n> B: Go straight on and turn right at the traffic lights. Go past the bank. The post office is on your left, opposite the park.\n> A: Is it far?\n> B: No, it\'s about five minutes on foot.\n\n> Higo\'nun ipucu: Yön verirken **at** ile yer belirtilir: *Turn left **at** the corner / **at** the traffic lights.*\n\n## can: yapabilmek\n**can**, Türkçedeki **-ebilmek / -abilmek** ekinin karşılığıdır. Üç işe yarar:\n\n| Ne anlatır? | Örnek | Türkçesi |\n|---|---|---|\n| Yetenek | I **can** swim. | Yüzebilirim. (yüzmeyi bilirim) |\n| İzin | **Can** I open the window? | Pencereyi açabilir miyim? |\n| Rica | **Can** you help me, please? | Bana yardım edebilir misiniz? |\n\n**Kurallar**\n- Her özneyle aynıdır, **-s almaz**: *She can dance.* (She cans yanlış)\n- Arkasından fiil **yalın** gelir, **to** gelmez: *I can speak*, *I can to speak* yanlış.\n- Olumsuz: **can\'t / cannot** → *He can\'t drive.* (Araba süremez.)\n- Soru: can başa geçer → *Can you play the guitar? Yes, I can. / No, I can\'t.*\n\n## Şehirde can ile cümleler\n- *You **can** take the metro to the airport.* Havalimanına metroyla gidebilirsin.\n- *You **can\'t** park here.* Buraya park edemezsin. (yasak)\n- ***Can** I have a map, please?* Bir harita alabilir miyim?\n- *Where **can** I buy a ticket?* Bileti nereden alabilirim?\n\n> Higo\'nun ipucu: Daha kibar bir rica için **Could you ...?** kullan: *Could you show me on the map?* (Haritada gösterebilir misiniz?)\n\n## Kendini kontrol et\n1. Turn left ___ the traffic lights.\n2. My sister ___ (yüzebilir) very well.\n3. ___ I sit here? (izin)\n4. Go ___ the bank, it\'s next to the café.\n\nCevaplar: 1. at · 2. can swim · 3. Can · 4. past','#3AB0E6',6,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(8,1,'Şu An','Şimdiki zaman, kıyafetler ve hava durumu','## Şu anda ne oluyor?\nBu ünitede **şu an** olan şeyleri anlatmayı (Present Continuous), fiillere **-ing** eklemenin yazım kurallarını ve hava durumunu konuşmayı öğreneceksin.\n\n## Present Continuous ne anlatır?\nPresent Continuous, Türkçedeki **-yor** ekine benzer. **Tam konuşurken** ya da **bu günlerde geçici olarak** devam eden olayları anlatır.\n\n| Ne anlatır? | Örnek | Türkçesi |\n|---|---|---|\n| Şu an olan | I\'m **reading** a book now. | Şu an kitap okuyorum. |\n| Bu sıralar geçici | She\'s **staying** with her aunt this week. | Bu hafta teyzesinde kalıyor. |\n| Değişen durum | It\'s **getting** cold. | Hava soğuyor. |\n\n**Yapı:** am / is / are + fiil**-ing**\n\n| Özne | Örnek |\n|---|---|\n| I | I**\'m** studying. |\n| he / she / it | He**\'s** sleeping. |\n| you / we / they | They**\'re** playing. |\n\n## Olumsuz ve soru\n**Olumsuz** (-mıyor):\n- I\'m **not** watching TV. → *Televizyon izlemiyorum.*\n- It **isn\'t** raining. → *Yağmur yağmıyor.*\n\n**Soru** (-yor mu?):\n- **Are** you listening? → *Dinliyor musun?* · *Yes, I am. / No, I\'m not.*\n- **What is** she doing? → *O ne yapıyor?*\n- **Why are** you laughing? → *Neden gülüyorsun?*\n\nZaman ifadeleri: **now** (şimdi), **right now** (tam şu an), **at the moment** (şu anda), **today**, **this week**, **Look!**, **Listen!**\n\n## Geniş zaman mı, şimdiki zaman mı?\nTürkçede ikisini de bazen \"-yor\" ile söyleriz, bu yüzden karıştırılır.\n\n| Present Simple (rutin) | Present Continuous (şu an) |\n|---|---|\n| I **walk** to school every day. *Her gün okula yürürüm.* | I\'m **taking** the bus today. *Bugün otobüse biniyorum.* |\n| He **plays** the piano. *Piyano çalar (bilir).* | He\'s **playing** the piano now. *Şu an piyano çalıyor.* |\n\n> Higo\'nun ipucu: Bazı fiiller \"durum\" bildirdiği için -ing almaz: **like, love, want, know, understand, need, believe**. *I\'m knowing* yanlış, **I know** doğru.\n\n## -ing yazımı\n| Kural | Örnek |\n|---|---|\n| Çoğu fiil: + ing | read → read**ing**, play → play**ing** |\n| Sessiz -e ile bitenler: e düşer | write → writ**ing**, dance → danc**ing** |\n| Kısa fiil, ünlü + tek ünsüz: son harf ikilenir | run → ru**nn**ing, swim → swi**mm**ing, sit → si**tt**ing |\n| -ie ile bitenler: ie → y | lie → l**ying**, die → d**ying** |\n\n## Hava durumu\n**What\'s the weather like?** (Hava nasıl?)\n\n| İngilizce | Türkçesi |\n|---|---|\n| It\'s sunny. | Hava güneşli. |\n| It\'s cloudy. | Bulutlu. |\n| It\'s windy. | Rüzgarlı. |\n| It\'s raining. / It\'s rainy. | Yağmur yağıyor. / Yağmurlu. |\n| It\'s snowing. | Kar yağıyor. |\n| It\'s hot / warm / cool / cold. | Sıcak / ılık / serin / soğuk. |\n| It\'s 25 degrees. | Hava 25 derece. |\n\n> Higo\'nun ipucu: Havadan söz ederken özne her zaman **it** olur: *It\'s raining*. Türkçedeki gibi özneyi atlayamazsın.\n\n## Kendini kontrol et\n1. Look! The baby ___ (sleep).\n2. We ___ (not / watch) TV now.\n3. ___ it raining in Ankara?\n4. My father ___ (cook) dinner every Sunday.\n\nCevaplar: 1. is sleeping · 2. aren\'t watching · 3. Is · 4. cooks','#8F7CF8',7,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(9,1,'Hafta Sonum','Hobiler, like + -ing ve A1 tekrarı','## Boş zamanında ne yaparsın?\nBu ünitede hobilerini anlatmayı, **like / love / hate + -ing** ile neyi sevip sevmediğini söylemeyi ve **soru kelimeleriyle** sohbet açmayı öğreneceksin. Son sayfada A1\'in kısa bir tekrarı var.\n\n| İngilizce | Türkçesi |\n|---|---|\n| play football / basketball | futbol / basketbol oynamak |\n| play the guitar / piano | gitar / piyano çalmak |\n| go swimming / cycling | yüzmeye / bisiklete gitmek |\n| watch films / series | film / dizi izlemek |\n| read comics | çizgi roman okumak |\n| hang out with friends | arkadaşlarla takılmak |\n\n> Higo\'nun ipucu: Spor için **play football** (the yok), çalgı için **play the guitar** (the var) dersin.\n\n## like / love / hate + -ing\nBir etkinliği sevip sevmediğini söylerken bu fiillerden sonra ikinci fiil **-ing** alır.\n\n| Fiil | Türkçesi | Örnek |\n|---|---|---|\n| love | çok sevmek | I **love dancing**. *Dans etmeyi çok severim.* |\n| like / enjoy | sevmek, hoşlanmak | She **likes reading**. *O okumayı sever.* |\n| don\'t mind | sorun etmemek | I **don\'t mind cooking**. *Yemek yapmak bana dert değil.* |\n| don\'t like | sevmemek | We **don\'t like waiting**. *Beklemeyi sevmeyiz.* |\n| hate | nefret etmek | He **hates getting up** early. *Erken kalkmaktan nefret eder.* |\n\nSoru: *Do you like playing chess?* (Satranç oynamayı sever misin?) · *What do you like doing at the weekend?* (Hafta sonu ne yapmayı seversin?)\n\n## would like: istemek (bir kez)\n**like** genel bir zevki anlatır; **would like** (I\'d like) şu an bir şeyi **istemeyi**, kibarca.\n- *I **like** pizza.* Pizza severim. (genel)\n- *I**\'d like** a pizza, please.* Bir pizza istiyorum. (şimdi)\n- *Would you like to come to the cinema?* Sinemaya gelmek ister misin? (davet; **to** + fiil)\n\n## Soru kelimeleri\n| Kelime | Türkçesi | Örnek |\n|---|---|---|\n| What | ne | What\'s your favourite sport? *En sevdiğin spor ne?* |\n| Where | nerede, nereye | Where do you play tennis? *Tenisi nerede oynarsın?* |\n| When | ne zaman | When is the match? *Maç ne zaman?* |\n| Who | kim | Who is your best friend? *En iyi arkadaşın kim?* |\n| Why | neden | Why do you like jazz? *Cazı neden seversin?* · Because... *Çünkü...* |\n| How | nasıl | How do you go to school? *Okula nasıl gidersin?* |\n| How old | kaç yaşında | How old is your brother? |\n| Which | hangisi | Which team do you support? *Hangi takımı tutarsın?* |\n| Whose | kimin | Whose bag is this? *Bu kimin çantası?* |\n\n**Sıra:** Soru kelimesi + do/does veya am/is/are + özne + fiil → *Where **do you** live?*\n\n## A1\'de neler öğrendin?\n| Konu | Örnek |\n|---|---|\n| to be | I\'m a student. Are you tired? |\n| have got | She\'s got two brothers. (sahiplik) |\n| İyelik ve \'s | my book, Ali\'s pen |\n| this / that / these / those | These are my friends. |\n| There is / are | There\'s a park near my house. |\n| Present Simple | He gets up at seven. |\n| can | I can swim but I can\'t ski. |\n| some / any, much / many | How much milk is there? |\n| Present Continuous | It\'s raining now. |\n| like + -ing | I love playing chess. |\n\n> Higo\'nun ipucu: A2\'ye geçmeden önce Present Simple ile Present Continuous\'ı tekrar et. Geçmiş zamanı öğrenirken bu ikisi temel olacak.\n\n## Kendini kontrol et\n1. My sister hates ___ (get up) early.\n2. ___ is your birthday? In May.\n3. I\'d like ___ (go) to the concert.\n4. ___ do you live? In Eskişehir.\n\nCevaplar: 1. getting · 2. When · 3. to go · 4. Where','#FF7FB0',8,'2026-10-04 20:30:40','2026-10-04 20:30:40'),
(10,2,'Dün','was / were ve düzenli geçmiş zaman','## Dün neredeydin?\nBu ünitede geçmişi anlatmaya başlıyorsun: **was / were** ile geçmişteki durumları, **-ed** ekiyle düzenli fiillerin geçmiş halini ve **dün, geçen hafta** gibi zaman ifadelerini öğreneceksin.\n\nTürkçede geçmişi **-di** ekiyle söyleriz: *evdeydim, yorgundu, oynadık*. İngilizcede bunun iki yolu var:\n- **to be** fiili için: **was / were** → *I was at home.* (Evdeydim.)\n- Diğer fiiller için: **-ed** (ya da düzensiz hali) → *We played.* (Oynadık.)\n\n## was / were: geçmişte \"-dı / -di\"\n**was** ve **were**, am / is / are\'ın geçmiş halidir. Geçmişteki bir **durumu, yeri, duyguyu** anlatır.\n\n| Özne | Şimdi | Geçmiş | Örnek | Türkçesi |\n|---|---|---|---|---|\n| I | am | **was** | I was tired. | Yorgundum. |\n| he / she / it | is | **was** | She was at school. | O okuldaydı. |\n| you / we / they | are | **were** | We were happy. | Mutluyduk. |\n\n- **Olumsuz:** *It wasn\'t cold.* (Hava soğuk değildi.) · *They weren\'t at home.* (Evde değillerdi.)\n- **Soru:** *Were you at the party?* (Partide miydin?) · *Yes, I was. / No, I wasn\'t.*\n- *Where were you yesterday?* (Dün neredeydin?)\n\n**there was / there were:** geçmişte \"vardı\" → *There was a big tree in our garden.* (Bahçemizde büyük bir ağaç vardı.)\n\n## Düzenli fiiller: -ed\nGeçmişte yapılıp **bitmiş** bir eylemi anlatmak için fiile **-ed** eklenir. Bu hal **her özneyle aynıdır**.\n\n| Yalın | Geçmiş | Örnek | Türkçesi |\n|---|---|---|---|\n| play | play**ed** | We played chess. | Satranç oynadık. |\n| watch | watch**ed** | She watched a film. | Bir film izledi. |\n| visit | visit**ed** | I visited my grandma. | Büyükannemi ziyaret ettim. |\n\n**Yazım kuralları**\n- Sonu -e ile bitenler: sadece **-d** → live**d**, dance**d**\n- ünsüz + y: **-ied** → study → stud**ied**, cry → cr**ied**\n- kısa fiil, ünlü + tek ünsüz: son harf ikilenir → stop → sto**pp**ed, plan → pla**nn**ed\n\n**Okunuşu:** -ed üç şekilde okunur: /t/ (walked), /d/ (played), /ɪd/ (wanted, needed). Sonu **t** ya da **d** ile biten fiillerde ayrı bir hece olur.\n\n## Geçmiş zaman ifadeleri\n| İngilizce | Türkçesi |\n|---|---|\n| yesterday | dün |\n| yesterday morning / evening | dün sabah / akşam |\n| last night / week / year | dün gece / geçen hafta / geçen yıl |\n| two days ago | iki gün önce |\n| in 2020 | 2020\'de |\n| when I was a child | çocukken |\n\n**ago** \"önce\" demektir ve süreden **sonra** gelir: *three years **ago*** (üç yıl önce).\n\n> Higo\'nun ipucu: \"Dün gece\" **last night** olur, *yesterday night* denmez. Ama \"dün sabah\" **yesterday morning** doğrudur.\n\n## Kısa bir anı\n> Last Saturday was great. The weather was sunny, so my friends and I walked to the park. We played football and then we watched a film at Emre\'s house. I was very tired in the evening.\n\n*Geçen cumartesi harikaydı. Hava güneşliydi, bu yüzden arkadaşlarımla parka yürüdük. Futbol oynadık, sonra Emre\'nin evinde film izledik. Akşam çok yorgundum.*\n\n## Kendini kontrol et\n1. I ___ at the cinema last night.\n2. ___ your parents at home yesterday?\n3. She ___ (study) for the exam.\n4. We visited Antalya two years ___.\n\nCevaplar: 1. was · 2. Were · 3. studied · 4. ago','#2EC4A0',0,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(11,2,'Hikâye Anlat','Düzensiz fiiller ve geçmişte soru','## Bir anı anlat\nBu ünitede geçmişte olan bir olayı hikâye gibi anlatmayı öğreneceksin. Bunun için en sık kullanılan **düzensiz fiillerin** geçmiş halleri ve **did** ile soru ve olumsuz cümleler gerekiyor.\n\nHikâye anlatırken olayları sıraya koyan kelimeler çok işe yarar:\n\n| İngilizce | Türkçesi |\n|---|---|\n| First, ... | Önce, ... |\n| Then / After that, ... | Sonra / Ondan sonra, ... |\n| Suddenly, ... | Aniden, ... |\n| In the end / Finally, ... | Sonunda, ... |\n\n## Düzensiz fiiller\nBazı fiiller geçmişte **-ed** almaz, tamamen değişir. Bunları ezberlemek gerekir; ama en sık kullanılan 20 tanesi konuşmanın büyük bölümünü karşılar.\n\n| Yalın | Geçmiş | Türkçesi |\n|---|---|---|\n| go | **went** | gitti |\n| have | **had** | sahipti, yedi |\n| get | **got** | aldı, oldu |\n| make | **made** | yaptı |\n| see | **saw** | gördü |\n| come | **came** | geldi |\n| take | **took** | aldı, götürdü |\n| eat | **ate** | yedi |\n| buy | **bought** | satın aldı |\n| find | **found** | buldu |\n| meet | **met** | tanıştı, buluştu |\n| say | **said** | dedi |\n| tell | **told** | anlattı, söyledi |\n| write | **wrote** | yazdı |\n| lose | **lost** | kaybetti |\n| leave | **left** | ayrıldı |\n\n- *We **went** to Kapadokya in the summer.* Yazın Kapadokya\'ya gittik.\n- *I **saw** a balloon in the sky.* Gökyüzünde bir balon gördüm.\n- *She **lost** her keys.* Anahtarlarını kaybetti.\n\n> Higo\'nun ipucu: Fiilleri gruplara ayırarak ezberle: **buy → bought, bring → brought, think → thought** hepsi \"-ought\" ile biter.\n\n## did ile olumsuz\nGeçmişte olumsuz cümle için **didn\'t** (did not) kullanılır. **didn\'t** geldiğinde ana fiil **yalın** haline döner, çünkü geçmiş bilgisini zaten did taşır.\n\n| Olumlu | Olumsuz | Türkçesi |\n|---|---|---|\n| I went to school. | I **didn\'t go** to school. | Okula gitmedim. |\n| She saw the film. | She **didn\'t see** the film. | Filmi görmedi. |\n| We played. | We **didn\'t play**. | Oynamadık. |\n\n*She didn\'t saw* **yanlış**: geçmiş iki kere söylenmez.\n\n## did ile soru\nSoru için **Did** başa gelir, ana fiil yine **yalın** olur.\n\n- **Did** you **enjoy** the trip? → *Geziden keyif aldın mı?* · *Yes, I did. / No, I didn\'t.*\n- **Where did** you **go**? → *Nereye gittin?*\n- **What did** she **buy**? → *O ne aldı?*\n- **When did** they **arrive**? → *Ne zaman vardılar?*\n\nDikkat: **was / were** cümlelerinde did kullanılmaz: *Did you were* yanlış, **Were you tired?** doğru.\n\n## Örnek hikâye\n> Last summer, my family and I **went** to Fethiye. First, we **took** a boat trip. Then we **swam** in the sea and **ate** fresh fish. Suddenly, my little brother **lost** his hat in the water! A kind man **found** it and **gave** it back. In the end, we **had** a wonderful day.\n\n*Geçen yaz ailemle Fethiye\'ye gittik. Önce tekne turuna çıktık. Sonra denizde yüzdük ve taze balık yedik. Aniden küçük kardeşim şapkasını suya düşürdü! Nazik bir adam onu buldu ve geri verdi. Sonunda harika bir gün geçirdik.*\n\n## Kendini kontrol et\n1. We ___ (go) to the zoo last weekend.\n2. I ___ (not / see) him yesterday.\n3. ___ you meet your cousin?\n4. What did she ___ (buy)?\n\nCevaplar: 1. went · 2. didn\'t see · 3. Did · 4. buy','#22B573',1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(12,2,'Planlar','be going to, gelecek planları ve tatil','## Gelecek planların\nBu ünitede geleceğe dair **planlarını ve niyetlerini** anlatmayı (be going to), önceden ayarlanmış randevuları (Present Continuous) ve gelecek zaman ifadelerini öğreneceksin.\n\n## be going to ne anlatır?\n**be going to**, Türkçedeki \"**-ecek / -acak**\" anlamını taşır ama özellikle **önceden karar verilmiş planları** anlatır. \"Bunu yapmayı düşünüyorum, niyetim bu\" demektir.\n\n| Ne anlatır? | Örnek | Türkçesi |\n|---|---|---|\n| Plan, niyet | I\'m going to learn the guitar. | Gitar öğreneceğim. (karar verdim) |\n| Kanıta dayalı tahmin | Look at those clouds! It\'s going to rain. | Şu bulutlara bak! Yağmur yağacak. |\n\n**Yapı:** am / is / are + going to + fiil (yalın)\n\n| Özne | Örnek |\n|---|---|\n| I | I\'m going to visit my aunt. |\n| he / she / it | She\'s going to study medicine. |\n| you / we / they | We\'re going to move house. |\n\n## Olumsuz ve soru\n- **Olumsuz:** *I\'m not going to watch TV tonight.* (Bu akşam TV izlemeyeceğim.) · *He isn\'t going to come.* (Gelmeyecek.)\n- **Soru:** *Are you going to join the club?* (Kulübe katılacak mısın?) · *Yes, I am. / No, I\'m not.*\n- *What are you going to do after school?* (Okuldan sonra ne yapacaksın?)\n- *Where is she going to stay?* (Nerede kalacak?)\n\n> Higo\'nun ipucu: Konuşma dilinde **going to** çoğu zaman **gonna** diye telaffuz edilir: *I\'m gonna call you.* Yazıda kullanma, ama dizilerde duyunca tanı.\n\n## Randevular: Present Continuous\nSaati, yeri belli, **ayarlanmış** gelecek planları için şimdiki zaman da kullanılır. Ajandana yazdığın şeyleri düşün.\n\n- *I\'m meeting Ayşe at 5 tomorrow.* Yarın 5\'te Ayşe ile buluşuyorum.\n- *We\'re flying to Izmir on Friday.* Cuma İzmir\'e uçuyoruz. (bilet alındı)\n- *What are you doing this weekend?* Bu hafta sonu ne yapıyorsun?\n\n## Zaman ifadeleri\n| İngilizce | Türkçesi |\n|---|---|\n| tonight | bu akşam |\n| tomorrow (morning) | yarın (sabah) |\n| the day after tomorrow | öbür gün |\n| next week / month / year | gelecek hafta / ay / yıl |\n| this weekend / summer | bu hafta sonu / yaz |\n| in two weeks | iki hafta sonra |\n| soon | yakında |\n\n**next** ile **the** kullanılmaz: *next Monday* (gelecek pazartesi), *the next Monday* değil.\n\n## Planlarını anlatan bir paragraf\n> This summer I\'m going to do lots of things. First, I\'m going to read five English books. In July, my family and I are visiting my grandparents in Rize. I\'m also going to learn how to swim. I\'m not going to spend all day on my phone!\n\n*Bu yaz birçok şey yapacağım. Önce beş İngilizce kitap okuyacağım. Temmuzda ailemle Rize\'de büyükannemle büyükbabamı ziyaret ediyoruz. Ayrıca yüzmeyi öğreneceğim. Bütün günü telefonla geçirmeyeceğim!*\n\n## Kendini kontrol et\n1. I ___ going to buy a new bike.\n2. ___ they going to play tennis?\n3. Look at the sky! It ___ (yağacak).\n4. We\'re meeting ___ Saturday.\n\nCevaplar: 1. am · 2. Are · 3. is going to rain · 4. on','#3A6FF7',2,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(13,2,'Karşılaştır','Karşılaştırma ve üstünlük sıfatları','## Hangisi daha iyi?\nBu ünitede iki şeyi **karşılaştırmayı** (daha büyük, daha ilginç), bir grubun içinde **en**\'i söylemeyi (en büyük, en ilginç) ve **as ... as** ile eşitliği anlatmayı öğreneceksin.\n\nTürkçede sıfatın önüne \"**daha**\" ve \"**en**\" koyarız. İngilizcede sıfatın uzunluğuna göre ya ek alır ya da önüne bir kelime gelir.\n\n## Karşılaştırma (Comparatives): daha ...\n| Sıfat türü | Kural | Örnek | Türkçesi |\n|---|---|---|---|\n| Kısa (tek hece) | **-er** | tall → taller | daha uzun |\n| -e ile biten | **-r** | nice → nicer | daha hoş |\n| ünlü + tek ünsüz | harf ikilenir + er | big → bigger | daha büyük |\n| -y ile biten | **-ier** | happy → happier | daha mutlu |\n| Uzun (2+ hece) | **more** + sıfat | interesting → more interesting | daha ilginç |\n\nKarşılaştırılan şey **than** (-den / -dan) ile gelir:\n- *Istanbul is **bigger than** Ankara.* İstanbul Ankara\'dan daha büyük.\n- *This book is **more interesting than** that one.* Bu kitap şundan daha ilginç.\n- *My brother is **younger than** me.* Kardeşim benden daha küçük.\n\n## Üstünlük (Superlatives): en ...\n| Sıfat türü | Kural | Örnek | Türkçesi |\n|---|---|---|---|\n| Kısa | **the -est** | tall → the tallest | en uzun |\n| -y ile biten | **the -iest** | easy → the easiest | en kolay |\n| Uzun | **the most** + sıfat | beautiful → the most beautiful | en güzel |\n\n- *Mount Ağrı is **the highest** mountain in Turkey.* Ağrı Dağı Türkiye\'nin en yüksek dağıdır.\n- *It\'s **the most popular** app in our class.* Sınıfımızdaki en popüler uygulama.\n\n\"-de / -da\" için yerlerde **in**, gruplarda **of** kullanılır: *the best student **in** the class*, *the oldest **of** the three*.\n\n## Düzensiz olanlar\n| Sıfat | Daha ... | En ... |\n|---|---|---|\n| good (iyi) | **better** | **the best** |\n| bad (kötü) | **worse** | **the worst** |\n| far (uzak) | **farther / further** | **the farthest / furthest** |\n| many / much | **more** | **the most** |\n\n- *My English is **better** now.* İngilizcem artık daha iyi.\n- *That was **the worst** day of my life!* Hayatımın en kötü günüydü!\n\n> Higo\'nun ipucu: İki ekli yapma: *more bigger* ya da *the most tallest* yanlış. Ya ek ya kelime: **bigger, the tallest**.\n\n## as ... as: kadar\nİki şeyin **eşit** olduğunu söylerken: **as + sıfat + as** (... kadar ...)\n- *Ali is **as tall as** his father.* Ali babası kadar uzun.\n- *This test isn\'t **as difficult as** the last one.* Bu sınav öncekisi kadar zor değil.\n\n**not as ... as**, \"daha az\" anlamı verir ve konuşmada çok kullanılır: *Trains aren\'t as fast as planes.* (Trenler uçaklar kadar hızlı değil.)\n\n## Karşılaştırma yapan bir paragraf\n> I live in Eskişehir. It\'s smaller than Istanbul and the traffic isn\'t as bad. In my opinion, it\'s the best city for students because it\'s cheaper and quieter than big cities. The most beautiful place is the Porsuk river.\n\n*Eskişehir\'de yaşıyorum. İstanbul\'dan daha küçük ve trafik o kadar kötü değil. Bence öğrenciler için en iyi şehir, çünkü büyük şehirlerden daha ucuz ve daha sakin. En güzel yer Porsuk çayı.*\n\n## Kendini kontrol et\n1. A car is ___ (fast) than a bike.\n2. This is the ___ (good) pizza in town.\n3. Maths is ___ difficult than art.\n4. She is as clever ___ her sister.\n\nCevaplar: 1. faster · 2. best · 3. more · 4. as','#FFB400',3,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(14,2,'Sağlık','Vücut, rahatsızlıklar ve should','## Kendini nasıl hissediyorsun?\nBu ünitede vücudun bölümlerini, **rahatsızlıkları** anlatmayı (başım ağrıyor, ateşim var) ve **should / shouldn\'t** ile tavsiye vermeyi öğreneceksin.\n\n| İngilizce | Türkçesi |\n|---|---|\n| head | baş |\n| stomach | mide, karın |\n| throat | boğaz |\n| back | sırt |\n| tooth / teeth | diş / dişler |\n| ear | kulak |\n| arm / leg | kol / bacak |\n| knee | diz |\n\n## Rahatsızlıklar\nRahatsızlık anlatırken çoğunlukla **have got / have** (sahiplik) kullanılır. Türkçedeki \"başım ağrıyor\"un karşılığı \"bir baş ağrım var\" gibidir.\n\n| İngilizce | Türkçesi |\n|---|---|\n| I\'ve got a headache. | Başım ağrıyor. |\n| I\'ve got a stomachache. | Midem ağrıyor. |\n| I\'ve got a toothache. | Dişim ağrıyor. |\n| I\'ve got a sore throat. | Boğazım ağrıyor. |\n| I\'ve got a temperature / a fever. | Ateşim var. |\n| I\'ve got a cold. / I\'ve got the flu. | Nezleyim. / Grip oldum. |\n| I\'ve got a cough. | Öksürüğüm var. |\n| My leg hurts. | Bacağım acıyor. |\n| I feel sick. / I feel dizzy. | Midem bulanıyor. / Başım dönüyor. |\n\n**Sormak için:** *What\'s the matter? / What\'s wrong?* (Neyin var? Ne oldu?) · *How do you feel?* (Nasıl hissediyorsun?)\n\n> Higo\'nun ipucu: **-ache** ile biten kelimeler \"ağrı\" demektir: head**ache**, back**ache**, ear**ache**. Bu kelimelerden önce genelde **a** kullanılır.\n\n## should / shouldn\'t: tavsiye\n**should** \"**-meli / -malı**\" anlamında bir **tavsiye, öneri** verir; zorunluluk değildir. \"Bence şunu yapsan iyi olur\" demektir.\n\n| Örnek | Türkçesi |\n|---|---|\n| You **should** see a doctor. | Doktora görünmelisin. |\n| You **should** drink lots of water. | Bol su içmelisin. |\n| You **shouldn\'t** eat so much sugar. | Bu kadar şeker yememelisin. |\n| He **shouldn\'t** go to school today. | Bugün okula gitmemeli. |\n\n**Kurallar:** her özneyle aynıdır (-s almaz), arkasından fiil yalın gelir (to yok).\n- **Soru:** *Should I take a painkiller?* (Ağrı kesici almalı mıyım?) · *What should I do?* (Ne yapmalıyım?)\n\n## Diğer tavsiye kalıpları\n| Kalıp | Örnek | Türkçesi |\n|---|---|---|\n| Why don\'t you ...? | Why don\'t you go to bed early? | Neden erken yatmıyorsun? (öneri) |\n| You\'d better ... | You\'d better stay at home. | Evde kalsan iyi olur. (daha güçlü) |\n| If I were you, I\'d ... | If I were you, I\'d rest. | Yerinde olsam dinlenirdim. |\n\n## Doktorda\n> Doctor: What\'s the matter?\n> Patient: I\'ve got a sore throat and a temperature.\n> Doctor: How long have you felt like this?\n> Patient: Since yesterday.\n> Doctor: You\'ve got the flu. You should stay in bed and drink warm drinks. You shouldn\'t go to school for two days.\n\n## Kendini kontrol et\n1. I\'ve got a ___ (diş ağrısı).\n2. You ___ eat more vegetables. (tavsiye)\n3. You ___ watch TV all night. (olumsuz tavsiye)\n4. What\'s the ___? I feel sick.\n\nCevaplar: 1. toothache · 2. should · 3. shouldn\'t · 4. matter','#FF5A5F',4,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(15,2,'Yolculuk','Ulaşım, will ve anlık kararlar','## Yola çıkalım\nBu ünitede seyahat kelimelerini, gelecek için **will** kullanımını ve **will ile going to arasındaki farkı** öğreneceksin.\n\n| İngilizce | Türkçesi |\n|---|---|\n| ticket | bilet |\n| passport | pasaport |\n| luggage | bavul, bagaj |\n| platform | peron |\n| book a hotel | otel ayırtmak |\n| check in | giriş yapmak |\n| departure / arrival | kalkış / varış |\n| delay | rötar |\n| return ticket | gidiş dönüş bilet |\n| single ticket | tek yön bilet |\n\n## will ne anlatır?\n**will** da \"**-ecek / -acak**\" demektir ama **önceden planlanmamış** gelecek için kullanılır:\n\n| Ne anlatır? | Örnek | Türkçesi |\n|---|---|---|\n| Anlık karar | It\'s cold. I\'ll close the window. | Hava soğuk. Pencereyi kapatayım. |\n| Tahmin, görüş | I think it will be sunny tomorrow. | Bence yarın hava güneşli olacak. |\n| Söz | I\'ll call you when I arrive. | Varınca seni arayacağım. |\n| Teklif | I\'ll carry your bag. | Çantanı ben taşırım. |\n| Rica | Will you help me? | Bana yardım eder misin? |\n\n**Yapı:** will + fiil (yalın), her özneyle aynı. Kısa hali **\'ll**: *I\'ll, she\'ll, we\'ll*.\n- **Olumsuz:** **won\'t** (will not) → *I won\'t be late.* (Geç kalmayacağım.)\n- **Soru:** *Will it be expensive?* (Pahalı olacak mı?) · *Yes, it will. / No, it won\'t.*\n\n> Higo\'nun ipucu: Tahminlerde will ile şu kalıplar çok kullanılır: **I think ..., I\'m sure ..., probably, maybe**. *She\'ll probably miss the bus.* (Muhtemelen otobüsü kaçıracak.)\n\n## going to mu, will mi?\n| going to | will |\n|---|---|\n| Önceden verilmiş karar, plan | O an verilen karar |\n| *I\'m going to visit Paris in May.* (Bileti aldım bile.) | *Oh, the phone is ringing. I\'ll answer it.* (Şimdi karar verdim.) |\n| Kanıta dayalı tahmin | Görüşe dayalı tahmin |\n| *Look, he\'s going to fall!* (Görüyorum, düşmek üzere.) | *I think he\'ll win the race.* (Bence kazanır.) |\n\n**Örnek:**\n> A: We haven\'t got any bread.\n> B: Really? I\'ll go to the shop. (anlık karar)\n> A: And what are your plans for tomorrow?\n> B: I\'m going to study for my test. (plan)\n\n## Seyahatte işe yarayan cümleler\n| İngilizce | Türkçesi |\n|---|---|\n| I\'d like a return ticket to Izmir, please. | İzmir\'e gidiş dönüş bir bilet istiyorum. |\n| What time does the train leave? | Tren kaçta kalkıyor? |\n| Which platform is it? | Hangi peron? |\n| I\'ve booked a room for two nights. | İki gecelik oda ayırttım. |\n| Is breakfast included? | Kahvaltı dahil mi? |\n| The flight is delayed. | Uçuş rötarlı. |\n\n## Kendini kontrol et\n1. I\'m thirsty. I think I ___ have some water. (anlık karar)\n2. We ___ going to stay at a hotel. (plan)\n3. Don\'t worry, I ___ (not) tell anyone.\n4. I\'d like a ___ ticket. (gidiş dönüş)\n\nCevaplar: 1. \'ll · 2. are · 3. won\'t · 4. return','#3AB0E6',5,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(16,2,'Deneyimler','Present perfect: ever / never','## Hiç ... yaptın mı?\nBu ünitede **hayatındaki deneyimleri** anlatmayı öğreneceksin. Bunun için İngilizcede Türkçede tam karşılığı olmayan bir zaman var: **Present Perfect**.\n\n## Present Perfect ne anlatır?\nPresent Perfect, geçmişte olan bir şeyin **şimdiyle bağlantısını** anlatır. Bu ünitede en önemli kullanımı: **ne zaman olduğu önemli olmayan hayat deneyimleri**.\n\n- *I **have been** to Paris.* Paris\'e gittim (hayatımda bir kez bulundum). Ne zaman olduğu önemli değil.\n- *She **has never eaten** sushi.* O hiç suşi yemedi.\n- ***Have** you ever **seen** a whale?* Hiç balina gördün mü?\n\nTürkçede bunları da \"-di\" ile söyleriz; bu yüzden İngilizcede iki zamanı ayırt etmek önemli.\n\n**Yapı:** have / has + fiilin **3. hali** (V3, past participle)\n\n| Özne | Örnek |\n|---|---|\n| I / you / we / they | I**\'ve** visited Rome. |\n| he / she / it | He**\'s** visited Rome. |\n\n## Fiilin 3. hali (V3)\nDüzenli fiillerde V3, geçmiş halle aynıdır (**-ed**): visit → visited → visited. Düzensizlerde ayrıca öğrenilir:\n\n| Yalın | Geçmiş (V2) | V3 | Türkçesi |\n|---|---|---|---|\n| be | was / were | **been** | olmak, bulunmak |\n| go | went | **gone** | gitmek |\n| see | saw | **seen** | görmek |\n| eat | ate | **eaten** | yemek |\n| do | did | **done** | yapmak |\n| write | wrote | **written** | yazmak |\n| meet | met | **met** | tanışmak |\n| fly | flew | **flown** | uçmak |\n| try | tried | **tried** | denemek |\n\n## ever / never\n| Kelime | Türkçesi | Nerede? | Örnek |\n|---|---|---|---|\n| ever | hiç (soruda) | soru | Have you **ever** tried snowboarding? *Hiç snowboard denedin mi?* |\n| never | hiç, asla (olumsuz anlam) | olumlu yapıda | I\'ve **never** been on a plane. *Hiç uçağa binmedim.* |\n\n**Cevaplar:** *Yes, I have. / No, I haven\'t.* · *Yes, once.* (Evet, bir kez.) · *No, never.* (Hayır, hiç.)\n\n## Present Perfect mi, Past Simple mı?\n| Present Perfect | Past Simple |\n|---|---|\n| Zaman **belli değil**, deneyim önemli | Zaman **belli** |\n| *I\'ve been to Antalya.* (Antalya\'yı gördüm.) | *I went to Antalya **last summer**.* |\n| *Have you ever met a famous person?* | *When did you meet him?* |\n\nSohbette sık görülen akış: önce Present Perfect ile deneyim sorulur, sonra Past Simple ile ayrıntıya geçilir.\n> A: Have you ever been to a concert?\n> B: Yes, I have. I went to a rock concert last year.\n> A: Did you enjoy it?\n> B: Yes, it was amazing!\n\n> Higo\'nun ipucu: **yesterday, last week, in 2019, ago** gibi kesin zaman ifadeleri Present Perfect ile kullanılmaz: *I have seen him yesterday* yanlış, **I saw him yesterday** doğru.\n\n## been mi, gone mı?\nİkisi de \"gitmek\" fiilinin V3\'ü gibi görünür ama anlamları farklıdır:\n\n| Cümle | Anlamı |\n|---|---|\n| She **has been** to London. | Londra\'ya gidip **döndü** (bir deneyim). |\n| She **has gone** to London. | Londra\'ya **gitti, hâlâ orada** (şu an burada değil). |\n\n## Kendini kontrol et\n1. Have you ___ been to Mardin?\n2. I have ___ (asla) eaten snails.\n3. She ___ (write) three books.\n4. We ___ (go) to the beach yesterday.\n\nCevaplar: 1. ever · 2. never · 3. has written · 4. went','#8F7CF8',6,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(17,2,'Kurallar','must / have to ve izinler','## Kurallar ve zorunluluklar\nBu ünitede okulda, evde ve trafikteki **kuralları** anlatmayı, **zorunluluk** (must, have to), **yasak** (mustn\'t) ve **gereksizlik** (don\'t have to) bildirmeyi öğreneceksin.\n\n| Kalıp | Anlamı | Türkçesi |\n|---|---|---|\n| must | zorunluluk (kişisel ya da yazılı kural) | -meli, zorunda |\n| have to | zorunluluk (dışarıdan gelen kural) | zorunda olmak |\n| mustn\'t | yasak | -memeli, yasak |\n| don\'t have to | gerek yok | zorunda değil |\n| can / can\'t | izin / izin yok | -ebilir / -emez |\n\n## must: zorunluluk\n**must**, bir şeyi **yapmanın şart** olduğunu söyler. Genellikle konuşan kişinin kendi düşüncesini ya da **yazılı kuralları** (tabelalar, yönetmelikler) anlatır.\n\n- *You **must** wear a seatbelt.* Emniyet kemeri takmalısın. (kural)\n- *I **must** finish this project today.* Bu projeyi bugün bitirmeliyim. (kendim öyle düşünüyorum)\n- *Passengers **must** show their tickets.* Yolcular biletlerini göstermelidir.\n\nHer özneyle aynıdır, arkasından fiil yalın gelir (to yok).\n\n## have to: dışarıdan gelen zorunluluk\n**have to** da zorunluluk anlatır, ama genellikle bir **kural, iş ya da durum** bizi zorunlu kılar. Konuşmada must\'tan daha sık kullanılır.\n\n- *I **have to** wear a uniform at school.* Okulda üniforma giymek zorundayım.\n- *She **has to** get up at 6 for work.* İş için altıda kalkmak zorunda.\n- *Do you **have to** do homework every day?* Her gün ödev yapmak zorunda mısın?\n\n**must\'ın geçmişi yoktur;** geçmişte **had to** kullanılır: *I had to wait for an hour.* (Bir saat beklemek zorunda kaldım.)\n\n## mustn\'t ve don\'t have to\nBu ikisi en çok karıştırılan yapılardır, çünkü olumsuz halleri **tamamen farklı** anlam taşır.\n\n| Yapı | Anlamı | Örnek | Türkçesi |\n|---|---|---|---|\n| **mustn\'t** | **yasak**, yapma! | You mustn\'t use your phone in the exam. | Sınavda telefon kullanmamalısın. (yasak) |\n| **don\'t have to** | **gerek yok**, istersen yap | You don\'t have to bring lunch. | Öğle yemeği getirmek zorunda değilsin. (gerek yok) |\n\n- *You **mustn\'t** swim here.* Burada yüzmek yasak. (tehlikeli)\n- *You **don\'t have to** swim if you don\'t want to.* İstemiyorsan yüzmek zorunda değilsin.\n\n> Higo\'nun ipucu: **mustn\'t** = kırmızı ışık (dur!), **don\'t have to** = yeşil ve sarı ışık birlikte (seçim senin).\n\n## Kurallar listesi örneği\n**Our school rules**\n- You **must** arrive before 8:30.\n- You **have to** wear your school uniform.\n- You **mustn\'t** run in the corridors.\n- You **mustn\'t** eat in the classroom.\n- You **don\'t have to** wear a tie on Fridays.\n- You **can** use the library after school.\n\n## Kendini kontrol et\n1. You ___ smoke in the hospital. (yasak)\n2. It\'s Sunday, so I ___ get up early. (gerek yok)\n3. She ___ to work on Saturdays. (zorunda)\n4. Yesterday I ___ to walk home. (zorunda kaldım)\n\nCevaplar: 1. mustn\'t · 2. don\'t have to · 3. has · 4. had','#FF7FB0',7,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(18,3,'Hayat Deneyimleri','Present perfect ve past simple, for / since','## Ne zamandır?\nBu ünitede Present Perfect\'i derinleştiriyorsun: bir şeyin **ne zamandır** sürdüğünü (for / since), **yeni** olan şeyleri (just) ve **beklenen** şeyleri (already / yet) anlatmayı öğreneceksin.\n\nA2\'de Present Perfect\'i \"hayat deneyimi\" için kullandın. B1\'de en önemli ikinci kullanımı geliyor: **geçmişte başlayıp hâlâ süren durumlar**.\n\n- *I **have lived** in Izmir **for** ten years.* On yıldır İzmir\'de yaşıyorum. (hâlâ yaşıyorum)\n- *She **has worked** here **since** 2021.* 2021\'den beri burada çalışıyor.\n\nTürkçede bunu **şimdiki zaman + -dır / -den beri** ile söyleriz. İngilizcede şimdiki zaman kullanılmaz: *I am living here for ten years* **yanlış**.\n\n## for / since\n| Kelime | Ne ile? | Türkçesi | Örnek |\n|---|---|---|---|\n| **for** | bir **süre** | -dır, boyunca | for two hours, for a week, for ages |\n| **since** | bir **başlangıç noktası** | -den beri | since Monday, since 2019, since I was a child |\n\n- *We\'ve known each other **for** five years.* Beş yıldır tanışıyoruz.\n- *I haven\'t seen him **since** last summer.* Geçen yazdan beri onu görmedim.\n- ***How long** have you had this phone?* Bu telefon ne zamandır sende?\n\n**Present Perfect Continuous** (have been + -ing): süren bir **eylemin** süresini vurgular.\n- *I**\'ve been waiting for** forty minutes!* Kırk dakikadır bekliyorum!\n- *She**\'s been studying** English **since** primary school.* İlkokuldan beri İngilizce çalışıyor.\n\n## Present perfect mi, past simple mı?\n| Present Perfect | Past Simple |\n|---|---|\n| Hâlâ süren ya da şimdiyle bağlantılı | Bitmiş, zamanı belli |\n| *I\'ve lived in Ankara for 3 years.* (hâlâ oradayım) | *I lived in Ankara for 3 years.* (artık orada değilim) |\n| *She\'s lost her keys.* (şu an anahtarı yok) | *She lost her keys yesterday.* (dün olan bir olay) |\n| Zaman ifadeleri: for, since, just, already, yet, ever, never, so far, recently | yesterday, last ..., ago, in 2010, when I was ... |\n\n> Higo\'nun ipucu: Kendine sor: \"Bu durum şu an hâlâ geçerli mi, sonucu şimdi görülüyor mu?\" Evetse Present Perfect, bitip gitmişse Past Simple.\n\n## just / already / yet\n| Kelime | Anlamı | Yeri | Örnek | Türkçesi |\n|---|---|---|---|---|\n| **just** | az önce, yeni | have ile V3 arası | I\'ve **just** finished. | Az önce bitirdim. |\n| **already** | çoktan, zaten (beklenenden erken) | have ile V3 arası | She\'s **already** left. | Çoktan çıktı. |\n| **yet** | henüz (olumsuz) / -dı mı? (soru) | cümle sonu | I haven\'t eaten **yet**. / Have you finished **yet**? | Henüz yemedim. / Bitirdin mi? |\n\n**Örnek diyalog**\n> A: Have you done your homework yet?\n> B: I\'ve already done maths, but I haven\'t started English yet.\n> A: Hurry up! The film has just started.\n\n## Kendini kontrol et\n1. I\'ve known Elif ___ 2018.\n2. They\'ve been married ___ twenty years.\n3. Have you seen the new series ___?\n4. We ___ (move) to Bursa in 2015.\n\nCevaplar: 1. since · 2. for · 3. yet · 4. moved','#3A6FF7',0,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(19,3,'Eskiden','Past continuous ve used to','## O sırada ne yapıyordun?\nBu ünitede geçmişte **devam eden** olayları (Past Continuous), bir olayın **başka bir olayı kesmesini** ve geçmişteki **alışkanlıkları** (used to) anlatmayı öğreneceksin. Bunlar hikâye anlatmanın temel taşlarıdır.\n\n## Past Continuous ne anlatır?\nPast Continuous, Türkçedeki **-yordu** ekine karşılık gelir. Geçmişte **belli bir anda devam etmekte olan** bir eylemi anlatır.\n\n- *At 8 o\'clock last night, I **was having** dinner.* Dün akşam saat 8\'de yemek yiyordum.\n- *They **were playing** football when it started to rain.* Yağmur başladığında futbol oynuyorlardı.\n\n**Yapı:** was / were + fiil-ing\n\n| Özne | Örnek |\n|---|---|\n| I / he / she / it | I **was reading**. |\n| you / we / they | We **were talking**. |\n\n- **Olumsuz:** *She wasn\'t listening.* (Dinlemiyordu.)\n- **Soru:** *What were you doing at midnight?* (Gece yarısı ne yapıyordun?)\n\n## Past continuous + past simple\nHikâyelerde iki zaman birlikte kullanılır: uzun süren **arka plan** Past Continuous, onu **kesen kısa olay** Past Simple.\n\n| Arka plan (-yordu) | Kesen olay (-di) |\n|---|---|\n| I **was walking** home | when I **saw** an accident. |\n| *Eve yürüyordum* | *bir kaza gördüğümde.* |\n| While she **was cooking**, | the phone **rang**. |\n| *O yemek yaparken* | *telefon çaldı.* |\n\n- **when** genellikle kısa olayla: *when the lights went out* (ışıklar gidince)\n- **while** genellikle uzun olayla: *while I was sleeping* (ben uyurken)\n\nİki eylem **aynı anda sürüyorsa** ikisi de Past Continuous: *While I was studying, my brother was playing games.*\n\n> Higo\'nun ipucu: Hikâyeye atmosfer kurarak başla: *It was raining and people were hurrying home. Suddenly, ...* Bu cümle yapısı yazma sınavlarında çok iyi puan getirir.\n\n## used to: eskiden\n**used to + fiil**, geçmişte **düzenli olan ama artık olmayan** alışkanlık ve durumları anlatır. Türkçedeki \"**eskiden ...ırdı / ...ardı**\" karşılığıdır.\n\n- *I **used to** play the piano.* Eskiden piyano çalardım. (artık çalmıyorum)\n- *There **used to** be a cinema here.* Eskiden burada bir sinema vardı.\n- *We **used to** live in Samsun.* Eskiden Samsun\'da yaşardık.\n\n- **Olumsuz:** *I **didn\'t use to** like vegetables.* (Eskiden sebze sevmezdim.) (didn\'t\'ten sonra **use**, -d yok)\n- **Soru:** ***Did** you **use to** have long hair?* (Eskiden uzun saçın var mıydı?)\n\n**Dikkat:** *be used to + -ing* farklı bir yapıdır ve \"**alışkın olmak**\" demektir: *I\'m used to getting up early.* (Erken kalkmaya alışkınım.)\n\n## Kısa bir hikâye\n> It was a cold winter evening. I was sitting by the window and my grandmother was telling me a story. Suddenly, we heard a strange noise. We went outside and saw a small cat. It was shaking. We took it inside. Now it\'s our cat, Pamuk! When I was little, I used to be afraid of cats, but not anymore.\n\n## Kendini kontrol et\n1. I ___ (sleep) when you called me.\n2. While we were walking, it ___ (start) to snow.\n3. My father ___ to smoke, but he stopped.\n4. ___ you use to play outside a lot?\n\nCevaplar: 1. was sleeping · 2. started · 3. used · 4. Did','#2F7CF6',1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(20,3,'Gelecek','Gelecek zamanlar ve first conditional','## Geleceği konuşmak\nBu ünitede gelecek zamanın **üç yolunu** karşılaştırıyorsun ve **şart cümlelerinin ilki** olan First Conditional ile **unless** kullanımını öğreneceksin.\n\n## Üç gelecek\n| Yapı | Ne zaman? | Örnek | Türkçesi |\n|---|---|---|---|\n| **will** | anlık karar, tahmin, söz | I\'ll help you. / It will be hot. | Yardım ederim. / Sıcak olacak. |\n| **be going to** | önceden plan, kanıta dayalı tahmin | I\'m going to apply for the job. | O işe başvuracağım. |\n| **Present Continuous** | ayarlanmış randevu | I\'m meeting the manager at 3. | Saat 3\'te müdürle görüşüyorum. |\n\nAyrıca tarifeler ve programlar için **Present Simple**: *The concert starts at 9.* (Konser 9\'da başlıyor.)\n\n> Higo\'nun ipucu: Sınavlarda zaman ipucuna bak: \"Look at...\" gibi bir **kanıt** varsa going to, \"I think / probably\" gibi bir **görüş** varsa will.\n\n## First Conditional ne anlatır?\nFirst Conditional, **gerçekleşmesi mümkün** bir koşulu ve onun **olası sonucunu** anlatır. Türkçedeki \"**-erse ... -ecek**\" yapısı.\n\n**Yapı:** If + Present Simple, will + fiil\n\n| Koşul (If ...) | Sonuç | Türkçesi |\n|---|---|---|\n| If it **rains**, | we **will stay** at home. | Yağmur yağarsa evde kalacağız. |\n| If you **study** hard, | you**\'ll pass** the exam. | Çok çalışırsan sınavı geçersin. |\n| If I **see** Ali, | I**\'ll tell** him. | Ali\'yi görürsem ona söylerim. |\n\n**Önemli kural:** \"if\" kısmında **will kullanılmaz**, Türkçede \"-ecek\" gibi düşünsek de: *If it will rain* **yanlış**.\n\nCümlenin sırası değişebilir; if sonda ise virgül gerekmez: *We\'ll stay at home if it rains.*\n\n## when, as soon as, until\nAynı kural zaman bağlaçlarında da geçerlidir: bağlaçtan sonra Present Simple.\n- *I\'ll call you **when** I **arrive**.* Varınca seni ararım.\n- *I\'ll tell her **as soon as** she **comes** back.* Döner dönmez ona söylerim.\n- *Wait here **until** I **come** back.* Ben dönene kadar burada bekle.\n\n**if** ile **when** farkı: *If I see him* (görebilirim de göremem de) · *When I see him* (göreceğim kesin).\n\n## unless: -medikçe\n**unless**, \"**if ... not**\" anlamına gelir: \"**-mezse, -medikçe**\".\n- ***Unless** you hurry, you\'ll miss the bus.* Acele etmezsen otobüsü kaçıracaksın.\n  = *If you **don\'t** hurry, you\'ll miss the bus.*\n- *I won\'t go **unless** you come with me.* Sen benimle gelmezsen gitmem.\n\nunless zaten olumsuz anlam taşır, ikinci bir olumsuz kullanma: *Unless you don\'t hurry* yanlış.\n\n## Diğer sonuç kalıpları\nSonuç kısmında will yerine başka yapılar da gelebilir:\n- *If you\'re tired, **you should** rest.* (tavsiye)\n- *If you finish early, **you can** go home.* (izin)\n- *If you see her, **tell** her to call me.* (emir)\n- *If you heat ice, it **melts**.* (her zaman doğru olan sonuç: Zero Conditional, iki taraf da Present Simple)\n\n## Kendini kontrol et\n1. If you ___ (miss) the bus, you\'ll be late.\n2. I\'ll buy it if it ___ (not / be) too expensive.\n3. ___ you leave now, you won\'t catch the train. (-mezsen)\n4. I\'ll phone you as soon as I ___ (get) home.\n\nCevaplar: 1. miss · 2. isn\'t · 3. Unless · 4. get','#22B5C0',2,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(21,3,'Hayaller','Second conditional ve wish','## Ya olsaydı?\nBu ünitede **hayal** ettiğin, **gerçek dışı** ya da **olasılığı düşük** durumları anlatmayı (Second Conditional) ve **şu an** olmasını istediğin şeyleri (wish + past simple) öğreneceksin.\n\n## Second Conditional ne anlatır?\nSecond Conditional, **şu anki ya da gelecekteki hayali** bir durumu anlatır. Türkçedeki \"**-se ... -ardı / -erdi**\" yapısı.\n\n**Yapı:** If + Past Simple, would + fiil\n\n| Koşul | Sonuç | Türkçesi |\n|---|---|---|\n| If I **had** a million dollars, | I **would travel** the world. | Bir milyon dolarım olsa dünyayı gezerdim. |\n| If she **lived** near the sea, | she **would swim** every day. | Denize yakın yaşasa her gün yüzerdi. |\n| If I **knew** the answer, | I**\'d tell** you. | Cevabı bilsem sana söylerdim. |\n\nGeçmiş zaman kullanılır ama anlam **geçmiş değildir**; \"gerçek değil, hayal\" demektir.\n\n**to be** için tüm öznelerde **were** tercih edilir: *If I **were** you, I would apologise.* (Yerinde olsam özür dilerdim.) Bu kalıp tavsiye vermenin en kibar yollarından biridir.\n\n## First mi, second mı?\nİkisini ayıran şey, konuşanın durumu **ne kadar gerçekçi** bulduğudur.\n\n| First (gerçekçi) | Second (hayali, düşük ihtimal) |\n|---|---|\n| If I **pass** the exam, I\'**ll celebrate**. | If I **won** the lottery, I\'**d buy** a house. |\n| *Sınavı geçersem kutlayacağım.* (olası) | *Piyangoyu kazansam ev alırdım.* (hayal) |\n| If it **rains** tomorrow, ... | If I **were** a bird, ... |\n\nAynı durum ikisiyle de söylenebilir; seçim, konuşanın bakış açısını gösterir:\n- *If I **get** the job, I\'ll move to Istanbul.* (alabileceğimi düşünüyorum)\n- *If I **got** the job, I\'d move to Istanbul.* (pek ihtimal vermiyorum)\n\n> Higo\'nun ipucu: **would**\'u if kısmına koyma: *If I would have money* yanlış, **If I had money** doğru. would sadece sonuç kısmında.\n\n## Soru ve olumsuz\n- *What **would** you **do** if you **saw** a ghost?* Bir hayalet görsen ne yapardın?\n- *I **wouldn\'t** say that if I **were** you.* Yerinde olsam bunu söylemezdim.\n- *If I **didn\'t** have homework, I\'d go out.* Ödevim olmasa dışarı çıkardım.\n\n**could / might** da sonuç kısmında kullanılabilir: *If I had more time, I **could** learn Japanese.* (Daha çok vaktim olsa Japonca öğrenebilirdim.)\n\n## wish + past simple\n**I wish + Past Simple**, **şu an** gerçek olmayan bir şeyi istemeyi anlatır. Türkçedeki \"**keşke ... olsa**\".\n\n- *I **wish** I **had** a dog.* Keşke bir köpeğim olsa. (yok)\n- *I **wish** I **lived** in the countryside.* Keşke kırsalda yaşasam.\n- *She **wishes** she **were** taller.* Keşke daha uzun olsa diyor.\n- *I **wish** I **could** speak French.* Keşke Fransızca konuşabilsem.\n\n**If only** daha güçlü bir istektir: *If only I had more free time!* (Keşke daha çok boş vaktim olsaydı!)\n\n## Kendini kontrol et\n1. If I ___ (be) rich, I would help everyone.\n2. What would you do if you ___ (find) a wallet?\n3. I wish I ___ (have) more friends.\n4. If it rains tomorrow, we ___ (cancel) the trip.\n\nCevaplar: 1. were · 2. found · 3. had · 4. will cancel','#8F7CF8',3,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(22,3,'Haberler','Edilgen yapı (passive voice)','## Ne oldu, kim yaptı?\nBu ünitede haber dilinin vazgeçilmezi olan **edilgen yapıyı** (Passive Voice) öğreneceksin: \"Köprü 1973\'te **yapıldı**\", \"Hırsız **yakalandı**\" gibi.\n\n## Passive voice ne anlatır?\nEdilgen yapı, **eylemi kimin yaptığı değil, eylemin kendisi ya da etkilenen şey** önemli olduğunda kullanılır. Türkçedeki **-ıl / -il / -ın / -in** (yapıl-, yaz-ıl-, gör-ül-) ekine karşılık gelir.\n\n| Etken (active) | Edilgen (passive) |\n|---|---|\n| Workers **built** the bridge in 1973. | The bridge **was built** in 1973. |\n| *İşçiler köprüyü 1973\'te yaptı.* | *Köprü 1973\'te yapıldı.* |\n| Someone **stole** my bike. | My bike **was stolen**. |\n| *Biri bisikletimi çaldı.* | *Bisikletim çalındı.* |\n\nEdilgen yapıyı seçme nedenleri: yapan kişi **bilinmiyor** (bisikleti kim çaldı?), **önemsiz** ya da **zaten belli** (polis hırsızı yakaladı).\n\n**Yapı:** be (zamana göre) + fiilin **3. hali** (V3)\n\n## Zamanlara göre passive\n| Zaman | Yapı | Örnek | Türkçesi |\n|---|---|---|---|\n| Present Simple | am / is / are + V3 | English **is spoken** all over the world. | İngilizce tüm dünyada konuşulur. |\n| Past Simple | was / were + V3 | The museum **was opened** in 2010. | Müze 2010\'da açıldı. |\n| Present Perfect | have / has been + V3 | The results **have been announced**. | Sonuçlar açıklandı. |\n| Present Continuous | am / is / are being + V3 | The road **is being repaired**. | Yol tamir ediliyor. |\n| Future | will be + V3 | The winner **will be chosen** tomorrow. | Kazanan yarın seçilecek. |\n| Modal | can / must be + V3 | Phones **must be switched** off. | Telefonlar kapatılmalıdır. |\n\n## by: kim tarafından\nEylemi yapanı söylemek önemliyse **by** kullanılır (... tarafından):\n- *Romeo and Juliet **was written by** Shakespeare.* Romeo ve Juliet, Shakespeare tarafından yazıldı.\n- *The vaccine **was developed by** a team of scientists.* Aşı bir bilim insanı ekibi tarafından geliştirildi.\n\nYapan kişi önemsizse by kısmı söylenmez: *The thief was caught (by the police).*\n\n> Higo\'nun ipucu: Haber başlıklarında be fiili çoğu zaman atılır: *\"Bridge closed after storm\"* = The bridge **was** closed after the storm. Gazete okurken bunu tanımak işini kolaylaştırır.\n\n## Soru ve olumsuz\n- *When **was** the Eiffel Tower **built**?* Eyfel Kulesi ne zaman yapıldı?\n- *Is breakfast **included**?* Kahvaltı dahil mi?\n- *The letter **wasn\'t sent**.* Mektup gönderilmedi.\n- *Has the problem **been solved** yet?* Sorun çözüldü mü?\n\n## Kısa bir haber\n> A rare painting **was found** in an old house in Bursa last week. It **is believed** to be more than 200 years old. The painting **was taken** to a museum, where it **is being examined** by experts. It **will be shown** to the public next year.\n\n*Geçen hafta Bursa\'daki eski bir evde nadir bir tablo bulundu. 200 yıldan daha eski olduğuna inanılıyor. Tablo bir müzeye götürüldü ve orada uzmanlarca inceleniyor. Gelecek yıl halka gösterilecek.*\n\n## Kendini kontrol et\n1. This house ___ (build) in 1920.\n2. Rice ___ (grow) in many Asian countries.\n3. The tests ___ (mark) yet. (olumsuz, present perfect)\n4. The Mona Lisa was painted ___ Leonardo da Vinci.\n\nCevaplar: 1. was built · 2. is grown · 3. haven\'t been marked · 4. by','#3AB0E6',4,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(23,3,'Dedi ki','Dolaylı anlatım (reported speech)','## Ne dedi?\nBu ünitede birinin söylediğini **aktarmayı** (Reported Speech) öğreneceksin: \"Yorgun olduğunu söyledi\", \"Bana nereye gittiğimi sordu\" gibi.\n\n| Doğrudan (direct) | Dolaylı (reported) |\n|---|---|\n| Ali: \"I\'m tired.\" | Ali said (that) he **was** tired. |\n| *Ali: \"Yorgunum.\"* | *Ali yorgun olduğunu söyledi.* |\n\nTürkçede \"**-dığını söyledi**\" ya da \"**... dedi**\" yapısıyla aktarırız. İngilizcede aktarırken üç şey değişir: **zaman, zamir, zaman/yer ifadeleri**.\n\n## Zaman bir geri gider\nAktarma fiili geçmişteyse (said, told), aktarılan cümlenin zamanı bir adım **geçmişe** kayar.\n\n| Doğrudan | Dolaylı |\n|---|---|\n| Present Simple: \"I **like** it.\" | Past Simple: She said she **liked** it. |\n| Present Continuous: \"I\'**m working**.\" | Past Continuous: He said he **was working**. |\n| Past Simple / Present Perfect: \"I **saw** / I\'**ve seen** it.\" | Past Perfect: She said she **had seen** it. |\n| will: \"I\'**ll** call you.\" | would: He said he **would** call me. |\n| can: \"I **can** swim.\" | could: She said she **could** swim. |\n| must: \"You **must** go.\" | had to: He said I **had to** go. |\n\n**Zaman ve yer ifadeleri de değişir:**\n| Doğrudan | Dolaylı |\n|---|---|\n| now | then |\n| today | that day |\n| tomorrow | the next day / the following day |\n| yesterday | the day before / the previous day |\n| here | there |\n| this | that |\n\n> Higo\'nun ipucu: Söylenen şey **hâlâ doğruysa** zaman değiştirmek zorunlu değildir: *She said she **lives** in Izmir.* (hâlâ orada yaşıyor)\n\n## say ve tell\nİkisi de \"söylemek\" demek ama yapıları farklıdır:\n\n| Fiil | Yapı | Örnek |\n|---|---|---|\n| **say** | say (that) ... / say **to** someone | He **said** (that) he was hungry. |\n| **tell** | tell **someone** (that) ... | He **told me** (that) he was hungry. |\n\n*He said me* **yanlış**, *He told that* **yanlış**. tell\'den sonra **mutlaka kişi** gelir.\n\nBazı sabit kalıplar: **tell** the truth (doğruyu söylemek), **tell** a lie (yalan söylemek), **tell** a story (hikâye anlatmak), **say** hello (merhaba demek), **say** sorry (özür dilemek).\n\n## Sorular ve istekler\n**Evet/hayır soruları:** asked + **if / whether** + düz cümle sırası\n- \"Are you OK?\" → She **asked if I was** OK. (İyi olup olmadığımı sordu.)\n\n**Soru kelimeli sorular:** asked + soru kelimesi + **düz cümle sırası** (do/did kullanılmaz)\n- \"Where do you live?\" → He **asked where I lived**. (Nerede yaşadığımı sordu.)\n- *He asked where did I live* **yanlış**.\n\n**Emir ve rica:** told / asked + kişi + **to** + fiil\n- \"Close the door.\" → She **told me to close** the door. (Bana kapıyı kapatmamı söyledi.)\n- \"Please help me.\" → He **asked me to help** him.\n- \"Don\'t be late.\" → The teacher **told us not to be** late. (Geç kalmamamızı söyledi.)\n\n## Kendini kontrol et\n1. \"I\'m busy.\" → She said she ___ busy.\n2. He ___ me that he was sorry. (say / tell)\n3. \"Do you like pizza?\" → She asked ___ I liked pizza.\n4. \"Sit down.\" → The teacher told us ___ sit down.\n\nCevaplar: 1. was · 2. told · 3. if · 4. to','#FF8A3D',5,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(24,3,'İnsanlar ve Yerler','Relative clauses: who, which, where','## Kimden, neyden bahsediyoruz?\nBu ünitede iki cümleyi birleştirip bir ismi **tanımlamayı** öğreneceksin: \"**Yanımda oturan** kız\", \"**Dün aldığım** kitap\". Bunun için İngilizcede **sıfat cümlecikleri** (relative clauses) kullanılır.\n\nTürkçede tanımlayıcı kısım ismin **önüne** gelir: *dün aldığım kitap*. İngilizcede **arkasına** gelir ve bir bağlaçla başlar: *the book **that I bought** yesterday*.\n\n## who · which · that · where · whose\n| Kelime | Ne için? | Örnek | Türkçesi |\n|---|---|---|---|\n| **who** | insanlar | The man **who** lives next door is a doctor. | Yan dairede oturan adam doktor. |\n| **which** | eşya, hayvan, fikir | This is the phone **which** I bought. | Bu, aldığım telefon. |\n| **that** | insan ya da eşya (konuşmada çok yaygın) | The film **that** we watched was boring. | İzlediğimiz film sıkıcıydı. |\n| **where** | yer | That\'s the café **where** we first met. | Orası ilk tanıştığımız kafe. |\n| **whose** | sahiplik | I\'ve got a friend **whose** father is a pilot. | Babası pilot olan bir arkadaşım var. |\n| **when** | zaman | I remember the day **when** I got my first bike. | İlk bisikletimi aldığım günü hatırlıyorum. |\n\n> Higo\'nun ipucu: Bağlaçtan sonra zamiri tekrar etme: *The book which I bought **it*** yanlış. which zaten \"it\" yerine geçiyor.\n\n## Ne zaman atlanabilir?\nBağlaç, cümleciğin **nesnesi** olduğunda (yani arkasından bir özne geliyorsa) atlanabilir. Konuşmada çok sık atlanır.\n\n| Bağlaç | Atlanabilir mi? | Örnek |\n|---|---|---|\n| Nesne (arkasında özne var) | **Evet** | The girl **(who)** I met yesterday is Spanish. *Dün tanıştığım kız İspanyol.* |\n| Özne (arkasında fiil var) | **Hayır** | The girl **who** sits next to me is Spanish. *Yanımda oturan kız İspanyol.* |\n\n- *The pizza **(that)** we ordered was cold.* Sipariş ettiğimiz pizza soğuktu. (we = özne, that atlanabilir)\n- *The bus **that** goes to the airport is late.* Havalimanına giden otobüs gecikti. (that = özne, atlanamaz)\n\n## Ek bilgi veren cümlecikler\nBazen cümlecik ismi tanımlamaz, sadece **ek bilgi** verir. O zaman **virgülle** ayrılır ve **that kullanılmaz**.\n\n- *My brother, **who** lives in Berlin, is an engineer.* Berlin\'de yaşayan ağabeyim mühendis. (tek ağabeyim var, ek bilgi)\n- *Istanbul, **which** has 16 million people, is Turkey\'s largest city.*\n\nVirgüllü cümleciklerde bağlaç **atlanamaz**.\n\n## Tanımlama oyunu\nSınav ve günlük hayatta kelimeyi bilmediğinde onu tanımlamak için bu yapı çok işe yarar:\n- *It\'s a person **who** repairs cars.* → mechanic (araç tamir eden kişi)\n- *It\'s a thing **which** you use to open a bottle.* → bottle opener\n- *It\'s a place **where** you can borrow books.* → library\n\n## Kendini kontrol et\n1. A vet is a doctor ___ looks after animals.\n2. This is the town ___ I was born.\n3. I met a woman ___ son plays for Galatasaray.\n4. The book ___ you gave me is great. (that / who)\n\nCevaplar: 1. who · 2. where · 3. whose · 4. that','#22B573',6,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(25,3,'İş Dünyası','Gerund / infinitive ve resmî e-posta','## İş hayatında İngilizce\nBu ünitede iş ve kariyer kelimelerini, bazı fiillerden sonra **-ing** mi yoksa **to + fiil** mi geleceğini ve **resmî e-posta** yazarken kullanılan kalıpları öğreneceksin.\n\n| İngilizce | Türkçesi |\n|---|---|\n| apply for a job | işe başvurmak |\n| CV / résumé | özgeçmiş |\n| interview | mülakat |\n| salary | maaş |\n| colleague | iş arkadaşı |\n| deadline | son teslim tarihi |\n| be in charge of | -den sorumlu olmak |\n| meeting | toplantı |\n| hire / fire | işe almak / kovmak |\n| promotion | terfi |\n\n## Gerund (-ing) alan fiiller\nBazı fiillerden sonra ikinci fiil **-ing** alır (gerund). Ezberlemek için gruplar halinde düşün:\n\n| Fiiller | Örnek | Türkçesi |\n|---|---|---|\n| enjoy, like, love, hate, don\'t mind | I **enjoy working** in a team. | Takım halinde çalışmaktan keyif alırım. |\n| finish, stop, give up | She **finished writing** the report. | Raporu yazmayı bitirdi. |\n| avoid, consider, suggest | He **suggested meeting** on Monday. | Pazartesi buluşmayı önerdi. |\n| keep, practise, miss | **Keep trying!** | Denemeye devam et! |\n\nAyrıca **edatlardan sonra** her zaman -ing gelir: *I\'m interested **in learning** Spanish.* · *Thank you **for helping** me.* · *I\'m good **at solving** problems.* · *I\'m looking forward **to hearing** from you.*\n\n## Infinitive (to + fiil) alan fiiller\n| Fiiller | Örnek | Türkçesi |\n|---|---|---|\n| want, would like, hope | I **hope to see** you soon. | Seni yakında görmeyi umuyorum. |\n| decide, plan, agree | We **decided to hire** her. | Onu işe almaya karar verdik. |\n| need, try, learn | You **need to update** your CV. | Özgeçmişini güncellemen gerekiyor. |\n| promise, offer, refuse | He **offered to help**. | Yardım etmeyi teklif etti. |\n| afford, manage, seem | I can\'t **afford to buy** a car. | Araba almaya gücüm yetmiyor. |\n\n> Higo\'nun ipucu: **stop** iki yapıyla da kullanılır ama anlam değişir. *I stopped **smoking**.* (Sigarayı bıraktım.) · *I stopped **to smoke**.* (Sigara içmek için durdum.) Aynısı **remember** ve **forget** için de geçerlidir.\n\n## Resmî e-posta kalıpları\n| Bölüm | Resmî | Türkçesi |\n|---|---|---|\n| Hitap (isim biliniyorsa) | Dear Ms Yılmaz, | Sayın Yılmaz Hanım, |\n| Hitap (isim bilinmiyorsa) | Dear Sir or Madam, | Sayın Yetkili, |\n| Amaç | I am writing to apply for the position of ... | ... pozisyonuna başvurmak için yazıyorum. |\n| Bilgi isteme | I would be grateful if you could send me ... | ... gönderirseniz minnettar olurum. |\n| Ek | Please find attached my CV. | Özgeçmişimi ekte bulabilirsiniz. |\n| Kapanış | I look forward to hearing from you. | Sizden haber bekliyorum. |\n| İmza (isim biliniyorsa) | Yours sincerely, | Saygılarımla, |\n| İmza (isim bilinmiyorsa) | Yours faithfully, | Saygılarımla, |\n\nResmî yazıda **kısaltma kullanma**: *I\'m* yerine **I am**, *can\'t* yerine **cannot**.\n\n## Örnek başvuru e-postası\n> Dear Mr Kaya,\n> I am writing to apply for the position of Junior Designer, which I saw on your website. I have recently graduated from Anadolu University and I enjoy working on creative projects.\n> Please find attached my CV. I would be happy to attend an interview at your convenience.\n> I look forward to hearing from you.\n> Yours sincerely,\n> Zeynep Arslan\n\n## Kendini kontrol et\n1. I don\'t mind ___ (work) at weekends.\n2. She decided ___ (apply) for the job.\n3. I look forward to ___ (meet) you.\n4. Dear Sir or Madam, ... Yours ___.\n\nCevaplar: 1. working · 2. to apply · 3. meeting · 4. faithfully','#FFB400',7,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(26,4,'Keşke Olsaydı','Third conditional ve geçmişle ilgili pişmanlıklar','## Geçmişi değiştirebilseydik\nBu ünitede **geçmişte olmamış** şeyleri hayal etmeyi (Third Conditional), geçmiş ile şimdiyi birleştiren **karma şart cümlelerini**, geçmişle ilgili pişmanlıkları (**wish + past perfect**) ve eleştiriyi (**should have**) öğreneceksin.\n\n| Yapı | Türkçesi |\n|---|---|\n| If I **had studied**, I **would have passed**. | Çalışsaydım geçerdim. |\n| I **wish** I **had listened**. | Keşke dinleseydim. |\n| You **should have told** me. | Bana söylemeliydin. |\n\nBütün bu yapılar aynı fikri taşır: **geçmiş değişmez**, biz sadece \"olsaydı ne olurdu\" diye düşünürüz.\n\n## Past Perfect hatırlatması\nBu ünitenin temeli **Past Perfect**\'tir: had + V3. Geçmişteki bir andan **daha önce** olan şeyi anlatır (Türkçede \"-mıştı\").\n- *When I arrived, the film **had** already **started**.* Vardığımda film çoktan başlamıştı.\n- *She **had never seen** snow before she moved to Erzurum.* Erzurum\'a taşınmadan önce hiç kar görmemişti.\n\n## Third Conditional ne anlatır?\nThird Conditional, **geçmişte gerçekleşmemiş** bir koşulu ve onun **gerçekleşmemiş sonucunu** anlatır. Türkçedeki \"**-seydi ... -ardı / -mış olurdu**\".\n\n**Yapı:** If + Past Perfect, would have + V3\n\n| Koşul | Sonuç | Türkçesi |\n|---|---|---|\n| If I **had left** earlier, | I **wouldn\'t have missed** the train. | Daha erken çıksaydım treni kaçırmazdım. |\n| If she **had known** your number, | she **would have called** you. | Numaranı bilseydi seni arardı. |\n| If we **hadn\'t taken** a taxi, | we **would have been** late. | Taksiye binmeseydik geç kalırdık. |\n\nGerçekte: erken çıkmadım, treni kaçırdım. Cümle, olmayanı hayal eder.\n\n**could have / might have** da kullanılabilir: *If you had asked, I **could have helped** you.* (Sorsaydın yardım edebilirdim.)\n\n> Higo\'nun ipucu: Konuşmada **would have** çoğu zaman **would\'ve** diye kısalır ve \"would of\" gibi duyulur. Yazarken asla *would of* yazma.\n\n## Mixed conditional\nKarma şart cümlesi, **geçmişteki** bir koşulun **şimdiki** sonucunu ya da **şimdiki** bir durumun **geçmişteki** sonucunu anlatır.\n\n| Tür | Yapı | Örnek | Türkçesi |\n|---|---|---|---|\n| Geçmiş koşul → şimdiki sonuç | If + had V3, would + fiil | If I **had taken** the job, I **would be** rich now. | O işi alsaydım şimdi zengin olurdum. |\n| Şimdiki durum → geçmiş sonuç | If + Past Simple, would have V3 | If I **were** braver, I **would have spoken** to her. | Daha cesur biri olsaydım onunla konuşurdum. |\n\nİpucu: cümlede **now, today, still** gibi bir kelime varsa genellikle sonuç şimdiye aittir.\n\n## wish + past perfect\n**I wish + Past Perfect**, **geçmişte** olan ya da olmayan bir şey için **pişmanlık** anlatır: \"**keşke ...saydım**\".\n\n| wish + past simple (şimdi) | wish + past perfect (geçmiş) |\n|---|---|\n| I wish I **knew** the answer. *Keşke cevabı bilsem.* | I wish I **had known** the answer. *Keşke cevabı bilseydim.* |\n| I wish I **lived** abroad. | I wish I **had studied** abroad. |\n\n- *She wishes she **hadn\'t said** that.* Keşke onu söylemeseydim diyor.\n- *If only I **had brought** my umbrella!* Keşke şemsiyemi getirseydim!\n\n**Gelecek ya da başkasının davranışı** için **wish + would**: *I wish it **would** stop raining.* (Keşke yağmur dursa.) · *I wish you **wouldn\'t** interrupt me.* (Keşke sözümü kesmesen.)\n\n## should have / shouldn\'t have\n**should have + V3**, geçmişte yapılması **gereken ama yapılmamış** bir şeyi anlatır (eleştiri, pişmanlık): \"**-meliydi / -malıydı**\".\n\n- *You **should have studied** harder.* Daha çok çalışmalıydın. (çalışmadın)\n- *I **shouldn\'t have eaten** so much.* Bu kadar çok yememeliydim. (yedim)\n- *They **should have booked** a table.* Masa ayırtmalıydılar.\n\n## Kendini kontrol et\n1. If I had seen you, I ___ (say) hello.\n2. I wish I ___ (not / spend) all my money yesterday.\n3. If she had studied medicine, she ___ (be) a doctor now.\n4. You ___ (tell) me earlier! (eleştiri)\n\nCevaplar: 1. would have said · 2. hadn\'t spent · 3. would be · 4. should have told','#8F7CF8',0,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(27,4,'Tahmin ve Çıkarım','Modals of deduction: must, might, can\'t (have)','## Dedektif gibi düşün\nBu ünitede **kanıtlara dayanarak çıkarım yapmayı** öğreneceksin: \"Evde olmalı\", \"Yorgun olabilir\", \"Bunu o yapmış olamaz\". Bunun için **must, might, may, could, can\'t** gibi modal fiiller kullanılır.\n\nBu modallar burada **zorunluluk ya da yetenek değil, ne kadar emin olduğumuzu** anlatır:\n\n| Modal | Kesinlik | Türkçesi |\n|---|---|---|\n| **must** | %95 eminim, öyle | -malı, kesin öyle |\n| **may / might / could** | %50, olabilir | -ebilir, belki |\n| **can\'t / couldn\'t** | %95 eminim, öyle değil | olamaz, imkânsız |\n\n## Şimdi için: modal + fiil\n- *The lights are on. They **must be** at home.* Işıklar yanıyor. Evde olmalılar.\n- *He isn\'t answering. He **might be** asleep.* Cevap vermiyor. Uyuyor olabilir.\n- *That **can\'t be** Ayşe. She\'s in London!* O Ayşe olamaz. Londra\'da!\n- *Where\'s Mert? He **could be** in the library.* Mert nerede? Kütüphanede olabilir.\n\n**Devam eden durum** için modal + be + -ing:\n- *She **must be working**; her office light is on.* Çalışıyor olmalı, ofisinin ışığı yanıyor.\n\n> Higo\'nun ipucu: must\'ın olumsuzu çıkarımda **mustn\'t değil, can\'t**\'tir. *He mustn\'t be hungry* yanlış; \"aç olamaz\" için **He can\'t be hungry. He\'s just eaten.**\n\n## Geçmiş için: modal + have + V3\nGeçmişteki bir olay hakkında çıkarım yaparken **modal + have + V3** kullanılır.\n\n| Yapı | Örnek | Türkçesi |\n|---|---|---|\n| must have V3 | The ground is wet. It **must have rained**. | Yer ıslak. Yağmur yağmış olmalı. |\n| might / may / could have V3 | She **might have missed** the bus. | Otobüsü kaçırmış olabilir. |\n| can\'t / couldn\'t have V3 | He **can\'t have stolen** it. He was with me. | Onu çalmış olamaz. Benimleydi. |\n\n- *You **must have been** very tired after the marathon.* Maratondan sonra çok yorulmuş olmalısın.\n- *I **may have left** my phone in the taxi.* Telefonumu takside bırakmış olabilirim.\n\n## could have: iki farklı anlam\n**could have + V3** iki şekilde kullanılır; bağlamdan anlaşılır:\n1. **Olasılık:** *She could have taken the wrong road.* (Yanlış yola sapmış olabilir.)\n2. **Gerçekleşmemiş fırsat:** *You could have won if you had tried harder.* (Daha çok uğraşsan kazanabilirdin.)\n\n## Dedektif sahnesi\n> The window is broken and there\'s mud on the carpet. The thief **must have come** in through the window. He **can\'t have used** the door because it was locked from inside. Look at these small footprints. It **might have been** a child, or the thief **could have worn** small shoes to confuse us.\n\n*Pencere kırık ve halıda çamur var. Hırsız pencereden girmiş olmalı. Kapıyı kullanmış olamaz çünkü içeriden kilitliydi. Şu küçük ayak izlerine bak. Bir çocuk olabilir ya da hırsız bizi şaşırtmak için küçük ayakkabı giymiş olabilir.*\n\n## Kendini kontrol et\n1. She\'s crying. She ___ be very upset. (eminim)\n2. He ___ have gone out. His car is in the garage. (imkânsız)\n3. I can\'t find my keys. I ___ have dropped them. (olabilir)\n4. You ___ have been hungry after the trip. (eminim)\n\nCevaplar: 1. must · 2. can\'t · 3. might / may / could · 4. must','#5B6CF0',1,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(28,4,'Bilim ve Teknoloji','İleri passive ve have something done','## Bilimsel dil\nBu ünitede bilim ve teknoloji metinlerinde çok sık geçen yapıları öğreneceksin: **modal fiillerle edilgen yapı**, **\"... olduğu söyleniyor / düşünülüyor\"** kalıpları ve bir işi **başkasına yaptırmak** (have / get something done).\n\n| İngilizce | Türkçesi |\n|---|---|\n| research | araştırma |\n| evidence | kanıt |\n| experiment | deney |\n| discovery | keşif |\n| device | cihaz |\n| invent | icat etmek |\n| data | veri |\n| develop | geliştirmek |\n| artificial intelligence | yapay zekâ |\n| breakthrough | çığır açan buluş |\n\n## Passive + modal\nModal fiillerle edilgen yapı: **modal + be + V3**. Talimatlarda, kurallarda ve bilimsel olasılıklarda yaygındır.\n\n| Örnek | Türkçesi |\n|---|---|\n| The data **must be checked** carefully. | Veriler dikkatle kontrol edilmelidir. |\n| This disease **can be cured**. | Bu hastalık tedavi edilebilir. |\n| The results **should be published** soon. | Sonuçlar yakında yayımlanmalı. |\n| Robots **could be used** in hospitals. | Robotlar hastanelerde kullanılabilir. |\n| The experiment **might be repeated**. | Deney tekrarlanabilir. |\n\n**Geçmiş için** modal + have been + V3: *The problem **could have been avoided**.* (Sorun önlenebilirdi.)\n\n## It is said / believed that...\nBilgiyi **kişisel olmayan, nesnel** bir dille aktarmak için kullanılır; haberlerde ve akademik metinlerde çok yaygındır.\n\n**Yapı 1:** It + is / was + V3 (said, believed, thought, known, reported, expected) + that ...\n- ***It is believed that*** the universe is 13.8 billion years old. *Evrenin 13,8 milyar yaşında olduğuna inanılıyor.*\n- ***It was reported that*** the company had lost millions. *Şirketin milyonlar kaybettiği bildirildi.*\n\n**Yapı 2:** Özne + is said / thought + **to** + fiil\n- *The new phone **is said to be** very fast.* Yeni telefonun çok hızlı olduğu söyleniyor.\n- *Coffee **is thought to have** health benefits.* Kahvenin sağlığa faydaları olduğu düşünülüyor.\n- Geçmiş için **to have + V3**: *The castle **is believed to have been built** in the 12th century.* (Kalenin 12. yüzyılda inşa edildiğine inanılıyor.)\n\n> Higo\'nun ipucu: YDS ve YÖKDİL okuma parçalarında bu yapılar çok sık çıkar. \"**It is widely accepted that ...**\" (... olduğu genel kabul görür) kalıbını görünce yazarın genel bir görüşü aktardığını anla.\n\n## have / get something done\nBir işi **kendin yapmadığını, başkasına yaptırdığını** anlatır. Türkçedeki \"**-tırmak / -dırmak**\" (saçımı kestirdim, arabamı tamir ettirdim) ekinin karşılığıdır.\n\n**Yapı:** have / get + nesne + V3\n\n| Kendin yaparsın | Başkasına yaptırırsın |\n|---|---|\n| I cut my hair. *Saçımı kestim.* | I **had my hair cut**. *Saçımı kestirdim.* |\n| He repaired his car. | He **got his car repaired**. *Arabasını tamir ettirdi.* |\n\n- *We\'re **having** our house **painted** next week.* Gelecek hafta evimizi boyatıyoruz.\n- *You should **get** your eyes **tested**.* Gözlerini muayene ettirmelisin.\n- **get** daha gündelik konuşma dilidir; **have** biraz daha resmîdir.\n\nAynı yapı **kötü bir olayı** da anlatabilir: *She **had her bag stolen** on the bus.* (Otobüste çantası çalındı.)\n\n## Kendini kontrol et\n1. The new vaccine ___ (can / produce) in large amounts.\n2. It ___ believed that he left the country.\n3. The pyramids are thought ___ been built by skilled workers.\n4. I need to ___ my phone screen repaired. (have / get)\n\nCevaplar: 1. can be produced · 2. is · 3. to have · 4. have / get','#22B5C0',2,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(29,4,'Çevre','Future continuous, future perfect ve kalıp sözler','## 2050\'de dünya\nBu ünitede gelecekte **belli bir anda devam ediyor olacak** olayları (Future Continuous), gelecekte **belli bir zamana kadar tamamlanmış olacak** olayları (Future Perfect) ve çevreyle ilgili güçlü kelime öbeklerini öğreneceksin.\n\n| İngilizce | Türkçesi |\n|---|---|\n| climate change | iklim değişikliği |\n| global warming | küresel ısınma |\n| renewable energy | yenilenebilir enerji |\n| carbon footprint | karbon ayak izi |\n| endangered species | nesli tükenmekte olan türler |\n| deforestation | ormansızlaşma |\n\n## Future Continuous ne anlatır?\nFuture Continuous, gelecekte **belli bir anda devam etmekte olacak** eylemi anlatır. Türkçedeki \"**-iyor olacak**\".\n\n**Yapı:** will be + fiil-ing\n\n- *This time tomorrow, I **will be flying** to Berlin.* Yarın bu saatte Berlin\'e uçuyor olacağım.\n- *In 2050, people **will be driving** electric cars.* 2050\'de insanlar elektrikli araba kullanıyor olacak.\n- *Don\'t call at 8. We**\'ll be having** dinner.* Saat 8\'de arama. Yemek yiyor olacağız.\n\n**Kibar soru** için de kullanılır (planı öğrenmek, baskı yapmadan): ***Will** you **be using** the car tonight?* (Bu akşam arabayı kullanacak mısın?)\n\n## Future Perfect ne anlatır?\nFuture Perfect, gelecekte **belli bir zamana kadar tamamlanmış olacak** eylemi anlatır. Türkçedeki \"**-miş olacak**\".\n\n**Yapı:** will have + V3 · Genellikle **by** (-e kadar) ile kullanılır.\n\n- ***By** 2030, we **will have built** 500 new wind farms.* 2030\'a kadar 500 yeni rüzgar santrali kurmuş olacağız.\n- *I**\'ll have finished** the report **by** Friday.* Raporu cumaya kadar bitirmiş olacağım.\n- ***By the time** you arrive, the film **will have started**.* Sen gelene kadar film başlamış olacak.\n\n**Olumsuz:** *Scientists warn that we **won\'t have solved** the problem by 2040.* (Bilim insanları sorunu 2040\'a kadar çözmüş olmayacağımız konusunda uyarıyor.)\n\n> Higo\'nun ipucu: **by** = \"en geç o zamana kadar\". **until** = \"o zamana kadar boyunca\". *I\'ll be here until 5.* (5\'e kadar buradayım.) · *I\'ll be there by 5.* (En geç 5\'te orada olurum.)\n\n## Üç gelecek zamanı karşılaştır\n| Zaman | Örnek | Anlamı |\n|---|---|---|\n| Future Simple | Sea levels **will rise**. | Deniz seviyesi yükselecek. (genel tahmin) |\n| Future Continuous | In 2050, sea levels **will be rising** fast. | 2050\'de hızla yükseliyor olacak. (o anda süren süreç) |\n| Future Perfect | By 2100, sea levels **will have risen** by 1 metre. | 2100\'e kadar 1 metre yükselmiş olacak. (tamamlanmış sonuç) |\n\n## Çevre kalıpları (collocations)\nDoğal İngilizce, kelimelerin doğru eşleşmesiyle olur. Bunları birlikte öğren:\n\n| Kalıp | Türkçesi |\n|---|---|\n| reduce emissions | emisyonları azaltmak |\n| take action | harekete geçmek |\n| raise awareness | farkındalık yaratmak |\n| protect the environment | çevreyi korumak |\n| run out of resources | kaynakların tükenmesi |\n| a serious threat to | ... için ciddi bir tehdit |\n| have an impact on | ... üzerinde etkisi olmak |\n| tackle a problem | bir sorunla mücadele etmek |\n\n*Governments must **take action** to **reduce emissions** before climate change becomes **a serious threat to** future generations.*\n\n## Kendini kontrol et\n1. This time next week, I ___ (lie) on a beach.\n2. By 2040, we ___ (switch) to clean energy.\n3. Please don\'t phone at 9. I ___ (watch) the match.\n4. We need to ___ awareness about plastic waste.\n\nCevaplar: 1. will be lying · 2. will have switched · 3. will be watching · 4. raise','#22B573',3,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(30,4,'Fikir Savun','Bağlaçlar: although, despite, whereas, however','## İkna edici konuş ve yaz\nBu ünitede bir fikri **savunmayı**, karşı görüşü **kabul edip çürütmeyi** ve **sebep-sonuç** ilişkisi kurmayı öğreneceksin. Bunlar fikir yazısı (opinion essay), münazara ve konuşma sınavları için temeldir.\n\nGüçlü bir argümanın yapısı:\n1. **Görüşünü söyle:** *In my opinion, school uniforms should be optional.*\n2. **Gerekçe ver:** *This is because students express themselves through clothes.*\n3. **Örnek ver:** *For example, ...*\n4. **Karşı görüşü kabul et ve cevapla:** *Although some argue that uniforms reduce bullying, ...*\n5. **Sonuçla:** *To sum up, ...*\n\n## Zıtlık bildiren bağlaçlar\n| Bağlaç | Yapı | Örnek | Türkçesi |\n|---|---|---|---|\n| **although / even though** | + cümle | **Although** it was raining, we went out. | Yağmur yağmasına rağmen dışarı çıktık. |\n| **despite / in spite of** | + isim / -ing | **Despite** the rain, we went out. / **Despite being** tired, she kept working. | Yağmura rağmen... / Yorgun olmasına rağmen... |\n| **however** | cümle başı, virgülle | It\'s expensive. **However**, it\'s worth it. | Pahalı. Ancak buna değer. |\n| **whereas / while** | iki şeyi karşılaştırır | I love tea, **whereas** my sister prefers coffee. | Ben çayı severim, oysa kız kardeşim kahveyi tercih eder. |\n| **on the other hand** | cümle başı | **On the other hand**, it can be dangerous. | Öte yandan tehlikeli olabilir. |\n\n> Higo\'nun ipucu: **despite**\'tan sonra **of** gelmez: *despite of* yanlış. Ama **in spite of** doğru. Ve despite\'tan sonra cümle değil isim gelir: *despite **the fact that** it rained* diyerek cümle bağlayabilirsin.\n\n## Sebep ve sonuç\n**Sebep bildirenler (çünkü, yüzünden):**\n| Bağlaç | Yapı | Örnek |\n|---|---|---|\n| because / as / since | + cümle | We stayed in **because** it was cold. |\n| because of / due to / owing to | + isim | The match was cancelled **due to** heavy snow. *Yoğun kar nedeniyle maç iptal edildi.* |\n\n**Sonuç bildirenler (bu yüzden):**\n| Bağlaç | Örnek | Türkçesi |\n|---|---|---|\n| so | It was late, **so** we took a taxi. | Geç olmuştu, bu yüzden taksiye bindik. |\n| therefore / as a result / consequently | Prices rose. **As a result**, sales fell. | Fiyatlar arttı. Sonuç olarak satışlar düştü. |\n| so ... that / such ... that | The film was **so** boring **that** I fell asleep. | Film o kadar sıkıcıydı ki uyuyakaldım. |\n\n## Fikir bildirme kalıpları\n| Amaç | Kalıp | Türkçesi |\n|---|---|---|\n| Görüş | In my view / From my point of view, ... | Bana göre, ... |\n| Güçlü görüş | I strongly believe that ... | ... olduğuna kesinlikle inanıyorum. |\n| Katılma | I completely agree with ... | ... ile tamamen katılıyorum. |\n| Kısmen katılma | I agree to some extent, but ... | Bir dereceye kadar katılıyorum ama ... |\n| Karşı çıkma | I\'m not sure I agree. / I see your point, but ... | Katıldığımdan emin değilim. / Haklı olduğun yer var ama ... |\n| Ekleme | Moreover / Furthermore / In addition, ... | Üstelik / Ayrıca, ... |\n| Örnek | For instance / such as ... | Örneğin, ... gibi |\n| Sonuç | To sum up / In conclusion, ... | Özetle / Sonuç olarak, ... |\n\n## Örnek paragraf\n> In my view, social media does more harm than good to teenagers. **Although** it helps young people stay in touch with friends, it **also** causes serious problems. **For instance**, many teenagers spend hours comparing themselves to others online. **As a result**, they may feel anxious or unhappy. **Furthermore**, constant notifications make it difficult to concentrate. **To sum up**, social media should be used carefully and in moderation.\n\n## Kendini kontrol et\n1. ___ the traffic, we arrived on time. (rağmen, isim)\n2. ___ she was ill, she went to work. (rağmen, cümle)\n3. The flight was delayed ___ the storm. (yüzünden)\n4. I studied hard. ___, I passed the exam.\n\nCevaplar: 1. Despite · 2. Although · 3. because of / due to · 4. As a result / Therefore','#FF8A3D',4,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(31,4,'Toplum ve Şehir','Kibar ifadeler, would rather ve it\'s time','## Toplumu ve şehrini konuş\nBu ünitede tercihleri ifade etmeyi (**would rather**), güçlü tavsiye ve uyarıyı (**had better**), bir şeyin **artık yapılması gerektiğini** söylemeyi (**It\'s time**) ve **kibar, dolaylı** konuşmayı öğreneceksin.\n\n| İngilizce | Türkçesi |\n|---|---|\n| public transport | toplu taşıma |\n| housing | konut |\n| urban | kentsel |\n| rural | kırsal |\n| inequality | eşitsizlik |\n| community | topluluk |\n| crowded | kalabalık |\n| affordable | uygun fiyatlı |\n\n## would rather: tercih\n**would rather** (I\'d rather), \"**... tercih ederim, ... yapmayı yeğlerim**\" anlamındadır.\n\n| Yapı | Örnek | Türkçesi |\n|---|---|---|\n| would rather + fiil | I\'d **rather stay** at home tonight. | Bu akşam evde kalmayı tercih ederim. |\n| would rather + fiil + than + fiil | I\'d **rather walk than take** the bus. | Otobüse binmektense yürümeyi tercih ederim. |\n| would rather not | I\'d **rather not** talk about it. | Bunun hakkında konuşmamayı tercih ederim. |\n| would rather + kişi + Past Simple | I\'d **rather you didn\'t** smoke here. | Burada sigara içmesen daha iyi olur. |\n\nSon yapıda geçmiş zaman kullanılır ama anlam **şimdi**dir; başkasının davranışıyla ilgili kibar bir istektir.\n\n**prefer** ile karşılaştır: *I prefer tea **to** coffee.* (genel tercih) · *I\'d rather have tea **than** coffee.* (şu anki tercih)\n\n## had better: güçlü tavsiye ve uyarı\n**had better** (\'d better), should\'dan **daha güçlü** bir tavsiyedir ve genellikle \"**yapmazsan kötü bir şey olur**\" uyarısı taşır.\n\n- *You**\'d better** leave now, or you\'ll miss your flight.* Şimdi çıksan iyi olur, yoksa uçağı kaçıracaksın.\n- *We**\'d better not** be late again.* Bir daha geç kalmasak iyi olur.\n\n**Dikkat:** had geçmiş görünse de anlam **şimdi/gelecek**tir. Arkasından fiil **yalın** gelir, to yok: *You\'d better to go* yanlış.\n\n## It\'s (high) time + past simple\n\"**Artık ... zamanı geldi (hatta geçiyor)**\" anlamında, genellikle bir şikâyet ya da eleştiri taşır.\n\n| Yapı | Örnek | Türkçesi |\n|---|---|---|\n| It\'s time + to + fiil | It\'s time **to go**. | Gitme zamanı. (genel) |\n| It\'s time + özne + Past Simple | It\'s time **you went** to bed. | Artık yatman gerek. |\n| It\'s high time + özne + Past Simple | It\'s **high** time the city **built** more bike lanes. | Şehrin artık daha çok bisiklet yolu yapmasının zamanı çoktan geldi. |\n\n**high** ve **about** eleştiriyi güçlendirir: *It\'s about time you apologised!* (Artık özür dilemenin vakti geldi!)\n\n## Kibar ve dolaylı ifadeler\nResmî ortamlarda ve yabancılarla konuşurken doğrudan soru sormak kaba kaçabilir. Dolaylı sorularda **cümle sırası düzdür**, do/does/did kullanılmaz.\n\n| Doğrudan | Dolaylı ve kibar |\n|---|---|\n| Where is the station? | **Could you tell me where** the station **is**? |\n| What time does it open? | **Do you know what time** it **opens**? |\n| Is there a pharmacy here? | **I was wondering if** there **was** a pharmacy near here. |\n| Give me the report. | **Would you mind giving** me the report? |\n| You\'re wrong. | **I\'m not sure that\'s quite right.** |\n\n> Higo\'nun ipucu: *Would you mind ...?* sorusuna \"tamam, olur\" demek için **No, not at all.** dersin, çünkü soru aslında \"sakıncası var mı?\" demektir.\n\n## Kendini kontrol et\n1. I\'d rather ___ (watch) a film than go out.\n2. You\'d better ___ (take) an umbrella.\n3. It\'s high time you ___ (find) a job.\n4. Could you tell me where the museum ___?\n\nCevaplar: 1. watch · 2. take · 3. found · 4. is','#3A6FF7',5,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(32,4,'Akademik İngilizce','Akademik okuma, YDS / YÖKDİL kalıpları','## Sınav metinlerini çöz\nBu ünite YDS, YÖKDİL, YDT, IELTS ve TOEFL gibi sınavlardaki **akademik okuma parçalarını** hızlı ve doğru çözmeye odaklanıyor: metnin yapısını tanımak, **sinyal kelimelerini** fark etmek ve **soru tiplerine** strateji geliştirmek.\n\nAkademik İngilizcede sık geçen kelimeler:\n| İngilizce | Türkçesi |\n|---|---|\n| significant | önemli, kayda değer |\n| indicate | göstermek, işaret etmek |\n| approach | yaklaşım |\n| assume | varsaymak |\n| factor | etken |\n| consequently | sonuç olarak |\n| hypothesis | hipotez |\n| crucial | çok önemli |\n| decline | düşüş, azalmak |\n| sufficient | yeterli |\n\n## Akademik metnin yapısı\nAkademik paragraflar genellikle aynı düzeni izler; bu düzeni bilmek, okumadan önce nereye bakacağını gösterir.\n\n| Bölüm | Görevi | İpucu |\n|---|---|---|\n| **Konu cümlesi** (topic sentence) | Paragrafın ana fikri | Genellikle ilk cümle |\n| **Destekleyici cümleler** | Kanıt, örnek, açıklama | for example, research shows |\n| **Karşı görüş** | Farklı bir bakış | however, critics argue |\n| **Sonuç cümlesi** | Toparlama | therefore, thus, in short |\n\n**Ana fikir soruları** için önce ilk ve son cümleleri oku. Ayrıntı soruları için soru kökündeki **anahtar kelimeyi** metinde tara (scanning).\n\n## Sinyal kelimeleri\nSinyal kelimeleri, yazarın düşüncesinin **nereye gittiğini** gösterir. Paragraf tamamlama ve anlam bütünlüğü sorularında doğru cevabı genellikle bunlar verir.\n\n| İşlevi | Kelimeler | Türkçesi |\n|---|---|---|\n| Ekleme | moreover, furthermore, in addition, besides | ayrıca, üstelik |\n| Zıtlık | however, nevertheless, yet, on the contrary, whereas | ancak, buna rağmen, aksine |\n| Sebep | because of, due to, owing to, since | yüzünden, çünkü |\n| Sonuç | therefore, thus, hence, consequently, as a result | bu nedenle, dolayısıyla |\n| Örnek | for instance, such as, namely, to illustrate | örneğin, yani |\n| Benzerlik | similarly, likewise, in the same way | benzer şekilde |\n| Özet | in short, to conclude, overall | kısacası, sonuç olarak |\n\n> Higo\'nun ipucu: Boşluktan önce olumlu, sonra olumsuz bir fikir varsa aradığın kelime büyük ihtimalle **however / nevertheless** gibi bir zıtlık bağlacıdır. Önce boşluğun iki tarafındaki fikirlerin ilişkisini bul, sonra şıklara bak.\n\n## Soru tipleri\n| Soru tipi | Ne soruyor? | Strateji |\n|---|---|---|\n| Ana fikir | Metnin genel konusu | İlk ve son cümle; çok dar ya da çok geniş şıkları ele |\n| Ayrıntı | Metinde açıkça yazan bilgi | Anahtar kelimeyi tara, eş anlamlısını ara |\n| Çıkarım | Metinden **çıkarılabilecek** sonuç | Metinde yazmayan ama metne aykırı olmayan şık |\n| Kelime anlamı | Bir kelimenin bağlamdaki anlamı | Cümleyi o şıkla tekrar oku |\n| Yazarın tutumu | Yazar destekliyor mu, eleştiriyor mu? | Sıfatlara ve zarflara dikkat: fortunately, unfortunately |\n| Paragraf tamamlama | Akışa uyan cümle | Önceki ve sonraki cümlenin bağlantısını kur |\n| Anlam bütünlüğünü bozan cümle | Konunun dışına çıkan cümle | Ana fikirle ilgisi zayıf olan cümleyi bul |\n\n## Çeldiricilerden korun\n- **Aşırı genelleme:** metin \"some\" diyorsa \"all\" diyen şık yanlıştır.\n- **Kelime tuzağı:** metindeki kelimeyi aynen tekrar eden şık her zaman doğru değildir; anlamı karşılaştır.\n- **Doğru ama ilgisiz:** gerçek hayatta doğru olan ama metinde geçmeyen bilgi.\n- **Kısmen doğru:** şıkkın yarısı metne uyuyor, diğer yarısı uymuyor.\n\n## Kendini kontrol et\n1. \"The project was expensive. ___, it was a great success.\" (zıtlık)\n2. \"Many species are disappearing ___ habitat loss.\" (sebep, isim)\n3. Bir paragrafın ana fikri genellikle hangi cümlededir?\n4. Metin \"some scientists\" diyorsa \"all scientists\" diyen şık için ne dersin?\n\nCevaplar: 1. However / Nevertheless · 2. due to · 3. İlk cümle (topic sentence) · 4. Aşırı genelleme, yanlış','#2F7CF6',6,'2026-10-04 20:30:41','2026-10-04 20:30:41'),
(33,4,'Kültür ve Medya','Phrasal verbs, deyimler ve doğal İngilizce','## Doğal İngilizce\nBu ünitede ana dili İngilizce olanların her gün kullandığı **phrasal verb**\'leri (deyimsel fiiller) ve **deyimleri** öğreneceksin. Dizilerde, sohbetlerde ve sınavların dinleme bölümlerinde en çok bunlar zorlar.\n\n| İngilizce | Türkçesi |\n|---|---|\n| media | medya |\n| headline | manşet |\n| broadcast | yayın, yayınlamak |\n| audience | izleyici kitlesi |\n| influencer | sosyal medya fenomeni |\n| go viral | viral olmak, hızla yayılmak |\n\n## Phrasal verbs ne demek?\nPhrasal verb, bir **fiil + edat / zarf** birleşimidir ve çoğu zaman **yeni bir anlam** kazanır. Parçaların anlamından tahmin etmek her zaman mümkün değildir.\n\n- **look** = bakmak → **look after** = bakmak, ilgilenmek · **look up** = (sözlükte) aramak · **look forward to** = dört gözle beklemek\n- **give** = vermek → **give up** = vazgeçmek, bırakmak\n\n| Phrasal verb | Türkçesi | Örnek |\n|---|---|---|\n| find out | öğrenmek, ortaya çıkarmak | I **found out** the truth. *Gerçeği öğrendim.* |\n| turn down | reddetmek; sesini kısmak | She **turned down** the offer. *Teklifi reddetti.* |\n| come up with | (fikir) bulmak | He **came up with** a great idea. *Harika bir fikir buldu.* |\n| put off | ertelemek | Don\'t **put off** your homework. *Ödevini erteleme.* |\n| run out of | -i tükenmek | We\'ve **run out of** milk. *Sütümüz bitti.* |\n| get over | atlatmak | It took weeks to **get over** the flu. *Gribi atlatmak haftalar sürdü.* |\n| set up | kurmak | They **set up** a YouTube channel. *Bir YouTube kanalı kurdular.* |\n| carry on | devam etmek | **Carry on**, I\'m listening. *Devam et, dinliyorum.* |\n| bring up | (konu) açmak; yetiştirmek | She **brought up** an interesting point. |\n| take up | (hobi) başlamak | I\'ve **taken up** yoga. *Yogaya başladım.* |\n| get along (with) | iyi geçinmek | I **get along with** my colleagues. |\n| show off | hava atmak | Stop **showing off**! *Hava atmayı bırak!* |\n\n## Ayrılabilen ve ayrılamayan\nBazı phrasal verb\'lerde nesne fiil ile edatın **arasına** girebilir, bazılarında giremez.\n\n| Tür | Örnek |\n|---|---|\n| Ayrılabilen | Turn **down** the music. = Turn the music **down**. |\n| Zamir gelirse **mutlaka arada** | Turn **it** down. (*Turn down it* yanlış) |\n| Ayrılamayan | I\'m **looking after** my sister. (*looking my sister after* yanlış) |\n\n> Higo\'nun ipucu: Phrasal verb\'leri tek tek değil, **konu gruplarıyla** öğren: ilişkiler (get along, fall out, break up), iş (set up, take over, lay off), seyahat (set off, check in, get away).\n\n## Sık deyimler\nDeyimler (idioms), kelimelerin tek tek anlamından çıkarılamayan kalıp ifadelerdir.\n\n| Deyim | Anlamı | Türkçe karşılığı |\n|---|---|---|\n| a piece of cake | çok kolay | çocuk oyuncağı |\n| break the ice | ilk gerginliği kırmak | buzları eritmek |\n| hit the books | sıkı ders çalışmak | kitaplara gömülmek |\n| under the weather | biraz hasta | keyifsiz, rahatsız |\n| once in a blue moon | çok nadiren | kırk yılda bir |\n| cost an arm and a leg | çok pahalı olmak | dudak uçuklatmak |\n| it\'s not my cup of tea | bana göre değil | pek benim tarzım değil |\n| let the cat out of the bag | sırrı ağzından kaçırmak | baklayı ağzından çıkarmak |\n| the ball is in your court | karar sende | top sende |\n| on the same page | aynı fikirde | aynı frekansta |\n\n## Medya diliyle bir paragraf\n> When the video first **came out**, nobody expected it to **go viral**. But within a week, millions of people had watched it. Journalists tried to **find out** who had made it, and soon the creator was invited to a TV show. He admitted he had almost **given up** on his channel. \"It was **a piece of cake** to film,\" he said, \"but getting people to notice it took years.\"\n\n## Kendini kontrol et\n1. I can\'t ___ out what this word means. (find)\n2. We\'ve run ___ of coffee.\n3. Don\'t put ___ the meeting again!\n4. The test was a piece of ___. (çok kolaydı)\n\nCevaplar: 1. find · 2. out · 3. off · 4. cake','#FF7FB0',7,'2026-10-04 20:30:41','2026-10-04 20:30:41');
